        return ops.sub;
    }
    if (operator == tk.Mul) {
        return ops.mul;
    }
    if (operator == tk.Quo) {
        return ops.div;
    }
    if (operator == tk.Mod) {
        return ops.mod;
    }
    if (operator == tk.And) {
        return ops.bit_and;
    }
    if (operator == tk.Or) {
        return ops.bit_or;
    }
    if (operator == tk.Xor) {
        return ops.bit_xor;
    }
    if (operator == tk.Shl) {
        return ops.shl;
    }
    if (operator == tk.Shr) {
        return ops.shr;
    }
    if (operator == tk.Lt) {
        return ops.lt;
    }
    if (operator == tk.LtEq) {
        return ops.le;
    }
    if (operator == tk.Gt) {
        return ops.gt;
    }
    if (operator == tk.GtEq) {
