        return tk.Sub;
    }
    if (assignment == tk.MulEq) {
        return tk.Mul;
    }
    if (assignment == tk.QuoEq) {
        return tk.Quo;
    }
    if (assignment == tk.ModEq) {
        return tk.Mod;
    }
    if (assignment == tk.AndEq) {
        return tk.And;
    }
    if (assignment == tk.OrEq) {
