            held := values[value_top - 1];
            if (held.storage == UnionStorage && held.record >= 0 && types[held.record].kind == TaskResultDecl) {
                step = TaskResultIsStep(forest, text, document, types, members, names, scopes[length(scopes) - 1],
                                        values, value_top, item, ops, target, at);
            } else {
                step = IsStep(forest, text, document, types, members, names, scopes[length(scopes) - 1], values, value_top,
                              item, ops, target, at);
            }
        } else {
            return Body.Failed(Diagnose(forest, item.node, document, format_text("unsupported syntax '{}'", parser.KindName(kind))));
        }
        // Apply the step, then the copy it or the control flow asks for.
        pass: int = 0;
        while (pass < 2) {
            if (pass == 1) {
                stepped = retained.storage != 0;
                if (stepped) {
                    at = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                          host: length(hosts), call: length(calls)};
                    step = RetainStep(retained, ops, target, at, node);
                }
            }
            if (stepped) {
                if (pass == 0 && kind == syntax.ReturnStatement) {
                    step = DropBeforeFinish(step, names, natives, ports, ops, target, at, node);
                }
                if (pass == 0 && !item.capture && BooleanPosition(forest, text, item.node)) {
                    // An earlier presence guard makes bool? read its bool
                    // payload, including in another condition. A fresh
                    // optional still asks about presence below.
                    if (item.phase != OptionalWrapPhase && item.phase != NarrowedOriginalPhase &&
                        item.phase != NarrowedReadPhase && item.phase != CopyValuePhase &&
                        OptionalStepProduced(types, step)) {
                        switch step {
                            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                          popped, value, retained, marks):
                                element := OptionalElement(types, value);
                                if (element.storage == BoolStorage && element.container == 0) {
                                    step = OptionalNarrowStep(forest, text, types, names, item.node, step,
                                                              ops, target, at, node);
                                }
                            case .Failed(diagnostic):
                                return Body.Failed(diagnostic);
                        }
                    }
                    // Direct conditions keep main's scoped payload-place binding.
                    optional_boolean = OptionalStepProduced(types, step) && !OptionalConditionPosition(forest, item.node);
                    if (!OptionalStepProduced(types, step) || optional_boolean) {
                        step = PresenceStep(types, step, ops, target, at, node);
                    }
                } else if (pass == 0 && !item.capture && item.phase != OptionalWrapPhase &&
                           item.phase != NarrowedOriginalPhase && item.phase != NarrowedReadPhase &&
                           item.phase != CopyValuePhase &&
                           (kind == syntax.Identifier || kind == syntax.MemberExpression)) {
                    step = OptionalNarrowStep(forest, text, types, names, item.node, step, ops, target, at, node);
                }
                switch step {
                    case .Failed(diagnostic):
                        return Body.Failed(diagnostic);
                    case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                                  added_calls, added_names, scheduled, popped, value, kept, marks):
                        if (pass == 0) {
                            switch StepFacts(forest, context, direct_write, facts, item.node, added_hosts, added_calls) {
                                case .Read(summary, recorded):
                                    direct_write = summary;
                                    facts = recorded;
                            }
                        }
                        if constant_element {
                            // Integer constant evaluation emits no branches.
                            code.extend(WithoutDebug(ops, added_code));
                        } else {
                            code.extend(added_code);
                        }
                        slots.extend(added_slots);
                        locals.extend(added_locals);
                        cells.extend(added_cells);
                        hosts.extend(added_hosts);
                        roots.extend(added_roots);
                        calls.extend(added_calls);
                        names.extend(added_names);
                        next.extend(scheduled);
                        value_top -= popped;
                        if (value.storage != 0) {
                            produced = value;
                        }
                        if (pass == 0) {
                            retained = kept;
                        }
                        if (length(marks) == 1) {
                            // A switch arm's test: the jump past the arm.
                            current := switches[length(switches) - 1];
                            current.skip = marks[0];
                            switches[length(switches) - 1] = current;
                        }
                        if (length(marks) == 2) {
                            // A map loop's head, whose step binds its names; leaving
                            // the loop drops them.
                            loop: Loop = {held_slot: iteration.slot, held_storage: iteration.storage,
                                          held_container: iteration.container, held_record: iteration.record,
                                          held_owned: iteration.owned, head: marks[0], first_break: length(breaks), first_continue: length(continues),
                                          each: true, index: at.local, mark: length(names) - length(added_names),
                                          leave: marks[1],
                                          reverse: false, counted: false, bound: -1, empty: -1};
                            loops.append(loop);
                        }
                        if (length(marks) == 3) {
                            // A for head: its loop, then its element's binding.
                            reverse := Field(forest, item.node, syntax.FieldReverse) >= 0;
                            loop: Loop = {held_slot: iteration.slot, held_storage: iteration.storage,
                                          held_container: iteration.container, held_record: iteration.record,
                                          held_owned: iteration.owned, head: marks[0], first_break: length(breaks), first_continue: length(continues),
                                          each: true, index: marks[2], mark: length(names), leave: marks[1],
                                          reverse: reverse, counted: false, bound: -1, empty: -1};
                            loops.append(loop);
                            // `for x, i in xs` names the item, then the index the loop owns.
                            if (Field(forest, item.node, syntax.FieldKey) >= 0 &&
                                Text(forest, text, Field(forest, item.node, syntax.FieldKey)) ==
                                Text(forest, text, Field(forest, item.node, syntax.FieldName))) {
                                return Body.Failed(Diagnose(forest, Field(forest, item.node, syntax.FieldName), document,
                                                            format_text("Duplicate declaration '{}'",
                                                                        Text(forest, text, Field(forest, item.node, syntax.FieldName)))));
                            }
                            if (Field(forest, item.node, syntax.FieldKey) >= 0) {
                                key: Name = {owned: false, name: Text(forest, text, Field(forest, item.node, syntax.FieldName)), place: LocalPlace,
                                             index: marks[2], storage: IntStorage, container: 0, record: -1,
                                             writable: false, node: Field(forest, item.node, syntax.FieldName)};
                                names.append(key);
                                code.append(SymbolCode(ops, key.node, node));
                            }
                            element := produced;
                            produced = NoValue();
                            if (Pointer(element.storage, element.container) &&
                                (lent_element ||
                                 Unchanging(forest, text, callables, natives, types, names, callable.package, mutated,
                                            Field(forest, item.node, syntax.FieldValue)))) {
                                // The array cannot change, so the element is read in place.
                                cells.append(MovedCell(element));
                                slots.append(AddressSlot(target));
                                code.extend(MoveCode(element, ops, target, length(slots) - 1,
                                                     length(cells) - 1, node));
                                produced = element;
                                lent: int = 0;
                                if (lent_element) {
                                    produced.cell = length(cells) - 1;
                                    lent = 1;
                                }
                                next.append(Resume(item.node, 3, lent, 0));
                            } else if (Pointer(element.storage, element.container)) {
                                retained = element;
                                next.append(Resume(item.node, 3, 0, 0));
                            } else {
                                locals.append(ValueLocal(element.storage));
                                code.append(Instruction(ops.save, element.storage, 0, element.slot, 0,
                                                        length(locals) - 1, node));
                                binding: Name = {owned: false, name: Text(forest, text, ItemField(forest, item.node)),
                                                 place: LocalPlace, index: length(locals) - 1, storage: element.storage,
                                                 container: 0, record: element.record, writable: false,
                                                 node: ItemField(forest, item.node)};
                                names.append(binding);
                                code.append(SymbolCode(ops, binding.node, node));
                                next.append(Visit(Field(forest, item.node, syntax.FieldBody)));
                                next.append(Resume(item.node, 4, 0, 0));
                            }
                        }
                        if (length(marks) == 4) {
                            loop: Loop = {held_slot: -1, held_storage: 0, held_container: 0, held_record: -1,
                                          held_owned: false, head: marks[0], first_break: length(breaks),
                                          first_continue: length(continues), each: true, index: -1, mark: length(names) - length(added_names), leave: marks[1],
                                          reverse: false, counted: false, bound: marks[2], empty: -1};
                            loops.append(loop);
                        }
                }
            }
            pass += 1;
        }
        types = table^;
        if (ops.debug && !constant_element && item.phase != OptionalWrapPhase && !optional_boolean &&
            item.phase != MathCapturePhase) {
            // A pointer whose member is read next is watched by that read.
            transient := length(next) > 0 && next[length(next) - 1].phase == PointerMemberReadPhase;
            switch DebugWatches(forest, item, produced, negated || transient, callables, params, natives, ports,
                                ops, target, length(slots)) {
                case .Read(added_code, added_slots, added_roots):
                    code.extend(added_code);
                    slots.extend(added_slots);
                    roots.extend(added_roots);
            }
        }
        // An argument of an overloaded native, on its last visit, reserves a
        // jump, a no-op until the call chooses its overload.
        if (ops.debug && item.phase != MathCapturePhase && !Resumed(next, item.node) && OverloadArgument(forest, work, work_top, item.node)) {
            reserved_nodes.append(item.node);
            reserved_jumps.append(length(code));
            code.append(Instruction(ops.jump, 0, 0, 0, 0, length(code) + 1, node));
        }
        // A compound assignment watches the value it stores at its target.
        if (item.phase == CombinePhase && kind == syntax.Assignment && produced.storage > 0) {
            code.append(WatchCode(ops, produced.slot, produced.storage, produced.container, produced.record,
                                  0, true, forest[Field(forest, item.node, syntax.FieldTarget)], target));
        }
        if (produced.storage != 0) {
            if (value_top < length(values)) {
                values[value_top] = produced;
            } else {
                values.append(produced);
            }
            value_top += 1;
        }
        // Run scheduled items in order: the last pushed runs first.
        at_next := length(next) - 1;
        while (at_next >= 0) {
            scheduled := next[at_next];
            scheduled.capture = scheduled.capture || item.capture;
            if (work_top < length(work)) {
                work[work_top] = scheduled;
            } else {
                work.append(scheduled);
            }
            work_top += 1;
            at_next -= 1;
        }
    }
    return FinishBody(forest, document, callable, declaration, inferring, values, value_top,
                      key, solid, undeclared, meaning, document_hash, params, named, names, natives, ports,
                      ops, target, slots, locals, cells, code, calls, hosts, roots, points, watches,
                      semantic_effects, direct_write, facts, retargets, retarget_starts);
}

// Complete the body after dispatch, keeping cleanup and result publication
// separate so dispatch fits each backend's function definition budget.
FinishBody :: (forest: snapshot.SnapshotNode[], document: int, callable: Callable,
               declaration: snapshot.SnapshotNode, inferring: bool, values: Value[], value_top: int,
               key: string, solid: int[], undeclared: u64, meaning: u64, document_hash: u64,
               params: Param[], named: int, names: Name[], natives: ResolvedNative[], ports: ResolvedPort[],
               ops: Ops, target: Target, input_slots: Slot[], input_locals: Slot[], input_cells: Cell[],
               input_code: Code[], input_calls: Invocation[], input_hosts: Host[], input_roots: Root[],
               input_points: SourcePoint[], watches: SourceWatch[], semantic_effects: int, direct_write: int,
               facts: SemanticFact[], retargets: int[], retarget_starts: int[]) -> Body {
    slots := input_slots;
    locals := input_locals;
    cells := input_cells;
    code := input_code;
    calls := input_calls;
    hosts := input_hosts;
    roots := input_roots;
    points := input_points;
    cleanup_at: Bases = {pc: length(code), slot: length(slots), local: length(locals),
                         cell: length(cells), host: length(hosts), call: length(calls)};
    switch DropNamesStep(names, 0, natives, ports, ops, target, cleanup_at, declaration) {
        case .Failed(diagnostic):
            return Body.Failed(diagnostic);
        case .Emitted(drop_code, drop_slots, drop_locals, drop_cells, drop_hosts, drop_roots,
                      drop_calls, drop_bound, drop_next, drop_popped, drop_value, drop_retained, drop_marks):
            code.extend(drop_code);
            slots.extend(drop_slots);
            locals.extend(drop_locals);
            cells.extend(drop_cells);
            hosts.extend(drop_hosts);
            roots.extend(drop_roots);
            calls.extend(drop_calls);
    }
    // A function completes at its end, and one with named results returns
    // them.
    if (callable.result == GenericInferStorage) {
        return Body.Inferred({storage: 0, container: 0, record: -1});
    }
    if (inferring && value_top > 0) {
        value := values[value_top - 1];
        return Body.Inferred({storage: value.storage, container: value.container, record: value.record});
    }
    points.append(PointAt(key, solid, FunctionRecord, meaning, true, declaration, declaration));
    code.append(PointCode(ops, length(points) - 1, declaration));
    if (callable.results > 0) {
        at: Bases = {pc: length(code), slot: length(slots), local: length(locals), cell: length(cells),
                     host: length(hosts), call: length(calls)};
        switch NamedResultsStep([], ops, target, params, callable, named, at, declaration) {
            case .Failed(diagnostic):
                return Body.Failed(diagnostic);
            case .Emitted(added_code, added_slots, added_locals, added_cells, added_hosts, added_roots,
                          added_calls, added_names, scheduled, popped, value, kept, marks):
                code.extend(added_code);
                slots.extend(added_slots);
                cells.extend(added_cells);
                hosts.extend(added_hosts);
        }
    }
    code.append(Instruction(ops.end, 0, 0, 0, 0, 0, declaration));
    code = Retargeted(code, retargets, retarget_starts);
    if (callable.result_container == ViewContainer && ReachesBodyEnd(code, ops)) {
        return Body.Failed(Diagnose(forest, callable.node, document,
                                    "view result requires an initialized value on every return path"));
    }
    if (!ops.debug) {
        code = WithoutDebug(ops, code);
        points = [];
    }
    return NumberPoints(forest, solid, undeclared, meaning, document_hash, declaration, ops, slots, locals, cells,
                        code, calls, hosts, roots, points, watches, semantic_effects, direct_write, facts);
}

// Follow both sides of each branch. A metadata-only view result header is
// never a live value, so a successful return must publish a value before END.
ReachesBodyEnd :: (code: Code[], ops: Ops) -> bool {
    visited := resize([false], length(code));
    pending: int[] = [int(0)];
    top: int = 1;
    while (top > 0) {
        top -= 1;
        at := pending[top];
        if (at >= 0 && at < length(code) && !visited[at]) {
            visited[at] = true;
            instruction := code[at];
            if (instruction.op == ops.end) {
                return true;
            }
            successors: int[] = [];
            if (instruction.op == ops.jump) {
                successors = [instruction.target];
            } else if (instruction.op == ops.branch_if) {
                successors = [instruction.target, at + 1];
            } else if (instruction.op != ops.finish) {
                successors = [at + 1];
            }
            for (successor in successors) {
                if (top < length(pending)) {
                    pending[top] = successor;
                } else {
                    pending.append(successor);
                }
                top += 1;
            }
        }
    }
    return false;
}

// A body's tables, with the points and watches the steps placed, each at its
// instruction's position. The runtime numbers each instruction that suspends,
// an invocation or a point, by its order, and a prepared module's bytes hold
// that number.
NumberPoints :: (forest: snapshot.SnapshotNode[], solid: int[], undeclared: u64, meaning: u64,
                 document_hash: u64, declaration: snapshot.SnapshotNode, ops: Ops, slots: Slot[], locals: Slot[],
                 cells: Cell[], code: Code[], calls: Invocation[], hosts: Host[], roots: Root[],
                 points: SourcePoint[], watches: SourceWatch[], effects: int, direct_write: int,
                 facts: SemanticFact[]) -> Body {
    numbered_code := code;
    numbered_points := points;
    numbered_watches := watches;
    suspension: int = 0;
    at_point: int = 0;
    while (at_point < length(numbered_code)) {
        op := numbered_code[at_point].op;
        if (op == ops.source_point && numbered_code[at_point].left < 0) {
            placed := numbered_code[at_point];
            occurrence := OccurrenceIn(document_hash, ExpressionRecord, solid[placed.start], solid[placed.end]);
            point_meaning: u64 = 0;
            point_kind := ExpressionRecord;
            if (placed.left == CompletionPoint) {
                occurrence = OccurrenceIn(document_hash, FunctionRecord, solid[declaration.start],
                                          solid[declaration.end]);
                point_meaning = meaning;
                point_kind = FunctionRecord;
            } else if (placed.left == SymbolPoint) {
                occurrence = SymbolOccurrence(forest, document_hash, solid, undeclared, placed.right);
                point_kind = SymbolRecord;
            } else if (placed.left == OccurrencePoint) {
                occurrence = placed.payload;
                point_kind = placed.right;
            }
            point: SourcePoint = {occurrence: occurrence, meaning: point_meaning, start: placed.start, end: placed.end,
                                  line: placed.line, column: placed.column, kind: point_kind,
                                  completion: placed.left == CompletionPoint};
            numbered_points.append(point);
            numbered_code[at_point] = {op: ops.source_point, type: 0, output: 0, left: length(numbered_points) - 1, right: 0,
                                       target: suspension, offset: 0, value_storage: 0, value_container: 0, value_record: -1,
                                       payload: 0, text: "", has_text: false, message: "", has_message: false,
                                       start: placed.start, end: placed.end, line: placed.line, column: placed.column};
            suspension += 1;
        } else if (op == ops.invoke || op == ops.source_point || op == ops.suspend) {
            numbered := numbered_code[at_point];
            numbered.target = suspension;
            numbered_code[at_point] = numbered;
            suspension += 1;
        } else if (op == ops.source_watch) {
            placed := numbered_code[at_point];
            // A default of another document carries its occurrence.
            occurrence := placed.payload;
            if (occurrence == 0) {
                occurrence = OccurrenceIn(document_hash, ExpressionRecord, solid[placed.start], solid[placed.end]);
            }
            watch: SourceWatch = {occurrence: occurrence,
                                  start: placed.start, end: placed.end, line: placed.line, column: placed.column,
                                  storage: placed.value_storage, container: placed.value_container,
                                  record: placed.value_record, ordinal: placed.right, output: placed.output == 1,
                                  reference: placed.offset == 1};
            numbered_watches.append(watch);
            numbered_code[at_point] = Instruction(ops.source_watch, placed.type, 0, placed.left, 0,
                                                  length(numbered_watches) - 1, Located(placed));
        }
        at_point += 1;
    }
    return Body.Emitted(slots, locals, cells, numbered_code, calls, hosts, roots, numbered_points, numbered_watches,
                        effects, direct_write, facts);
}
package package_compiler

import snapshot "project:source_snapshot"
import routes "project:package_routes"
import graph "project:package_graph"
import binding "project:lexical_binding"
import syntax "project:syntax_diagnostics"
import writer "project:prepared_writer"
import json "project:json_string"
import strings "core:strings"
import tk "project:source_tokenizer"

// Compiles packages of functions, records and unions, and the packages they
// import, to a prepared closure. Stage zero builds this compiler; everything
// after the raw parser is authored.

// Facts of the runtime this compiler targets, which Chibi cannot see: pointer
// width, the byte offsets of a value header's and an array's members, and the
// failure kinds a host call and a failed assertion report.
pub Target :: struct {
    pointer_storage: int;
    pointer_size: int;
    value_size: int;
    payload_offset: int;
    arguments_offset: int;
    delta_seconds_offset: int;
    results_offset: int;
    error_status_offset: int;
    type_offset: int;
    container_offset: int;
    name_offset: int;
    record_offset: int;
    schema_offset: int;
    count_offset: int;
    items_offset: int;
    data_offset: int;
    stride_offset: int;
    map_count_offset: int;
    data_failure: int;
    argument_failure: int;
    // The failure kind of an assert whose condition is false.
    assert_failure: int;
}
// Prepared instructions this compiler emits, as ordinals on the target.
Ops :: struct {
    constant: int;
    argument: int;
    local: int;
    save: int;
    context: int;
    array: int;
    host_slot: int;
    string_equal: int;
    index: int;
    load: int;
    write: int;
    result: int;
    host_call: int;
    command_argument: int;
    command_begin: int;
    command_result: int;
    command_output: int;
    suspend: int;
    invoke: int;
    guard: int;
    check: int;
    branch_if: int;
    jump: int;
    finish: int;
    end: int;
    add: int;
    sub: int;
    mul: int;
    div: int;
    mod: int;
    neg: int;
    bit_and: int;
    bit_or: int;
    bit_xor: int;
    bit_not: int;
    shl: int;
    shr: int;
    lt: int;
    le: int;
    gt: int;
    ge: int;
    eq: int;
    ne: int;
    cast: int;
    select: int;
    math_abs: int;
    math_min: int;
    math_max: int;
    math_sqrt: int;
    math_floor: int;
    math_ceil: int;
    math_round: int;
    math_exp: int;
    math_log: int;
    math_pow: int;
    math_sin: int;
    math_cos: int;
    math_tan: int;
    math_asin: int;
    math_acos: int;
    math_atan: int;
    math_atan2: int;
    variable: int;
    store: int;
    store_value: int;
    owner: int;
    query_variable: int;
    convert: int;
    source_point: int;
    source_watch: int;
    // Whether the code carries debugger points and watches.
    debug: bool;
}
// A type: a storage code, whether it is an array, and for records, unions and
// arrays of them the index of their declaration in `types`.
ValueType :: struct {
    storage: int;
    container: int;
    record: int;
}
// A function of package `package`; its parameters are params[first, first +
// count). It has one `result` of its own type, storage 0 for none, or
// `results` named results, the params after its parameters.
Callable :: struct {
    name: string;
    package: int;
    document: int;
    node: int;
    first: int;
    count: int;
    result: int;
    result_container: int;
    result_record: int;
    results: int;
    waits: bool;
    // A monomorphized function retains its canonical template/binding identity.
    identity: u64;
    owner_package: int;
}
// A function's parameters, then its named results, and its callable.
Signature :: union {
    Failed(diagnostic: syntax.Diagnostic) | Read(callable: Callable, added: Param[])
}
Param :: struct {
    name: string;
    storage: int;
    container: int;
    record: int;
    // A literal default a call that omits the argument passes: its bits, or
    // its text for a string.
    has_default: bool;
    default_bits: u64;
    default_text: string;
    // The occurrence of the default's expression, which stage zero evaluates
    // where a call omits the argument.
    default_occurrence: u64;
    // A scoped pointer parameter, whose argument is a reference to the
    // caller's location.
    reference: bool;
    // A scoped parameter its function changes, or passes on to one that does:
    // the native lane passes it by reference, a pointer to the caller's
    // variable. The module's analysis sets it; the source never does.
    written: bool;
    // The node that declares the parameter, -1 when the source declares none.
    node: int;
}
// A native function the target links, as its catalog describes it. Its
// parameters and then its results are ports[first, first + parameters +
// results); its ID and ABI are identities[2 * index] and [2 * index + 1]. A
// variadic native's last parameter takes any number of arguments, none
// included.
pub Native :: struct {
    name: string;
    first: int;
    parameters: int;
    results: int;
    variadic: bool;
    effects: int;
}
// Rich catalogs retain function and action declarations with their actual
// names and kinds. `direct` admits only bindings callable as synchronous data;
// unsupported rows remain visible to source name resolution.
pub CatalogNative :: struct {
    name: string;
    first: int;
    parameters: int;
    results: int;
    variadic: bool;
    direct: bool;
    qualified_name: string;
    kind: int;
    intrinsic: int;
    effects: int;
}
ResolvedNative :: struct {
    name: string;
    first: int;
    parameters: int;
    results: int;
    variadic: bool;
    direct: bool;
    qualified_name: string;
    kind: int;
    intrinsic: int;
    // The catalog's declared script effects, such as suspension.
    effects: int;
    // Exact parsed callable IDs identify source-owned rows for this compile.
    source: bool;
}
NativeFunctionKind: int : 0;
NativeActionKind: int : 1;
LegacyNatives :: (natives: Native[], names: string[]) -> ResolvedNative[] {
    resolved: ResolvedNative[] = [];
    for (native in natives) {
        // The stable pure catalog predates linked intrinsic metadata.
        intrinsic: int = 0;
        if (NameMatches("assert", native.name)) {
            intrinsic = Ordinal(names, "ASSERT");
        }
        row: ResolvedNative = {name: native.name, first: native.first, parameters: native.parameters,
                               results: native.results, variadic: native.variadic, direct: true,
                               qualified_name: native.name, kind: NativeFunctionKind, intrinsic: intrinsic,
                               effects: native.effects, source: false};
        resolved.append(row);
    }
    return resolved;
}
CatalogNatives :: (natives: CatalogNative[]) -> ResolvedNative[] {
    resolved: ResolvedNative[] = [];
    for (native in natives) {
        row: ResolvedNative = {name: native.name, first: native.first, parameters: native.parameters,
                               results: native.results, variadic: native.variadic, direct: native.direct,
                               qualified_name: native.qualified_name, kind: native.kind,
                               intrinsic: native.intrinsic, effects: native.effects, source: false};
        resolved.append(row);
    }
    return resolved;
}
// Host kernels have canonical names such as host:clock.Sample. Only the owning
// authored package sees the exact private member. Keep every row's index so its
// ports, effects and identity/ABI pair remain those supplied by the host.
HostPackageAvailable :: (natives: ResolvedNative[], identity: string) -> bool {
    if (!strings.HasPrefix(identity, "host:")) {
        return true;
    }
    prefix := format_text("{}.", identity);
    for (native in natives) {
        if (!native.source && strings.HasPrefix(native.name, prefix)) {
            return true;
        }
    }
    return false;
}

PackageNatives :: (natives: ResolvedNative[], identity: string) -> ResolvedNative[] {
    if (!strings.HasPrefix(identity, "host:")) {
        return natives;
    }
    prefix := format_text("{}.", identity);
    prefix_length := strings.ByteLength(prefix);
    scoped: ResolvedNative[] = [];
    for (item in natives) {
        native := item;
        if (!native.source && strings.HasPrefix(native.name, prefix)) {
            native.name = strings.Slice(native.name, prefix_length, strings.ByteLength(native.name) - prefix_length);
        }
        scoped.append(native);
    }
    return scoped;
}
// A native port. Storage 0 is a type the call infers, one type for every such
// port of the native; AnyPort takes each argument's own type, and
// UnsupportedPort is a type this compiler cannot pass.
pub Port :: struct {
    name: string;
    storage: int;
    container: int;
    c_string: bool;
}
// Rich game ports preserve nominal identity and actual native defaults. The
// game wrapper resolves nominal types before any body is emitted; unsupported
// defaults reject only calls that omit that parameter.
pub CatalogPort :: struct {
    name: string;
    storage: int;
    container: int;
    c_string: bool;
    nominal: u64;
    has_default: bool;
    default_owner: bool;
    default_supported: bool;
    default_bits: u64;
    default_text: string;
}
ResolvedPort :: struct {
    name: string;
    storage: int;
    container: int;
    c_string: bool;
    record: int;
    has_default: bool;
    default_owner: bool;
    default_supported: bool;
    default_bits: u64;
    default_text: string;
}
LegacyPorts :: (ports: Port[]) -> ResolvedPort[] {
    resolved: ResolvedPort[] = [];
    for (port in ports) {
        row: ResolvedPort = {name: port.name, storage: port.storage, container: port.container,
                             c_string: port.c_string, record: -1, has_default: false, default_owner: false,
                             default_supported: false, default_bits: 0, default_text: ""};
        resolved.append(row);
    }
    return resolved;
}
// The natives the sources declare with foreign blocks, appended to the target's
// own so calls resolve through the ordinary native path. A foreign function is
// a native whose identity names its library and symbol; a target that does not
// link that library has no such native, so a program that calls it cannot be
// loaded there. Parameters and the result are integers, floats, bool or
// rawptr, an opaque 64-bit word.
ForeignRows :: union {
    Failed(diagnostic: syntax.Diagnostic) |
    Declared(natives: ResolvedNative[], ports: ResolvedPort[], identities: u64[], effects: int[])
}
// The type `node` spells as a native port storage, 0 when a foreign signature
// may not use it. A function type is the address it holds, a word, and a
// cstring is a string the call copies, with its NUL, for the callee to read.
ForeignStorage :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    if (GenericCallableType(forest, node) >= 0) {
        return WordStorage;
    }
    spelled := Text(forest, text, node);
    if (spelled == "rawptr") {
        return WordStorage;
    }
    if (spelled == "cstring") {
        return TextStorage;
    }
    storage := ScalarStorage(spelled);
    if (storage == 0 || storage == TextStorage) {
        return 0;
    }
    return storage;
}
// The element storage of the type `node` when it spells `T[]` for a number `T`,
// 0 otherwise. A foreign parameter of this type is the pointer to the
// array's elements, which the callee may write; the length is a parameter of
// its own, as in C.
ForeignArray :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    if (node < 0 || !Is(forest, node, syntax.Type) || Field(forest, node, syntax.FieldName) < 0 || HasToken(forest, node, tk.Question) ||
        Field(forest, node, syntax.FieldTrait) >= 0) {
        return 0;
    }
    brackets: int = 0;
    child := forest[node].first_child;
    while (child >= 0) {
        if (!forest[child].is_extra && forest[child].kind == tk.OpenBracket) {
            brackets += 1;
        }
        child = forest[child].next_sibling;
    }
    storage := ScalarStorage(Text(forest, text, Field(forest, node, syntax.FieldName)));
    if (brackets != 1 || (!Integer(storage) && !Floating(storage))) {
        return 0;
    }
    return storage;
}
// The type `node` spells as a foreign result, 0 when it may not: a cstring
// names bytes the callee owns, which no value here can hold.
ForeignResultStorage :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    storage := ForeignStorage(forest, text, node);
    if (storage == TextStorage) {
        return 0;
    }
    return storage;
}
// The storages of procedure type `proc`: its parameters, then its result, 0
// when it has none. A part a foreign signature may not use is -1.
ProcShape :: (forest: snapshot.SnapshotNode[], text: string, proc: int) -> int[] {
    shape: int[] = [];
    for (parameter in Members(forest, Field(forest, proc, syntax.FieldParameters))) {
        storage := -1;
        kind := Field(forest, parameter, syntax.FieldType);
        if (kind >= 0 && ForeignStorage(forest, text, kind) != 0) {
            storage = ForeignStorage(forest, text, kind);
        }
        shape.append(storage);
    }
    result := Field(forest, proc, syntax.FieldResults);
    storage := 0;
    if (result >= 0) {
        storage = ForeignResultStorage(forest, text, result);
        if (storage == 0) {
            storage = -1;
        }
    }
    shape.append(storage);
    return shape;
}
// The name of the native that calls through an address of procedure type
// `proc`, "" when the type is not one a foreign signature can spell. Its first
// parameter is the address.
ProcName :: (forest: snapshot.SnapshotNode[], text: string, proc: int) -> string {
    shape := ProcShape(forest, text, proc);
    name := "proc:";
    for (storage in shape) {
        if (storage < 0) {
            return "";
        }
        name = format_text("{}{},", name, storage);
    }
    return name;
}
// Whether the function type `callable` holds a runtime address: it types a local
// or a foreign function's parameter or result, or sits inside such a type. A
// function type that types an authored function's parameter is a callback the
// compiler specializes, and holds none.
RuntimeCallable :: (forest: snapshot.SnapshotNode[], callable: int) -> bool {
    typed := forest[callable].parent;
    owner := forest[typed].parent;
    if (owner < 0) {
        return false;
    }
    if (Is(forest, owner, syntax.LocalDeclaration) || Is(forest, owner, syntax.ForeignFunction)) {
        return true;
    }
    if (!Is(forest, owner, syntax.Parameter)) {
        return false;
    }
    declaration := forest[forest[owner].parent].parent;
    if (Is(forest, declaration, syntax.CallableType)) {
        return RuntimeCallable(forest, declaration);
    }
    return Is(forest, declaration, syntax.ForeignFunction);
}
// The function type of the variable `callee` names, -1 when it holds none: the
// type its declaration spells, or the result type of the foreign function its
// initializer calls.
ProcOf :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], callee: int) -> int {
    found := Lookup(names, Text(forest, text, callee));
    if (found < 0 || names[found].storage != WordStorage || names[found].container != 0 || names[found].node < 0) {
        return -1;
    }
    declaration := forest[names[found].node].parent;
    declared := Field(forest, declaration, syntax.FieldType);
    if (declared >= 0) {
        return GenericCallableType(forest, declared);
    }
    value := Field(forest, declaration, syntax.FieldValue);
    if (value < 0 || !Is(forest, Unparenthesized(forest, value), syntax.CallExpression)) {
        return -1;
    }
    function := ScalarForeignDeclaration(forest, text, Unparenthesized(forest, value));
    if (function < 0 || Field(forest, function, syntax.FieldResults) < 0) {
        return -1;
    }
    return GenericCallableType(forest, Field(forest, function, syntax.FieldResults));
}
ForeignNatives :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], natives: ResolvedNative[],
                   ports: ResolvedPort[], identities: u64[], effects: int[]) -> ForeignRows {
    for (file in 0..<length(documents)) {
        text := documents[file].text;
        libraries: string[] = [];
        paths: string[] = [];
        member := FirstMember(forest, documents[file].syntax_root);
        while (member >= 0) {
            if (Is(forest, member, syntax.ForeignImportDeclaration)) {
                spelled := Text(forest, text, Field(forest, member, syntax.FieldPath));
                if (strings.ByteLength(spelled) < 2 || strings.Contains(spelled, "\\")) {
                    return ForeignRows.Failed(Diagnose(forest, member, file, "A foreign library path is a plain string"));
                }
                libraries.append(Text(forest, text, Field(forest, member, syntax.FieldAlias)));
                paths.append(strings.Slice(spelled, 1, strings.ByteLength(spelled) - 2));
            } else if (Is(forest, member, syntax.ForeignBlock)) {
                alias := "";
                path: string = "";
                // A block with no library declares symbols of the program's own objects.
                known := Field(forest, member, syntax.FieldLibrary) < 0;
                if (!known) {
                    alias = Text(forest, text, Field(forest, member, syntax.FieldLibrary));
                }
                for (index in 0..<length(libraries)) {
                    if (libraries[index] == alias) {
                        path = paths[index];
                        known = true;
                    }
                }
                if (!known) {
                    return ForeignRows.Failed(Diagnose(forest, Field(forest, member, syntax.FieldLibrary), file,
                                                       format_text("No foreign import named '{}'", alias)));
                }
                for (declaration in Members(forest, member)) {
                    if (!Is(forest, declaration, syntax.ForeignFunction)) {
                        continue;
                    }
                    name := Text(forest, text, Field(forest, declaration, syntax.FieldName));
                    for (native in natives) {
                        if (native.name == name) {
                            return ForeignRows.Failed(Diagnose(forest, declaration, file,
                                                               format_text("Duplicate declaration '{}'", name)));
                        }
                    }
                    first := length(ports);
                    signature := "";
                    parameters: int = 0;
                    for (parameter in Members(forest, Field(forest, declaration, syntax.FieldParameters))) {
                        kind := Field(forest, parameter, syntax.FieldType);
                        storage := 0;
                        container := 0;
                        marker := "";
                        if (kind >= 0) {
                            storage = ForeignStorage(forest, text, kind);
                            if (ForeignArray(forest, text, kind) != 0) {
                                storage = ForeignArray(forest, text, kind);
                                container = ArrayContainer;
                                marker = "[]";
                            }
                        }
                        if (storage == 0) {
                            return ForeignRows.Failed(Diagnose(forest, parameter, file,
                                                               "A foreign parameter is an integer, float, bool, rawptr, cstring, function type or array of numbers"));
                        }
                        port: ResolvedPort = {name: Text(forest, text, Field(forest, parameter, syntax.FieldName)),
                                              storage: storage, container: container, c_string: false, record: -1,
                                              has_default: false, default_owner: false, default_supported: false,
                                              default_bits: 0, default_text: ""};
                        ports.append(port);
                        signature = format_text("{}{}{},", signature, storage, marker);
                        parameters += 1;
                    }
                    results: int = 0;
                    result := Field(forest, declaration, syntax.FieldResults);
                    if (result >= 0) {
                        storage := ForeignResultStorage(forest, text, result);
                        if (storage == 0) {
                            return ForeignRows.Failed(Diagnose(forest, result, file,
                                                               "A foreign result is an integer, float, bool, rawptr or function type"));
                        }
                        output: ResolvedPort = {name: "Result", storage: storage, container: 0, c_string: false,
                                                record: -1, has_default: false, default_owner: false,
                                                default_supported: false, default_bits: 0, default_text: ""};
                        ports.append(output);
                        signature = format_text("{}->{}", signature, storage);
                        results = 1;
                    }
                    row: ResolvedNative = {name: name, first: first, parameters: parameters, results: results,
                                           variadic: false, direct: true, qualified_name: name,
                                           kind: NativeFunctionKind, intrinsic: 0,
                                           effects: ReadEffect | WriteEffect, source: false};
                    natives.append(row);
                    identities.append(binding.ID("foreign", format_text("{}:{}", path, name)));
                    identities.append(binding.ID("foreign-signature", signature));
                    effects.append(ReadEffect | WriteEffect);
                }
            }
            member = NextMember(forest, member);
        }
        // Calling through a procedure value is the native of its signature, the
        // address first.
        pending: int[] = [documents[file].syntax_root];
        top: int = 1;
        while (top > 0) {
            top -= 1;
            node := pending[top];
            kind := forest[node].kind;
            if (kind == syntax.CallableType && !RuntimeCallable(forest, node)) {
                continue;
            }
            child := forest[node].first_child;
            while (child >= 0 && !Expression(kind)) {
                if (forest[child].is_named && !forest[child].is_extra) {
                    if (top < length(pending)) {
                        pending[top] = child;
                    } else {
                        pending.append(child);
                    }
                    top += 1;
                }
                child = forest[child].next_sibling;
            }
            if (kind != syntax.CallableType) {
                continue;
            }
            name := ProcName(forest, text, node);
            if (name == "") {
                return ForeignRows.Failed(Diagnose(forest, node, file,
                                                   "A function type's parameters and result are integers, floats, bool, rawptr, cstring or function types"));
            }
            declared := false;
            for (native in natives) {
                declared = declared || native.name == name;
            }
            if (declared) {
                continue;
            }
            shape := ProcShape(forest, text, node);
            first := length(ports);
            callee: ResolvedPort = {name: "callee", storage: WordStorage, container: 0, c_string: false, record: -1,
                                    has_default: false, default_owner: false, default_supported: false,
                                    default_bits: 0, default_text: ""};
            ports.append(callee);
            results: int = 0;
            for (index in 0..<length(shape)) {
                port: ResolvedPort = {name: "Result", storage: shape[index], container: 0, c_string: false,
                                      record: -1, has_default: false, default_owner: false,
                                      default_supported: false, default_bits: 0, default_text: ""};
                if (index == length(shape) - 1) {
                    if (shape[index] == 0) {
                        continue;
                    }
                    results = 1;
                } else {
                    port.name = format_text("argument{}", index);
                }
                ports.append(port);
            }
            row: ResolvedNative = {name: name, first: first, parameters: length(shape), results: results,
                                   variadic: false, direct: true, qualified_name: name,
                                   kind: NativeFunctionKind, intrinsic: 0,
                                   effects: ReadEffect | WriteEffect, source: false};
            natives.append(row);
            identities.append(binding.ID("foreign-indirect", name));
            identities.append(binding.ID("foreign-signature", name));
            effects.append(ReadEffect | WriteEffect);
        }
    }
    return ForeignRows.Declared(natives, ports, identities, effects);
}
NativeInputValid :: (natives: ResolvedNative[], ports: ResolvedPort[], identities: u64[], effects: int[]) -> bool {
    if (length(identities) != 2 * length(natives) || length(effects) != length(natives)) {
        return false;
    }
    for (effect in effects) {
        if (effect < 0 || effect > NativeEffectsMask) {
            return false;
        }
    }
    for (native in natives) {
        if (native.first < 0 || native.parameters < 0 || native.results < 0 || native.first > length(ports) ||
            native.parameters > length(ports) - native.first ||
            native.results > length(ports) - native.first - native.parameters) {
            return false;
        }
    }
    return true;
}
AnyPort: int : -2;
UnsupportedPort: int : -1;
// A declared type. A record's fields and a variant's payload are
// members[first, first + count); a union's variants are types[first, first +
// count), and each variant names its union as `parent`. A native type, one the
// game links, also has its storage, ID and layout, and a component its
// component ID, and a record or union its package-symbol ID. A map type
// `[K: V]` that a package spells has its key's storage and its value's type,
// and is named as stage zero names it.
TypeDecl :: struct {
    name: string;
    type_name: string;
    package: int;
    // The source declaration, or -1 for a native or synthesized type.
    node: int;
    kind: int;
    first: int;
    count: int;
    size: int;
    parent: int;
    storage: int;
    id: u64;
    layout: u64;
    component: u64;
    key: int;
    value_storage: int;
    value_container: int;
    value_record: int;
    error: bool;
}
// A record field, with its byte offset, or a variant's payload field. A
// native type's field may be read-only, a constant whose value is its name,
// or read by natives[read] when that is not -1, with `read_key` instead of
// the value when that is not "".
TypeMember :: struct {
    name: string;
    storage: int;
    container: int;
    record: int;
    offset: int;
    writable: bool;
    c_string: bool;
    constant: bool;
    read: int;
    read_key: string;
}
Result :: union {
    Rejected(diagnostic: syntax.Diagnostic) | Compiled(module: u64, bytes: u8[])
}
// Package assembly also returns the effects of its callables, so importers
// reuse their summaries without compiling a dependency's bodies again.
