                   ops.end, ops.add, ops.sub, ops.mul, ops.div, ops.mod, ops.neg, ops.bit_and, ops.bit_or,
                   ops.bit_xor, ops.bit_not, ops.shl, ops.shr, ops.lt, ops.le, ops.gt, ops.ge, ops.eq, ops.ne, ops.cast,
                   ops.select, ops.variable, ops.store, ops.store_value, ops.owner, ops.query_variable, ops.convert, ops.source_point,
                   ops.source_watch];
    for (op in used) {
        if (op < 0) {
            return false;
        }
    }
    return true;
}
// The storage of a scalar type, any of which a record field may hold: an
// integer, bool, string or rawptr; 0 for any other.
ScalarStorage :: (text: string) -> int {
    integer: int = Int8Storage;
    while (integer <= WordStorage) {
        if (text == TypeName(integer)) {
            return integer;
        }
        integer += 1;
    }
    if (text == "i32") {
        return IntStorage;
    }
    if (text == "bool") {
        return BoolStorage;
    }
    if (text == "string") {
        return TextStorage;
    }
    // An opaque 64-bit word, the C pointer a foreign function takes and gives.
    if (text == "rawptr") {
        return WordStorage;
    }
    if (text == "number" || text == "f32") {
        return FloatStorage;
    }
    if (text == "f64") {
        return DoubleStorage;
    }
    return 0;
}
CharIndex :: (types: TypeDecl[]) -> int {
    for declared, index in types {
        if (declared.kind == BuiltinScalarDecl && declared.id == binding.ID("type", "char")) {
            return index;
        }
    }
    return -1;
}
CharTypes :: (input: TypeDecl[]) -> TypeDecl[] {
    if (CharIndex(input) >= 0) { return input; }
    declared: TypeDecl = {name: "char", type_name: "char", package: -1, node: -1,
                          kind: BuiltinScalarDecl, first: 0, count: 0, size: 4, parent: -1,
                          storage: IntStorage, id: binding.ID("type", "char"), layout: 0,
                          component: 0, key: 0, value_storage: 0, value_container: 0, value_record: -1, error: false};
    return append(input, declared);
}
CharType :: (types: TypeDecl[], storage: int, container: int, record: int) -> bool {
    return storage == IntStorage && container == 0 && record >= 0 &&
           types[record].kind == BuiltinScalarDecl && types[record].id == binding.ID("type", "char");
}
// The record or union of `package` named `name`, -1 when none.
FindType :: (types: TypeDecl[], package: int, name: string) -> int {
    index: int = 0;
    while (index < length(types)) {
        if (types[index].package == package && types[index].kind != VariantDecl &&
            types[index].kind != BuiltinScalarDecl && types[index].name == name) {
            return index;
        }
        index += 1;
    }
    // Game-native types are shared by every executable source.
    index = 0;
    while (index < length(types)) {
        if (types[index].package == -1 && types[index].kind != BuiltinScalarDecl && types[index].name == name) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// The constant of `package` named `name`, -1 when none.
FindConstant :: (constants: ConstDecl[], package: int, name: string) -> int {
    index: int = 0;
    while (index < length(constants)) {
        if (constants[index].package == package && constants[index].name == name) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// The import aliases of file `file`, each a name for the package it imports,
// from the graph's bindings. They are the outermost names of its functions.
Aliases :: (links: graph.Binding[], file: int) -> Name[] {
    aliases: Name[] = [];
    for (link in links) {
        if (link.file == file) {
            alias: Name = {owned: false, name: link.name, place: AliasPlace, index: link.target, storage: 0, container: 0,
                           record: -1, writable: false, node: -1};
            if (link.import_index == -2) {
                alias.place = LibraryPlace;
            }
            aliases.append(alias);
        }
    }
    return aliases;
}
// The index of the type whose ID is `id`, -1 when none.
TypeWithId :: (types: TypeDecl[], id: u64) -> int {
    index: int = 0;
    while (index < length(types)) {
        if (types[index].id == id) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// The variant `name` of union types[of], -1 when none.
FindVariant :: (types: TypeDecl[], of: int, name: string) -> int {
    at := types[of].first;
    while (at < types[of].first + types[of].count) {
        if (types[at].name == name) {
            return at;
        }
        at += 1;
    }
    return -1;
}
// The type a `type` node names: a field type, a record or union of package
// `package` or, qualified by an alias in `names`, of an imported one, or an
// array of one; storage 0 for any other.
ReadType :: (forest: snapshot.SnapshotNode[], text: string, table: ^(TypeDecl[]), names: Name[], package: int,
             node: int) -> ValueType {
    none: ValueType = {storage: 0, container: 0, record: -1};
    view := HasTypeTrait(forest, text, node, "view");
    if (!Is(forest, node, syntax.Type) || !ViewTraits(forest, text, node) || Field(forest, node, syntax.FieldArguments) >= 0) {
        return none;
    }
    pointer := TypePointerNode(forest, node);
    if (pointer >= 0) {
        element := ReadType(forest, text, table, names, package, Field(forest, pointer, syntax.FieldTarget));
        if (CharType(table^, element.storage, element.container, element.record)) { return none; }
        declared := FindPointer(table^, element, false);
        if (declared < 0) {
            return none;
        }
        return ReadTypeSuffixes(forest, node, table, {storage: PointerStorage, container: 0, record: declared},
                                package, view);
    }
    grouped := TypeGroupNode(forest, node);
    if (grouped >= 0) {
        return ReadTypeSuffixes(forest, node, table, ReadType(forest, text, table, names, package, grouped),
                                package, view);
    }
    map := Field(forest, node, syntax.FieldMap);
    if (map >= 0) {
        key := ReadType(forest, text, table, names, package, Field(forest, map, syntax.FieldKey));
        value := ReadType(forest, text, table, names, package, Field(forest, map, syntax.FieldValue));
        if (CharType(table^, key.storage, key.container, key.record) ||
            CharType(table^, value.storage, value.container, value.record)) { return none; }
        declared := FindMap(table^, key, value);
        if (declared < 0) {
            return none;
        }
        return ReadTypeSuffixes(forest, node, table, {storage: UnionStorage, container: MapContainer, record: declared},
                                package, view);
    }
    callable := GenericCallableType(forest, node);
    if (callable >= 0) {
        if (ProcName(forest, text, callable) == "") {
            return none;
        }
        return ReadTypeSuffixes(forest, node, table, {storage: WordStorage, container: 0, record: -1}, package, view);
    }
    application := ApplicationNode(forest, node);
    if (application >= 0) {
        found := FindType(table^, package, ApplicationName(forest, text, table^, package, application));
        if (found < 0) {
            return none;
        }
        return ReadTypeSuffixes(forest, node, table, {storage: StructStorage, container: 0, record: found}, package, view);
    }
    first := FirstMember(forest, Field(forest, node, syntax.FieldName));
    if (first < 0) {
        return none;
    }
    name := Text(forest, text, first);
    home := package;
    part := NextMember(forest, first);
    if (part >= 0) {
        home = QualifierOf(forest, text, names, package, first);
        name = Text(forest, text, part);
        if (home < 0 || NextMember(forest, part) >= 0) {
            return none;
        }
    } else if (name == "char") {
        declared := CharIndex(table^);
        if (declared < 0) { return none; }
        return ReadTypeSuffixes(forest, node, table, {storage: IntStorage, container: 0, record: declared}, package, view);
    } else if (name == "rawptr") {
        // The opaque 64-bit word a foreign function takes or returns, also the
        // type of an authored function's parameter, result or local.
        return ReadTypeSuffixes(forest, node, table, {storage: WordStorage, container: 0, record: -1}, package, view);
    } else if (ScalarStorage(name) != 0) {
        return ReadTypeSuffixes(forest, node, table, {storage: ScalarStorage(name), container: 0, record: -1},
                                package, view);
    }
    if (part < 0) {
        bound := Lookup(names, name);
        if (bound >= 0 && names[bound].place == GenericTypePlace) {
            value := names[bound];
            return ReadTypeSuffixes(forest, node, table,
                                    {storage: value.storage, container: value.container, record: value.record}, package, view);
        }
    }
    declared := FindType(table^, home, name);
    if (declared < 0 || table^[declared].kind == TemplateDecl) {
        return none;
    }
    storage := StructStorage;
    if (table^[declared].kind == NativeDecl || table^[declared].kind == NamespaceDecl) {
        storage = table^[declared].storage;
    } else if (table^[declared].kind == UnionDecl) {
        storage = UnionStorage;
    }
    return ReadTypeSuffixes(forest, node, table, {storage: storage, container: 0, record: declared}, package, view);
}
// Whether the type `node` has the trait `trait`. Native signatures may
// repeat a trait, so look at every trait child.
HasTypeTrait :: (forest: snapshot.SnapshotNode[], text: string, node: int, trait: string) -> bool {
    if (node < 0) {
        return false;
    }
    child := forest[node].first_child;
    while (child >= 0) {
        if (forest[child].field == syntax.FieldTrait && Text(forest, text, child) == trait) {
            return true;
        }
        child = forest[child].next_sibling;
    }
    return false;
}
// Whether every trait of the type `node` is `view`, the only one ReadType
// reads.
ViewTraits :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> bool {
    if (node < 0) {
        return false;
    }
    child := forest[node].first_child;
    while (child >= 0) {
        if (forest[child].field == syntax.FieldTrait && Text(forest, text, child) != "view") {
            return false;
        }
        child = forest[child].next_sibling;
    }
    return true;
}
// Suffixes are applied in source order. int?[] holds optional integers;
// int[]? is an optional array. Pointer presence remains its own nullable flag.
ReadTypeSuffixes :: (forest: snapshot.SnapshotNode[], node: int, table: ^(TypeDecl[]), base: ValueType,
                     package: int, view: bool) -> ValueType {
    value := base;
    if (value.storage == 0) {
        return value;
    }
    child := forest[node].first_child;
    while (child >= 0) {
        token := forest[child].kind;
        if (CharType(table^, value.storage, value.container, value.record) && !forest[child].is_extra &&
            (token == tk.OpenBracket || token == tk.Question)) {
            return {storage: 0, container: 0, record: -1};
        }
        if (!forest[child].is_extra && token == tk.OpenBracket) {
            if (value.container != 0 || SequenceFlags(table^, value) != 0) {
                EnsureSequenceCollection(table, value, package);
            }
            value = SequenceArrayType(table^, value);
        } else if (!forest[child].is_extra && token == tk.Question) {
            if (value.storage == PointerStorage && value.container == 0) {
                element := PointerElement(table^, Typed(-1, value.storage, value.container, value.record));
                value.record = EnsurePointer(table, element, true, package);
            } else {
                optional := EnsureOptional(table, value, package);
                value = {storage: UnionStorage, container: 0, record: optional};
            }
        }
        child = forest[child].next_sibling;
    }
    if (view && CharType(table^, value.storage, value.container, value.record)) {
        return {storage: 0, container: 0, record: -1};
    }
    if (view) {
        return ReadViewType(table, value, package);
    }
    return value;
}
ReadViewType :: (table: ^(TypeDecl[]), value: ValueType, package: int) -> ValueType {
    element := OptionalElement(table^, Typed(-1, value.storage, value.container, value.record));
    if (element.storage != 0) {
        viewed := ReadViewType(table, element, package);
        if (viewed.storage == 0) {
            return viewed;
        }
        return {storage: UnionStorage, container: 0, record: EnsureOptional(table, viewed, package)};
    }
    if (value.container != ArrayContainer) {
        return {storage: 0, container: 0, record: -1};
    }
    return {storage: value.storage, container: ViewContainer, record: value.record};
}
// The map type keyed by `key` holding `value`, -1 when none is declared.
FindMap :: (types: TypeDecl[], key: ValueType, value: ValueType) -> int {
    index: int = 0;
    while (index < length(types)) {
        declared := types[index];
        if (declared.kind == MapDecl && declared.key == key.storage && declared.value_storage == value.storage &&
            declared.value_container == value.container && declared.value_record == value.record) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// The ID stage zero gives a single key or value type: its storage and the
// ID of the record, union or native type it names.
TypeTag :: (types: TypeDecl[], storage: int, record: int) -> u64 {
    return SemanticTag(types, {storage: storage, container: 0, record: record});
}
// Declares each map type that file `root` spells, inner ones first, when its
// key is a number, bool or string and its value a single value of a type
// this compiler supports. Stage zero names the map's collection type from
// both types.
DeclareMaps :: (forest: snapshot.SnapshotNode[], text: string, types: TypeDecl[], aliases: Name[], package: int,
                root: int) -> TypeDecl[] {
    // A depth-first walk that skips expressions, where no type is spelled,
    // so it visits a small part of the file.
    found: int[] = [];
    pending: int[] = [root];
    top: int = 1;
    while (top > 0) {
        top -= 1;
        node := pending[top];
        kind := forest[node].kind;
        if (kind == syntax.MapType) {
            found.append(node);
        }
        child := forest[node].first_child;
        while (child >= 0 && !Expression(kind)) {
            if (forest[child].is_named && !forest[child].is_extra) {
                if (top < length(pending)) {
                    pending[top] = child;
                } else {
                    pending.append(child);
                }
                top += 1;
            }
            child = forest[child].next_sibling;
        }
    }
    // Candidate map declarations belong to the returned table until accepted.
    known := types;
    at := length(found) - 1;
    while (at >= 0) {
        map := found[at];
        at -= 1;
        key := ReadType(forest, text, &known, aliases, package, Field(forest, map, syntax.FieldKey));
        value := ReadType(forest, text, &known, aliases, package, Field(forest, map, syntax.FieldValue));
        if (key.storage == 0 || key.container != 0 || key.record >= 0 || value.storage == 0 ||
            FindMap(known, key, value) >= 0) {
            continue;
        }
        id := binding.ID("collection-type", format_text("{}:{}:{}", MapContainer, OptionalTag(known, key),
                                                        OptionalTag(known, value)));
        declared: TypeDecl = {name: "", type_name: format_text("__collection_{}", id), package: package, node: -1, kind: MapDecl,
                              first: 0, count: 0, size: 0, parent: -1, storage: UnionStorage, id: id, layout: 0, component: 0,
                              key: key.storage, value_storage: value.storage, value_container: value.container,
                              value_record: value.record, error: false};
        known.append(declared);
    }
    return known;
}
// Field width, which is also its alignment, as the runtime lays records out.
FieldSize :: (storage: int, target: Target) -> int {
    if (storage == TextStorage || storage == PointerStorage) {
        return target.pointer_size;
    }
    if (Integer(storage)) {
        return Width(storage) / 8;
    }
    if (storage == FloatStorage) {
        return 4;
    }
    if (storage == DoubleStorage) {
        return 8;
    }
    return 1;
}
RecordFieldType :: (types: TypeDecl[], value: ValueType) -> bool {
    if (value.container != 0 && value.container != ArrayContainer) {
        return false;
    }
    if (value.storage == PointerStorage) {
        return value.record >= 0 && types[value.record].kind == PointerDecl;
    }
    if (value.storage == StructStorage) {
        return value.record >= 0 &&
               (types[value.record].kind == RecordDecl || types[value.record].kind == NativeDecl);
    }
    if (value.storage == UnionStorage) {
        return value.container == 0 && value.record >= 0 && types[value.record].kind == UnionDecl;
    }
    return value.record < 0 && (Integer(value.storage) || Floating(value.storage) ||
                                value.storage == BoolStorage || value.storage == TextStorage);
}
RecordFieldSize :: (field: TypeMember, types: TypeDecl[], target: Target) -> int {
    if (field.container == ArrayContainer) {
        return target.pointer_size;
    }
    if (field.storage == UnionStorage) {
        return target.pointer_size;
    }
    if (field.storage == StructStorage) {
        return types[field.record].size;
    }
    return FieldSize(field.storage, target);
}
// Matches the runtime's owned-layout preflight: descriptor and field visits
// are counted per expanded occurrence, with root duplicate-name comparisons.
RecordLayoutWorkLimit: int : 1048576;
AlignTo :: (size: int, alignment: int) -> int {
    rest := size % alignment;
    if (rest == 0) {
        return size;
    }
    return size + alignment - rest;
}
InputFailure :: (document: int, message: string) -> Result {
    diagnostic: syntax.Diagnostic = {start: 0, end: 0, line: 1, column: 1, document: document, message: message};
    return Result.Rejected(diagnostic);
}
AssemblyFailure :: (document: int, message: string) -> Assembly {
    diagnostic: syntax.Diagnostic = {start: 0, end: 0, line: 1, column: 1, document: document, message: message};
    return Assembly.Rejected(diagnostic);
}

// The declarations of a compile's active packages, dependencies first, with
// the order they were declared in and the imports and edges that bind: the
// file-level ones, and those of the `when` branches the active packages keep.
Active :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Declared(callables: Callable[], params: Param[], types: TypeDecl[], members: TypeMember[],
               constants: ConstDecl[], order: int[], links: graph.Binding[], edges: graph.Edge[])
}
// Every record, union and function of each active package, dependencies
// first, so a package's declarations follow those of every package it imports.
// The root and every project package are active, even when no other project
// package imports them, and so is what their bound imports reach; a
// collection package enters only through one. `order` is the graph's, over
// every import, which snapshot validation checks whole.
pub Declare :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], packages: graph.Package[],
                files_of: int[], order: int[], edges: graph.Edge[], root: int, imports: snapshot.ResolvedImport[],
                links: graph.Binding[], target: Target) -> Active {
    no_types: TypeDecl[] = [];
    no_members: TypeMember[] = [];
    return DeclareSeeded(forest, documents, packages, files_of, order, edges, root, imports, links, target, no_types,
                         no_members);
}
// Declare for packages that share the native types `seed_types` and their
// fields `seed_members`, which come first in the tables.
//
// An import inside a `when` branch binds only if the branch is kept. A
// package's conditions read its file-level imports, so once those are
// declared its branches are chosen, its kept imports bound and their packages
// made active, and it is declared after them. `order` puts every import's
// package first, so each sweep declares what is ready, and a package waits
// one sweep for each conditional import that activates a package before it;
// there are a few such imports, so a few sweeps.
DeclareSeeded :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], packages: graph.Package[],
                  files_of: int[], order: int[], edges: graph.Edge[], root: int,
                  imports: snapshot.ResolvedImport[], links: graph.Binding[], target: Target, seed_types: TypeDecl[],
                  seed_members: TypeMember[]) -> Active {
    callables: Callable[] = [];
    params: Param[] = [];
    types: TypeDecl[] = seed_types;
    members: TypeMember[] = seed_members;
    constants: ConstDecl[] = [];
    switch DeclareMath(forest, documents, types, members, target) {
        case .Failed(message):
            return Active.Failed({start: 0, end: 0, line: 1, column: 1, document: 0, message: message});
        case .Read(math_types, math_members):
            types = math_types;
            members = math_members;
    }
    count := length(packages);
    bound: graph.Binding[] = [];
    for (link in links) {
        if (!link.conditional) {
            bound.append(link);
        }
    }
    kept: graph.Edge[] = [];
    for (edge in edges) {
        if (!edge.conditional) {
            kept.append(edge);
        }
    }
    active := resize([false], count);
    chosen := resize([false], count);
    declared := resize([false], count);
    pending: int[] = [];
    for (package in 0..<count) {
        identity := documents[files_of[packages[package].member_start]].identity;
        // paths[0] still names the requested root, including a direct compile
        // of a collection package with no project package in its snapshot.
        if (package == root || strings.HasPrefix(identity, "project:")) {
            active[package] = true;
            pending.append(package);
        }
    }
    Activate(kept, &active, &pending);
    selected: int[] = [];
    progress := true;
    while (progress) {
        progress = false;
        for (package in order) {
            if (!active[package] || declared[package]) {
                continue;
            }
            files := slice(files_of, packages[package].member_start, packages[package].member_count);
            if (!chosen[package]) {
                if (!Ready(edges, declared, package, true)) {
                    continue;
                }
                switch KeptImports(forest, documents, files, package, bound, constants, imports) {
                    case .Failed(diagnostic):
                        return Active.Failed(diagnostic);
                    case .Kept(indices):
                        for (link in links) {
                            if (link.conditional && indices.contains(link.import_index)) {
                                for (other in bound) {
                                    if (other.file == link.file && other.name == link.name) {
                                        return Active.Failed(snapshot.Diagnostic(snapshot.ImportRange(imports[link.import_index]),
                                                                                 "Duplicate file-local import binding"));
                                    }
                                }
                                bound.append(link);
                            }
                        }
                        for (index in indices) {
                            to := PackageAt(packages, imports[index].directory);
                            edge: graph.Edge = {from: package, to: to, import_index: index, conditional: false};
                            kept.append(edge);
                            if (!active[to]) {
                                active[to] = true;
                                pending.append(to);
                            }
                        }
                        Activate(kept, &active, &pending);
                }
                chosen[package] = true;
                progress = true;
            }
            if (!Ready(kept, declared, package, false)) {
                continue;
            }
            switch DeclarePackage(forest, documents, files, package, packages[package].name, bound, target, callables,
                                  params, types, members, constants) {
                case .Failed(diagnostic):
                    return Active.Failed(diagnostic);
                case .Collected(more_callables, more_params, more_types, more_members, more_constants):
                    callables = more_callables;
                    params = more_params;
                    types = more_types;
                    members = more_members;
                    constants = more_constants;
            }
            // An import alias may not name a declaration of its package.
            for (link in bound) {
                if (Position(files, link.file) >= 0 &&
                    (FindType(types, package, link.name) >= 0 || FindCallable(callables, package, link.name) >= 0 ||
                     FindConstant(constants, package, link.name) >= 0)) {
                    return Active.Failed(snapshot.Diagnostic(snapshot.ImportRange(imports[link.import_index]),
                                                             "Package import alias conflicts with a package declaration"));
                }
            }
            declared[package] = true;
            selected.append(package);
            progress = true;
        }
    }
    // Every active package is declared: the graph has no cycle, so a sweep
    // that declares nothing has nothing waiting.
    for (package in order) {
        assert(!active[package] || declared[package], "an active package is declared");
    }
    return Active.Declared(callables, params, types, members, constants, selected, bound, kept);
}
// Marks active what the pending packages reach through `edges`, draining
// `pending`.
Activate :: (edges: graph.Edge[], active: ^(bool[]), pending: ^(int[])) {
    next: int = 0;
    while (next < length(pending^)) {
        from := pending^[next];
        for (edge in edges) {
            if (edge.from == from && !active^[edge.to]) {
                active^[edge.to] = true;
                pending.append(edge.to);
            }
        }
        next += 1;
    }
    pending^ = [];
}
// Whether every package `package` imports through `edges` is declared; with
// `certain`, only through file-level imports. A compile has tens of packages
// and a few hundred edges, so a sweep's checks are some thousands of steps.
Ready :: (edges: graph.Edge[], declared: bool[], package: int, certain: bool) -> bool {
    for (edge in edges) {
        if (edge.from == package && edge.to != package && (!certain || !edge.conditional) && !declared[edge.to]) {
            return false;
        }
    }
    return true;
}
// The package whose files are in `directory`.
PackageAt :: (packages: graph.Package[], directory: string) -> int {
    for (index in 0..<length(packages)) {
        if (packages[index].directory == directory) {
            return index;
        }
    }
    assert(false, "an import names a package of the graph");
    return -1;
}
Kept :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Kept(indices: int[])
}
// The conditional imports of the package's files that the branches its
// conditions select hold, by their index in `imports`.
KeptImports :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], files: int[], package: int,
                links: graph.Binding[], constants: ConstDecl[], imports: snapshot.ResolvedImport[]) -> Kept {
    indices: int[] = [];
    for (file in files) {
        document := documents[file];
        conditional := false;
        for (index in document.first_import..<document.first_import + document.import_count) {
            conditional = conditional || imports[index].conditional;
        }
        if (!conditional) {
            continue;
        }
        switch SelectMembers(forest, documents, links, constants, package, file) {
            case .Failed(diagnostic):
                return Kept.Failed(diagnostic);
            case .Chosen(nodes):
                for (node in nodes) {
                    if (!Is(forest, node, syntax.ImportDeclaration)) {
                        continue;
                    }
                    for (index in document.first_import..<document.first_import + document.import_count) {
                        if (imports[index].conditional && imports[index].range_start == forest[node].start) {
                            indices.append(index);
                        }
                    }
                }
        }
    }
    return Kept.Kept(indices);
}
// Package-scope `when`. A package's declarations are its file's members with
// each `when condition { ... } else { ... }` replaced by the members of the
// branch its constant condition selects, so `when target.Os == target.Darwin`
// can choose a constant or a function per platform. The condition reads
// literals and the constants of imported packages, which are folded before
// this package is declared.
Decided :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Waiting
    | Yes
    | No
}
Expanded :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Done
}
Selected :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Chosen(nodes: int[])
}
ComparisonOperator :: (operator: int) -> bool {
    return operator == tk.CmpEq || operator == tk.NotEq || operator == tk.Lt || operator == tk.LtEq || operator == tk.Gt ||
           operator == tk.GtEq;
}
FoldCondition :: (forest: snapshot.SnapshotNode[], text: string, file: int, constants: ConstDecl[], aliases: Name[],
                  package: int, node: int) -> Decided {
    value := Unparenthesized(forest, node);
    if (Is(forest, value, syntax.Boolean)) {
        if (Text(forest, text, value) == "true") {
            return Decided.Yes;
        }
        return Decided.No;
    }
    named := ConstantOf(forest, text, constants, aliases, package, value);
    if (named >= 0 && constants[named].storage == BoolStorage) {
        if (!constants[named].folded) {
            return Decided.Waiting;
        }
        if (constants[named].bits != 0) {
            return Decided.Yes;
        }
        return Decided.No;
    }
    operator := Operator(forest, value);
    // `not (condition)` reads as a call of `not`, as the grammar keeps both.
    negated := Is(forest, value, syntax.CallExpression) && Text(forest, text, Field(forest, value, syntax.FieldFunction)) == "not";
    operand := Field(forest, value, syntax.FieldOperand);
    if (negated) {
        operand = FirstMember(forest, Field(forest, value, syntax.FieldArguments));
    }
    if (negated || (Is(forest, value, syntax.UnaryExpression) && (operator == tk.NotKeyword || operator == tk.Not))) {
        switch FoldCondition(forest, text, file, constants, aliases, package, operand) {
            case .Failed(diagnostic):
                return Decided.Failed(diagnostic);
            case .Waiting:
                return Decided.Waiting;
            case .Yes:
                return Decided.No;
            case .No:
                return Decided.Yes;
        }
    }
    if (!Is(forest, value, syntax.BinaryExpression)) {
        return Decided.Failed(Diagnose(forest, node, file, "a when condition must be constant"));
    }
    if (operator == tk.AndKeyword || operator == tk.CmpAnd || operator == tk.OrKeyword || operator == tk.CmpOr) {
        conjunction := operator == tk.AndKeyword || operator == tk.CmpAnd;
        switch FoldCondition(forest, text, file, constants, aliases, package, Field(forest, value, syntax.FieldLeft)) {
            case .Failed(diagnostic):
                return Decided.Failed(diagnostic);
            case .Waiting:
                return Decided.Waiting;
            case .Yes:
                if (!conjunction) {
                    return Decided.Yes;
                }
            case .No:
                if (conjunction) {
                    return Decided.No;
                }
        }
        return FoldCondition(forest, text, file, constants, aliases, package, Field(forest, value, syntax.FieldRight));
    }
    if (!ComparisonOperator(operator)) {
        return Decided.Failed(Diagnose(forest, node, file, "a when condition must be constant"));
    }
    left: u64 = 0;
    switch FoldConstant(forest, text, file, constants, aliases, package, Field(forest, value, syntax.FieldLeft), IntStorage) {
        case .Failed(diagnostic):
            return Decided.Failed(diagnostic);
        case .Waiting:
            return Decided.Waiting;
        case .Folded(bits):
            left = bits;
    }
    right: u64 = 0;
    switch FoldConstant(forest, text, file, constants, aliases, package, Field(forest, value, syntax.FieldRight), IntStorage) {
        case .Failed(diagnostic):
            return Decided.Failed(diagnostic);
        case .Waiting:
            return Decided.Waiting;
        case .Folded(bits):
            right = bits;
    }
    same := left == right;
    ordered := i64(wrap: left) < i64(wrap: right);
    taken := false;
    if (operator == tk.CmpEq) {
        taken = same;
    } else if (operator == tk.NotEq) {
        taken = !same;
    } else if (operator == tk.Lt) {
        taken = ordered;
    } else if (operator == tk.LtEq) {
        taken = ordered || same;
    } else if (operator == tk.Gt) {
        taken = !ordered && !same;
    } else {
        taken = !ordered;
    }
    if (taken) {
        return Decided.Yes;
    }
    return Decided.No;
}
// Appends `members` to `out`, a `when` replaced by the branch it selects.
ExpandMembers :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], links: graph.Binding[],
                  constants: ConstDecl[], package: int, file: int, members: int[], out: ^(int[])) -> Expanded {
    for (member in members) {
        if (!Is(forest, member, syntax.WhenDeclaration)) {
            out.append(member);
            continue;
        }
        selected: int[] = [];
        switch FoldCondition(forest, documents[file].text, file, constants, Aliases(links, file), package,
                             Field(forest, member, syntax.FieldCondition)) {
            case .Failed(diagnostic):
                return Expanded.Failed(diagnostic);
            case .Waiting:
                return Expanded.Failed(Diagnose(forest, Field(forest, member, syntax.FieldCondition), file,
                                                "a when condition may name only literals and imported constants"));
            case .Yes:
                selected = Members(forest, Field(forest, member, syntax.FieldConsequence));
            case .No:
                alternative := Field(forest, member, syntax.FieldAlternative);
                if (Is(forest, alternative, syntax.WhenDeclaration)) {
                    selected = [alternative];
                } else if (alternative >= 0) {
                    selected = Members(forest, alternative);
                }
        }
        switch ExpandMembers(forest, documents, links, constants, package, file, selected, out) {
            case .Failed(diagnostic):
                return Expanded.Failed(diagnostic);
            case .Done:
                continue;
        }
    }
    return Expanded.Done;
}
SelectMembers :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], links: graph.Binding[],
                  constants: ConstDecl[], package: int, file: int) -> Selected {
    nodes: int[] = [];
    switch ExpandMembers(forest, documents, links, constants, package, file,
                         Members(forest, documents[file].syntax_root), &nodes) {
        case .Failed(diagnostic):
            return Selected.Failed(diagnostic);
        case .Done:
            return Selected.Chosen(nodes);
    }
}
// The members of `file` that SelectMembers chose, from the lists of all files.
ChosenMembers :: (nodes: int[], starts: int[], counts: int[], files: int[], file: int) -> int[] {
    index: int = 0;
    while (index < length(files)) {
        if (files[index] == file) {
            return slice(nodes, starts[index], counts[index]);
        }
        index += 1;
    }
    return [];
}
ChosenAt :: (chosen: int[], at: int) -> int {
    if (at < length(chosen)) {
        return chosen[at];
    }
    return -1;
}
// Adds package `package`'s records, unions, functions and constants, in file
// and source order. Types come first, so any signature or payload may name any
// type.
pub DeclarePackage :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], files: int[],
                       package: int, package_name: string, links: graph.Binding[], target: Target,
                       callables: Callable[], params: Param[], types: TypeDecl[],
                       members: TypeMember[], constants: ConstDecl[]) -> Declarations {
    types = CharTypes(types);
    selected: int[] = [];
    selected_starts: int[] = [];
    selected_counts: int[] = [];
    for (file in files) {
        switch SelectMembers(forest, documents, links, constants, package, file) {
            case .Failed(diagnostic):
                return Declarations.Failed(diagnostic);
            case .Chosen(nodes):
                selected_starts.append(length(selected));
                selected_counts.append(length(nodes));
                selected.extend(nodes);
        }
    }
    for (file in files) {
        text := documents[file].text;
        chosen := ChosenMembers(selected, selected_starts, selected_counts, files, file);
        chosen_at: int = 0;
        member := ChosenAt(chosen, chosen_at);
        while (member >= 0) {
            record := Is(forest, member, syntax.RecordDeclaration);
            if (record || Is(forest, member, syntax.UnionDeclaration)) {
                attributes := DeclarationAttributes(forest, text, file, member, "error");
                if length(attributes) > 0 {
                    return Declarations.Failed(attributes[0]);
                }
                name := Text(forest, text, Field(forest, member, syntax.FieldName));
                if (name == "") {
                    return Declarations.Failed(Diagnose(forest, Field(forest, member, syntax.FieldName), file, "Invalid string or embedded NUL"));
                }
                if (FindType(types, package, name) >= 0) {
                    return Declarations.Failed(Diagnose(forest, member, file, format_text("Duplicate declaration '{}'", name)));
                }
                if (record && Field(forest, member, syntax.FieldParameters) >= 0) {
                    // A template has no values of its own: its applications are records.
                    template: TypeDecl = {name: name, type_name: format_text("{}.{}", package_name, name), package: package,
                                          node: member, kind: TemplateDecl, first: 0, count: 0, size: 0, parent: -1,
                                          storage: 0,
                                          id: binding.ID("package-symbol", format_text("{}:{}:{}", documents[files[0]].identity,
                                                                                       TypeKind, name)),
                                          layout: 0, component: 0, key: 0, value_storage: 0, value_container: 0,
                                          value_record: -1, error: false};
                    types.append(template);
                    chosen_at += 1;
            member = ChosenAt(chosen, chosen_at);
                    continue;
                }
                declared: TypeDecl = {name: name, type_name: format_text("{}.{}", package_name, name), package: package,
                                      node: member,
                                      kind: RecordDecl, first: length(members), count: 0, size: 0, parent: -1,
                                      storage: 0,
                                      id: binding.ID("package-symbol", format_text("{}:{}:{}", documents[files[0]].identity,
                                                                                   TypeKind, name)),
                                      layout: 0, component: 0, key: 0, value_storage: 0,
                                      value_container: 0, value_record: -1, error: ErrorMarked(forest, text, member)};
                if (!record) {
                    // Variants follow their union; their payloads resolve below.
                    declared.kind = UnionDecl;
                    declared.first = length(types) + 1;
                    holder := length(types);
                    types.append(declared);
                    variant := FirstMember(forest, member);
                    while (variant >= 0) {
                        if (Is(forest, variant, syntax.UnionVariant)) {
                            if (Field(forest, variant, syntax.FieldLiteral) >= 0) {
                                return Declarations.Failed(Diagnose(forest, variant, file,
                                                                    "literal union alternatives are not supported yet"));
                            }
                            variant_name := Text(forest, text, Field(forest, variant, syntax.FieldName));
                            if (FindVariant(types, holder, variant_name) >= 0) {
                                return Declarations.Failed(Diagnose(forest, variant, file,
                                                                    format_text("Duplicate union alternative '{}'", variant_name)));
                            }
                            alternative: TypeDecl = {name: variant_name, type_name: "", package: package, node: member,
                                                     kind: VariantDecl, first: 0, count: 0, size: 0, parent: holder,
                                                     storage: 0, id: 0, layout: 0, component: 0, key: 0, value_storage: 0,
                                                     value_container: 0, value_record: -1, error: false};
                            types.append(alternative);
                            grown := types[holder];
                            grown.count += 1;
                            types[holder] = grown;
                        }
                        variant = NextMember(forest, variant);
                    }
                } else {
                    item := FirstMember(forest, Field(forest, member, syntax.FieldBody));
                    while (item >= 0) {
                        field_name := Text(forest, text, Field(forest, item, syntax.FieldName));
                        if (field_name == "") {
                            return Declarations.Failed(Diagnose(forest, Field(forest, item, syntax.FieldName), file, "Invalid string or embedded NUL"));
                        }
                        pointer_field := TypePointerNode(forest, Field(forest, item, syntax.FieldType)) >= 0;
                        initial := Field(forest, item, syntax.FieldValue);
                        nullable_pointer := pointer_field && HasToken(forest, Field(forest, item, syntax.FieldType), tk.Question);
                        if (initial >= 0 && !(nullable_pointer && Is(forest, initial, syntax.Nil))) {
                            return Declarations.Failed(Diagnose(forest, item, file,
                                                                "record field defaults require a nullable pointer and nil"));
                        }
                        at := declared.first;
                        while (at < length(members)) {
                            if (members[at].name == field_name) {
                                return Declarations.Failed(Diagnose(forest, item, file,
                                                                    format_text("Duplicate field '{}'", field_name)));
                            }
                            at += 1;
                        }
                        // Names are published before their field types resolve, so
                        // a field may name a later record in the package.
                        field: TypeMember = {name: field_name, storage: 0, container: 0, record: -1, offset: 0,
                                             writable: true, c_string: false, constant: false, read: -1, read_key: ""};
                        members.append(field);
                        item = NextMember(forest, item);
                    }
                    if (length(members) == declared.first) {
                        return Declarations.Failed(Diagnose(forest, member, file, "record needs a field"));
                    }
                    declared.count = length(members) - declared.first;
                    types.append(declared);
                }
            }
            chosen_at += 1;
            member = ChosenAt(chosen, chosen_at);
        }
    }
    instance_records: int[] = [];
    instance_files: int[] = [];
    instance_starts: int[] = [];
    instance_counts: int[] = [];
    instance_bound: Name[] = [];
    switch InstantiateRecords(forest, documents, files, package, package_name, documents[files[0]].identity, types, members) {
        case .Failed(diagnostic):
            return Declarations.Failed(diagnostic);
        case .Collected(more_types, more_members, records, record_files, starts, counts, bound):
            types = more_types;
            members = more_members;
            instance_records = records;
            instance_files = record_files;
            instance_starts = starts;
            instance_counts = counts;
            instance_bound = bound;
    }
    for (file in files) {
        types = DeclarePointers(forest, documents[file].text, types, Aliases(links, file), package, documents[file].syntax_root);
        types = DeclareMaps(forest, documents[file].text, types, Aliases(links, file), package, documents[file].syntax_root);
        types = DeclarePointers(forest, documents[file].text, types, Aliases(links, file), package, documents[file].syntax_root);
    }
    // Resolve nested collection spellings from their element types outwards.
    // Each source bracket/map can introduce at most one dependency level.
    depth: int = 0;
    for (syntax_node in forest) {
        if (syntax_node.kind == syntax.Type) {
            brackets: int = 0;
            child := syntax_node.first_child;
            while (child >= 0) {
                if (!forest[child].is_extra && forest[child].kind == tk.OpenBracket) {
                    brackets += 1;
                }
                child = forest[child].next_sibling;
            }
            if (brackets > depth) {
                depth = brackets;
            }

        }
    }
    passes: int = 0;
    changed := true;
    while (changed && passes <= length(forest)) {
        before := length(types);
        types = DeclareSequenceCollections(types, depth, package);
        types = DeclareSequenceOptionals(types, package);
        for (file in files) {
            types = DeclarePointers(forest, documents[file].text, types, Aliases(links, file), package, documents[file].syntax_root);
            types = DeclareMaps(forest, documents[file].text, types, Aliases(links, file), package, documents[file].syntax_root);
        }
        changed = length(types) != before;
        passes += 1;
    }
    // An address points to any declared type, so its pointers are added once
    // the other types stop changing; adding them inside the loop would add
    // a pointer to every new pointer and optional on each pass.
    addresses := false;
    for (file in files) {
        switch DeclareAddressPointers(forest, documents[file].text, types, Aliases(links, file), package,
                                      documents[file].syntax_root) {
            case .Declared(more_types, file_addresses):
                types = more_types;
                addresses = addresses || file_addresses;
        }
    }
    if (addresses) {
        types = DeclareUniversePointers(types, package);
    }
    types = DeclareSequenceOptionals(types, package);
    // Resolve every field after names and type constructors exist. Pointer
    // links carry identity but do not participate in inline layout cycles.
    for (file in files) {
        for (declaration in ChosenMembers(selected, selected_starts, selected_counts, files, file)) {
            if (!Is(forest, declaration, syntax.RecordDeclaration) || Field(forest, declaration, syntax.FieldParameters) >= 0) {
                continue;
            }
            holder := FindType(types, package, Text(forest, documents[file].text, Field(forest, declaration, syntax.FieldName)));
            index := types[holder].first;
            for (field_node in Members(forest, Field(forest, declaration, syntax.FieldBody))) {
                hidden := PrivateType(forest, documents[file].text, types, Aliases(links, file), package,
                                      Field(forest, field_node, syntax.FieldType));
                if (hidden >= 0) {
                    return Declarations.Failed(Diagnose(forest, hidden, file,
                                                        PrivateMessage(Text(forest, documents[file].text, hidden))));
                }
                resolved := ReadType(forest, documents[file].text, &types, Aliases(links, file), package,
                                     Field(forest, field_node, syntax.FieldType));
                if (!RecordFieldType(types, resolved)) {
                    return Declarations.Failed(Diagnose(forest, field_node, file,
                                                        "record fields require a scalar, pointer, record, union or array of those types"));
                }
                field := members[index];
                field.storage = resolved.storage;
                field.container = resolved.container;
                field.record = resolved.record;
                members[index] = field;
                index += 1;
            }
        }
    }
    // `a?.b` yields the optional of b's type, so a project that writes one
    // declares those optionals for the fields of its records.
    chained := false;
    for (syntax_node in forest) {
        chained = chained || syntax_node.kind == syntax.OptionalMemberExpression;
    }
    if (chained) {
        for (member in members) {
            if (member.container == 0 && member.storage != 0 && member.storage != PointerStorage && member.read < 0 &&
                !member.c_string && OptionalElement(types, Typed(-1, member.storage, member.container, member.record)).storage == 0) {
                EnsureOptional(&types, {storage: member.storage, container: member.container, record: member.record}, package);
            }
        }
    }
    switch ResolveInstances(forest, documents, links, package, types, members, instance_records, instance_files,
                            instance_starts, instance_counts, instance_bound) {
        case .Failed(diagnostic):
            return Declarations.Failed(diagnostic);
        case .Read(more_types, more_members):
            types = more_types;
            members = more_members;
    }
    // Each type is solved once. Child summaries prevent repeated references
    // from expanding recursively during size, alignment, depth and hash work.
    record_alignments: int[] = [];
    record_depths: int[] = [];
    record_work: int[] = [];
    record_needed: bool[] = [];
    pending_records: int[] = [];
    for (record_index in 0..<length(types)) {
        record_alignments.append(0);
        record_depths.append(0);
        record_work.append(0);
        needed := types[record_index].kind == RecordDecl;
        record_needed.append(needed);
        if (needed) {
            pending_records.append(record_index);
        }
    }
    // A native catalog may expose fields this compiler cannot read. Only
    // native layouts reached by authored fields need complete source facts.
    while (length(pending_records) > 0) {
        record_index := pending_records[length(pending_records) - 1];
        pending_records = slice(pending_records, 0, length(pending_records) - 1);
        declared := types[record_index];
        for (field_index in declared.first..<declared.first + declared.count) {
            field := members[field_index];
            if (field.storage == StructStorage && field.record >= 0 && field.record < length(types) &&
                !record_needed[field.record]) {
                record_needed[field.record] = true;
                pending_records.append(field.record);
            }
        }
    }
    unresolved := true;
    while (unresolved) {
        unresolved = false;
        progress := false;
        for (record_index in 0..<length(types)) {
            declared := types[record_index];
            if (!record_needed[record_index] || record_alignments[record_index] != 0) {
                continue;
            }
            ready := true;
            depth: int = 1;
            expanded_work := 1 + declared.count;
            overflow := declared.count >= RecordLayoutWorkLimit;
            for (field_index in declared.first..<declared.first + declared.count) {
                field := members[field_index];
                if (field.storage != StructStorage) {
                    continue;
                }
                if (field.record < 0 || field.record >= length(types) || record_alignments[field.record] == 0) {
                    ready = false;
                    continue;
                }
                child_depth := 1 + record_depths[field.record];
                if (child_depth > depth) {
                    depth = child_depth;
                }
                if (record_work[field.record] > RecordLayoutWorkLimit - expanded_work) {
                    overflow = true;
                } else {
                    expanded_work += record_work[field.record];
                }
            }
            if (!ready) {
                unresolved = true;
                continue;
            }
            comparisons := i64(declared.count) * i64(declared.count - 1) / 2;
            if (overflow || comparisons > i64(RecordLayoutWorkLimit - expanded_work) || depth > 16) {
                for (file in files) {
                    if (declared.node >= 0 && Ancestor(forest, documents[file].syntax_root, declared.node)) {
                        return Declarations.Failed(Diagnose(forest, declared.node, file,
                                                            "record value layout exceeds the supported metadata work or nesting limit"));
                    }
                }
                return Declarations.Failed({start: 0, end: 0, line: 1, column: 1, document: files[0],
                                            message: "record value layout exceeds the supported metadata work or nesting limit"});
            }
            size: int = 0;
            alignment: int = 1;
            for (field_index in declared.first..<declared.first + declared.count) {
                field := members[field_index];
                step := FieldSize(field.storage, target);
                if (field.container == ArrayContainer || field.storage == UnionStorage) {
                    step = target.pointer_size;
                } else if (field.storage == StructStorage) {
                    step = record_alignments[field.record];
                }
                size = AlignTo(size, step);
                if (declared.kind == RecordDecl) {
                    field.offset = size;
                    members[field_index] = field;
                }
                size += RecordFieldSize(field, types, target);
                if (step > alignment) {
                    alignment = step;
                }
            }
            if (declared.kind == RecordDecl) {
                declared.size = AlignTo(size, alignment);
                declared.layout = LayoutHash(declared, members, types, target);
                types[record_index] = declared;
            }
            record_alignments[record_index] = alignment;
            record_depths[record_index] = depth;
            record_work[record_index] = expanded_work;
            progress = true;
        }
        if (unresolved && !progress) {
            for (file in files) {
                for (declaration in ChosenMembers(selected, selected_starts, selected_counts, files, file)) {
                    if (Is(forest, declaration, syntax.RecordDeclaration) && Field(forest, declaration, syntax.FieldParameters) < 0) {
                        holder := FindType(types, package, Text(forest, documents[file].text,
                                                                Field(forest, declaration, syntax.FieldName)));
                        if (record_alignments[holder] == 0) {
                            return Declarations.Failed(Diagnose(forest, declaration, file,
                                                                "record has a recursive inline or array value layout; use a pointer for recursive links"));
                        }
                    }
                }
            }
            return Declarations.Failed({start: 0, end: 0, line: 1, column: 1, document: files[0],
                                        message: "record has a recursive inline or array value layout; use a pointer for recursive links"});
        }
    }
    // Payloads may name any type, so they resolve once every type is known.
    for (file in files) {
        text := documents[file].text;
        aliases := Aliases(links, file);
        chosen := ChosenMembers(selected, selected_starts, selected_counts, files, file);
        chosen_at: int = 0;
        member := ChosenAt(chosen, chosen_at);
        while (member >= 0) {
            if (Is(forest, member, syntax.UnionDeclaration)) {
                holder := FindType(types, package, Text(forest, text, Field(forest, member, syntax.FieldName)));
                variant := FirstMember(forest, member);
                while (variant >= 0) {
                    if (Is(forest, variant, syntax.UnionVariant)) {
                        at := FindVariant(types, holder, Text(forest, text, Field(forest, variant, syntax.FieldName)));
                        alternative := types[at];
                        alternative.first = length(members);
                        parameter := FirstMember(forest, Field(forest, variant, syntax.FieldParameters));
                        while (parameter >= 0) {
                            hidden := PrivateType(forest, text, types, aliases, package, Field(forest, parameter, syntax.FieldType));
                            if (hidden >= 0) {
                                return Declarations.Failed(Diagnose(forest, hidden, file,
                                                                    PrivateMessage(Text(forest, text, hidden))));
                            }
                            payload := ReadType(forest, text, &types, aliases, package, Field(forest, parameter, syntax.FieldType));
                            if (CharType(types, payload.storage, payload.container, payload.record)) {
                                return Declarations.Failed(Diagnose(forest, parameter, file, "char union payloads are not supported yet"));
                            }
                            if (payload.storage == 0) {
                                return Declarations.Failed(Diagnose(forest, parameter, file, "payload type is not supported yet"));
                            }
                            field: TypeMember = {name: Text(forest, text, Field(forest, parameter, syntax.FieldName)),
                                                 storage: payload.storage, container: payload.container, record: payload.record, offset: 0,
                                                 writable: true, c_string: false, constant: false, read: -1, read_key: ""};
                            members.append(field);
                            parameter = NextMember(forest, parameter);
                        }
                        alternative.count = length(members) - alternative.first;
                        types[at] = alternative;
                    }
                    variant = NextMember(forest, variant);
                }
            }
            chosen_at += 1;
            member = ChosenAt(chosen, chosen_at);
        }
    }
    // Which pointer parameters are scoped depends on the functions they are
    // passed to, in any file of the package, so the package decides it at once.
    declared_functions: int[] = [];
    declared_texts: string[] = [];
    for (file in files) {
        for (member in ChosenMembers(selected, selected_starts, selected_counts, files, file)) {
            if (Is(forest, member, syntax.FunctionDeclaration)) {
                declared_functions.append(member);
                declared_texts.append(documents[file].text);
            }
        }
    }
    scopes := ScopedParameters(forest, declared_texts, declared_functions);
    for (file in files) {
        text := documents[file].text;
        solid := SolidOffsets(text);
        aliases := Aliases(links, file);
        chosen := ChosenMembers(selected, selected_starts, selected_counts, files, file);
        chosen_at: int = 0;
        member := ChosenAt(chosen, chosen_at);
        while (member >= 0) {
            if (Is(forest, member, syntax.FunctionDeclaration)) {
                name := Text(forest, text, Field(forest, member, syntax.FieldName));
                if (name == "") {
                    return Declarations.Failed(Diagnose(forest, Field(forest, member, syntax.FieldName), file, "Invalid string or embedded NUL"));
                }
                // Types, functions and constants share the package scope.
                if (FindCallable(callables, package, name) >= 0 || FindType(types, package, name) >= 0 ||
                    FindConstant(constants, package, name) >= 0) {
                    return Declarations.Failed(Diagnose(forest, member, file, format_text("Duplicate declaration '{}'", name)));
                }
                if (GenericTemplate(forest, member)) {
                    template: Callable = {name: name, package: package, document: file, node: member, first: length(params),
                                          count: -1, result: 0, result_container: 0, result_record: -1, results: 0,
                                          waits: false, identity: 0, owner_package: package};
                    callables.append(template);
                    params.extend(GenericParameters(forest, text, member));
                    chosen_at += 1;
            member = ChosenAt(chosen, chosen_at);
                    continue;
                }
                switch FunctionSignature(forest, text, documents[file].key, solid, &types, aliases, package, file,
                                         member, name, length(params), scopes) {
                    case .Failed(diagnostic):
                        return Declarations.Failed(diagnostic);
                    case .Read(callable, added):
                        params.extend(added);
                        callables.append(callable);
                }
            } else if (Is(forest, member, syntax.ConstantDeclaration)) {
                name := Text(forest, text, Field(forest, member, syntax.FieldName));
                if (name == "") {
                    return Declarations.Failed(Diagnose(forest, Field(forest, member, syntax.FieldName), file, "Invalid string or embedded NUL"));
                }
                if (FindCallable(callables, package, name) >= 0 || FindType(types, package, name) >= 0 ||
                    FindConstant(constants, package, name) >= 0) {
                    return Declarations.Failed(Diagnose(forest, member, file, format_text("Duplicate declaration '{}'", name)));
                }
                // An untyped constant is an int, as its integer literals are;
                // its value folds once every constant of the package is known.
                storage := IntStorage;
                declared := Field(forest, member, syntax.FieldType);
                if (declared >= 0) {
                    hidden := PrivateType(forest, text, types, aliases, package, declared);
                    if (hidden >= 0) {
                        return Declarations.Failed(Diagnose(forest, hidden, file,
                                                            PrivateMessage(Text(forest, text, hidden))));
                    }
                    constant_type := ReadType(forest, text, &types, aliases, package, declared);
                    storage = constant_type.storage;
                    if ((!Integer(storage) && !Floating(storage)) || constant_type.container != 0 ||
                        CharType(types, storage, constant_type.container, constant_type.record)) {
                        return Declarations.Failed(Diagnose(forest, declared, file, "constant type is not supported yet"));
                    }
                }
                named := forest[Field(forest, member, syntax.FieldName)];
                constant: ConstDecl = {name: name, package: package, storage: storage, bits: 0,
                                       node: Field(forest, member, syntax.FieldValue), file: file, folded: false,
                                       occurrence: Occurrence(documents[file].key, SymbolRecord, solid[named.start],
                                                              solid[named.end])};
                constants.append(constant);
            } else if (!Is(forest, member, syntax.PackageHeader) && !Is(forest, member, syntax.ImportDeclaration) &&
                       !Is(forest, member, syntax.RecordDeclaration) && !Is(forest, member, syntax.UnionDeclaration) &&
                       !Is(forest, member, syntax.ForeignImportDeclaration) && !Is(forest, member, syntax.ForeignBlock)) {
                return Declarations.Failed(Diagnose(forest, member, file, "unsupported declaration"));
            }
            chosen_at += 1;
            member = ChosenAt(chosen, chosen_at);
        }
    }
    // Constants may name one another in any order: fold every one whose
    // operands are known, until none is left or none can be.
    progress := true;
    waiting: int = 0;
    while (progress) {
        progress = false;
        waiting = 0;
        at: int = 0;
        while (at < length(constants)) {
            constant := constants[at];
            if (constant.package == package && !constant.folded) {
                switch FoldCalling(forest, documents, links, callables, params, constants, types, members, package, constant.file,
                                constant.node, constant.storage) {
                    case .Failed(diagnostic):
                        return Declarations.Failed(diagnostic);
                    case .Waiting:
                        waiting += 1;
                    case .Folded(value):
                        constant.bits = value;
                        constant.folded = true;
                        constants[at] = constant;
                        progress = true;
                }
            }
            at += 1;
        }
    }
    for (constant in constants) {
        if (waiting > 0 && constant.package == package && !constant.folded) {
            return Declarations.Failed(Diagnose(forest, constant.node, constant.file,
                                                format_text("Constant '{}' depends on itself", constant.name)));
        }
    }
    return Declarations.Collected(callables, params, types, members, constants);
}

Folding :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Waiting
    | Folded(bits: u64)
}
Evaluated :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Waiting
    | Value(exact: u64[])
}
// The number type a conversion call converts to, 0 for any other node.
NumberConversionType :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    callee := Field(forest, node, syntax.FieldFunction);
    if (!Is(forest, node, syntax.CallExpression) || !Is(forest, callee, syntax.Identifier)) {
        return 0;
    }
    storage := ScalarStorage(Text(forest, text, callee));
    if (!Integer(storage) && !Floating(storage)) {
        return 0;
    }
    return storage;
}
// The integer type a conversion call converts to, 0 for any other node.
ConversionType :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    storage := NumberConversionType(forest, text, node);
    if (!Integer(storage)) {
        return 0;
    }
    return storage;
}
Arithmetic :: (operator: int) -> bool {
    return operator == tk.Add || operator == tk.Sub || operator == tk.Mul || operator == tk.Quo || operator == tk.Mod ||
           operator == tk.And || operator == tk.Or || operator == tk.Xor;
}
Shift :: (operator: int) -> bool {
    return operator == tk.Shl || operator == tk.Shr;
}
// Whether `node` is a constant integer expression: integer literals, the
// package's constants and an import's, parentheses, conversions to integer
// types and the integer operators over them.
ConstantExpression :: (forest: snapshot.SnapshotNode[], text: string, constants: ConstDecl[], aliases: Name[],
                       package: int, node: int) -> bool {
    value := Unparenthesized(forest, node);
    if (Is(forest, value, syntax.Number)) {
        return InferredNumberStorage(forest, text, value) != FloatStorage;
    }
    named := ConstantOf(forest, text, constants, aliases, package, value);
    if (named >= 0) {
        // This classifier admits only the exact integer evaluator. Floating
        // expressions in bodies retain ordinary runtime lowering.
        return Integer(constants[named].storage);
    }
    if (ConversionType(forest, text, value) != 0) {
        argument := FirstMember(forest, Field(forest, value, syntax.FieldArguments));
        if (argument < 0 || NextMember(forest, argument) >= 0) {
            return false;
        }
        if (Is(forest, argument, syntax.NamedArgument)) {
            argument = Field(forest, argument, syntax.FieldValue);
        }
        return ConstantExpression(forest, text, constants, aliases, package, argument);
    }
    operator := Operator(forest, value);
    if (Is(forest, value, syntax.UnaryExpression)) {
        return (operator == tk.Add || operator == tk.Sub || operator == tk.Complement) &&
               ConstantExpression(forest, text, constants, aliases, package, Field(forest, value, syntax.FieldOperand));
    }
    return Is(forest, value, syntax.BinaryExpression) && (Arithmetic(operator) || Shift(operator)) &&
           ConstantExpression(forest, text, constants, aliases, package, Field(forest, value, syntax.FieldLeft)) &&
           ConstantExpression(forest, text, constants, aliases, package, Field(forest, value, syntax.FieldRight));
}
// The type a constant expression has of its own: a constant's or a
// conversion's, through unary operators and a shift's value, else either
// operand's of another binary operator, left first. 0 when it is untyped
// literals alone, which take their type from its use.
ConstantType :: (forest: snapshot.SnapshotNode[], text: string, constants: ConstDecl[], aliases: Name[], package: int,
                 node: int) -> int {
    value := Unparenthesized(forest, node);
    named := ConstantOf(forest, text, constants, aliases, package, value);
    if (named >= 0) {
        return constants[named].storage;
    }
    if (ConversionType(forest, text, value) != 0) {
        return ConversionType(forest, text, value);
    }
    callee := Field(forest, value, syntax.FieldFunction);
    if (Is(forest, value, syntax.CallExpression) && Is(forest, callee, syntax.Identifier)) {
        converted := ScalarStorage(Text(forest, text, callee));
        if (Floating(converted)) {
            return converted;
        }
    }
    if (Is(forest, value, syntax.UnaryExpression)) {
        return ConstantType(forest, text, constants, aliases, package, Field(forest, value, syntax.FieldOperand));
    }
    if (!Is(forest, value, syntax.BinaryExpression)) {
        return 0;
    }
    left := ConstantType(forest, text, constants, aliases, package, Field(forest, value, syntax.FieldLeft));
    if (left != 0 || Shift(Operator(forest, value))) {
        return left;
    }
    return ConstantType(forest, text, constants, aliases, package, Field(forest, value, syntax.FieldRight));
}
// An untyped floating literal takes its spelled type, number, through
// grouping and unary signs. Integer operands retain i64, or u64 for a literal
// beyond it.
UntypedStorage :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    literal := Unparenthesized(forest, node);
    while (Is(forest, literal, syntax.UnaryExpression) &&
           (Operator(forest, literal) == tk.Add || Operator(forest, literal) == tk.Sub)) {
        literal = Unparenthesized(forest, Field(forest, literal, syntax.FieldOperand));
    }
    if (Is(forest, literal, syntax.Number) && Floating(InferredNumberStorage(forest, text, literal))) {
        return InferredNumberStorage(forest, text, literal);
    }
    switch ParseNumber(forest, text, Unparenthesized(forest, node)) {
        case .Invalid:
            return Int64Storage;
        case .Number(negative, magnitude):
            if (Fits(negative, magnitude, Int64Storage)) {
                return Int64Storage;
            }
            return WordStorage;
    }
}
// The bits of a constant of its own type, or the context's storage when
// untyped. Integer expressions fold exactly; floating literals, names and
// conversions use their represented values. Waiting on an unfolded name.
FoldConstant :: (forest: snapshot.SnapshotNode[], text: string, file: int, constants: ConstDecl[], aliases: Name[],
                 package: int, node: int, storage: int) -> Folding {
    typed := ConstantType(forest, text, constants, aliases, package, node);
    if (typed == 0) {
        typed = storage;
    }
    if (Floating(storage)) {
        if (typed != storage && !FloatWidens(typed, storage) && !Integer(typed)) {
            return Folding.Failed(Diagnose(forest, node, file, "a constant of another type needs a conversion"));
        }
        if (Integer(typed)) {
            // Reuse the ordinary exact fold before the existing decimal-to-
            // floating conversion, including the source integer's range check.
            switch FoldConstant(forest, text, file, constants, aliases, package, node, typed) {
                case .Failed(diagnostic):
                    return Folding.Failed(diagnostic);
                case .Waiting:
                    return Folding.Waiting;
                case .Folded(bits):
                    exact := ExactStored(bits, typed);
                    switch LiteralBits(format_text("{}", LowBits(Magnitude(exact))), ExactNegative(exact)) {
                        case .OutOfRange:
                            return Folding.Failed(OutsideRange(forest, file, node, storage));
                        case .Finite(wide, fits, narrow):
                            if (storage == FloatStorage) {
                                return Folding.Folded(narrow);
                            }
                            return Folding.Folded(wide);
                    }
            }
        }
        value := Unparenthesized(forest, node);
        if (ParsedLiteral(forest, text, value)) {
            switch NumberBits(forest, text, value) {
                case .OutOfRange:
                    return Folding.Failed(Diagnose(forest, value, file, "Numeric literal is outside the range of its type"));
                case .Finite(wide, fits, narrow):
                    if (storage == FloatStorage && !fits) {
                        return Folding.Failed(Diagnose(forest, value, file, "Numeric literal is outside the range of number"));
                    }
                    if (storage == FloatStorage) {
                        return Folding.Folded(narrow);
                    }
                    return Folding.Folded(wide);
            }
        }
        named := ConstantOf(forest, text, constants, aliases, package, value);
        if (named >= 0) {
            constant := constants[named];
            if (constant.package != package && PrivateDeclaration(forest, forest[constant.node].parent)) {
                return Folding.Failed(Diagnose(forest, value, file, PrivateMessage(Text(forest, text, value))));
            }
            if (!constant.folded) {
                return Folding.Waiting;
            }
            return Folding.Folded(FloatingBits(constant.bits, constant.storage, storage));
        }
        callee := Field(forest, value, syntax.FieldFunction);
        if (Is(forest, value, syntax.CallExpression) && Is(forest, callee, syntax.Identifier) &&
            Floating(ScalarStorage(Text(forest, text, callee)))) {
            converted := ScalarStorage(Text(forest, text, callee));
            operand := FirstMember(forest, Field(forest, value, syntax.FieldArguments));
            if (operand < 0 || NextMember(forest, operand) >= 0) {
                return Folding.Failed(Diagnose(forest, value, file, "Conversion takes one value"));
            }
            if (Is(forest, operand, syntax.NamedArgument)) {
                return Folding.Failed(Diagnose(forest, value, file, "wrap and clamp convert between integer types"));
            }
            inner := ConstantType(forest, text, constants, aliases, package, operand);
            if (inner == 0) {
                inner = UntypedStorage(forest, text, Unparenthesized(forest, operand));
                if (Floating(inner)) {
                    // Untyped floating literals take the conversion's context;
                    // already typed operands keep their represented values.
                    inner = converted;
                }
            }
            // Integer-to-floating conversion uses the same ordinary FoldConstant
            // entry; floating-to-integer is not expanded by this dependency.
            if (Integer(inner)) {
                switch FoldConstant(forest, text, file, constants, aliases, package, operand, inner) {
                    case .Failed(diagnostic):
                        return Folding.Failed(diagnostic);
                    case .Waiting:
                        return Folding.Waiting;
                    case .Folded(bits):
                        exact := ExactStored(bits, inner);
                        switch LiteralBits(format_text("{}", LowBits(Magnitude(exact))), ExactNegative(exact)) {
                            case .OutOfRange:
                                return Folding.Failed(OutsideRange(forest, file, operand, converted));
                            case .Finite(wide, fits, narrow):
                                converted_bits := wide;
                                if (converted == FloatStorage) {
                                    converted_bits = narrow;
                                }
                                return Folding.Folded(FloatingBits(converted_bits, converted, storage));
                        }
                }
            }
            switch FoldConstant(forest, text, file, constants, aliases, package, operand, inner) {
                case .Failed(diagnostic):
                    return Folding.Failed(diagnostic);
                case .Waiting:
                    return Folding.Waiting;
                case .Folded(bits):
                    return Folding.Folded(FloatingBits(FloatingBits(bits, inner, converted), converted, storage));
            }
        }
        operator := Operator(forest, value);
        if (Is(forest, value, syntax.UnaryExpression) && (operator == tk.Add || operator == tk.Sub)) {
            switch FoldConstant(forest, text, file, constants, aliases, package,
                                Field(forest, value, syntax.FieldOperand), storage) {
                case .Failed(diagnostic):
                    return Folding.Failed(diagnostic);
                case .Waiting:
                    return Folding.Waiting;
                case .Folded(bits):
                    if (operator == tk.Sub) {
                        sign: u64 = 0x8000000000000000;
                        if (storage == FloatStorage) {
                            sign = 0x80000000;
                        }
                        return Folding.Folded(bits ^ sign);
                    }
                    return Folding.Folded(bits);
            }
        }
        return Folding.Failed(Diagnose(forest, value, file, "floating constant initializer is not supported yet"));
    }
    if (typed != storage && !Widens(typed, storage)) {
        return Folding.Failed(Diagnose(forest, node, file, "a constant of another type needs a conversion"));
    }
    switch Evaluate(forest, text, file, constants, aliases, package, node, typed) {
        case .Failed(diagnostic):
            return Folding.Failed(diagnostic);
        case .Waiting:
            return Folding.Waiting;
        case .Value(exact):
            if (!ExactFits(exact, typed)) {
                // Anchored inside parentheses, as stage zero anchors it.
                return Folding.Failed(OutsideRange(forest, file, Unparenthesized(forest, node), typed));
            }
            return Folding.Folded(ExactWrapped(exact, typed));
    }
}
// The exact value of the constant integer expression `node` of type
// `storage`.
Evaluate :: (forest: snapshot.SnapshotNode[], text: string, file: int, constants: ConstDecl[], aliases: Name[],
             package: int, node: int, storage: int) -> Evaluated {
    if (Is(forest, node, syntax.ParenthesizedExpression)) {
        return Evaluate(forest, text, file, constants, aliases, package, Field(forest, node, syntax.FieldExpression), storage);
    }
    // A literal, `-` on one included, so the most negative value is one.
    signed_literal := Is(forest, node, syntax.UnaryExpression) &&
                      Operator(forest, node) == tk.Sub &&
                      Is(forest, Field(forest, node, syntax.FieldOperand), syntax.Number);
    if (Is(forest, node, syntax.Number) || signed_literal) {
        switch ParseNumber(forest, text, node) {
            case .Invalid:
                return Evaluated.Failed(Diagnose(forest, node, file, "only integer constants are supported yet"));
            case .Number(negative, magnitude):
                if (!Fits(negative, magnitude, storage)) {
                    return Evaluated.Failed(Diagnose(forest, node, file,
                                                     format_text("Numeric literal is outside the range of {}",
                                                                 TypeName(storage))));
                }
                return Evaluated.Value(ExactOf(negative, magnitude));
        }
    }
    named := ConstantOf(forest, text, constants, aliases, package, node);
    if (named >= 0) {
        if (constants[named].package != package && PrivateDeclaration(forest, forest[constants[named].node].parent)) {
            return Evaluated.Failed(Diagnose(forest, node, file, PrivateMessage(Text(forest, text, node))));
        }
        if (!constants[named].folded) {
            return Evaluated.Waiting;
        }
        if (!Integer(constants[named].storage)) {
            return Evaluated.Failed(Diagnose(forest, node, file, "constant value must be an integer expression"));
        }
        return Evaluated.Value(ExactStored(constants[named].bits, constants[named].storage));
    }
    if (ConversionType(forest, text, node) != 0) {
        return EvaluateConversion(forest, text, file, constants, aliases, package, node);
    }
    unary := Is(forest, node, syntax.UnaryExpression);
    if (!unary && !Is(forest, node, syntax.BinaryExpression)) {
        return Evaluated.Failed(Diagnose(forest, node, file, "constant value must be an integer expression"));
    }
    operator := Operator(forest, node);
    if (!unary && Shift(operator)) {
        return EvaluateShift(forest, text, file, constants, aliases, package, node, storage);
    }
    if ((unary && operator != tk.Add && operator != tk.Sub && operator != tk.Complement) || (!unary && !Arithmetic(operator))) {
        return Evaluated.Failed(Diagnose(forest, node, file,
                                         format_text("constant operator '{}' is not supported yet",
                                                     Text(forest, text, Field(forest, node, syntax.FieldOperator)))));
    }
    if (unary && operator == tk.Sub && !Signed(storage)) {
        return Evaluated.Failed(Diagnose(forest, node, file, "Cannot negate an unsigned constant"));
    }
    operands: int[] = [Field(forest, node, syntax.FieldOperand)];
    if (!unary) {
        operands = [Field(forest, node, syntax.FieldLeft), Field(forest, node, syntax.FieldRight)];
        left_type := ConstantType(forest, text, constants, aliases, package, operands[0]);
        right_type := ConstantType(forest, text, constants, aliases, package, operands[1]);
        if (left_type != 0 && right_type != 0 && left_type != right_type) {
            return Evaluated.Failed(Diagnose(forest, node, file,
                                             format_text("Mismatched integer types {} and {}; convert one operand",
                                                         TypeName(left_type), TypeName(right_type))));
        }
    }
    value: u64[] = [];
    right: u64[] = [];
    for (index in 0..<length(operands)) {
        switch Evaluate(forest, text, file, constants, aliases, package, operands[index], storage) {
            case .Failed(diagnostic):
                return Evaluated.Failed(diagnostic);
            case .Waiting:
                return Evaluated.Waiting;
            case .Value(exact):
                if (index == 0) {
                    value = exact;
                } else {
                    right = exact;
                }
        }
    }
    if (unary && operator == tk.Sub) {
        value = ExactNegate(value);
    } else if (unary && operator == tk.Complement && Signed(storage)) {
        value = ExactSubtract(ExactNegate(value), ExactOf(false, 1));
    } else if (unary && operator == tk.Complement) {
        // An unsigned type's complement is its largest value less this one.
        value = ExactSubtract(ExactMax(storage), value);
    } else if (!unary && operator == tk.Add) {
        // A unary plus keeps its operand.
        value = ExactAdd(value, right);
    } else if (operator == tk.Sub) {
        value = ExactSubtract(value, right);
    } else if (operator == tk.Mul) {
        value = ExactMultiply(value, right);
    } else if (operator == tk.Quo || operator == tk.Mod) {
        if (ExactZero(right)) {
            return Evaluated.Failed(Diagnose(forest, node, file, "Constant division by zero"));
        }
        value = ExactDivide(value, right, operator == tk.Mod);
    } else if (!unary) {
        value = ExactBitwise(operator, value, right);
    }
    if (MagnitudeBits(Magnitude(value)) > ExactLimit) {
        return Evaluated.Failed(OutsideRange(forest, file, node, storage));
    }
    return Evaluated.Value(value);
}
// A constant whose value does not fit its type. A value beyond ExactLimit
// bits fits none.
OutsideRange :: (forest: snapshot.SnapshotNode[], file: int, node: int, storage: int) -> syntax.Diagnostic {
    return Diagnose(forest, node, file, format_text("Constant value is outside the range of {}", TypeName(storage)));
}
// A shift's value has the type of its left operand. Its count has its own
// type, which must be unsigned, and must not be negative.
EvaluateShift :: (forest: snapshot.SnapshotNode[], text: string, file: int, constants: ConstDecl[], aliases: Name[],
                  package: int, node: int, storage: int) -> Evaluated {
    count := Unparenthesized(forest, Field(forest, node, syntax.FieldRight));
    count_type := ConstantType(forest, text, constants, aliases, package, count);
    if (Signed(count_type)) {
        return Evaluated.Failed(Diagnose(forest, count, file, "Shift count must be unsigned; convert it with u32(value)"));
    }
    if (count_type == 0) {
        count_type = UntypedStorage(forest, text, count);
    }
    value: u64[] = [];
    shift: u64[] = [];
    operands: int[] = [Field(forest, node, syntax.FieldLeft), count];
    types: int[] = [storage, count_type];
    for (index in 0..<2) {
        switch Evaluate(forest, text, file, constants, aliases, package, operands[index], types[index]) {
            case .Failed(diagnostic):
                return Evaluated.Failed(diagnostic);
            case .Waiting:
                return Evaluated.Waiting;
            case .Value(exact):
                if (index == 0) {
                    value = exact;
                } else {
                    shift = exact;
                }
        }
    }
    if (ExactNegative(shift)) {
        return Evaluated.Failed(Diagnose(forest, count, file, "Shift count must not be negative"));
    }
    if (MagnitudeCompare(Magnitude(shift), Magnitude(ExactOf(false, u64(ExactLimit)))) > 0) {
        return Evaluated.Failed(Diagnose(forest, count, file, "Constant shift count is too large"));
    }
    bits := int(LowBits(Magnitude(shift)));
    if (Operator(forest, node) == tk.Shr) {
        return Evaluated.Value(ExactShiftRight(value, bits));
    }
    shifted := ExactShiftLeft(value, bits);
    if (MagnitudeBits(Magnitude(shifted)) > ExactLimit) {
        return Evaluated.Failed(OutsideRange(forest, file, node, storage));
    }
    return Evaluated.Value(shifted);
}
// `T(value)` must fit T; `T(wrap: value)` keeps the low bits. The value has
// its own type, or i64 when untyped, and must fit it.
EvaluateConversion :: (forest: snapshot.SnapshotNode[], text: string, file: int, constants: ConstDecl[],
                       aliases: Name[], package: int, node: int) -> Evaluated {
    storage := ConversionType(forest, text, node);
    argument := FirstMember(forest, Field(forest, node, syntax.FieldArguments));
    if (argument < 0 || NextMember(forest, argument) >= 0) {
        return Evaluated.Failed(Diagnose(forest, node, file, "Conversion takes one value"));
    }
    wrap := Is(forest, argument, syntax.NamedArgument);
    value := argument;
    if (wrap) {
        if (Text(forest, text, Field(forest, argument, syntax.FieldName)) != "wrap") {
            return Evaluated.Failed(Diagnose(forest, Field(forest, argument, syntax.FieldName), file,
                                             "A conversion argument may only be named wrap"));
        }
        value = Field(forest, argument, syntax.FieldValue);
    }
    inner := ConstantType(forest, text, constants, aliases, package, value);
    if (inner == 0) {
        inner = UntypedStorage(forest, text, value);
    }
    if (Floating(inner)) {
        return Evaluated.Failed(Diagnose(forest, value, file,
                                         "floating-to-integer constant conversion is not supported yet"));
    }
    switch FoldConstant(forest, text, file, constants, aliases, package, value, inner) {
        case .Failed(diagnostic):
            return Evaluated.Failed(diagnostic);
        case .Waiting:
            return Evaluated.Waiting;
        case .Folded(bits):
            exact := ExactStored(bits, inner);
            if (wrap) {
                return Evaluated.Value(ExactStored(ExactWrapped(exact, storage), storage));
            }
            if (!ExactFits(exact, storage)) {
                return Evaluated.Failed(Diagnose(forest, node, file,
                                                 format_text("Constant does not fit in {}; use {}(wrap: value)",
                                                             TypeName(storage), TypeName(storage))));
            }
            return Evaluated.Value(exact);
    }
}

Default :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Read(bits: u64, text: string)
}
// A parameter's default, as the literal stage zero folds it to: an integer of
// the parameter's type, a bool or a string.
LiteralDefault :: (forest: snapshot.SnapshotNode[], text: string, file: int, node: int, declared: ValueType) -> Default {
    if (declared.container == ViewContainer) {
        return Default.Failed(Diagnose(forest, node, file, "view requires an initialized value"));
    }
    if (declared.container != 0) {
        return Default.Failed(Diagnose(forest, node, file, "a parameter default needs a literal yet"));
    }
    if (Floating(declared.storage)) {
        literal := StateNumberNode(forest, text, node);
        if (literal >= 0) {
            switch NumberBits(forest, text, literal) {
                case .Finite(double_bits, float_fits, float_bits):
                    if (declared.storage == DoubleStorage) {
                        return Default.Read(double_bits, "");
                    }
                    if (float_fits) {
                        return Default.Read(float_bits, "");
                    }
                case .OutOfRange:
                    return Default.Failed(Diagnose(forest, node, file, "Numeric literal is outside the range of its type"));
            }
        }
        return Default.Failed(Diagnose(forest, node, file, "a parameter default needs a representable numeric literal"));
    }
    if (Integer(declared.storage)) {
        switch ParseNumber(forest, text, node) {
            case .Invalid:
                return Default.Failed(Diagnose(forest, node, file, "a parameter default needs a literal yet"));
            case .Number(negative, magnitude):
                if (!Fits(negative, magnitude, declared.storage)) {
                    return Default.Failed(Diagnose(forest, node, file,
                                                   format_text("Numeric literal is outside the range of {}",
                                                               TypeName(declared.storage))));
                }
                return Default.Read(Bits(negative, magnitude), "");
        }
    }
    if (declared.storage == BoolStorage && Is(forest, node, syntax.Boolean)) {
        if (Text(forest, text, node) == "true") {
            return Default.Read(1, "");
        }
        return Default.Read(0, "");
    }
    if (declared.storage == TextStorage && Is(forest, node, syntax.String)) {
        decoded := json.Value(Text(forest, text, node));
        if (!decoded.valid) {
            return Default.Failed(Diagnose(forest, node, file, "Invalid string literal"));
        }
        return Default.Read(0, decoded.value);
    }
    return Default.Failed(Diagnose(forest, node, file, "a parameter default needs a literal yet"));
}
// The signature of the function `member` named `name`, its params numbered
// from `first`. Named results include text, arrays and boxed optionals.
FunctionSignature :: (forest: snapshot.SnapshotNode[], text: string, key: string, solid: int[], table: ^(TypeDecl[]),
                      aliases: Name[], package: int, file: int, member: int, name: string, first: int,
                      scopes: ScopeTable) -> Signature {
    attributes := DeclarationAttributes(forest, text, file, member, "test");
    if (length(attributes) > 0) {
        return Signature.Failed(attributes[0]);
    }
    added: Param[] = [];
    parameter := FirstMember(forest, Field(forest, member, syntax.FieldParameters));
    while (parameter >= 0) {
        type_node := Field(forest, parameter, syntax.FieldType);
        if (GenericCallableType(forest, type_node) >= 0 || Field(forest, parameter, syntax.FieldComptime) >= 0) {
            parameter = NextMember(forest, parameter);
            continue;
        }
        hidden := PrivateType(forest, text, table^, aliases, package, type_node);
        if (hidden >= 0) {
            return Signature.Failed(Diagnose(forest, hidden, file, PrivateMessage(Text(forest, text, hidden))));
        }
        // A scoped pointer parameter takes a reference to its target.
        pointer := PointerAnnotation(forest, type_node);
        reference := false;
        if (pointer >= 0) {
            // The table lists the pointer parameters of declared functions. A
            // signature without a body, such as a callable parameter's, has no
            // uses that could make its pointer managed.
            verdict := ScopedVerdict(scopes, parameter);
            reference = verdict == 1 || (verdict < 0 && Field(forest, member, syntax.FieldBody) < 0);
        }
        if (reference) {
            type_node = Field(forest, pointer, syntax.FieldTarget);
        }
        declared := ReadType(forest, text, table, aliases, package, type_node);
        if (reference && CharType(table^, declared.storage, declared.container, declared.record)) {
            return Signature.Failed(Diagnose(forest, parameter, file, "char pointers are not supported yet"));
        }
        if (declared.storage == 0) {
            return Signature.Failed(Diagnose(forest, parameter, file, "parameter type is not supported yet"));
        }
        if (reference && Field(forest, parameter, syntax.FieldValue) >= 0) {
            return Signature.Failed(Diagnose(forest, parameter, file, "a scoped pointer parameter takes no default"));
        }
        param_name := Text(forest, text, Field(forest, parameter, syntax.FieldName));
        if (param_name == "") {
            return Signature.Failed(Diagnose(forest, Field(forest, parameter, syntax.FieldName), file,
                                             "Invalid string or embedded NUL"));
        }
        default_value := Field(forest, parameter, syntax.FieldValue);
        if (default_value >= 0 && CharType(table^, declared.storage, declared.container, declared.record)) {
            return Signature.Failed(Diagnose(forest, default_value, file, "char parameter defaults are not supported yet"));
        }
        default_occurrence: u64 = 0;
        if (default_value >= 0) {
            default_occurrence = Occurrence(key, ExpressionRecord, solid[forest[default_value].start],
                                            solid[forest[default_value].end]);
        }
        param: Param = {name: param_name, storage: declared.storage, container: declared.container,
                        record: declared.record, has_default: false, default_bits: 0, default_text: "",
                        default_occurrence: default_occurrence, reference: reference, written: false,
                        node: Field(forest, parameter, syntax.FieldName)};
        if (default_value >= 0 && declared.storage == PointerStorage && declared.container == 0 &&
            declared.record >= 0 && table^[declared.record].key != 0 && Is(forest, default_value, syntax.Nil)) {
            param.has_default = true;
        } else if (default_value >= 0 && OptionalElement(table^, Typed(-1, declared.storage, declared.container,
                                                                       declared.record)).storage != 0 &&
                   Is(forest, default_value, syntax.Nil)) {
            param.has_default = true;
        } else if (default_value >= 0) {
            switch LiteralDefault(forest, text, file, default_value, declared) {
                case .Failed(diagnostic):
                    return Signature.Failed(diagnostic);
                case .Read(bits, literal):
                    param.has_default = true;
                    param.default_bits = bits;
                    param.default_text = literal;
            }
        }
        added.append(param);
        parameter = NextMember(forest, parameter);
    }
    count := length(added);
    result: ValueType = {storage: 0, container: 0, record: -1};
    results := Field(forest, member, syntax.FieldResults);
    if (Is(forest, results, syntax.ParameterList)) {
        named := FirstMember(forest, results);
        if (named < 0) {
            return Signature.Failed(Diagnose(forest, results, file, "named results need at least one result"));
        }
        while (named >= 0) {
            hidden := PrivateType(forest, text, table^, aliases, package, Field(forest, named, syntax.FieldType));
            if (hidden >= 0) {
                return Signature.Failed(Diagnose(forest, hidden, file, PrivateMessage(Text(forest, text, hidden))));
            }
            declared := ReadType(forest, text, table, aliases, package, Field(forest, named, syntax.FieldType));
            if (declared.storage == 0 || declared.storage == PointerStorage ||
                (declared.container != 0 && declared.container != ArrayContainer) ||
                (declared.storage == UnionStorage && declared.container == 0 &&
                 OptionalElement(table^, Typed(-1, declared.storage, declared.container, declared.record)).storage == 0)) {
                return Signature.Failed(Diagnose(forest, named, file, "named result type is not supported yet"));
            }
            initial := Field(forest, named, syntax.FieldValue);
            if (OptionalElement(table^, Typed(-1, declared.storage, declared.container, declared.record)).storage != 0 &&
                initial >= 0 && !Is(forest, initial, syntax.Nil)) {
                return Signature.Failed(Diagnose(forest, initial, file, "named optional result initializer is not supported yet"));
            }
            result_name := Text(forest, text, Field(forest, named, syntax.FieldName));
            param: Param = {name: result_name, storage: declared.storage, container: declared.container,
                            record: declared.record,
                            has_default: false, default_bits: 0, default_text: "", default_occurrence: 0,
                            reference: false, written: false, node: Field(forest, named, syntax.FieldName)};
            added.append(param);
            named = NextMember(forest, named);
        }
    } else if (results >= 0) {
        hidden := PrivateType(forest, text, table^, aliases, package, results);
        if (hidden >= 0) {
            return Signature.Failed(Diagnose(forest, hidden, file, PrivateMessage(Text(forest, text, hidden))));
        }
        result = ReadType(forest, text, table, aliases, package, results);
        if (result.storage == 0) {
            return Signature.Failed(Diagnose(forest, results, file, "result type is not supported yet"));
        }
    }
    callable: Callable = {name: name, package: package, document: file, node: member, first: first, count: count,
                          result: result.storage, result_container: result.container, result_record: result.record,
                          results: length(added) - count, waits: false, identity: 0, owner_package: package};
    for index in count..<length(added) - 1 {
        earlier := added[index];
        if ErrorBearing(table^, {storage: earlier.storage, container: earlier.container, record: earlier.record}) {
            return Signature.Failed(Diagnose(forest, earlier.node, file, "An error-bearing result must be the final result"));
        }
    }
    return Signature.Read(callable, added);
}
ScalarValue :: (storage: int, wide: int) -> writer.Value {
    return {tag: storage, container: 0, type_name: "", has_type_name: false, authored: false,
            wide: wide, text: "", has_text: false, present: false, first: 0, count: 0};
}
// The header of an absent value of a type. A record names its layout; an
// array of records, like a record, names its type, and so does a handle of a
// game type, such as an entity. A native type's header lists no fields.
Header :: (storage: int, container: int, record: int, types: TypeDecl[], layouts: int[]) -> writer.Value {
    if (record >= 0 && types[record].kind == CollectionDecl) {
        return SequenceHeader({storage: storage, container: container, record: record}, types);
    }
    if (container != 0) {
        value := ScalarValue(storage, 0);
        value.container = container;
        if (container == MapContainer) {
            value.type_name = types[record].type_name;
            value.has_type_name = true;
        } else if (storage == StructStorage || storage == PointerStorage) {
            value.type_name = types[record].type_name;
            value.has_type_name = true;
            value.authored = storage == StructStorage && types[record].kind != NativeDecl;
        }
        return value;
    }
    if (storage == HandleStorage && record >= 0) {
        handle := ScalarValue(storage, 0);
        handle.type_name = types[record].type_name;
        handle.has_type_name = true;
        return handle;
    }
    if (storage == PointerStorage && record >= 0) {
        value := ScalarValue(storage, 0);
        value.type_name = types[record].type_name;
        value.has_type_name = true;
        return value;
    }
    if (storage != StructStorage) {
        return ScalarValue(storage, 0);
    }
    if (types[record].kind == NativeDecl) {
        return {tag: StructStorage, container: 0, type_name: types[record].type_name, has_type_name: true,
                authored: false, wide: layouts[record], text: "", has_text: false, present: false, first: 0, count: 0};
    }
    return {tag: StructStorage, container: 0, type_name: types[record].type_name, has_type_name: true,
            authored: true, wide: layouts[record], text: "", has_text: false, present: false, first: 0,
            count: types[record].count};
}
// A parameter's header: its type's, or a scoped parameter's descriptor pointer.
ParamHeader :: (param: Param, types: TypeDecl[], layouts: int[], target: Target) -> writer.Value {
    if (param.reference) {
        return ScalarValue(target.pointer_storage, 0);
    }
    return Header(param.storage, param.container, param.record, types, layouts);
}
NoSource :: () -> writer.Source {
    return {graph: 0, call: 0, parent: -1, asset: "", has_asset: false, start: 0, end: 0, line: 0, column: 0};
}
Range :: (first: int, count: int) -> writer.Span {
    return {first: first, count: count};
}
Own :: (index: int) -> writer.Reference {
    return {imported: -1, own: index, function: 0, role: 0};
}
// FNV-1a over `count` little-endian bytes of `value`, as the runtime hashes
// layouts.
HashBytes :: (hash: u64, value: u64, count: int) -> u64 {
    out := hash;
    rest := value;
    index: int = 0;
    while (index < count) {
        out = (out ^ (rest & 255)) * 1099511628211;
        rest = rest >> 8;
        index += 1;
    }
    return out;
}
HashText :: (hash: u64, text: string) -> u64 {
    out := hash;
    // Each ByteAt measures the text, so a whole text reads Bytes once.
    for (byte in strings.Bytes(text)) {
        out = HashBytes(out, u64(byte), 1);
    }
    return HashBytes(out, 0, 1);
}
// The runtime's layout hash, including container markers and complete child
// layouts while preserving the existing scalar field encoding.
LayoutHash :: (record: TypeDecl, fields: TypeMember[], types: TypeDecl[], target: Target) -> u64 {
    hash: u64 = 1469598103934665603;
    hash = HashBytes(hash, u64(record.size), target.pointer_size);
    hash = HashBytes(hash, u64(record.count), 4);
    at := record.first;
    while (at < record.first + record.count) {
        field := fields[at];
        hash = HashText(hash, field.name);
        hash = HashBytes(hash, u64(field.offset), target.pointer_size);
        hash = HashBytes(hash, u64(RecordFieldSize(field, types, target)), target.pointer_size);
        hash = HashBytes(hash, u64(field.storage), 4);
        if (field.container != 0) {
            hash = HashBytes(hash, u64(field.container), 4);
        }
        if (field.storage == TextStorage && field.container == 0) {
            hash = HashBytes(hash, 1, 1);
        }
        if (field.storage == PointerStorage || field.storage == StructStorage ||
            (field.storage == UnionStorage && field.record >= 0)) {
            hash = HashText(hash, types[field.record].type_name);
        } else {
            hash = HashText(hash, "");
        }
        if (field.storage == StructStorage) {
            hash = HashBytes(hash, types[field.record].layout, 8);
        }
        at += 1;
    }
    return hash;
}

// Whether each of `count` packages is `package` or one it imports, directly
// or through others.
Reachable :: (edges: graph.Edge[], count: int, package: int) -> bool[] {
    seen := resize([false], count);
    seen[package] = true;
    pending: int[] = [package];
    while (length(pending) > 0) {
        at := pending[length(pending) - 1];
        pending = slice(pending, 0, length(pending) - 1);
        for (edge in edges) {
            if (edge.from == at && !seen[edge.to]) {
                seen[edge.to] = true;
                pending.append(edge.to);
            }
        }
    }
    return seen;
}
// The closure of every package, each a prepared module, rooted at package
// `root`. Dependencies come first, so an importer has every module it imports.
Link :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], packages: graph.Package[],
         files_of: int[], root: int, order: int[], edges: graph.Edge[], links: graph.Binding[],
         input_callables: Callable[], input_params: Param[], input_types: TypeDecl[], input_members: TypeMember[],
         constants: ConstDecl[], natives: ResolvedNative[], ports: ResolvedPort[], identities: u64[], native_effects: int[], ops: Ops,
         target: Target, abi: u64) -> Result {
    callables := WaitingCallables(forest, input_callables);
    params := input_params;
    generic_bindings: GenericBinding[] = [];
    types := input_types;
    members := input_members;
    switch TaskResultDeclarations(callables, params, types, members) {
        case .Collected(declared_types, declared_members):
            types = declared_types;
            members = declared_members;
    }
    // Each package's identity and module ID, and the fingerprint of its module.
    package_names: string[] = [];
    package_ids: u64[] = [];
    for (listed in packages) {
        package_names.append(documents[files_of[listed.member_start]].identity);
        package_ids.append(binding.ID("module", package_names[length(package_names) - 1]));
    }
    context: BodyContext = BodyContext.Known(native_effects);
    switch SpecializePackages(forest, documents, order, links, package_names, callables, params, &types, members,
                              constants, natives, ports, identities, context, ops, target) {
        case .Failed(diagnostic):
            return Result.Rejected(diagnostic);
        case .Ready(concrete, concrete_params, bindings):
            callables = concrete;
            params = concrete_params;
            generic_bindings = bindings;
    }
    prepared: Body[] = [];
    retained: StateDecl[] = [];
    retained_owners: int[] = [];
    switch RetainedLocals(forest, documents, callables, package_names, &types, ops) {
        case .Failed(diagnostic):
            return Result.Rejected(diagnostic);
        case .Read(states, owners):
            retained = states;
            retained_owners = owners;
    }
    // Bodies may declare types, which every module then reads.
    switch PreparePackages(forest, documents, packages, files_of, order, edges, links, package_names,
                           callables, params, &types, members, constants, natives, ports, identities,
                           context, generic_bindings, ops, target, retained, retained_owners) {
        case .Failed(diagnostic):
            return Result.Rejected(diagnostic);
        case .Read(bodies):
            switch GenericSynchronous(forest, callables, bodies, generic_bindings, native_effects) {
                case .Valid:
                    prepared = bodies;
                case .Failed(diagnostic):
                    return Result.Rejected(diagnostic);
            }
    }
    fingerprints := resize([u64(0)], length(packages));
    data: u8[] = [];
    closure_ids: u64[] = [];
    closure_names: string[] = [];
    starts: int[] = [];
    lengths: int[] = [];
    effects := resize([int(0)], length(callables));
    for (package in order) {
        switch Assemble(forest, documents, package, files_of[packages[package].member_start], package_names,
                        package_ids, fingerprints,
                        Reachable(edges, length(packages), package), links, callables, params, types, members, constants,
                        natives, ports, identities, native_effects, effects, ops, target, abi, Game.Package, prepared,
                        PackageStates(retained, retained_owners, callables, package)) {
            case .Rejected(diagnostic):
                return Result.Rejected(diagnostic);
            case .Compiled(module, bytes, summaries):
                effects = summaries;
                // Only an importer reads a fingerprint, and none imports the root.
                if (package != root) {
                    fingerprints[package] = writer.Fingerprint(bytes);
                }
                closure_ids.append(package_ids[package]);
                closure_names.append(package_names[package]);
                starts.append(length(data));
                lengths.append(length(bytes));
                data.extend(bytes);
        }
    }
    return Result.Compiled(package_ids[root],
                           writer.Closure(package_ids[root], closure_ids, closure_names, data, starts, lengths));
}
// The prepared module of package `package`, or of a behavior, whose
// functions are its handlers; its bytes are the Compiled result's. Each body
// is a canonical definition the runtime verifies and finalizes when it loads
// it.
// `constants`, each another package's taking the occurrence of the first use
// in package `package`, where stage zero declares its symbol.
UsedConstants :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], links: graph.Binding[],
                  callables: Callable[], constants: ConstDecl[], package: int, first_own: int,
                  reachable: bool[]) -> ConstDecl[] {
    // Only a package this one imports declares a constant it can use.
    outside := false;
    for (constant in constants) {
        outside = outside || (constant.package != package && reachable[constant.package]);
    }
    if (!outside) {
        return constants;
    }
    seen := resize([false], length(constants));
    firsts := resize([u64(0)], length(constants));
    solid: int[] = [];
    solid_document: int = -1;
    index := first_own;
    while (index < length(callables) && callables[index].owner_package == package) {
        document := callables[index].document;
        text := documents[document].text;
        if (document != solid_document) {
            solid = SolidOffsets(text);
            solid_document = document;
        }
        aliases := Aliases(links, document);
        // The body's nodes in source order.
        pending: int[] = [Field(forest, callables[index].node, syntax.FieldBody)];
        while (length(pending) > 0) {
            node := pending[length(pending) - 1];
            pending = slice(pending, 0, length(pending) - 1);
            found: int = -1;
            if (Is(forest, node, syntax.MemberExpression)) {
                found = ConstantOf(forest, text, constants, aliases, package, node);
            }
            if (found >= 0 && constants[found].package != package && !seen[found]) {
                seen[found] = true;
                firsts[found] = Occurrence(documents[document].key, SymbolRecord, solid[forest[node].start],
                                           solid[forest[node].end]);
            }
            children: int[] = [];
            child := forest[node].first_child;
            while (child >= 0) {
                children.append(child);
                child = forest[child].next_sibling;
            }
            at_child := length(children) - 1;
            while (at_child >= 0) {
                pending.append(children[at_child]);
                at_child -= 1;
            }
        }
        index += 1;
    }
    used: ConstDecl[] = [];
    at: int = 0;
    while (at < length(constants)) {
        occurrence := constants[at].occurrence;
        if (seen[at]) {
            occurrence = firsts[at];
        }
        first: ConstDecl = {name: constants[at].name, package: constants[at].package, storage: constants[at].storage,
                            bits: constants[at].bits, node: constants[at].node, file: constants[at].file,
                            folded: constants[at].folded, occurrence: occurrence};
        used.append(first);
        at += 1;
    }
    return used;
}
// A closed, prepared source cycle starts at its direct facts. Unknown native
// contracts remain unknown; WRITE propagates through actual invocation edges.
WriteSummaries :: (bodies: Body[]) -> int[] {
    summaries: int[] = [];
    for (body in bodies) {
        switch body {
            case .Failed(diagnostic):
                summaries.append(UnknownWrite);
            case .Specialize(template, call, arguments, caller_names):
                summaries.append(UnknownWrite);
            case .Inferred(value):
                summaries.append(UnknownWrite);
            case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects,
                          direct_write, facts):
                summaries.append(direct_write);
        }
    }
    changed := true;
    while (changed) {
        changed = false;
        index: int = 0;
        for (body in bodies) {
            switch body {
                case .Failed(diagnostic):
                    summaries[index] = UnknownWrite;
                case .Specialize(template, call, arguments, caller_names):
                    summaries[index] = UnknownWrite;
                case .Inferred(value):
                    summaries[index] = UnknownWrite;
                case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects,
                              direct_write, facts):
                    for (call in calls) {
                        joined := JoinWrite(summaries[index], summaries[call.callee]);
                        if (joined != summaries[index]) {
                            summaries[index] = joined;
                            changed = true;
                        }
                    }
            }
            index += 1;
        }
    }
    return summaries;
}
ItemWrite :: (forest: snapshot.SnapshotNode[], facts: SemanticFact[], item: int, summaries: int[],
              context: BodyContext) -> int {
    summary: int = 0;
    for (fact in facts) {
        if (fact.kind != UpdateFact && InSubtree(forest, fact.node, item)) {
            if (fact.kind == WriteFact) {
                summary = WriteEffect;
            } else if (fact.kind == NativeFact) {
                summary = JoinWrite(summary, NativeWrite(context, fact.target));
            } else if (fact.kind == CallFact) {
                summary = JoinWrite(summary, summaries[fact.target]);
            }
        }
    }
    return summary;
}
// Only a proven clear item may mutate the receiver in place. The first pass
// uses contextual in-place typing, but is never published before this proof.
GenericUpdates :: (forest: snapshot.SnapshotNode[], body: Body, summaries: int[], context: BodyContext) -> int[] {
    generic: int[] = [];
    switch body {
        case .Failed(diagnostic):
            return generic;
        case .Specialize(template, call, arguments, caller_names):
            return generic;
        case .Inferred(value):
            return generic;
        case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects,
                      direct_write, facts):
            for (fact in facts) {
                if (fact.kind == UpdateFact && ItemWrite(forest, facts, fact.target, summaries, context) != 0) {
                    generic.append(fact.node);
                }
            }
    }
    return generic;
}
// Changing the lowering must preserve its resolved semantic write contract.
StablePreparation :: (forest: snapshot.SnapshotNode[], before: Body, next_body: Body, summaries: int[],
                      context: BodyContext) -> bool {
    switch before {
        case .Failed(diagnostic):
            return false;
        case .Specialize(template, call, arguments, caller_names):
            return false;
        case .Inferred(value):
            return false;
        case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects,
                      direct_write, facts):
            switch next_body {
                case .Failed(diagnostic):
                    return false;
                case .Specialize(template, call, arguments, caller_names):
                    return false;
                case .Inferred(next_value):
                    return false;
                case .Emitted(next_slots, next_locals, next_cells, next_code, next_calls, next_hosts, next_roots,
                              next_points, next_watches, next_effects, next_write, next_facts):
                    if (direct_write != next_write || length(calls) != length(next_calls)) {
                        return false;
                    }
                    index: int = 0;
                    while (index < length(calls)) {
                        if (calls[index].callee != next_calls[index].callee) {
                            return false;
                        }
                        index += 1;
                    }
                    index = 0;
                    next_index: int = 0;
                    while (index < length(facts)) {
                        if (facts[index].kind == UpdateFact) {
                            while (next_index < length(next_facts) && next_facts[next_index].kind != UpdateFact) {
                                next_index += 1;
                            }
                            if (next_index == length(next_facts)) {
                                return false;
                            }
                            old := facts[index];
                            current := next_facts[next_index];
                            if (old.node != current.node || old.target != current.target ||
                                ItemWrite(forest, facts, old.target, summaries, context) !=
                                ItemWrite(forest, next_facts, current.target, summaries, context)) {
                                return false;
                            }
                            next_index += 1;
                        }
                        index += 1;
                    }
                    while (next_index < length(next_facts)) {
                        if (next_facts[next_index].kind == UpdateFact) {
                            return false;
                        }
                        next_index += 1;
                    }
            }
    }
    return true;
}
Preparation :: union {
    Failed(diagnostic: syntax.Diagnostic) | Read(bodies: Body[])
}
// Pure packages use the same two-stage body cache as executable sources.
// Constants keep the importing package's first-use symbol occurrence.
PreparePackages :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], packages: graph.Package[],
                    files_of: int[], order: int[], edges: graph.Edge[], links: graph.Binding[],
                    package_names: string[], callables: Callable[], params: Param[], table: ^(TypeDecl[]),
                    members: TypeMember[], constants: ConstDecl[], natives: ResolvedNative[], ports: ResolvedPort[],
                    identities: u64[], context: BodyContext, generic_bindings: GenericBinding[], ops: Ops, target: Target,
                    retained: StateDecl[], retained_owners: int[]) -> Preparation {
    bodies: Body[] = [];
    for (callable in callables) {
        bodies.append(Body.Failed(Diagnose(forest, callable.node, callable.document, "missing prepared body")));
    }
    summaries: int[] = [];
    // A scoped parameter's `p^` reads and writes `p` in every body.
    scoped := forest;
    if (AnyReference(params)) {
        scoped = ScopedTargets(forest, documents, callables, params);
    }
    pass: int = 0;
    while (pass < 2) {
        for (package in order) {
            if (!HostPackageAvailable(natives, package_names[package])) {
                document := files_of[packages[package].member_start];
                return Preparation.Failed(Diagnose(forest, documents[document].root, document,
                                                   "Host package is unavailable for this target"));
            }
            first: int = 0;
            while (first < length(callables) && callables[first].owner_package != package) {
                first += 1;
            }
            // The second pass prepares only callables with generic updates,
            // so it reads a package's constants for its first such callable.
            used: ConstDecl[] = [];
            undeclared: u64 = 0;
            loaded := false;
            solid: int[] = [];
            solid_document: int = -1;
            index := first;
            while (index < length(callables) && callables[index].owner_package == package) {
                callable := callables[index];
                generic: int[] = [];
                if (pass > 0) {
                    generic = GenericUpdates(scoped, bodies[index], summaries, context);
                }
                if (pass == 0 || length(generic) > 0) {
                    if (!loaded) {
                        used = UsedConstants(forest, documents, links, callables, constants, package, first,
                                             Reachable(edges, length(packages), package));
                        first_document := files_of[packages[package].member_start];
                        first_solid := SolidOffsets(documents[first_document].text);
                        undeclared = OccurrenceIn(DocumentHash(documents[first_document].key), SymbolRecord, 0,
                                                  first_solid[length(first_solid) - 1]);
                        loaded = true;
                    }
                    if (callable.document != solid_document) {
                        solid = SolidOffsets(documents[callable.document].text);
                        solid_document = callable.document;
                    }
                    meaning := CallableIdentity(package_names, callable);
                    body := FunctionBody(scoped, documents, callables, params, table, members,
                                         GenericConstants(forest, used, generic_bindings, index, callable, documents), natives, ports,
                                         identities, extend(GenericAliases(Aliases(links, callable.document), generic_bindings, index),
                                                            RetainedNames(retained, retained_owners, callables, package, index)),
                                         [], [], [], index, solid,
                                         undeclared, meaning, context, generic, ops, target);
                    switch body {
                        case .Failed(diagnostic):
                            return Preparation.Failed(diagnostic);
                        case .Specialize(template, call, arguments, caller_names):
                            return Preparation.Failed(Diagnose(forest, call, callable.document, "unresolved generic call"));
                        case .Inferred(value):
                            return Preparation.Failed(Diagnose(forest, callable.node, callable.document,
                                                               "expression inferred where a callable body was required"));
                        case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects,
                                      direct_write, facts):
                            if (pass > 0 && !StablePreparation(scoped, bodies[index], body, summaries, context)) {
                                return Preparation.Failed(Diagnose(forest, callable.node, callable.document,
                                                                   "array update effects changed during preparation"));
                            }
                            bodies[index] = body;
                    }
                }
                index += 1;
            }
        }
        if (pass == 0) {
            summaries = WriteSummaries(bodies);
        }
        pass += 1;
    }
    return Preparation.Read(bodies);
}
// A body may declare the sequence and optional types it uses in `table`.
FunctionBody :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], callables: Callable[],
                 params: Param[], table: ^(TypeDecl[]), members: TypeMember[], constants: ConstDecl[],
                 natives: ResolvedNative[], ports: ResolvedPort[], identities: u64[], aliases: Name[],
                 operators: NumericOperator[], makes: NativeMake[], make_fields: int[], index: int,
                 solid: int[], undeclared: u64, meaning: u64, context: BodyContext, generic_updates: int[],
                 ops: Ops, target: Target) -> Body {
    callable := callables[index];
    document := documents[callable.document];
    analysis_body := Field(forest, callable.node, syntax.FieldBody);
    if (analysis_body < 0) {
        return Body.Failed(Diagnose(forest, callable.node, callable.document,
                                    format_text("Callable '{}' has no body", callable.name)));
    }
    referenced: string[] = [];
    if (AnyReference(params)) {
        referenced = ReferencedNames(forest, document.text, callables, params, natives, aliases, callable.package,
                                     analysis_body);
    }
    mutated := MutatedNames(forest, document.text, analysis_body, referenced);
    built: int[] = [];
    if (callable.results == 0) {
        built = BuiltLocals(forest, document.text, table^, aliases, callable.package, analysis_body, referenced);
    }
    body_natives := natives;
    if (strings.HasPrefix(document.identity, "host:")) {
        body_natives = PackageNatives(natives, document.identity);
    }
    emitted := EmitBody(forest, document.text, callable.document, callables, params, table, members, constants,
                        body_natives, ports, identities, operators, makes, make_fields, aliases, document.key, solid,
                        undeclared, meaning, index, referenced, mutated, built, context, generic_updates, ops, target);
    switch emitted {
        case .Emitted(slots, locals, cells, code, calls, hosts, roots, points, watches, effects, direct_write, facts):
            // Read current resolved return types, including imported source
            // declarations. Ordinary optional absence remains ordinary.
            requires_check := false;
            for fact in facts {
                if fact.kind == CallFact && fact.target >= 0 && fact.target < length(callables) &&
                   ErrorResult(table^, params, callables[fact.target]) {
                    requires_check = true;
                    break;
                }
            }
            if requires_check {
                problems := FallibleBody(forest, documents, callables, params, table^, callable, facts);
                if length(problems) > 0 {
                    return Body.Failed(problems[0]);
                }
            }
        case:
            return emitted;
    }
    return emitted;
}
Assemble :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], package: int, first_document: int,
             package_names: string[], package_ids: u64[], fingerprints: u64[], reachable: bool[],
             links: graph.Binding[], callables: Callable[], params: Param[], types: TypeDecl[],
             members: TypeMember[], constants: ConstDecl[], natives: ResolvedNative[], ports: ResolvedPort[],
             identities: u64[], native_effects: int[], callable_effects: int[], ops: Ops, target: Target,
             abi: u64, game: Game, prepared: Body[], retained: StateDecl[]) -> Assembly {
    identity := package_names[package];
    module := package_ids[package];
    // A behavior's states, the event each of its functions handles, the
    // game's events and the type of the entity that owns it.
    kept_states: StateDecl[] = [];
    handled: int[] = [];
    game_events: GameEvent[] = [];
    game_fields: GameEventField[] = [];
    owner_type: u64 = 0;
    source_mode: bool = true;
    library_mode: bool = false;
    switch game {
        case .Package:
            source_mode = false;
            kept_states = retained;
        case .Library(entity, operators, globals, makes, made_fields):
            owner_type = entity;
            library_mode = true;
        case .Behavior(declared_states, handlers, declared_events, payloads, entity, operators, globals, makes,
                       made_fields):
            kept_states = declared_states;
            handled = handlers;
            game_events = declared_events;
            game_fields = payloads;
            owner_type = entity;
    }
    wide: u64[] = [0];
    values: writer.Value[] = [];
    ints: int[] = [];
    spans: writer.Span[] = [];
    functions: writer.Function[] = [];
    instructions: writer.Instruction[] = [];
    locals: writer.Local[] = [];
    parameters: writer.Parameter[] = [];
    frames: writer.Frame[] = [];
    sources: writer.Source[] = [];
    data: writer.Data[] = [];
    hosts: writer.Host[] = [];
    commands: writer.Command[] = [];
    roots: writer.Root[] = [];
    calls: writer.Call[] = [];
    references: writer.Reference[] = [];
    components: writer.Component[] = [];
    entries: writer.Entry[] = [];
    effects: int[] = [];
    for (summary in callable_effects) {
        effects.append(summary);
    }
    effect_calls: EffectCall[] = [];
    requirements: writer.Requirement[] = [];
    fields: writer.Field[] = [];
    // Each record's layout and each variant's tag, as indices into `wide`, for
    // the types of this package and those it reaches; no others can occur.
    // Shared types, such as char, the math types and game natives, belong to
    // no package; a math type is written only where this module uses it. A
    // requirement's index counts the requirements the loop below writes first.
    assembled: bool[] = [];
    requirement_indices: int[] = [];
    requirement_count: int = 0;
    for declared, at in types {
        kept := declared.kind != BuiltinScalarDecl &&
                (source_mode || declared.package < 0 || reachable[declared.package]) &&
                (declared.kind != MathDecl || MathRequired(at, types, callables, params, prepared, package) ||
                 MathStateRequired(at, types, kept_states));
        assembled.append(kept);
        index: int = -1;
        if (kept && (declared.kind == RecordDecl || declared.kind == MathDecl || declared.kind == NativeDecl ||
                     (declared.kind == PointerDecl && declared.key == 0))) {
            index = requirement_count;
            requirement_count += 1;
        }
        requirement_indices.append(index);
    }
    layouts: int[] = [];
    tags: int[] = [];
    for (declared in types) {
        layouts.append(int(0));
        tags.append(int(0));
        if (!assembled[length(layouts) - 1]) {
            continue;
        }
        if (declared.kind == VariantDecl) {
            // Stage zero's tag: the union's ID in decimal, then the variant.
            union_id := binding.ID("package-symbol",
                                   format_text("{}:{}:{}", package_names[declared.package], TypeKind, types[declared.parent].name));
            tag := binding.ID("union-variant", format_text("{}:{}", union_id, declared.name));
            if (types[declared.parent].kind == TaskResultDecl) {
                tag = declared.id;
            }
            wide.append(tag);
            tags[length(tags) - 1] = length(wide) - 1;
        } else if (declared.kind == RecordDecl || declared.kind == MathDecl) {
            id := declared.id;
            if (!source_mode && declared.kind != MathDecl) {
                id = binding.ID("package-symbol",
                                format_text("{}:{}:{}", package_names[declared.package], TypeKind, declared.name));
            }
            wide.append(id);
            wide.append(declared.layout);
            layouts[length(layouts) - 1] = length(wide) - 1;
            requirement: writer.Requirement = {id: length(wide) - 2, layout: length(wide) - 1, storage: StructStorage,
                                               name: declared.type_name, size: declared.size, authored: true, first: length(fields),
                                               count: declared.count};
            requirements.append(requirement);
            at := declared.first;
            while (at < declared.first + declared.count) {
                field: writer.Field = {name: members[at].name, kind: members[at].storage,
                                       container: members[at].container, record: -1, type_name: "",
                                       has_type_name: false, unit: "", has_unit: false};
                if (members[at].storage == StructStorage) {
                    field.record = requirement_indices[members[at].record];
                }
                if (members[at].storage == PointerStorage || members[at].storage == StructStorage ||
                    (members[at].storage == UnionStorage && members[at].record >= 0)) {
                    field.type_name = types[members[at].record].type_name;
                    field.has_type_name = true;
                }
                fields.append(field);
                at += 1;
            }
        } else if (declared.kind == PointerDecl && declared.key == 0) {
            wide.append(declared.id);
            pointer_requirement: writer.Requirement = {id: length(wide) - 1, layout: 0, storage: declared.storage,
                                                       name: declared.type_name, size: target.pointer_size,
                                                       authored: false, first: 0, count: 0};
            requirements.append(pointer_requirement);
        } else if (declared.kind == NativeDecl) {
            wide.append(declared.id);
            wide.append(declared.layout);
            layouts[length(layouts) - 1] = length(wide) - 1;
            requirement: writer.Requirement = {id: length(wide) - 2, layout: length(wide) - 1, storage: declared.storage,
                                               name: declared.type_name, size: declared.size, authored: false, first: 0,
                                               count: 0};
            requirements.append(requirement);
        }
    }
    abi_one := length(wide);
    wide.append(u64(1));
    // A package's functions are contiguous; the module numbers them from 0.
    first_own: int = 0;
    while (first_own < length(callables) && callables[first_own].owner_package != package) {
        first_own += 1;
    }
    // The packages this module calls into, each an import row.
    imported: int[] = [];
    imports: writer.Import[] = [];
    points: writer.Point[] = [];
    watches: writer.Watch[] = [];
    index := first_own;
    while (index < length(callables) && callables[index].owner_package == package) {
        callable := callables[index];
        handler: int = -1;
        if (index - first_own < length(handled)) {
            handler = handled[index - first_own];
        }
        tables := prepared[index];
        switch tables {
            case .Failed(diagnostic):
                return Assembly.Rejected(diagnostic);
            case .Specialize(template, call, arguments, caller_names):
                return AssemblyFailure(callable.document, "unresolved generic call");
            case .Inferred(value):
                return AssemblyFailure(callable.document, "expression inferred where a callable body was required");
            case .Emitted(body_slots, body_locals, body_cells, body_code, body_calls, body_hosts, body_roots,
                          body_points, body_watches, body_effects, body_write, body_facts):
                direct_effects := body_effects;
                if (library_mode) {
                    for (instruction in body_code) {
                        if (instruction.op == ops.owner) {
                            direct_effects = direct_effects | InvocationReadEffect;
                        }
                    }
                }
                host_indices: int[] = [];
                command_indices: int[] = [];
                host_count: int = 0;
                command_count: int = 0;
                for (operation in body_hosts) {
                    host_indices.append(host_count);
                    command_indices.append(command_count);
                    if (operation.command == 0) {
                        host_count += 1;
                    } else {
                        command_count += 1;
                    }
                }
                base := length(spans);
                argument_count := callable.count;
                spans.append(Range(length(values), argument_count));
                at: int = 0;
                while (at < argument_count) {
                    values.append(ParamHeader(params[callable.first + at], types, layouts, target));
                    at += 1;
                }
                spans.append(Range(length(ints), argument_count));
                at = 0;
                while (at < argument_count) {
                    kind: int = 0;
                    if (params[callable.first + at].reference) {
                        kind = ReferenceKind;
                    }
                    ints.append(kind);
                    at += 1;
                }
                // Result defaults and kinds: the one result, or each named one.
                result_count := callable.results;
                if (callable.result != 0) {
                    result_count = 1;
                }
                spans.append(Range(length(values), result_count));
                if (callable.result != 0) {
                    values.append(Header(callable.result, callable.result_container, callable.result_record,
                                         types, layouts));
                }
                at = 0;
                while (at < callable.results) {
                    named := params[callable.first + callable.count + at];
                    values.append(Header(named.storage, named.container, named.record, types, layouts));
                    at += 1;
                }
                spans.append(Range(length(ints), result_count));
                at = 0;
                while (at < result_count) {
                    ints.append(int(0));
                    at += 1;
                }
                // A behavior's states are each function's variables.
                spans.append(Range(length(values), length(kept_states)));
                for (kept in kept_states) {
                    values.append(StateValue(kept, types, layouts, length(wide)));
                    wide.append(kept.bits);
                }
                spans.append(Range(length(ints), length(body_slots)));
                for (slot in body_slots) {
                    ints.append(slot.storage);
                }
                spans.append(Range(length(ints), length(body_slots)));
                for (slot in body_slots) {
                    ints.append(slot.kind);
                }
                // Record and array pointers each slot may hold while the function waits.
                spans.append(Range(length(roots), length(body_roots)));
                for (root in body_roots) {
                    values.append(Header(root.storage, root.container, root.record, types, layouts));
                    row: writer.Root = {bank: 0, index: root.slot, shape: length(values) - 1};
                    roots.append(row);
                }
                // Instructions, each with its own value row and its origin's source row.
                // The instructions of one expression share its origin, so each
                // run of equal origins is one source row: in a self-compile
                // about three instructions in four repeat the previous origin.
                // origins[pc] is the instruction's row, counted from 1; row 0
                // is the empty origin.
                origins: int[] = [];
                rows: int = 0;
                for (code, at in body_code) {
                    if (at == 0 || code.start != body_code[at - 1].start || code.end != body_code[at - 1].end ||
                        code.line != body_code[at - 1].line || code.column != body_code[at - 1].column) {
                        rows += 1;
                    }
                    origins.append(rows);
                }
                spans.append(Range(length(instructions), length(body_code)));
                pc: int = 0;
                for (body_instruction in body_code) {
                    code := body_instruction;
                    if (code.op == ops.host_call) {
                        code.target = host_indices[code.target];
                    }
                    if (code.op == ops.command_begin) {
                        code.target = command_indices[code.target];
                    }
                    node_id: int = 0;
                    if (code.op == ops.command_begin || code.op == ops.suspend) {
                        wide.append(code.payload);
                        node_id = length(wide) - 1;
                        code.payload = 0;
                    }
                    value := Header(code.value_storage, code.value_container, code.value_record, types, layouts);
                    if (code.has_text) {
                        value.text = code.text;
                        value.has_text = true;
                    }
                    if (code.payload != 0) {
                        value.wide = length(wide);
                        wide.append(code.payload);
                    }
                    values.append(value);
                    row: writer.Instruction = {op: code.op, type: code.type, output: code.output,
                                               left: code.left, right: code.right, target: code.target, source: origins[pc],
                                               offset: code.offset, node: node_id, value: length(values) - 1,
                                               message: code.message, has_message: code.has_message};
                    instructions.append(row);
                    pc += 1;
                }
                spans.append(Range(length(locals), length(body_locals)));
                for (body_local in body_locals) {
                    values.append(ScalarValue(body_local.storage, 0));
                    local: writer.Local = {kind: body_local.kind, initial: length(values) - 1, frame: 0, node: 0, pin: 0,
                                           offset: 0, parameter: false, array_default: false, data_index: 0};
                    locals.append(local);
                }
                spans.append(Range(length(parameters), callable.count));
                at = 0;
                while (at < callable.count) {
                    values.append(ParamHeader(params[callable.first + at], types, layouts, target));
                    parameter: writer.Parameter = {initial: length(values) - 1, frame: 0, pin: 0};
                    parameters.append(parameter);
                    at += 1;
                }
                // One frame with an empty origin, then the instruction origins.
                sources.append(NoSource());
                frame: writer.Frame = {source: length(sources) - 1, depth: 0, resume: 0, source_index: 0, stack: -1};
                spans.append(Range(length(frames), 1));
                frames.append(frame);
                spans.append(Range(length(sources), rows + 1));
                sources.append(NoSource());
                asset := documents[callable.document].key;
                for (code, at in body_code) {
                    if (at == 0 || origins[at] != origins[at - 1]) {
                        source := NoSource();
                        source.asset = asset;
                        source.has_asset = true;
                        source.start = code.start;
                        source.end = code.end;
                        source.line = code.line;
                        source.column = code.column;
                        sources.append(source);
                    }
                }
                spans.append(Range(0, 0));
                spans.append(Range(0, 0));
                // Data cells: record cells own a buffer of the record's size;
                // others may hold a constant or a variant's tag.
                spans.append(Range(length(data), length(body_cells)));
                for (cell in body_cells) {
                    value := Header(cell.storage, cell.container, cell.record, types, layouts);
                    size: int = 0;
                    if (cell.storage == StructStorage && cell.container == 0) {
                        size = types[cell.record].size;
                    }
                    if (cell.variant >= 0) {
                        value.wide = tags[cell.variant];
                    } else if (cell.constant != 0) {
                        value.wide = length(wide);
                        wide.append(cell.constant);
                    }
                    values.append(value);
                    datum: writer.Data = {kind: cell.kind, initial: length(values) - 1, size: size};
                    data.append(datum);
                }
                spans.append(Range(length(hosts), host_count));
                for (host in body_hosts) {
                    if (host.command != 0) {
                        continue;
                    }
                    capability := length(wide);
                    host_abi := abi_one;
                    if (host.linked >= 0) {
                        direct_effects = direct_effects | native_effects[host.linked];
                        wide.append(identities[2 * host.linked]);
                        wide.append(identities[2 * host.linked + 1]);
                        host_abi = capability + 1;
                    } else {
                        wide.append(IntrinsicBase | u64(host.intrinsic));
                    }
                    row: writer.Host = {owned_arguments: host.owned_arguments, capability: capability, abi: host_abi, first: host.first,
                                        result_first: host.result_first, result_count: host.result_count, outcome_first: 0,
                                        outcome_count: 0};
                    hosts.append(row);
                }
                spans.append(Range(length(commands), command_count));
                for (operation in body_hosts) {
                    if (operation.command == 0) {
                        continue;
                    }
                    wide.append(TaskCommandBase | u64(operation.command));
                    command_abi: u64 = 2;
                    if (operation.command == DelayCommand) {
                        command_abi = 1;
                    }
                    wide.append(command_abi);
                    wide.append(TaskCommandNode(operation.command, operation.syntax_node));
                    command: writer.Command = {capability: length(wide) - 3, abi: length(wide) - 2,
                                               first: operation.first, count: operation.result_first - operation.first,
                                               node: length(wide) - 1, result_first: operation.result_first,
                                               result_count: operation.result_count};
                    commands.append(command);
                    if (operation.command == CancelCommand || operation.command == CancelAfterCommand) {
                        direct_effects = direct_effects | WriteEffect;
                    } else {
                        direct_effects = direct_effects | SuspendEffect;
                    }
                }
                // The command banks use the same stable cell coordinates as the
                // body's host banks. Each has independent mutable payload storage.
                command_cells: int = 0;
                if (command_count > 0) {
                    command_cells = length(body_cells);
                }
                spans.append(Range(length(values), command_cells));
                at = 0;
                while (at < command_cells) {
                    cell := body_cells[at];
                    initial := Header(cell.storage, cell.container, cell.record, types, layouts);
                    if (cell.constant != 0) {
                        wide.append(cell.constant);
                        initial.wide = length(wide) - 1;
                    }
                    if (cell.variant >= 0) {
                        initial.wide = tags[cell.variant];
                    }
                    values.append(initial);
                    at += 1;
                }
                spans.append(Range(length(ints), command_cells));
                at = 0;
                while (at < command_cells) {
                    ints.append(ValueKind);
                    at += 1;
                }
                spans.append(Range(length(values), command_cells));
                at = 0;
                while (at < command_cells) {
                    cell := body_cells[at];
                    values.append(Header(cell.storage, cell.container, cell.record, types, layouts));
                    at += 1;
                }
                spans.append(Range(length(ints), command_cells));
                at = 0;
                while (at < command_cells) {
                    ints.append(ValueKind);
                    at += 1;
                }
                spans.append(Range(length(calls), length(body_calls)));
                for (invocation in body_calls) {
                    effect_call: EffectCall = {caller: index, callee: invocation.callee, task: invocation.task};
                    effect_calls.append(effect_call);
                    callee := callables[invocation.callee];
                    if (callee.owner_package == package) {
                        references.append(Own(invocation.callee - first_own));
                    } else {
                        row := Position(imported, callee.owner_package);
                        if (row < 0) {
                            imported.append(callee.owner_package);
                            wide.append(package_ids[callee.owner_package]);
                            wide.append(fingerprints[callee.owner_package]);
                            dependency: writer.Import = {id: length(wide) - 2, fingerprint: length(wide) - 1};
                            imports.append(dependency);
                            row = length(imports) - 1;
                        }
                        called_id := CallableIdentity(package_names, callee);
                        if (source_mode) {
                            called_id = binding.ID("symbol", format_text("{}:1:{}:callable", package_names[callee.package], callee.name));
                        }
                        wide.append(called_id);
                        imported_reference: writer.Reference = {imported: row, own: 0, function: length(wide) - 1, role: 0};
                        references.append(imported_reference);
                    }
                    call: writer.Call = {owned_arguments: invocation.owned_arguments, function: length(references) - 1, first: invocation.first,
                                         count: invocation.count, result_first: invocation.result_first,
                                         result_count: invocation.result_count, task: invocation.task};
                    calls.append(call);
                }
                // No definitions; then the components the body reads or
                // writes through references, each once, and each write.
                spans.append(Range(0, 0));
                written := ComponentsOf(body_cells, body_hosts, true);
                reached := Distinct(ComponentsOf(body_cells, body_hosts, false));
                effects[index] = direct_effects;
                if (source_mode) {
                    effects[index] = effects[index] | Effects(ops, body_code, length(reached) != 0, length(written) != 0);
                }
                spans.append(Range(length(components), length(reached)));
                for (component_id in reached) {
                    reached_row: writer.Component = {id: length(wide), binding: false};
                    components.append(reached_row);
                    wide.append(component_id);
                }
                spans.append(Range(length(ints), length(written)));
                for (component_id in written) {
                    ints.append(length(wide));
                    wide.append(component_id);
                }
                spans.append(Range(length(points), length(body_points)));
                for (point in body_points) {
                    wide.append(point.occurrence);
                    wide.append(point.meaning);
                    row: writer.Point = {occurrence: length(wide) - 2, meaning: length(wide) - 1, start: point.start,
                                         end: point.end, line: point.line, column: point.column, kind: point.kind,
                                         completion: point.completion};
                    points.append(row);
                }
                // Each watch's origin is a point of its own, past the
                // function's points, and its initial value the type's header.
                spans.append(Range(length(watches), length(body_watches)));
                for (watched in body_watches) {
                    wide.append(watched.occurrence);
                    wide.append(u64(0));
                    origin: writer.Point = {occurrence: length(wide) - 2, meaning: length(wide) - 1,
                                            start: watched.start, end: watched.end, line: watched.line,
                                            column: watched.column, kind: ExpressionRecord, completion: false};
                    points.append(origin);
                    // A behavior's handles are its entities.
                    watched_record := watched.record;
                    if (watched.storage == HandleStorage && watched_record < 0 && owner_type != 0) {
                        watched_record = TypeWithId(types, owner_type);
                    }
                    values.append(Header(watched.storage, watched.container, watched_record, types, layouts));
                    row: writer.Watch = {origin: length(points) - 1, initial: length(values) - 1,
                                         ordinal: watched.ordinal, output: watched.output, reference: watched.reference};
                    watches.append(row);
                }
                while (length(spans) < base + writer.Tables) {
                    spans.append(Range(0, 0));
                }
                head: writer.Function = {argument_count: argument_count, result_count: result_count,
                                         variable_count: length(kept_states), root_steps: 0, child_budget: 0,
                                         depth_bound: 0, pure_depth_limit: 0, breakpoints: false, batchable: false,
                                         managed: false, custom_lowering: false, checkpoints: false, pin_watches: false,
                                         watch_size: 0, component_bindings: false, component_access: length(reached) != 0,
                                         spans: base};
                functions.append(head);
                references.append(Own(index - first_own));
                references.append(Own(-1));
                if (handler >= 0) {
                    // Stage zero's handler ID: the source, the handler's offset and its kind.
                    handled_event := game_events[handler];
                    function_kind := HandlerFunction;
                    wide.append(binding.ID("function", format_text("{}:{}:{}", identity,
                                                                   forest[callable.node].start, function_kind)));
                    wide.append(handled_event.id);
                    wide.append(handled_event.abi);
                    wide.append(u64(0));
                    row: writer.Entry = {id: length(wide) - 4, kind: function_kind, entry_name: "", has_entry: false,
                                         event_id: length(wide) - 3, event_abi: length(wide) - 2,
                                         event_name: handled_event.name, has_event_name: true, continuation_wait: false,
                                         effects: length(wide) - 1, body: length(references) - 2,
                                         subscription: length(references) - 1};
                    entries.append(row);
                } else if (source_mode) {
                    // A behavior's member procedure is a symbol of its source's scope.
                    // Stage zero lets every authored function wait.
                    wide.append(binding.ID("symbol", format_text("{}:1:{}:callable", identity,
                                                                 callable.name)));
                    procedure: writer.Entry = {id: length(wide) - 1, kind: 0, entry_name: "", has_entry: false,
                                               event_id: 0, event_abi: 0, event_name: "", has_event_name: false,
                                               continuation_wait: true, effects: 0, body: length(references) - 2,
                                               subscription: length(references) - 1};
                    entries.append(procedure);
                } else {
                    wide.append(CallableIdentity(package_names, callable));
                    exported_name := callable.name;
                    attributes := ReadAttributes(forest, documents[callable.document].text, callable.node);
                    if (attributes.fault >= 0) {
                        return Assembly.Rejected(Diagnose(forest, attributes.fault, callable.document, attributes.message));
                    }
                    if (attributes.test) {
                        if (callable.count != 0 || callable.results != 0 || callable.result != 0) {
                            return Assembly.Rejected(Diagnose(forest, callable.node, callable.document,
                                                              "A @test function takes no parameters and returns nothing"));
                        }
                        // A package test is exported as "@test NAME", so the host that runs tests
                        // finds the tests among a module's entries.
                        exported_name = format_text("@test {}", callable.name);
                    }
                    exported: writer.Entry = {id: length(wide) - 1, kind: 0, entry_name: exported_name, has_entry: true,
                                              event_id: 0, event_abi: 0, event_name: "", has_event_name: false,
                                              continuation_wait: false, effects: 0, body: length(references) - 2,
                                              subscription: length(references) - 1};
                    entries.append(exported);
                }
        }
        index += 1;
    }
    // A local cycle reaches a fixed point; imported callees already carry
    // the summaries computed when their dependency modules were assembled.
    changed := true;
    while (changed) {
        changed = false;
        for (called in effect_calls) {
            inherited := effects[called.callee];
            if (called.task) {
                inherited = inherited & ~SuspendEffect;
            }
            combined := effects[called.caller] | inherited;
            if (combined != effects[called.caller]) {
                effects[called.caller] = combined;
                changed = true;
            }
        }
    }
    at_entry: int = 0;
    while (at_entry < length(entries)) {
        declared := entries[at_entry];
        wide.append(u64(effects[first_own + at_entry]));
        declared.effects = length(wide) - 1;
        entries[at_entry] = declared;
        at_entry += 1;
    }
    // The events the handlers take, each once, in the order they first do.
    event_declarations: writer.Event[] = [];
    event_fields: writer.EventField[] = [];
    listed: int[] = [];
    for (handler in handled) {
        if (handler < 0 || Position(listed, handler) >= 0) {
            continue;
        }
        listed.append(handler);
        handled_event := game_events[handler];
        wide.append(handled_event.id);
        wide.append(handled_event.abi);
        declared: writer.Event = {id: length(wide) - 2, abi: length(wide) - 1, name: handled_event.name,
                                  first: length(event_fields), count: handled_event.count};
        event_declarations.append(declared);
        at := handled_event.first;
        while (at < handled_event.first + handled_event.count) {
            payload := game_fields[at];
            values.append(ScalarValue(payload.storage, 0));
            wide.append(payload.nominal);
            field: writer.EventField = {name: payload.name, nominal: length(wide) - 1, has_default: payload.has_default,
                                        default_owner: payload.default_owner, initial: length(values) - 1};
            event_fields.append(field);
            at += 1;
        }
    }
    states: writer.State[] = [];
    for (kept in kept_states) {
        values.append(StateValue(kept, types, layouts, length(wide)));
        wide.append(kept.bits);
        wide.append(kept.id);
        row: writer.State = {id: length(wide) - 1, initial: length(values) - 1, shared: false, contains_tasks: false};
        states.append(row);
    }
    layouts_table: writer.ResultLayout[] = [];
    queries: writer.Query[] = [];
    descriptions: writer.QueryDescription[] = [];
    system_root: int = -1;
    system_variables: int = 0;
    system_description: int = 0;
    return Assembly.Compiled(module, writer.Write(writer.Module.Tables(module, owner_type, abi, target.pointer_size, wide, values, ints, requirements,
                                                                       fields, event_declarations, event_fields, imports, functions, spans, roots, instructions,
                                                                       locals, parameters, frames, sources, layouts_table, data, hosts, commands, calls,
                                                                       references, components, points, watches, states, entries,
                                                                       queries, system_root, system_variables, 0, descriptions,
                                                                       system_description)), effects);
}

// The attributes before a function declaration: `@test` marks a package test,
// and nothing else is an attribute. `fault` is the node of the first one that
// is unknown or repeated, -1 when there is none.
Attributes :: struct {
    test: bool;
    fault: int;
    message: string;
}
ReadAttributes :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> Attributes {
    read: Attributes = {test: false, fault: -1, message: ""};
    for (member in Members(forest, node)) {
        if (!Is(forest, member, syntax.Attribute)) {
            continue;
        }
        name := Text(forest, text, Field(forest, member, syntax.FieldName));
        if (name != "test") {
            read.fault = member;
            read.message = format_text("Unknown attribute '@{}'", name);
            return read;
        }
        if (read.test) {
            read.fault = member;
            read.message = "Duplicate attribute '@test'";
            return read;
        }
        read.test = true;
    }
    return read;
}
// `paths` and `sources` are the files of every package, `paths[0]` one of the
// root package's; `project` and each named collection are roots that paths
// and imports resolve against. `abi` is the target's prepared header ABI,
// `names` its instruction names in ordinal order, and `natives` the native
// functions it links.
pub Compile :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                sources: string[], debug: bool, target: Target, abi: u64, names: string[], natives: Native[],
                ports: Port[], identities: u64[]) -> (module: u64, bytes: u8[], error: syntax.Diagnostic?) {
    compiled := CompileWithEffects(project, collection_names, collection_paths, paths, sources, debug, target, abi,
                                   names, natives, ports, identities, resize([int(0)], length(natives)));
    return (compiled.module, compiled.bytes, compiled.error);
}
// The complete target catalog supplies one effect mask per native, in the
// same order as natives and identities. Compile supplies zero effect masks
// for its verified pure-native catalog.
pub CompileWithEffects :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                           sources: string[], debug: bool, target: Target, abi: u64, names: string[], natives: Native[],
                           ports: Port[], identities: u64[], native_effects: int[])
-> (module: u64, bytes: u8[], error: syntax.Diagnostic?) {
    switch CompileInput(project, collection_names, collection_paths, paths, sources, debug, target, abi,
                        names, natives, ports, identities, native_effects) {
        case .Rejected(diagnostic):
            return (0, [], diagnostic);
        case .Compiled(compiled_module, prepared):
            return (compiled_module, prepared, nil);
    }
}
// Whether `path` is the file of the core collection's target package, whose
// text a compile with a platform replaces.
TargetPackagePath :: (collection_names: string[], collection_paths: string[], path: string) -> bool {
    index: int = 0;
    while (index < length(collection_names)) {
        if (collection_names[index] == "core" && path == format_text("{}/target/Target.chibi", collection_paths[index])) {
            return true;
        }
        index += 1;
    }
    return false;
}
// The constants of core:target for a platform: os 1 Linux, 2 Darwin, 3 Windows;
// arch 1 x86-64, 2 Arm64; native 1 for a native program, 0 for the VM.
TargetPackageText :: (os: int, arch: int, pointer_bits: int, native: int) -> string {
    return format_text("package target\n\npub Linux: int : 1\npub Darwin: int : 2\npub Windows: int : 3\n\npub X86_64: int : 1\npub Arm64: int : 2\n\npub Os: int : {}\npub Arch: int : {}\npub PointerBits: int : {}\n\npub Native: int : {}\n", os, arch, pointer_bits, native);
}
CompileInput :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                 sources: string[], debug: bool, target: Target, abi: u64, names: string[], natives: Native[],
                 ports: Port[], identities: u64[], native_effects: int[]) -> Result {
    no_types: TypeDecl[] = [];
    no_members: TypeMember[] = [];
    return CompileResolved(project, collection_names, collection_paths, paths, sources, debug, target, abi, names,
                           LegacyNatives(natives, names), LegacyPorts(ports), identities, native_effects, no_types,
                           no_members, 0, 0);
}
// The same compile for a resolved native catalog. `seed_types` and
// `seed_members` are the catalog's native types, which every package shares.
CompileResolved :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                    sources: string[], debug: bool, target: Target, abi: u64, names: string[],
                    resolved_natives: ResolvedNative[], resolved_ports: ResolvedPort[], identities: u64[],
                    native_effects: int[], seed_types: TypeDecl[], seed_members: TypeMember[], os: int,
                    arch: int) -> Result {
    ops := ResolveOps(names, debug);
    complete := NativeInputValid(resolved_natives, resolved_ports, identities, native_effects);
    if (abi == 0 || !Complete(ops) || !complete || length(paths) == 0 || length(paths) != length(sources) ||
        length(collection_names) != length(collection_paths)) {
        return InputFailure(-1, "unsupported compiler input or target");
    }
    collections: routes.Collection[] = [];
    index: int = 0;
    while (index < length(collection_names)) {
        collection: routes.Collection = {name: collection_names[index], path: collection_paths[index], has_name: true,
                                         has_path: true};
        collections.append(collection);
        index += 1;
    }
    inputs: snapshot.Input[] = [];
    sizes: u64[] = [];
    index = 0;
    while (index < length(paths)) {
        text := sources[index];
        if (os != 0 && TargetPackagePath(collection_names, collection_paths, paths[index])) {
            text = TargetPackageText(os, arch, target.pointer_size * 8, 0);
        }
        input: snapshot.Input = {path: paths[index], text: text, has_path: true, has_text: true};
        inputs.append(input);
        sizes.append(u64(strings.ByteLength(text)));
        index += 1;
    }
    options: snapshot.Options = {project: project, has_project: true, has_options: true,
                                 has_files: true, has_collections: length(collections) != 0, file_count: length(inputs),
                                 collection_count: length(collections)};
    switch snapshot.Build(options, collections, inputs, sizes) {
        case .Rejected(diagnostic, related, graph_error, cycle, documents, nodes, imports):
            return Result.Rejected(diagnostic);
        case .Accepted(roots, documents, nodes, imports, built):
            switch ForeignNatives(nodes, documents, resolved_natives, resolved_ports, identities, native_effects) {
                case .Failed(diagnostic):
                    return Result.Rejected(diagnostic);
                case .Declared(foreign_natives, foreign_ports, foreign_identities, foreign_effects):
                    resolved_natives = foreign_natives;
                    resolved_ports = foreign_ports;
                    identities = foreign_identities;
                    native_effects = foreign_effects;
            }
            switch built {
                case .Rejected(error, cycle):
                    return InputFailure(-1, "package graph is invalid");
                case .Accepted(packages, files_of, file_packages, order, edges, links):
                    switch DeclareSeeded(nodes, documents, packages, files_of, order, edges, file_packages[0], imports, links,
                                         target, seed_types, seed_members) {
                        case .Failed(diagnostic):
                            return Result.Rejected(diagnostic);
                        case .Declared(callables, params, types, members, constants, active_order, bound, kept):
                            return Link(nodes, documents, packages, files_of, file_packages[0], active_order, kept, bound,
                                        callables, params, types, members, constants, resolved_natives, resolved_ports, identities, native_effects, ops, target,
                                        abi);
                    }
            }
    }
}
// A compile against the target's reflected catalog: its native types, with
// their fields, and the native ports that name them. `entity` is the entity
// type's identity.
pub CompileWithCatalog :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                           sources: string[], debug: bool, target: Target, abi: u64, names: string[],
                           natives: CatalogNative[], ports: CatalogPort[], identities: u64[], types: GameType[],
                           type_fields: GameField[], entity: u64, os: int, arch: int, native_effects: int[])
-> (module: u64, bytes: u8[], error: syntax.Diagnostic?) {
    native_types := NativeTypes(types);
    switch CompileResolved(project, collection_names, collection_paths, paths, sources, debug, target, abi, names,
                           CatalogNatives(natives), CatalogPorts(ports, native_types, entity), identities,
                           native_effects, native_types, NativeFields(type_fields), os, arch) {
        case .Rejected(diagnostic):
            return (0, [], diagnostic);
        case .Compiled(compiled_module, prepared):
            return (compiled_module, prepared, nil);
    }
}
pub CompileClosureWithCatalog :: (project: string, collection_names: string[], collection_paths: string[],
                                  paths: string[], sources: string[], debug: bool, target: Target, abi: u64,
                                  names: string[], natives: CatalogNative[], ports: CatalogPort[], identities: u64[],
                                  types: GameType[], type_fields: GameField[], entity: u64, os: int, arch: int,
                                  native_effects: int[]) -> u8[] {
    compiled := CompileWithCatalog(project, collection_names, collection_paths, paths, sources, debug, target, abi,
                                   names, natives, ports, identities, types, type_fields, entity, os, arch,
                                   native_effects);
    if (compiled.error) {
        return [];
    }
    return compiled.bytes;
}
// Compile's closure, for a host that takes one byte[] result; empty when
// Compile rejects the input, whose diagnostic Compile returns.
pub CompileClosure :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                       sources: string[], debug: bool, target: Target, abi: u64, names: string[],
                       natives: Native[], ports: Port[], identities: u64[]) -> u8[] {
    compiled := Compile(project, collection_names, collection_paths, paths, sources, debug, target, abi,
                        names, natives, ports, identities);
    if (compiled.error) {
        return [];
    }
    return compiled.bytes;
}
pub CompileClosureWithEffects :: (project: string, collection_names: string[], collection_paths: string[], paths: string[],
                                  sources: string[], debug: bool, target: Target, abi: u64, names: string[],
                                  natives: Native[], ports: Port[], identities: u64[], native_effects: int[]) -> u8[] {
    compiled := CompileWithEffects(project, collection_names, collection_paths, paths, sources, debug, target, abi,
                                   names, natives, ports, identities, native_effects);
    if (compiled.error) {
        return [];
    }
    return compiled.bytes;
}
package package_compiler

import snapshot "project:source_snapshot"
import graph "project:package_graph"
import syntax "project:syntax_diagnostics"
import tk "project:source_tokenizer"

// Compile-time execution of authored functions. A constant initializer may
// call a function of any package whose parameters and result are integers,
// bool, arrays of them, or records of them: the body runs on the compiler, with
// locals (arrays and records too), assignment (plain, compound, by element and
// by field), `append`, `if`, `while`,
// `for` over a range or an array, `break`, `continue` and `return`.
// Expressions reuse the exact constant evaluator, so arithmetic keeps its
// range checks and a result that does not fit its type is an error, not a
// wrap. Each evaluation has a step budget and a call-depth limit.
CtSteps: int : 65536;
CtDepth: int : 128;
// A row's element type is a storage code below this; at or above it the row is
// the fields of the record whose declaration is `CtRecord` less.
CtRecord: int : 1048576;

// What the compiler knows while it runs a function, read-only except `steps`.
CtContext :: struct {
    forest: snapshot.SnapshotNode[];
    documents: snapshot.Document[];
    links: graph.Binding[];
    callables: Callable[];
    params: Param[];
    constants: ConstDecl[];
    types: TypeDecl[];
    members: TypeMember[];
    steps: int;
}
// The locals of one activation, innermost last. A local's storage is its
// type, or the negation of its row type when it is an array or a record, whose
// elements or field values are in `arrays`.
CtFrame :: struct {
    names: string[];
    bits: u64[];
    storages: int[];
    arrays: CtRow[];
}
// The elements of one array local, or the fields of a record local.
CtRow :: struct {
    items: u64[];
}

CtResult :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Waiting
    | Value(bits: u64, storage: int)
    | Elements(values: u64[], storage: int)
}
CtFlow :: union {
    Failed(diagnostic: syntax.Diagnostic)
    | Waiting
    | Normal
    | Returned(bits: u64, storage: int)
    | ReturnedElements(values: u64[], storage: int)
    | Broke
    | Continued
}

// The constant `name` of an activation, its current value.
CtLocal :: (name: string, package: int, file: int, storage: int, bits: u64) -> ConstDecl {
    return {name: name, package: package, storage: storage, bits: bits, node: -1, file: file, folded: true,
            occurrence: 0};
}
// What an expression of an activation reads: the nodes already evaluated, its
// scalar locals, innermost first, then the constants.
CtScope :: (constants: ConstDecl[], package: int, file: int, frame: ^CtFrame, memo: ConstDecl[]) -> ConstDecl[] {
    scope := memo;
    at := length(frame.names) - 1;
    while (at >= 0) {
        if (frame.storages[at] > 0) {
            scope.append(CtLocal(frame.names[at], package, file, frame.storages[at], frame.bits[at]));
        }
        at -= 1;
    }
    scope.extend(constants);
    return scope;
}
// The memo constant standing for the evaluated node, -1 for none. Memo
// constants have no name and come first, so the search ends at the first name.
FindMemo :: (constants: ConstDecl[], node: int) -> int {
    index: int = 0;
    while (index < length(constants) && constants[index].name == "") {
        if (constants[index].node == node) {
            return index;
        }
        index += 1;
    }
    return -1;
}
// The function a call names, in `package` or through an import alias; -1 when
// it names none.
CtCallee :: (context: ^CtContext, package: int, file: int, call: int) -> int {
    text := context.documents[file].text;
    function := Field(context.forest, call, syntax.FieldFunction);
    if (Is(context.forest, function, syntax.Identifier)) {
        return FindCallable(context.callables, package, Text(context.forest, text, function));
    }
    if (Is(context.forest, function, syntax.MemberExpression)) {
        home := QualifierOf(context.forest, text, Aliases(context.links, file), package,
                            Field(context.forest, function, syntax.FieldObject));
        if (home < 0) {
            return -1;
        }
        return FindCallable(context.callables, home, Text(context.forest, text, Field(context.forest, function, syntax.FieldMember)));
    }
    return -1;
}
// Whether `call` is `length(array)`.
CtLength :: (context: ^CtContext, package: int, file: int, call: int) -> bool {
    function := Field(context.forest, call, syntax.FieldFunction);
    return Is(context.forest, call, syntax.CallExpression) && Is(context.forest, function, syntax.Identifier) &&
           Text(context.forest, context.documents[file].text, function) == "length" &&
           CtCallee(context, package, file, call) < 0;
}
// Whether `node` reads a field of a record local or of a call's record result.
CtFieldRead :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, node: int) -> bool {
    if (!Is(context.forest, node, syntax.MemberExpression)) {
        return false;
    }
    object := Unparenthesized(context.forest, Field(context.forest, node, syntax.FieldObject));
    if (CtArrayLocal(context, file, frame, object) >= 0) {
        return true;
    }
    if (!Is(context.forest, object, syntax.CallExpression)) {
        return false;
    }
    callee := CtCallee(context, package, file, object);
    return callee >= 0 && context.callables[callee].result == StructStorage &&
           context.callables[callee].result_container == 0;
}
// Appends the outermost nodes of the expression `node` that run before it is
// folded: calls of authored functions, `length(array)`, `array[index]` and
// `record.field`. Their own operands are evaluated with them.
CtCollect :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, node: int, out: ^(int[])) {
    if (node < 0) {
        return;
    }
    if (Is(context.forest, node, syntax.IndexExpression) || CtFieldRead(context, package, file, frame, node) ||
        (Is(context.forest, node, syntax.CallExpression) &&
         (CtCallee(context, package, file, node) >= 0 || CtLength(context, package, file, node)))) {
        out.append(node);
        return;
    }
    for (child in Members(context.forest, node)) {
        CtCollect(context, package, file, frame, child, out);
    }
}
// Whether `node` is a condition: a comparison, a logical operation, `not`, or
// a boolean literal, local or call.
CtBoolean :: (forest: snapshot.SnapshotNode[], text: string, scope: ConstDecl[], aliases: Name[], package: int,
              node: int) -> bool {
    value := Unparenthesized(forest, node);
    if (Is(forest, value, syntax.Boolean)) {
        return true;
    }
    named := ConstantOf(forest, text, scope, aliases, package, value);
    if (named >= 0) {
        return scope[named].storage == BoolStorage;
    }
    if (Is(forest, value, syntax.CallExpression)) {
        return Text(forest, text, Field(forest, value, syntax.FieldFunction)) == "not";
    }
    if (Is(forest, value, syntax.UnaryExpression)) {
        operator := Operator(forest, value);
        return operator == tk.NotKeyword || operator == tk.Not;
    }
    if (Is(forest, value, syntax.BinaryExpression)) {
        operator := Operator(forest, value);
        return ComparisonOperator(operator) || operator == tk.AndKeyword || operator == tk.CmpAnd || operator == tk.OrKeyword ||
               operator == tk.CmpOr;
    }
    return false;
}
CtFail :: (context: ^CtContext, node: int, file: int, message: string) -> syntax.Diagnostic {
    return Diagnose(context.forest, node, file, message);
}
// Counts a step against the budget; false once it is spent.
CtStep :: (context: ^CtContext, node: int, file: int) -> bool {
    context.steps += 1;
    return context.steps <= CtSteps;
}
// The index of local `name`, the newest first; -1 for none.
CtLookup :: (frame: ^CtFrame, name: string) -> int {
    at := length(frame.names) - 1;
    while (at >= 0) {
        if (frame.names[at] == name) {
            return at;
        }
        at -= 1;
    }
    return -1;
}
// The array or record local that `node` names, -1 when it names none.
CtArrayLocal :: (context: ^CtContext, file: int, frame: ^CtFrame, node: int) -> int {
    value := Unparenthesized(context.forest, node);
    if (!Is(context.forest, value, syntax.Identifier)) {
        return -1;
    }
    at := CtLookup(frame, Text(context.forest, context.documents[file].text, value));
    if (at >= 0 && frame.storages[at] < 0) {
        return at;
    }
    return -1;
}
// Whether `node` is a row-valued expression here: an array literal, an array
// or record local, or a call of a function that returns an array or a record.
CtIsArray :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, node: int) -> bool {
    value := Unparenthesized(context.forest, node);
    if (Is(context.forest, value, syntax.ArrayExpression)) {
        return true;
    }
    if (CtArrayLocal(context, file, frame, value) >= 0) {
        return true;
    }
    if (Is(context.forest, value, syntax.CallExpression)) {
        callee := CtCallee(context, package, file, value);
        return callee >= 0 && (context.callables[callee].result_container == ArrayContainer ||
                               (context.callables[callee].result == StructStorage &&
                                context.callables[callee].result_container == 0));
    }
    return false;
}
// The row type of a declared type: the element storage of an array, `CtRecord`
// plus the declaration of a record, 0 for any other type.
CtRowType :: (storage: int, container: int, record: int) -> int {
    if (container == ArrayContainer) {
        return storage;
    }
    if (container == 0 && storage == StructStorage && record >= 0) {
        return CtRecord + record;
    }
    return 0;
}
// Whether a row of `kind` holds numbers and bools only: an array of them, or a
// record that declares nothing else.
CtRowOk :: (context: ^CtContext, kind: int) -> bool {
    if (kind < CtRecord) {
        return Integer(kind) || kind == BoolStorage;
    }
    declaration := context.types[kind - CtRecord];
    if (declaration.kind != RecordDecl) {
        return false;
    }
    at := declaration.first;
    while (at < declaration.first + declaration.count) {
        member := context.members[at];
        if (member.container != 0 || (!Integer(member.storage) && member.storage != BoolStorage)) {
            return false;
        }
        at += 1;
    }
    return true;
}
// The value of the scalar expression `node` in an activation. `want` is the
// type an untyped expression takes, 0 for the default.
CtEval :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, node: int,
           want: int) -> CtResult {
    text := context.documents[file].text;
    memo: ConstDecl[] = [];
    reads: int[] = [];
    CtCollect(context, package, file, frame, node, &reads);
    for (read in reads) {
        switch CtRead(context, package, file, frame, depth, read) {
            case .Failed(diagnostic):
                return CtResult.Failed(diagnostic);
            case .Waiting:
                return CtResult.Waiting;
            case .Elements(values, storage):
                return CtResult.Failed(CtFail(context, read, file, "an array or record cannot be used as a number here"));
            case .Value(value, storage):
                placed: ConstDecl = {name: "", package: package, storage: storage, bits: value, node: read,
                                     file: file, folded: true, occurrence: 0};
                memo.append(placed);
        }
    }
    scope := CtScope(context.constants, package, file, frame, memo);
    aliases := Aliases(context.links, file);
    if (CtBoolean(context.forest, text, scope, aliases, package, node)) {
        switch FoldCondition(context.forest, text, file, scope, aliases, package, node) {
            case .Failed(diagnostic):
                return CtResult.Failed(diagnostic);
            case .Waiting:
                return CtResult.Waiting;
            case .Yes:
                return CtResult.Value(1, BoolStorage);
            case .No:
                return CtResult.Value(0, BoolStorage);
        }
    }
    typed := ConstantType(context.forest, text, scope, aliases, package, node);
    if (typed == 0) {
        typed = want;
    }
    if (typed == 0) {
        typed = IntStorage;
    }
    switch FoldConstant(context.forest, text, file, scope, aliases, package, node, typed) {
        case .Failed(diagnostic):
            return CtResult.Failed(diagnostic);
        case .Waiting:
            return CtResult.Waiting;
        case .Folded(folded):
            return CtResult.Value(folded, typed);
    }
}
// The value of a row-valued expression: its elements or fields and their row
// type. `want` is the row type an untyped literal takes, 0 for the default.
CtEvalArray :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, node: int,
                want: int) -> CtResult {
    value := Unparenthesized(context.forest, node);
    local := CtArrayLocal(context, file, frame, value);
    if (local >= 0) {
        return CtResult.Elements(frame.arrays[local].items, -frame.storages[local]);
    }
    if (Is(context.forest, value, syntax.CallExpression)) {
        return CtRead(context, package, file, frame, depth, value);
    }
    if (Is(context.forest, value, syntax.StructExpression) && want >= CtRecord) {
        return CtRecordLiteral(context, package, file, frame, depth, value, want - CtRecord);
    }
    if (!Is(context.forest, value, syntax.ArrayExpression)) {
        return CtResult.Failed(CtFail(context, node, file, "a compile-time array or record is a literal, a local or a call"));
    }
    elements: u64[] = [];
    storage := want;
    for (element in Members(context.forest, value)) {
        switch CtEval(context, package, file, frame, depth, element, storage) {
            case .Failed(diagnostic):
                return CtResult.Failed(diagnostic);
            case .Waiting:
                return CtResult.Waiting;
            case .Elements(values, kind):
                return CtResult.Failed(CtFail(context, element, file, "compile-time arrays hold numbers and bools"));
            case .Value(item, kind):
                if (storage == 0) {
                    storage = kind;
                }
                if (kind != storage && !Widens(kind, storage)) {
                    return CtResult.Failed(CtFail(context, element, file, "array elements differ in type"));
                }
                elements.append(CtWidened(item, kind, storage));
        }
    }
    if (storage == 0) {
        return CtResult.Failed(CtFail(context, node, file, "an empty compile-time array needs its type"));
    }
    return CtResult.Elements(elements, storage);
}
// The value of the record literal `{field: value, ...}` of declaration
// `record`: each field once, in any order.
CtRecordLiteral :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, node: int,
                    record: int) -> CtResult {
    if (!CtRowOk(context, CtRecord + record)) {
        return CtResult.Failed(CtFail(context, node, file, "compile-time records hold numbers and bools only"));
    }
    declaration := context.types[record];
    fields := Members(context.forest, node);
    if (length(fields) != declaration.count) {
        return CtResult.Failed(CtFail(context, node, file, "a compile-time record literal needs every field once"));
    }
    values: u64[] = [];
    seen: bool[] = [];
    at := 0;
    while (at < declaration.count) {
        values.append(0);
        seen.append(false);
        at += 1;
    }
    for (initializer in fields) {
        name := Text(context.forest, context.documents[file].text, Field(context.forest, initializer, syntax.FieldName));
        index := FindField(context.types, context.members, record, name);
        if (index < 0 || seen[index - declaration.first]) {
            return CtResult.Failed(CtFail(context, initializer, file, "a compile-time record literal needs every field once"));
        }
        kind := context.members[index].storage;
        switch CtEval(context, package, file, frame, depth, Field(context.forest, initializer, syntax.FieldValue), kind) {
            case .Failed(diagnostic):
                return CtResult.Failed(diagnostic);
            case .Waiting:
                return CtResult.Waiting;
            case .Elements(more, other):
                return CtResult.Failed(CtFail(context, initializer, file, "compile-time records hold numbers and bools only"));
            case .Value(item, storage):
                if (storage != kind && !Widens(storage, kind)) {
                    return CtResult.Failed(CtFail(context, initializer, file, "field value differs from its type"));
                }
                values[index - declaration.first] = CtWidened(item, storage, kind);
                seen[index - declaration.first] = true;
        }
    }
    return CtResult.Elements(values, CtRecord + record);
}
// The value of `record.field`: the field of a record local or of a call's result.
CtReadField :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, node: int) -> CtResult {
    switch CtEvalArray(context, package, file, frame, depth, Field(context.forest, node, syntax.FieldObject), 0) {
        case .Failed(diagnostic):
            return CtResult.Failed(diagnostic);
        case .Waiting:
            return CtResult.Waiting;
        case .Value(item, kind):
            return CtResult.Failed(CtFail(context, node, file, "only a record has fields"));
        case .Elements(values, kind):
            if (kind < CtRecord) {
                return CtResult.Failed(CtFail(context, node, file, "only a record has fields"));
            }
            record := kind - CtRecord;
            name := Text(context.forest, context.documents[file].text, Field(context.forest, node, syntax.FieldMember));
            index := FindField(context.types, context.members, record, name);
            if (index < 0) {
                return CtResult.Failed(CtFail(context, node, file, format_text("Unknown field '{}'", name)));
            }
            return CtResult.Value(values[index - context.types[record].first], context.members[index].storage);
    }
}
// Evaluates a node CtCollect found: a call, `length(array)`, `array[index]` or
// `record.field`.
CtRead :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, node: int) -> CtResult {
    if (Is(context.forest, node, syntax.MemberExpression)) {
        return CtReadField(context, package, file, frame, depth, node);
    }
    if (Is(context.forest, node, syntax.CallExpression) && !CtLength(context, package, file, node)) {
        return CtCall(context, package, file, frame, depth, node);
    }
    if (Is(context.forest, node, syntax.CallExpression)) {
        arguments := Members(context.forest, Field(context.forest, node, syntax.FieldArguments));
        if (length(arguments) != 1) {
            return CtResult.Failed(CtFail(context, node, file, "length takes one array"));
        }
        switch CtEvalArray(context, package, file, frame, depth, arguments[0], 0) {
            case .Failed(diagnostic):
                return CtResult.Failed(diagnostic);
            case .Waiting:
                return CtResult.Waiting;
            case .Value(item, kind):
                return CtResult.Failed(CtFail(context, arguments[0], file, "length takes an array"));
            case .Elements(values, kind):
                if (kind >= CtRecord) {
                    return CtResult.Failed(CtFail(context, arguments[0], file, "length takes an array"));
                }
                return CtResult.Value(u64(length(values)), IntStorage);
        }
    }
    switch CtEvalArray(context, package, file, frame, depth, Field(context.forest, node, syntax.FieldObject), 0) {
        case .Failed(diagnostic):
            return CtResult.Failed(diagnostic);
        case .Waiting:
            return CtResult.Waiting;
        case .Value(item, kind):
            return CtResult.Failed(CtFail(context, node, file, "only an array can be indexed at compile time"));
        case .Elements(values, kind):
            if (kind >= CtRecord) {
                return CtResult.Failed(CtFail(context, node, file, "only an array can be indexed at compile time"));
            }
            switch CtEval(context, package, file, frame, depth, Field(context.forest, node, syntax.FieldIndex), IntStorage) {
                case .Failed(diagnostic):
                    return CtResult.Failed(diagnostic);
                case .Waiting:
                    return CtResult.Waiting;
                case .Elements(more, other):
                    return CtResult.Failed(CtFail(context, node, file, "an array index is a number"));
                case .Value(position, storage):
                    if (!Integer(storage)) {
                        return CtResult.Failed(CtFail(context, node, file, "an array index is a number"));
                    }
                    signed := ExactStored(position, storage);
                    if (ExactNegative(signed) ||
                        MagnitudeCompare(Magnitude(signed), Magnitude(ExactOf(false, u64(length(values))))) >= 0) {
                        return CtResult.Failed(CtFail(context, node, file, "array index out of range"));
                    }
                    return CtResult.Value(values[int(LowBits(Magnitude(signed)))], kind);
            }
    }
}
// Calls the function that `call` names with its arguments evaluated here.
CtCall :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, call: int) -> CtResult {
    callee := CtCallee(context, package, file, call);
    callable := context.callables[callee];
    if (callable.count < 0) {
        return CtResult.Failed(CtFail(context, call, file, "compile-time execution does not call generic functions yet"));
    }
    if (depth >= CtDepth) {
        return CtResult.Failed(CtFail(context, call, file, "compile-time evaluation exceeded 128 nested calls"));
    }
    arguments := Members(context.forest, Field(context.forest, call, syntax.FieldArguments));
    if (length(arguments) != callable.count) {
        return CtResult.Failed(CtFail(context, call, file, "compile-time call needs every argument"));
    }
    inner: CtFrame = {names: [], bits: [], storages: [], arrays: []};
    index: int = 0;
    while (index < length(arguments)) {
        param := context.params[callable.first + index];
        row := CtRowType(param.storage, param.container, param.record);
        if ((row == 0 && (param.container != 0 || (!Integer(param.storage) && param.storage != BoolStorage))) ||
            (row != 0 && !CtRowOk(context, row)) || param.reference ||
            Is(context.forest, arguments[index], syntax.NamedArgument)) {
            return CtResult.Failed(CtFail(context, arguments[index], file,
                                          "compile-time calls take integers, bools, and arrays and records of them by position"));
        }
        if (row != 0) {
            switch CtEvalArray(context, package, file, frame, depth, arguments[index], row) {
                case .Failed(diagnostic):
                    return CtResult.Failed(diagnostic);
                case .Waiting:
                    return CtResult.Waiting;
                case .Value(item, kind):
                    return CtResult.Failed(CtFail(context, arguments[index], file, "the argument must be an array or record"));
                case .Elements(values, kind):
                    if (kind != row) {
                        return CtResult.Failed(CtFail(context, arguments[index], file,
                                                      "argument differs from its parameter type"));
                    }
                    inner.names.append(param.name);
                    inner.bits.append(0);
                    inner.storages.append(-row);
                    CtAddRow(&inner, values);
            }
        } else {
            switch CtEval(context, package, file, frame, depth, arguments[index], param.storage) {
                case .Failed(diagnostic):
                    return CtResult.Failed(diagnostic);
                case .Waiting:
                    return CtResult.Waiting;
                case .Elements(values, kind):
                    return CtResult.Failed(CtFail(context, arguments[index], file, "the argument must be a number"));
                case .Value(value, storage):
                    if (storage != param.storage && !Widens(storage, param.storage)) {
                        return CtResult.Failed(CtFail(context, arguments[index], file,
                                                      format_text("Mismatched integer types {} and {}; convert one operand",
                                                                  TypeName(storage), TypeName(param.storage))));
                    }
                    inner.names.append(param.name);
                    inner.bits.append(CtWidened(value, storage, param.storage));
                    inner.storages.append(param.storage);
                    CtAddRow(&inner, []);
            }
        }
        index += 1;
    }
    return CtRun(context, callee, &inner, depth + 1);
}
// `value` of type `from` as a value of the wider type `to`.
CtWidened :: (value: u64, from: int, to: int) -> u64 {
    return ExactWrapped(ExactStored(value, from), to);
}
// Runs function `callee` with its arguments in `frame`.
CtRun :: (context: ^CtContext, callee: int, frame: ^CtFrame, depth: int) -> CtResult {
    callable := context.callables[callee];
    file := callable.document;
    row := CtRowType(callable.result, callable.result_container, callable.result_record);
    if (callable.result == 0 || callable.results != 0 ||
        (row == 0 && (callable.result_container != 0 || (!Integer(callable.result) && callable.result != BoolStorage))) ||
        (row != 0 && !CtRowOk(context, row))) {
        return CtResult.Failed(CtFail(context, callable.node, file,
                                      "compile-time execution needs a function with one integer, bool, array or record result"));
    }
    body := Field(context.forest, callable.node, syntax.FieldBody);
    switch CtBlock(context, callable.package, file, frame, depth, callable, Members(context.forest, body)) {
        case .Failed(diagnostic):
            return CtResult.Failed(diagnostic);
        case .Waiting:
            return CtResult.Waiting;
        case .Returned(value, storage):
            return CtResult.Value(value, storage);
        case .ReturnedElements(values, storage):
            return CtResult.Elements(values, storage);
        case .Normal:
            return CtResult.Failed(CtFail(context, callable.node, file, "a compile-time function must return a value"));
        case .Broke:
            return CtResult.Failed(CtFail(context, callable.node, file, "break outside a loop"));
        case .Continued:
            return CtResult.Failed(CtFail(context, callable.node, file, "continue outside a loop"));
    }
}
// `left op right` over exact values.
CtApply :: (operator: int, left: u64[], right: u64[]) -> u64[] {
    if (operator == tk.Add) {
        return ExactAdd(left, right);
    }
    if (operator == tk.Sub) {
        return ExactSubtract(left, right);
    }
    if (operator == tk.Mul) {
        return ExactMultiply(left, right);
    }
    if (operator == tk.Quo || operator == tk.Mod) {
        return ExactDivide(left, right, operator == tk.Mod);
    }
    return ExactBitwise(operator, left, right);
}
// Adds the elements of a new array local, or an empty row for a scalar.
CtAddRow :: (frame: ^CtFrame, values: u64[]) {
    row: CtRow = {items: values};
    frame.arrays.append(row);
}
CtSetRow :: (frame: ^CtFrame, at: int, values: u64[]) {
    row: CtRow = {items: values};
    frame.arrays[at] = row;
}
// Drops the locals declared after the first `mark`.
CtDrop :: (frame: ^CtFrame, mark: int) {
    frame.names.resize(mark);
    frame.bits.resize(mark);
    frame.storages.resize(mark);
    frame.arrays.resize(mark);
}
// Runs the statements of a block of `function`; its locals end with it.
CtBlock :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, function: Callable,
            statements: int[]) -> CtFlow {
    mark := length(frame.names);
    for (statement in statements) {
        if (!CtStep(context, statement, file)) {
            return CtFlow.Failed(CtFail(context, statement, file, "compile-time evaluation exceeded 65536 steps"));
        }
        switch CtStatement(context, package, file, frame, depth, function, statement) {
            case .Normal:
                continue;
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Returned(value, storage):
                CtDrop(frame, mark);
                return CtFlow.Returned(value, storage);
            case .ReturnedElements(values, storage):
                CtDrop(frame, mark);
                return CtFlow.ReturnedElements(values, storage);
            case .Broke:
                CtDrop(frame, mark);
                return CtFlow.Broke;
            case .Continued:
                CtDrop(frame, mark);
                return CtFlow.Continued;
        }
    }
    CtDrop(frame, mark);
    return CtFlow.Normal;
}
// The storage a type text names: negated row type for an array of a scalar or
// a record, 0 for none.
CtDeclared :: (context: ^CtContext, package: int, text: string) -> int {
    size := text_byte_length(text);
    if (size > 2 && text_slice(text, size - 2, 2) == "[]") {
        return -ScalarStorage(text_slice(text, 0, size - 2));
    }
    storage := ScalarStorage(text);
    if (storage != 0) {
        return storage;
    }
    record := FindType(context.types, package, text);
    if (record >= 0 && context.types[record].kind == RecordDecl) {
        return -(CtRecord + record);
    }
    return 0;
}
CtStatement :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, function: Callable,
                statement: int) -> CtFlow {
    forest := context.forest;
    if (Is(forest, statement, syntax.ReturnStatement)) {
        value := Field(forest, statement, syntax.FieldValue);
        if (value < 0) {
            return CtFlow.Failed(CtFail(context, statement, file, "return needs a value"));
        }
        row := CtRowType(function.result, function.result_container, function.result_record);
        if (row != 0) {
            switch CtEvalArray(context, package, file, frame, depth, value, row) {
                case .Failed(diagnostic):
                    return CtFlow.Failed(diagnostic);
                case .Waiting:
                    return CtFlow.Waiting;
                case .Value(item, kind):
                    return CtFlow.Failed(CtFail(context, value, file, "returned value differs from the result type"));
                case .Elements(values, kind):
                    if (kind != row) {
                        return CtFlow.Failed(CtFail(context, value, file, "returned value differs from the result type"));
                    }
                    return CtFlow.ReturnedElements(values, kind);
            }
        }
        switch CtEval(context, package, file, frame, depth, value, function.result) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Elements(values, kind):
                return CtFlow.Failed(CtFail(context, value, file, "returned value differs from the result type"));
            case .Value(returned, storage):
                if (storage != function.result && !Widens(storage, function.result)) {
                    return CtFlow.Failed(CtFail(context, value, file, "returned value differs from the result type"));
                }
                return CtFlow.Returned(CtWidened(returned, storage, function.result), function.result);
        }
    }
    if (Is(forest, statement, syntax.BreakStatement)) {
        return CtFlow.Broke;
    }
    if (Is(forest, statement, syntax.ContinueStatement)) {
        return CtFlow.Continued;
    }
    if (Is(forest, statement, syntax.LocalDeclaration)) {
        return CtDeclaration(context, package, file, frame, depth, statement);
    }
    if (Is(forest, statement, syntax.Assignment)) {
        return CtAssignment(context, package, file, frame, depth, statement);
    }
    if (Is(forest, statement, syntax.ExpressionStatement)) {
        return CtAppend(context, package, file, frame, depth, statement);
    }
    if (Is(forest, statement, syntax.IfStatement)) {
        switch CtEval(context, package, file, frame, depth, Field(forest, statement, syntax.FieldCondition), BoolStorage) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Elements(values, kind):
                return CtFlow.Failed(CtFail(context, statement, file, "an if condition must be a bool"));
            case .Value(taken, storage):
                if (storage != BoolStorage) {
                    return CtFlow.Failed(CtFail(context, Field(forest, statement, syntax.FieldCondition), file,
                                                "an if condition must be a bool"));
                }
                if (taken != 0) {
                    return CtBlock(context, package, file, frame, depth, function,
                                   Members(forest, Field(forest, statement, syntax.FieldConsequence)));
                }
                alternative := Field(forest, statement, syntax.FieldAlternative);
                if (Is(forest, alternative, syntax.IfStatement)) {
                    return CtStatement(context, package, file, frame, depth, function, alternative);
                }
                if (alternative >= 0) {
                    return CtBlock(context, package, file, frame, depth, function, Members(forest, alternative));
                }
                return CtFlow.Normal;
        }
    }
    if (Is(forest, statement, syntax.WhileStatement)) {
        return CtWhile(context, package, file, frame, depth, function, statement);
    }
    if (Is(forest, statement, syntax.ForStatement)) {
        return CtFor(context, package, file, frame, depth, function, statement);
    }
    return CtFlow.Failed(CtFail(context, statement, file, "compile-time execution does not support this statement yet"));
}
// `name: type = value` or `name := value`, scalar, array or record.
CtDeclaration :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int,
                  statement: int) -> CtFlow {
    forest := context.forest;
    text := context.documents[file].text;
    want: int = 0;
    declared := Field(forest, statement, syntax.FieldType);
    if (declared >= 0) {
        want = CtDeclared(context, package, Text(forest, text, declared));
        if (want == 0 || (want > 0 && !Integer(want) && want != BoolStorage) ||
            (want < 0 && !CtRowOk(context, -want))) {
            return CtFlow.Failed(CtFail(context, declared, file,
                                        "compile-time locals are integers, bools, and arrays and records of them"));
        }
    }
    value := Field(forest, statement, syntax.FieldValue);
    if (value < 0) {
        return CtFlow.Failed(CtFail(context, statement, file, "a compile-time local needs a value"));
    }
    name := Text(forest, text, Field(forest, statement, syntax.FieldName));
    if (want < 0 || (want == 0 && CtIsArray(context, package, file, frame, value))) {
        switch CtEvalArray(context, package, file, frame, depth, value, -want) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Value(item, kind):
                return CtFlow.Failed(CtFail(context, value, file, "local value differs from its type"));
            case .Elements(values, kind):
                if (want < 0 && kind != -want) {
                    return CtFlow.Failed(CtFail(context, value, file, "local value differs from its type"));
                }
                frame.names.append(name);
                frame.bits.append(0);
                frame.storages.append(-kind);
                CtAddRow(frame, values);
                return CtFlow.Normal;
        }
    }
    switch CtEval(context, package, file, frame, depth, value, want) {
        case .Failed(diagnostic):
            return CtFlow.Failed(diagnostic);
        case .Waiting:
            return CtFlow.Waiting;
        case .Elements(values, kind):
            return CtFlow.Failed(CtFail(context, value, file, "local value differs from its type"));
        case .Value(initial, storage):
            if (want != 0 && storage != want && !Widens(storage, want)) {
                return CtFlow.Failed(CtFail(context, value, file, "local value differs from its type"));
            }
            if (want == 0) {
                want = storage;
            }
            frame.names.append(name);
            frame.bits.append(CtWidened(initial, storage, want));
            frame.storages.append(want);
            CtAddRow(frame, []);
            return CtFlow.Normal;
    }
}
// `x = v`, `x op= v`, `array[i] = v`, `record.field = v`, each also `op=`, and
// `array = other`.
CtAssignment :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int,
                 statement: int) -> CtFlow {
    forest := context.forest;
    text := context.documents[file].text;
    target := Field(forest, statement, syntax.FieldTarget);
    operator := CompoundOperator(Operator(forest, statement));
    value := Field(forest, statement, syntax.FieldValue);
    element: int = -1;
    named: int = -1;
    holder := target;
    if (Is(forest, target, syntax.IndexExpression)) {
        holder = Field(forest, target, syntax.FieldObject);
        element = Field(forest, target, syntax.FieldIndex);
    }
    if (Is(forest, target, syntax.MemberExpression)) {
        holder = Field(forest, target, syntax.FieldObject);
        named = Field(forest, target, syntax.FieldMember);
    }
    if (!Is(forest, holder, syntax.Identifier)) {
        return CtFlow.Failed(CtFail(context, statement, file, "compile-time assignment needs a local"));
    }
    at := CtLookup(frame, Text(forest, text, holder));
    if (at < 0) {
        return CtFlow.Failed(CtFail(context, statement, file, "compile-time assignment needs a local"));
    }
    local := frame.storages[at];
    if (element < 0 && named < 0 && local < 0) {
        if (operator != NoOperator) {
            return CtFlow.Failed(CtFail(context, statement, file, "compound assignment needs integer operands"));
        }
        switch CtEvalArray(context, package, file, frame, depth, value, -local) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Value(item, kind):
                return CtFlow.Failed(CtFail(context, statement, file, "assigned value differs from its local"));
            case .Elements(values, kind):
                if (kind != -local) {
                    return CtFlow.Failed(CtFail(context, statement, file, "assigned value differs from its local"));
                }
                CtSetRow(frame, at, values);
                return CtFlow.Normal;
        }
    }
    kind := local;
    position: int = 0;
    if (named >= 0) {
        if (local >= 0 || -local < CtRecord) {
            return CtFlow.Failed(CtFail(context, statement, file, "only a record has fields"));
        }
        record := -local - CtRecord;
        name := Text(forest, text, named);
        index := FindField(context.types, context.members, record, name);
        if (index < 0) {
            return CtFlow.Failed(CtFail(context, named, file, format_text("Unknown named '{}'", name)));
        }
        kind = context.members[index].storage;
        position = index - context.types[record].first;
    }
    if (element >= 0) {
        if (local >= 0 || -local >= CtRecord) {
            return CtFlow.Failed(CtFail(context, statement, file, "only an array can be indexed at compile time"));
        }
        kind = -local;
        switch CtEval(context, package, file, frame, depth, element, IntStorage) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Elements(more, other):
                return CtFlow.Failed(CtFail(context, element, file, "an array index is a number"));
            case .Value(index, storage):
                signed := ExactStored(index, storage);
                if (!Integer(storage) || ExactNegative(signed) ||
                    MagnitudeCompare(Magnitude(signed), Magnitude(ExactOf(false, u64(length(frame.arrays[at].items))))) >= 0) {
                    return CtFlow.Failed(CtFail(context, element, file, "array index out of range"));
                }
                position = int(LowBits(Magnitude(signed)));
        }
    }
    switch CtEval(context, package, file, frame, depth, value, kind) {
        case .Failed(diagnostic):
            return CtFlow.Failed(diagnostic);
        case .Waiting:
            return CtFlow.Waiting;
        case .Elements(values, other):
            return CtFlow.Failed(CtFail(context, statement, file, "assigned value differs from its local"));
        case .Value(assigned, storage):
            if (storage != kind && !Widens(storage, kind)) {
                return CtFlow.Failed(CtFail(context, statement, file, "assigned value differs from its local"));
            }
            current: u64 = 0;
            if (element >= 0 || named >= 0) {
                current = frame.arrays[at].items[position];
            } else {
                current = frame.bits[at];
            }
            result := CtWidened(assigned, storage, kind);
            if (operator != NoOperator) {
                if (!Integer(kind)) {
                    return CtFlow.Failed(CtFail(context, statement, file, "compound assignment needs integer operands"));
                }
                operand := ExactStored(result, kind);
                if ((operator == tk.Quo || operator == tk.Mod) && ExactZero(operand)) {
                    return CtFlow.Failed(CtFail(context, statement, file, "Constant division by zero"));
                }
                combined := CtApply(operator, ExactStored(current, kind), operand);
                if (MagnitudeBits(Magnitude(combined)) > ExactLimit || !ExactFits(combined, kind)) {
                    return CtFlow.Failed(OutsideRange(forest, file, statement, kind));
                }
                result = ExactWrapped(combined, kind);
            }
            if (element >= 0 || named >= 0) {
                row := frame.arrays[at].items;
                row[position] = result;
                CtSetRow(frame, at, row);
            } else {
                frame.bits[at] = result;
            }
            return CtFlow.Normal;
    }
}
// `array.append(value)`, the one expression statement a compile-time function
// may use.
CtAppend :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int,
             statement: int) -> CtFlow {
    forest := context.forest;
    text := context.documents[file].text;
    call := FirstMember(forest, statement);
    function := Field(forest, call, syntax.FieldFunction);
    if (!Is(forest, call, syntax.CallExpression) || !Is(forest, function, syntax.MemberExpression) ||
        Text(forest, text, Field(forest, function, syntax.FieldMember)) != "append") {
        return CtFlow.Failed(CtFail(context, statement, file, "compile-time execution does not support this statement yet"));
    }
    at := CtArrayLocal(context, file, frame, Field(forest, function, syntax.FieldObject));
    arguments := Members(forest, Field(forest, call, syntax.FieldArguments));
    if (at < 0 || length(arguments) != 1) {
        return CtFlow.Failed(CtFail(context, statement, file, "append takes one value for a local array"));
    }
    kind := -frame.storages[at];
    if (kind >= CtRecord) {
        return CtFlow.Failed(CtFail(context, statement, file, "append takes an array"));
    }
    switch CtEval(context, package, file, frame, depth, arguments[0], kind) {
        case .Failed(diagnostic):
            return CtFlow.Failed(diagnostic);
        case .Waiting:
            return CtFlow.Waiting;
        case .Elements(values, other):
            return CtFlow.Failed(CtFail(context, statement, file, "array elements differ in type"));
        case .Value(item, storage):
            if (storage != kind && !Widens(storage, kind)) {
                return CtFlow.Failed(CtFail(context, statement, file, "array elements differ in type"));
            }
            row := frame.arrays[at].items;
            row.append(CtWidened(item, storage, kind));
            CtSetRow(frame, at, row);
            return CtFlow.Normal;
    }
}
// `while condition { ... }`.
CtWhile :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, function: Callable,
            statement: int) -> CtFlow {
    forest := context.forest;
    while (true) {
        if (!CtStep(context, statement, file)) {
            return CtFlow.Failed(CtFail(context, statement, file, "compile-time evaluation exceeded 65536 steps"));
        }
        switch CtEval(context, package, file, frame, depth, Field(forest, statement, syntax.FieldCondition), BoolStorage) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Elements(values, kind):
                return CtFlow.Failed(CtFail(context, statement, file, "a while condition must be a bool"));
            case .Value(taken, storage):
                if (storage != BoolStorage) {
                    return CtFlow.Failed(CtFail(context, Field(forest, statement, syntax.FieldCondition), file,
                                                "a while condition must be a bool"));
                }
                if (taken == 0) {
                    return CtFlow.Normal;
                }
        }
        switch CtBlock(context, package, file, frame, depth, function, Members(forest, Field(forest, statement, syntax.FieldBody))) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Returned(value, storage):
                return CtFlow.Returned(value, storage);
            case .ReturnedElements(values, storage):
                return CtFlow.ReturnedElements(values, storage);
            case .Broke:
                return CtFlow.Normal;
            case .Normal:
                continue;
            case .Continued:
                continue;
        }
    }
}
// `for i in first..<last`, `for i in first..last`, `for item in array`,
// `for index, item in array`, each also reversed with `for <`.
CtFor :: (context: ^CtContext, package: int, file: int, frame: ^CtFrame, depth: int, function: Callable,
          statement: int) -> CtFlow {
    forest := context.forest;
    text := context.documents[file].text;
    name := Text(forest, text, Field(forest, statement, syntax.FieldName));
    reverse := Field(forest, statement, syntax.FieldReverse) >= 0;
    if (Field(forest, statement, syntax.FieldReference) >= 0) {
        return CtFlow.Failed(CtFail(context, statement, file, "compile-time loops iterate by value"));
    }
    values: u64[] = [];
    kind: int = IntStorage;
    key := Field(forest, statement, syntax.FieldKey);
    if (Field(forest, statement, syntax.FieldFirst) >= 0) {
        first: u64 = 0;
        last: u64 = 0;
        switch CtEval(context, package, file, frame, depth, Field(forest, statement, syntax.FieldFirst), 0) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Elements(more, other):
                return CtFlow.Failed(CtFail(context, statement, file, "a range bound is a number"));
            case .Value(low, storage):
                first = low;
                kind = storage;
        }
        switch CtEval(context, package, file, frame, depth, Field(forest, statement, syntax.FieldLast), kind) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Elements(more, other):
                return CtFlow.Failed(CtFail(context, statement, file, "a range bound is a number"));
            case .Value(high, storage):
                last = CtWidened(high, storage, kind);
        }
        if (!Integer(kind)) {
            return CtFlow.Failed(CtFail(context, statement, file, "a range bound is an integer"));
        }
        low := ExactStored(first, kind);
        high := ExactStored(last, kind);
        if (Text(forest, text, Field(forest, statement, syntax.FieldBound)) == "..") {
            high = ExactAdd(high, ExactOf(false, 1));
        }
        while (!ExactNegative(ExactSubtract(high, low)) && !ExactZero(ExactSubtract(high, low))) {
            if (length(values) >= CtSteps) {
                return CtFlow.Failed(CtFail(context, statement, file, "compile-time evaluation exceeded 65536 steps"));
            }
            values.append(ExactWrapped(low, kind));
            low = ExactAdd(low, ExactOf(false, 1));
        }
    } else {
        switch CtEvalArray(context, package, file, frame, depth, Field(forest, statement, syntax.FieldValue), 0) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Value(item, other):
                return CtFlow.Failed(CtFail(context, statement, file, "only an array can be iterated at compile time"));
            case .Elements(items, storage):
                if (storage >= CtRecord) {
                    return CtFlow.Failed(CtFail(context, statement, file, "only an array can be iterated at compile time"));
                }
                values = items;
                kind = storage;
        }
    }
    mark := length(frame.names);
    position: int = 0;
    while (position < length(values)) {
        if (!CtStep(context, statement, file)) {
            return CtFlow.Failed(CtFail(context, statement, file, "compile-time evaluation exceeded 65536 steps"));
        }
        at := position;
        if (reverse) {
            at = length(values) - 1 - position;
        }
        if (key >= 0) {
            frame.names.append(Text(forest, text, key));
            frame.bits.append(u64(at));
            frame.storages.append(IntStorage);
            CtAddRow(frame, []);
        }
        frame.names.append(name);
        frame.bits.append(values[at]);
        frame.storages.append(kind);
        CtAddRow(frame, []);
        position += 1;
        switch CtBlock(context, package, file, frame, depth, function, Members(forest, Field(forest, statement, syntax.FieldBody))) {
            case .Failed(diagnostic):
                return CtFlow.Failed(diagnostic);
            case .Waiting:
                return CtFlow.Waiting;
            case .Returned(value, storage):
                CtDrop(frame, mark);
                return CtFlow.Returned(value, storage);
            case .ReturnedElements(items, storage):
                CtDrop(frame, mark);
                return CtFlow.ReturnedElements(items, storage);
            case .Broke:
                CtDrop(frame, mark);
                return CtFlow.Normal;
            case .Normal:
                CtDrop(frame, mark);
            case .Continued:
                CtDrop(frame, mark);
        }
    }
    CtDrop(frame, mark);
    return CtFlow.Normal;
}
// Folds the value of a constant whose expression calls authored functions:
// each call runs first and stands for its value.
FoldCalling :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], links: graph.Binding[],
                callables: Callable[], params: Param[], constants: ConstDecl[], types: TypeDecl[],
                members: TypeMember[], package: int, file: int, node: int, storage: int) -> Folding {
    text := documents[file].text;
    aliases := Aliases(links, file);
    context: CtContext = {forest: forest, documents: documents, links: links, callables: callables, params: params,
                          constants: constants, types: types, members: members, steps: 0};
    frame: CtFrame = {names: [], bits: [], storages: [], arrays: []};
    reads: int[] = [];
    CtCollect(&context, package, file, &frame, node, &reads);
    if (length(reads) == 0) {
        return FoldConstant(forest, text, file, constants, aliases, package, node, storage);
    }
    memo: ConstDecl[] = [];
    for (read in reads) {
        switch CtRead(&context, package, file, &frame, 0, read) {
            case .Failed(diagnostic):
                return Folding.Failed(diagnostic);
            case .Waiting:
                return Folding.Waiting;
            case .Elements(values, kind):
                return Folding.Failed(Diagnose(forest, read, file, "constant value must be an integer expression"));
            case .Value(value, result):
                placed: ConstDecl = {name: "", package: package, storage: result, bits: value, node: read, file: file,
                                     folded: true, occurrence: 0};
                memo.append(placed);
        }
    }
    scope := memo;
    scope.extend(constants);
    return FoldConstant(forest, text, file, scope, aliases, package, node, storage);
}
package package_compiler

import snapshot "project:source_snapshot"
import syntax "project:syntax_diagnostics"
import tk "project:source_tokenizer"

// Error category belongs to a declared type, independently of callable names.
ErrorMarked :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> bool {
    for child in Members(forest, node) {
        if Is(forest, child, syntax.Attribute) && Text(forest, text, Field(forest, child, syntax.FieldName)) == "error" {
            return true;
        }
    }
    return false;
}

DeclarationAttributes :: (forest: snapshot.SnapshotNode[], text: string, file: int, node: int,
                          allowed: string) -> syntax.Diagnostic[] {
    seen: string[] = [];
    for child in Members(forest, node) {
        if Is(forest, child, syntax.Attribute) {
            name := Text(forest, text, Field(forest, child, syntax.FieldName));
            if name != allowed {
                return [Diagnose(forest, child, file, format_text("Unknown attribute '@{}'", name))];
            }
            for previous in seen {
                if previous == name {
                    return [Diagnose(forest, child, file, format_text("Duplicate attribute '@{}'", name))];
                }
            }
            seen.append(name);
        }
    }
    return [];
}

// Optional descriptors and existing native aliases retain their value's
// category. Owning a field or container of errors does not make a value an error.
ErrorBearing :: (types: TypeDecl[], value: ValueType) -> bool {
    current := value;
    visited: int[] = [];
    while current.container == 0 && (current.storage == StructStorage || current.storage == UnionStorage) &&
          current.record >= 0 {
        if visited.contains(current.record) {
            return false;
        }
        visited.append(current.record);
        declared := types[current.record];
        if declared.error {
            return true;
        }
        if declared.kind == OptionalDecl {
            current = {storage: declared.value_storage, container: declared.value_container, record: declared.value_record};
        } else if declared.kind == NativeDecl && declared.parent >= 0 {
            current.record = declared.parent;
        } else {
            return false;
        }
    }
    return false;
}

ErrorResult :: (types: TypeDecl[], params: Param[], callable: Callable) -> bool {
    last: ValueType = {storage: callable.result, container: callable.result_container, record: callable.result_record};
    if callable.results > 0 {
        result := params[callable.first + callable.count + callable.results - 1];
        last = {storage: result.storage, container: result.container, record: result.record};
    }
    return ErrorBearing(types, last);
}

FallibleBinding :: struct {
    name: string;
    node: int;
    scope: int;
    visible: int;
    until: int;
    returned: bool;
}
FallibleBind :: (name: string, node: int, scope: int, visible: int, until: int, returned: bool) -> FallibleBinding {
    return {name: name, node: node, scope: scope, visible: visible, until: until, returned: returned};
}

FallibleWithin :: (forest: snapshot.SnapshotNode[], node: int, scope: int) -> bool {
    at := node;
    while (at >= 0) {
        if (at == scope) {
            return true;
        }
        at = forest[at].parent;
    }
    return false;
}

// Binding identities are declaration nodes, not spellings. A local is visible
// after its initializer, and a loop binding only inside the loop's body.
FallibleBindings :: (forest: snapshot.SnapshotNode[], text: string, callable: Callable) -> FallibleBinding[] {
    bindings: FallibleBinding[] = [];
    for (field in [syntax.FieldParameters, syntax.FieldResults]) {
        list := Field(forest, callable.node, field);
        if (Is(forest, list, syntax.ParameterList)) {
            for (parameter in Members(forest, list)) {
                name := Field(forest, parameter, syntax.FieldName);
                if (name >= 0) {
                    bindings.append(FallibleBind(Text(forest, text, name), name, callable.node,
                                                 0, forest[callable.node].end, field == syntax.FieldResults));
                }
            }
        }
    }
    body := Field(forest, callable.node, syntax.FieldBody);
    work: int[] = [body];
    while (length(work) > 0) {
        node := work[length(work) - 1];
        work = slice(work, 0, length(work) - 1);
        if (Is(forest, node, syntax.LocalDeclaration)) {
            name := Field(forest, node, syntax.FieldName);
            bindings.append(FallibleBind(Text(forest, text, name), name, forest[node].parent,
                                         forest[node].end, forest[forest[node].parent].end, false));
        }
        if (Is(forest, node, syntax.ForStatement)) {
            for (field in [syntax.FieldName, syntax.FieldKey]) {
                name := Field(forest, node, field);
                if (name >= 0) {
                    loop_body := Field(forest, node, syntax.FieldBody);
                    bindings.append(FallibleBind(Text(forest, text, name), name, loop_body,
                                                 forest[loop_body].start, forest[loop_body].end, false));
                }
            }
        }
        if (Is(forest, node, syntax.IfStatement) || Is(forest, node, syntax.WhileStatement)) {
            condition := Field(forest, node, syntax.FieldCondition);
            consequence := Field(forest, node, syntax.FieldConsequence);
            if (consequence < 0) {
                consequence = Field(forest, node, syntax.FieldBody);
            }
            patterns: int[] = [condition];
            while (length(patterns) > 0) {
                pattern := patterns[length(patterns) - 1];
                patterns = slice(patterns, 0, length(patterns) - 1);
                if (Is(forest, pattern, syntax.IsExpression)) {
                    declared: int[] = [];
                    name := Field(forest, pattern, syntax.FieldBinding);
                    if (name >= 0) {
                        declared.append(name);
                    }
                    variant := Field(forest, pattern, syntax.FieldType);
                    if (Is(forest, variant, syntax.VariantPattern)) {
                        declared.extend(Members(forest, Field(forest, variant, syntax.FieldBindings)));
                    }
                    for (bound_name in declared) {
                        bindings.append(FallibleBind(Text(forest, text, bound_name), bound_name, consequence,
                                                     forest[consequence].start, forest[consequence].end, false));
                        bindings.append(FallibleBind(Text(forest, text, bound_name), bound_name, node,
                                                     forest[pattern].end, forest[condition].end, false));
                    }
                }
                patterns.extend(Members(forest, pattern));
            }
        }
        if (Is(forest, node, syntax.SwitchArm)) {
            pattern := Field(forest, node, syntax.FieldValue);
            arm_body := Field(forest, node, syntax.FieldBody);
            if (Is(forest, pattern, syntax.VariantPattern)) {
                for (bound_name in Members(forest, Field(forest, pattern, syntax.FieldBindings))) {
                    bindings.append(FallibleBind(Text(forest, text, bound_name), bound_name, arm_body,
                                                 forest[arm_body].start, forest[arm_body].end, false));
                }
            }
        }
        // Nested callable bodies own independent obligations.
        if (node >= 0 && !Is(forest, node, syntax.FunctionDeclaration)) {
            work.extend(Members(forest, node));
        }
    }
    return bindings;
}

FallibleFindBinding :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[], node: int) -> int {
    if (!Is(forest, node, syntax.Identifier)) {
        return -1;
    }
    name := Text(forest, text, node);
    scope := node;
    while (scope >= 0) {
        found: int = -1;
        for (binding, index in bindings) {
            if (binding.scope == scope && binding.name == name && binding.visible <= forest[node].start &&
                forest[node].end <= binding.until &&
                (found < 0 || bindings[found].visible < binding.visible)) {
                found = index;
            }
        }
        if (found >= 0) {
            return found;
        }
        scope = forest[scope].parent;
    }
    return -1;
}

// The binding each identifier of a body names, by node index from `first`:
// the walk asks for the same identifiers once per fallible call site, so they
// are resolved once per body. -2 marks a node the body did not resolve.
FallibleNames :: struct {
    first: int;
    bindings: int[];
}
FallibleResolveNames :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[],
                         body: int) -> FallibleNames {
    identifiers: int[] = [];
    first: int = -1;
    last: int = -1;
    work: int[] = [body];
    while (length(work) > 0) {
        node := work[length(work) - 1];
        work = slice(work, 0, length(work) - 1);
        if (Is(forest, node, syntax.Identifier)) {
            identifiers.append(node);
            if (first < 0 || node < first) {
                first = node;
            }
            if (node > last) {
                last = node;
            }
        }
        // Nested callable bodies own independent obligations.
        if (node >= 0 && !Is(forest, node, syntax.FunctionDeclaration)) {
            work.extend(Members(forest, node));
        }
    }
    if (first < 0) {
        return {first: 0, bindings: []};
    }
    resolved := resize([int(0)], last - first + 1);
    for (index in 0..<length(resolved)) {
        resolved[index] = -2;
    }
    for (node in identifiers) {
        resolved[node - first] = FallibleFindBinding(forest, text, bindings, node);
    }
    return {first: first, bindings: resolved};
}
FallibleNamed :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[], names: FallibleNames,
                  node: int) -> int {
    at := node - names.first;
    if (at >= 0 && at < length(names.bindings) && names.bindings[at] != -2) {
        return names.bindings[at];
    }
    return FallibleFindBinding(forest, text, bindings, node);
}

FallibleDeclarationBinding :: (bindings: FallibleBinding[], node: int) -> int {
    for (binding, index in bindings) {
        if (binding.node == node) {
            return index;
        }
    }
    return -1;
}

FallibleNode :: struct {
    statement: int;
    first: int;
    second: int;
    guard: bool;
}
FallibleNodeFor :: (statement: int, first: int, second: int, guard: bool) -> FallibleNode {
    return {statement: statement, first: first, second: second, guard: guard};
}
FallibleLink :: (input: FallibleNode[], index: int, first: int, second: int) -> FallibleNode[] {
    nodes := input;
    row := nodes[index];
    row.first = first;
    row.second = second;
    nodes[index] = row;
    return nodes;
}
FallibleGraph :: union {
    Built(nodes: FallibleNode[], start: int)
}

FallibleTruth :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    value := Unparenthesized(forest, node);
    if (Is(forest, value, syntax.Boolean)) {
        if (Text(forest, text, value) == "true") {
            return 1;
        }
        return 0;
    }
    if (Is(forest, value, syntax.UnaryExpression) && Operator(forest, value) == tk.Not) {
        truth := FallibleTruth(forest, text, Field(forest, value, syntax.FieldOperand));
        if (truth >= 0) {
            return 1 - truth;
        }
    }
    return -1;
}

FallibleBuildGraph :: (forest: snapshot.SnapshotNode[], text: string, statement: int, next: int,
                       leave: int, repeat: int, input: FallibleNode[]) -> FallibleGraph {
    nodes := input;
    if (statement < 0) {
        return FallibleGraph.Built(nodes, next);
    }
    kind := forest[statement].kind;
    if (kind == syntax.Block || kind == syntax.CallableBody || kind == syntax.SequenceStatement) {
        members := Members(forest, statement);
        start := next;
        index := length(members);
        while (index > 0) {
            index -= 1;
            switch FallibleBuildGraph(forest, text, members[index], start, leave, repeat, nodes) {
                case .Built(changed, head):
                    nodes = changed;
                    start = head;
            }
        }
        return FallibleGraph.Built(nodes, start);
    }
    if (kind == syntax.SwitchArm || kind == syntax.BranchStatement) {
        return FallibleBuildGraph(forest, text, Field(forest, statement, syntax.FieldBody), next, leave, repeat, nodes);
    }
    current := length(nodes);
    nodes.append(FallibleNodeFor(statement, next, -1, false));
    if (kind == syntax.ReturnStatement || kind == syntax.GotoStatement) {
        nodes = FallibleLink(nodes, current, -1, nodes[current].second);
    } else if (kind == syntax.BreakStatement) {
        nodes = FallibleLink(nodes, current, leave, nodes[current].second);
    } else if (kind == syntax.ContinueStatement) {
        nodes = FallibleLink(nodes, current, repeat, nodes[current].second);
    } else if (kind == syntax.IfStatement || kind == syntax.WhileStatement) {
        body := Field(forest, statement, syntax.FieldConsequence);
        outgoing := next;
        loop_leave := leave;
        loop_repeat := repeat;
        if (kind == syntax.WhileStatement) {
            body = Field(forest, statement, syntax.FieldBody);
            outgoing = current;
            loop_leave = next;
            loop_repeat = current;
        }
        switch FallibleBuildGraph(forest, text, body, outgoing, loop_leave, loop_repeat, nodes) {
            case .Built(changed, head):
                nodes = changed;
                nodes = FallibleLink(nodes, current, head, nodes[current].second);
        }
        alternative := next;
        if (kind == syntax.IfStatement) {
            switch FallibleBuildGraph(forest, text, Field(forest, statement, syntax.FieldAlternative), next, leave, repeat, nodes) {
                case .Built(changed, head):
                    nodes = changed;
                    alternative = head;
            }
        }
        nodes = FallibleLink(nodes, current, nodes[current].first, alternative);
        truth := FallibleTruth(forest, text, Field(forest, statement, syntax.FieldCondition));
        if (truth == 0) {
            nodes = FallibleLink(nodes, current, alternative, -1);
        }
        if (truth == 1) {
            nodes = FallibleLink(nodes, current, nodes[current].first, -1);
        }
    } else if (kind == syntax.ForStatement) {
        guard := length(nodes);
        nodes.append(FallibleNodeFor(statement, next, -1, true));
        switch FallibleBuildGraph(forest, text, Field(forest, statement, syntax.FieldBody), guard, next, guard, nodes) {
            case .Built(changed, head):
                nodes = changed;
                nodes = FallibleLink(nodes, guard, nodes[guard].first, head);
        }
        nodes = FallibleLink(nodes, current, guard, nodes[current].second);
    } else if (kind == syntax.SwitchStatement) {
        dispatch := next;
        arms := Members(forest, statement);
        // The subject is cached once. Candidate expressions run in source
        // order only while previous candidates have failed to match.
        exhaustive := false;
        has_default := false;
        booleans: int = 0;
        for (arm in arms) {
            if (Is(forest, arm, syntax.SwitchArm)) {
                pattern := Field(forest, arm, syntax.FieldValue);
                exhaustive = exhaustive || Is(forest, pattern, syntax.VariantPattern);
                truth := FallibleTruth(forest, text, pattern);
                if (truth >= 0) {
                    booleans = booleans | (truth + 1);
                }
                if (pattern < 0) {
                    has_default = true;
                    switch FallibleBuildGraph(forest, text, Field(forest, arm, syntax.FieldBody), next, leave, repeat, nodes) {
                        case .Built(changed, head):
                            nodes = changed;
                            dispatch = head;
                    }
                }
            }
        }
        exhaustive = exhaustive || booleans == 3;
        last_case := true;
        index := length(arms);
        while (index > 0) {
            index -= 1;
            arm := arms[index];
            if (Is(forest, arm, syntax.SwitchArm) && Field(forest, arm, syntax.FieldValue) >= 0) {
                switch FallibleBuildGraph(forest, text, Field(forest, arm, syntax.FieldBody), next, leave, repeat, nodes) {
                    case .Built(changed, head):
                        nodes = changed;
                        unmatched := dispatch;
                        if (last_case && !has_default && exhaustive) {
                            unmatched = -1;
                        }
                        link := length(nodes);
                        nodes.append(FallibleNodeFor(arm, head, unmatched, false));
                        dispatch = link;
                        last_case = false;
                }
            }
        }
        nodes = FallibleLink(nodes, current, dispatch, nodes[current].second);
    }
    return FallibleGraph.Built(nodes, current);
}

// What a point of the walk knows about the bindings that hold, point at or
// once held the outcome: rows of FallibleRowSize ints in increasing binding
// order, (binding, alias, pointer target or -1, associated as 0 or 1). A
// binding without a row holds no alias, points nowhere and was never
// associated, which is true of most bindings, so a row exists only when a field
// differs from that. Rows are ints, not records: on the VM a record row costs
// about 1.5% more of a self-compile. The row count bounds every scan below; it
// is the bindings that touch the outcome or an address.
FallibleRowSize: int : 4;
FallibleAliasAt: int : 1;
FalliblePointerAt: int : 2;
FallibleAssociatedAt: int : 3;
FallibleRow :: (facts: int[], binding: int) -> int {
    at: int = 0;
    while (at < length(facts) && facts[at] <= binding) {
        if (facts[at] == binding) {
            return at;
        }
        at += FallibleRowSize;
    }
    return -1;
}
FallibleAliasOf :: (facts: int[], binding: int) -> int {
    row := FallibleRow(facts, binding);
    if (row < 0) {
        return 0;
    }
    return facts[row + FallibleAliasAt];
}
FalliblePointerOf :: (facts: int[], binding: int) -> int {
    row := FallibleRow(facts, binding);
    if (row < 0) {
        return -1;
    }
    return facts[row + FalliblePointerAt];
}
FallibleAssociated :: (facts: int[], binding: int) -> bool {
    row := FallibleRow(facts, binding);
    return row >= 0 && facts[row + FallibleAssociatedAt] != 0;
}
// Appends a binding's row unless every field has its default.
FallibleAppendRow :: (facts: ^(int[]), binding: int, alias: int, pointer: int, associated: bool) {
    if (alias != 0 || pointer >= 0 || associated) {
        flag: int = 0;
        if (associated) {
            flag = 1;
        }
        facts.extend([binding, alias, pointer, flag]);
    }
}
FallibleSame :: (left: int[], right: int[]) -> bool {
    if (length(left) != length(right)) {
        return false;
    }
    for (value, index in left) {
        if (value != right[index]) {
            return false;
        }
    }
    return true;
}
// Every alias reads as none; pointer targets stay, and associations too unless
// `associations` is false.
FallibleForget :: (facts: int[], associations: bool) -> int[] {
    result: int[] = [];
    at: int = 0;
    while (at < length(facts)) {
        FallibleAppendRow(&result, facts[at], 0, facts[at + FalliblePointerAt],
                          associations && facts[at + FallibleAssociatedAt] != 0);
        at += FallibleRowSize;
    }
    return result;
}

// Only pending incoming paths contribute aliases. Intersecting them prevents
// a read that names the error on one branch from hiding loss on another.
FallibleEval :: union {
    Evaluated(pending: bool, lost: bool, value: int, facts: int[])
}
FallibleJoin :: (left_pending: bool, left: int[], right_pending: bool, right: int[]) -> FallibleEval {
    // Bindings without a row on either side join to the default, so the rows
    // of both, merged in binding order, are all that can differ from it.
    facts: int[] = [];
    at: int = 0;
    other: int = 0;
    while (at < length(left) || other < length(right)) {
        binding := 0;
        if (other >= length(right) || (at < length(left) && left[at] <= right[other])) {
            binding = left[at];
        } else {
            binding = right[other];
        }
        // Read through each predecessor's intact pointer map before a join
        // discards differing targets. Cached address aliases can be stale.
        first: int = 0;
        first_pointer: int = -1;
        first_associated := false;
        if (at < length(left) && left[at] == binding) {
            first = left[at + FallibleAliasAt];
            first_pointer = left[at + FalliblePointerAt];
            first_associated = left[at + FallibleAssociatedAt] != 0;
            if (first_pointer >= 0) {
                first = FallibleAlias(left, binding);
            }
            at += FallibleRowSize;
        }
        second: int = 0;
        second_pointer: int = -1;
        second_associated := false;
        if (other < length(right) && right[other] == binding) {
            second = right[other + FallibleAliasAt];
            second_pointer = right[other + FalliblePointerAt];
            second_associated = right[other + FallibleAssociatedAt] != 0;
            if (second_pointer >= 0) {
                second = FallibleAlias(right, binding);
            }
            other += FallibleRowSize;
        }
        alias := first;
        if (right_pending && !left_pending) {
            alias = second;
        } else if (right_pending && left_pending) {
            alias = first & second;
        }
        pointer := first_pointer;
        if (pointer != second_pointer) {
            pointer = -1;
        }
        FallibleAppendRow(&facts, binding, alias, pointer, first_associated || second_associated);
    }
    return FallibleEval.Evaluated(left_pending || right_pending, false, 0, facts);
}

// A pointer chain has at most one hop per row, so a longer one is a cycle.
FallibleAlias :: (facts: int[], binding: int) -> int {
    if (binding < 0) {
        return 0;
    }
    rows := length(facts) / FallibleRowSize;
    at := binding;
    levels: int = 0;
    while (FalliblePointerOf(facts, at) >= 0 && levels < rows) {
        at = FalliblePointerOf(facts, at);
        levels += 1;
    }
    alias := FallibleAliasOf(facts, at);
    if (levels >= rows || alias == 0) {
        return 0;
    }
    return alias + levels * 8;
}

// `target` comes to hold `value` and point at `pointer`, and is associated if
// it was or `associated` says so.
FallibleWrite :: (facts: int[], target: int, value: int, pointer: int, associated: bool) -> int[] {
    // The cell may hold this outcome on only some incoming paths. An unknown
    // merged pointer cannot retain a proof across its overwrite. Known pointers
    // follow live targets and normalize at the next join.
    was := FallibleAssociated(facts, target);
    clear := was && value == 0;
    result: int[] = [];
    placed := false;
    at: int = 0;
    while (at < length(facts)) {
        if (!placed && facts[at] >= target) {
            FallibleAppendRow(&result, target, value, pointer, was || associated);
            placed = true;
        }
        if (facts[at] != target) {
            alias := facts[at + FallibleAliasAt];
            if (clear && facts[at + FalliblePointerAt] < 0 && alias >= 8) {
                alias = 0;
            }
            FallibleAppendRow(&result, facts[at], alias, facts[at + FalliblePointerAt],
                              facts[at + FallibleAssociatedAt] != 0);
        }
        at += FallibleRowSize;
    }
    if (!placed) {
        FallibleAppendRow(&result, target, value, pointer, was || associated);
    }
    return result;
}

FallibleTarget :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[], names: FallibleNames,
                   facts: int[], node: int) -> int {
    value := Unparenthesized(forest, node);
    if (Is(forest, value, syntax.Identifier)) {
        return FallibleNamed(forest, text, bindings, names, value);
    }
    if (Is(forest, value, syntax.DereferenceExpression)) {
        target := FallibleTarget(forest, text, bindings, names, facts, Field(forest, value, syntax.FieldOperand));
        if (target >= 0) {
            return FalliblePointerOf(facts, target);
        }
    }
    return -1;
}

FalliblePointer :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[], names: FallibleNames,
                    facts: int[], node: int) -> int {
    value := Unparenthesized(forest, node);
    if (Is(forest, value, syntax.AddressExpression)) {
        return FallibleTarget(forest, text, bindings, names, facts, Field(forest, value, syntax.FieldOperand));
    }
    target := FallibleTarget(forest, text, bindings, names, facts, value);
    if (target >= 0) {
        return FalliblePointerOf(facts, target);
    }
    return -1;
}

// mode 0 copies an alias, 1 inspects its value, 2 transfers it explicitly.
// Comparing an address does not inspect the error stored at that address.
FallibleExpression :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[], names: FallibleNames, source: int,
                       error_name: string, tuple: bool, node: int, mode: int, input_pending: bool,
                       input_facts: int[]) -> FallibleEval {
    facts := input_facts;
    pending := input_pending;
    lost := false;
    value: int = 0;
    if (node < 0) {
        return FallibleEval.Evaluated(pending, lost, value, facts);
    }
    kind := forest[node].kind;
    if (kind == syntax.Identifier) {
        value = FallibleAlias(facts, FallibleNamed(forest, text, bindings, names, node));
    } else if (kind == syntax.ParenthesizedExpression) {
        return FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                                  Field(forest, node, syntax.FieldExpression), mode, pending, facts);
    } else if (kind == syntax.MemberExpression || kind == syntax.DereferenceExpression || kind == syntax.AddressExpression) {
        operand := Field(forest, node, syntax.FieldObject);
        if (kind != syntax.MemberExpression) {
            operand = Field(forest, node, syntax.FieldOperand);
        }
        switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple, operand, 0, pending, facts) {
            case .Evaluated(next_pending, next_lost, owner, changed):
                pending = next_pending;
                lost = next_lost;
                facts = changed;
                if (kind == syntax.AddressExpression && owner > 0) {
                    value = owner + 8;
                }
                if (kind == syntax.DereferenceExpression && owner >= 8) {
                    value = owner - 8;
                }
                if (kind == syntax.MemberExpression) {
                    member := Text(forest, text, Field(forest, node, syntax.FieldMember));
                    if (owner > 0 && owner < 8 && member == error_name) {
                        value = 2;
                    } else if ((owner & 2) != 0 && owner < 8) {
                        pending = false;
                    }
                }
        }
    } else if (kind == syntax.BinaryExpression) {
        operator := Operator(forest, node);
        switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                                  Field(forest, node, syntax.FieldLeft), 1, pending, facts) {
            case .Evaluated(next_pending, next_lost, ignored, changed):
                pending = next_pending;
                lost = next_lost;
                facts = changed;
        }
        skip := operator == tk.CmpAnd || operator == tk.CmpOr || operator == tk.AndKeyword || operator == tk.OrKeyword || operator == tk.Coalesce;
        truth := FallibleTruth(forest, text, Field(forest, node, syntax.FieldLeft));
        runs := true;
        if (skip && truth >= 0 && operator != tk.Coalesce) {
            runs = truth == 1;
            if (operator == tk.CmpOr || operator == tk.OrKeyword) {
                runs = !runs;
            }
        }
        if (runs) {
            before := facts;
            before_pending := pending;
            switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                                      Field(forest, node, syntax.FieldRight), 1, pending, facts) {
                case .Evaluated(next_pending, next_lost, ignored, changed):
                    pending = next_pending;
                    lost = lost || next_lost;
                    facts = changed;
            }
            if (skip && truth < 0) {
                switch FallibleJoin(before_pending, before, pending, facts) {
                    case .Evaluated(next_pending, ignored_lost, ignored, changed):
                        pending = next_pending;
                        facts = changed;
                }
            }
        }
    } else {
        children: int[] = [];
        child_mode: int = 1;
        if (kind == syntax.CallExpression) {
            children.append(Field(forest, node, syntax.FieldFunction));
            children.extend(Members(forest, Field(forest, node, syntax.FieldArguments)));
            child_mode = 2;
        } else if (kind == syntax.UnaryExpression || kind == syntax.ForceUnwrapExpression ||
                   kind == syntax.OptionalMemberExpression) {
            children.append(Field(forest, node, syntax.FieldOperand));
        } else if (kind == syntax.NamedArgument || kind == syntax.StructField) {
            children.append(Field(forest, node, syntax.FieldValue));
            child_mode = 2;
        } else if (kind == syntax.AsExpression || kind == syntax.IsExpression || kind == syntax.AwaitExpression) {
            children.append(Field(forest, node, syntax.FieldValue));
        } else if (kind == syntax.IndexExpression) {
            children.append(Field(forest, node, syntax.FieldObject));
            children.append(Field(forest, node, syntax.FieldIndex));
        } else if (kind == syntax.RangeExpression) {
            children.append(Field(forest, node, syntax.FieldStart));
            children.append(Field(forest, node, syntax.FieldEnd));
        } else if (kind == syntax.ArrayExpression || kind == syntax.StructExpression ||
                   kind == syntax.ArgumentList || kind == syntax.MapExpression || kind == syntax.MapEntry) {
            children = Members(forest, node);
            child_mode = 2;
        }
        for (child in children) {
            switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                                      child, child_mode, pending, facts) {
                case .Evaluated(next_pending, next_lost, ignored, changed):
                    pending = next_pending;
                    lost = lost || next_lost;
                    facts = changed;
            }
        }
        if (node == source) {
            lost = lost || pending;
            pending = true;
            facts = FallibleForget(facts, false);
            value = 2;
            if (tuple) {
                value = 1;
            }
        }
    }
    if ((mode == 1 && value > 0 && value < 8) || (mode == 2 && value > 0)) {
        pending = false;
    }
    return FallibleEval.Evaluated(pending, lost, value, facts);
}

// Computing a destination can call functions or inspect an index. Merely
// replacing the error slot itself does not read or acknowledge its old value.
FallibleAddress :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[], names: FallibleNames, source: int,
                    error_name: string, tuple: bool, destination: int, input_pending: bool,
                    input_facts: int[]) -> FallibleEval {
    pending := input_pending;
    facts := input_facts;
    lost := false;
    node := Unparenthesized(forest, destination);
    expressions: int[] = [];
    if (Is(forest, node, syntax.MemberExpression) || Is(forest, node, syntax.IndexExpression)) {
        expressions.append(Field(forest, node, syntax.FieldObject));
    } else if (Is(forest, node, syntax.DereferenceExpression)) {
        expressions.append(Field(forest, node, syntax.FieldOperand));
    }
    for (expression in expressions) {
        switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                                  expression, 0, pending, facts) {
            case .Evaluated(next_pending, next_lost, ignored, changed):
                pending = next_pending;
                lost = lost || next_lost;
                facts = changed;
        }
    }
    if (Is(forest, node, syntax.IndexExpression)) {
        switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                                  Field(forest, node, syntax.FieldIndex), 1, pending, facts) {
            case .Evaluated(next_pending, next_lost, ignored, changed):
                pending = next_pending;
                lost = lost || next_lost;
                facts = changed;
        }
    }
    return FallibleEval.Evaluated(pending, lost, 0, facts);
}

FallibleTransfer :: (forest: snapshot.SnapshotNode[], text: string, bindings: FallibleBinding[], names: FallibleNames, source: int,
                     error_name: string, tuple: bool, current: FallibleNode, input_pending: bool,
                     input_facts: int[]) -> FallibleEval {
    pending := input_pending;
    facts := input_facts;
    lost := false;
    node := current.statement;
    if (node < 0 || current.guard) {
        return FallibleEval.Evaluated(pending, lost, 0, facts);
    }
    kind := forest[node].kind;
    if (kind == syntax.Assignment) {
        switch FallibleAddress(forest, text, bindings, names, source, error_name, tuple,
                               Field(forest, node, syntax.FieldTarget), pending, facts) {
            case .Evaluated(next_pending, next_lost, ignored, changed):
                pending = next_pending;
                lost = next_lost;
                facts = changed;
        }
    }
    expression: int = -1;
    mode: int = 1;
    if (kind == syntax.LocalDeclaration || kind == syntax.Assignment || kind == syntax.ReturnStatement) {
        expression = Field(forest, node, syntax.FieldValue);
        mode = 0;
        if (kind == syntax.ReturnStatement) {
            mode = 2;
        }
    } else if (kind == syntax.IfStatement || kind == syntax.WhileStatement) {
        expression = Field(forest, node, syntax.FieldCondition);
    } else if (kind == syntax.SwitchStatement || kind == syntax.SwitchArm || kind == syntax.ForStatement) {
        expression = Field(forest, node, syntax.FieldValue);
    } else if (kind == syntax.ReduceStatement || kind == syntax.CancelStatement) {
        expression = Field(forest, node, syntax.FieldValue);
        mode = 2;
    } else if (kind == syntax.DeleteStatement) {
        expression = Field(forest, node, syntax.FieldTarget);
    } else if (kind == syntax.ExpressionStatement) {
        expression = FirstMember(forest, node);
        mode = 0;
    }
    value: int = 0;
    switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                              expression, mode, pending, facts) {
        case .Evaluated(next_pending, next_lost, produced, changed):
            pending = next_pending;
            lost = lost || next_lost;
            value = produced;
            facts = changed;
    }
    if (kind == syntax.ForStatement || kind == syntax.CancelStatement) {
        for (field in [syntax.FieldFirst, syntax.FieldLast, syntax.FieldDuration]) {
            switch FallibleExpression(forest, text, bindings, names, source, error_name, tuple,
                                      Field(forest, node, field), 1, pending, facts) {
                case .Evaluated(next_pending, next_lost, ignored, changed):
                    pending = next_pending;
                    lost = lost || next_lost;
                    facts = changed;
            }
        }
    }
    if (kind == syntax.LocalDeclaration) {
        target := FallibleDeclarationBinding(bindings, Field(forest, node, syntax.FieldName));
        if (target >= 0) {
            pointer := FalliblePointer(forest, text, bindings, names, facts, expression);
            facts = FallibleWrite(facts, target, value, pointer, value > 0);
        }
    } else if (kind == syntax.Assignment) {
        destination := Unparenthesized(forest, Field(forest, node, syntax.FieldTarget));
        target := FallibleTarget(forest, text, bindings, names, facts, destination);
        if (target >= 0) {
            pointer := FalliblePointer(forest, text, bindings, names, facts, expression);
            facts = FallibleWrite(facts, target, value, pointer, value > 0);
        } else if (Is(forest, destination, syntax.MemberExpression)) {
            owner := FallibleTarget(forest, text, bindings, names, facts, Field(forest, destination, syntax.FieldObject));
            member := Text(forest, text, Field(forest, destination, syntax.FieldMember));
            if (owner >= 0 && FallibleAlias(facts, owner) == 1) {
                if (member == error_name) {
                    kept: int = 0;
                    if (value > 0) {
                        kept = 1;
                    }
                    facts = FallibleWrite(facts, owner, kept, -1, kept > 0);
                }
            } else if (value > 0) {
                pending = false;
            }
        } else if (Is(forest, destination, syntax.DereferenceExpression)) {
            // Unknown merged pointees cannot prove the old alias survived.
            facts = FallibleForget(facts, true);
        } else if (value > 0) {
            pending = false;
        }
    } else if (kind == syntax.ReturnStatement) {
        for (binding, index in bindings) {
            if (binding.returned && FallibleAlias(facts, index) > 0) {
                pending = false;
            }
        }
        lost = lost || pending;
    }
    return FallibleEval.Evaluated(pending, lost, 0, facts);
}

FallibleOutcome :: (forest: snapshot.SnapshotNode[], text: string, callable: Callable, bindings: FallibleBinding[],
                    names: FallibleNames,
                    nodes: FallibleNode[], start: int, source: int, error_name: string, tuple: bool) -> bool {
    // A node's facts are the rows pool[first[node]] onward, count[node] ints;
    // an update appends its rows, so a node's earlier rows stay as they were.
    pool: int[] = [];
    first := resize([int(0)], length(nodes));
    count := resize([int(0)], length(nodes));
    reached := resize([false], length(nodes));
    pending := resize([false], length(nodes));
    reached[start] = true;
    work: int[] = [start];
    lost := false;
    while (length(work) > 0) {
        current := work[length(work) - 1];
        work = slice(work, 0, length(work) - 1);
        facts: int[] = [];
        if (count[current] > 0) {
            facts = slice(pool, first[current], count[current]);
        }
        outgoing := pending[current];
        switch FallibleTransfer(forest, text, bindings, names, source, error_name, tuple, nodes[current], outgoing, facts) {
            case .Evaluated(next_pending, next_lost, ignored, changed):
                outgoing = next_pending;
                lost = lost || next_lost;
                facts = changed;
        }
        if (current == 0) {
            for (binding, index in bindings) {
                if (binding.returned && FallibleAlias(facts, index) > 0) {
                    outgoing = false;
                }
            }
            lost = lost || outgoing;
        }
        for (destination in [nodes[current].first, nodes[current].second]) {
            if (destination >= 0) {
                changed := !reached[destination];
                merged := facts;
                next_pending := outgoing;
                if (reached[destination]) {
                    previous: int[] = [];
                    if (count[destination] > 0) {
                        previous = slice(pool, first[destination], count[destination]);
                    }
                    switch FallibleJoin(pending[destination], previous, outgoing, facts) {
                        case .Evaluated(joined, ignored_lost, ignored, joined_facts):
                            next_pending = joined;
                            merged = joined_facts;
                    }
                    changed = pending[destination] != next_pending || !FallibleSame(previous, merged);
                }
                if (changed) {
                    reached[destination] = true;
                    pending[destination] = next_pending;
                    first[destination] = length(pool);
                    count[destination] = length(merged);
                    pool.extend(merged);
                    work.append(destination);
                }
            }
        }
    }
    return lost;
}

// Resolved call facts come from emission, including calls into imported source
// packages. No native source analyzer or spelling-based error inference runs.
FallibleBody :: (forest: snapshot.SnapshotNode[], documents: snapshot.Document[], callables: Callable[],
                 params: Param[], types: TypeDecl[], callable: Callable, facts: SemanticFact[]) -> syntax.Diagnostic[] {
    sources: SemanticFact[] = [];
    for (fact in facts) {
        if (fact.kind == CallFact && Is(forest, fact.node, syntax.CallExpression) &&
            fact.target >= 0 && fact.target < length(callables)) {
            producer := callables[fact.target];
            if (ErrorResult(types, params, producer)) {
                if (producer.waits) {
                    return [Diagnose(forest, fact.node, callable.document,
                                     "Task error result checking is not supported by stage one yet")];
                }
                duplicate := false;
                for (source in sources) {
                    duplicate = duplicate || source.node == fact.node;
                }
                if (!duplicate) {
                    sources.append(fact);
                }
            }
        }
    }
    if (length(sources) == 0) {
        return [];
    }
    // A generated system-query evaluator retains the system's source node,
    // but executes its header rather than that node's authored body.
    if (Field(forest, callable.node, syntax.FieldBody) < 0) {
        return [Diagnose(forest, sources[0].node, callable.document,
                         "Error result checking requires an authored function body in stage one")];
    }
    text := documents[callable.document].text;
    bindings := FallibleBindings(forest, text, callable);
    names := FallibleResolveNames(forest, text, bindings, Field(forest, callable.node, syntax.FieldBody));
    nodes: FallibleNode[] = [{statement: -1, first: -1, second: -1, guard: true}];
    start: int = 0;
    switch FallibleBuildGraph(forest, text, Field(forest, callable.node, syntax.FieldBody), 0, 0, 0, nodes) {
        case .Built(built, head):
            nodes = built;
            start = head;
    }
    // Gotos resolve once all label nodes exist, preserving ordinary control flow.
    for (node, index in nodes) {
        if (Is(forest, node.statement, syntax.GotoStatement)) {
            name := Text(forest, text, Field(forest, node.statement, syntax.FieldName));
            for (label, target in nodes) {
                if (Is(forest, label.statement, syntax.LabelStatement) &&
                    Text(forest, text, Field(forest, label.statement, syntax.FieldName)) == name) {
                    nodes = FallibleLink(nodes, index, target, nodes[index].second);
                }
            }
        }
    }
    for (source in sources) {
        producer := callables[source.target];
        error_name: string = "";
        if (producer.results > 0) {
            error_name = params[producer.first + producer.count + producer.results - 1].name;
        }
        if (FallibleOutcome(forest, text, callable, bindings, names, nodes, start, source.node, error_name, producer.results > 1)) {
            return [Diagnose(forest, source.node, callable.document,
                             "Error result is ignored on a reachable path; check, report, store or return it")];
        }
    }
    return [];
}
package package_compiler

import snapshot "project:source_snapshot"
import graph "project:package_graph"
