GenericBinder :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    if (node < 0 || Is(forest, node, syntax.TypeBinder)) {
        return node;
    }
    for (child in Members(forest, node)) {
        found := GenericBinder(forest, child);
        if (found >= 0) {
            return found;
        }
    }
    return -1;
}
GenericTemplate :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    parameters := Field(forest, node, syntax.FieldParameters);
    if (GenericBinder(forest, parameters) >= 0) {
        return true;
    }
    for (parameter in Members(forest, parameters)) {
        if (Field(forest, parameter, syntax.FieldComptime) >= 0 ||
            GenericCallableType(forest, Field(forest, parameter, syntax.FieldType)) >= 0) {
            return true;
        }
    }
    return false;
}
GenericCallableType :: (forest: snapshot.SnapshotNode[], node: int) -> int {
    if (node < 0 || Is(forest, node, syntax.CallableType)) {
        return node;
    }
    if (!Is(forest, node, syntax.Type) || HasToken(forest, node, tk.OpenBracket) || HasToken(forest, node, tk.Question) ||
        Field(forest, node, syntax.FieldTrait) >= 0) {
        return -1;
    }
    for (child in Members(forest, node)) {
        if (Is(forest, child, syntax.CallableType)) {
            return child;
        }
        if (Is(forest, child, syntax.ParenthesizedType)) {
            return GenericCallableType(forest, Field(forest, child, syntax.FieldType));
        }
    }
    return -1;
}
GenericOmitted :: (names: Name[], node: int) -> bool {
    for (name in names) {
        if (name.place == GenericOmittedPlace && name.node == node) {
            return true;
        }
    }
    return false;
}
// Template headers retain labels before their types are concrete. These rows
// are never runtime parameters; each instance appends its own typed signature.
GenericParameters :: (forest: snapshot.SnapshotNode[], text: string, declaration: int) -> Param[] {
    params: Param[] = [];
    for (parameter in Members(forest, Field(forest, declaration, syntax.FieldParameters))) {
        storage: int = 0;
        if (GenericCallableType(forest, Field(forest, parameter, syntax.FieldType)) >= 0) {
            storage = GenericFunctionStorage;
        }
        params.append({name: Text(forest, text, Field(forest, parameter, syntax.FieldName)), storage: storage,
                       container: 0, record: -1, has_default: false, default_bits: 0, default_text: "",
                       default_occurrence: 0, reference: false, written: false, node: Field(forest, parameter, syntax.FieldName)});
    }
    return params;
}
GenericArgumentValue :: (forest: snapshot.SnapshotNode[], argument: int) -> int {
    if (Is(forest, argument, syntax.NamedArgument)) { return Field(forest, argument, syntax.FieldValue); }
    return argument;
}
GenericSourceParameter :: (forest: snapshot.SnapshotNode[], text: string, params: Param[], definition: Callable,
                           argument: int, position: int) -> int {
    if (!Is(forest, argument, syntax.NamedArgument)) { return position; }
    label := Text(forest, text, Field(forest, argument, syntax.FieldName));
    count := length(Members(forest, Field(forest, definition.node, syntax.FieldParameters)));
    index: int = 0;
    while (index < count) {
        if (params[definition.first + index].name == label) { return index; }
        index += 1;
    }
    return -1;
}
GenericResolvedCall :: (names: Name[], call: int) -> bool {
    for (name in names) {
        if (name.place == GenericCallPlace && name.node == call) { return true; }
    }
    return false;
}
GenericCallParameter :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                         names: Name[], called: int, call: int, argument: int, ordinal: int) -> int {
    if (GenericResolvedCall(names, call) && Is(forest, argument, syntax.NamedArgument)) {
        label := Text(forest, text, Field(forest, argument, syntax.FieldName));
        index: int = 0;
        while (called >= 0 && index < callables[called].count) {
            if (params[callables[called].first + index].name == label) { return index; }
            index += 1;
