        return SourceCallable(callables, natives, names, package, name);
    }
    if (Is(forest, value, syntax.MemberExpression)) {
        home := QualifierOf(forest, text, names, package, Field(forest, value, syntax.FieldObject));
        if (home >= 0) {
            return QualifiedCallable(callables, natives, names, home, Text(forest, text, Field(forest, value, syntax.FieldMember)),
                                     Text(forest, text, value));
        }
    }
    return -1;
}
GenericCallbackSignature :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], call: int) -> int {
    callee := Field(forest, call, syntax.FieldFunction);
    if (!Is(forest, callee, syntax.Identifier)) {
        return -1;
