GenericCallbackParameter :: (forest: snapshot.SnapshotNode[], text: string, signature: int,
                             argument: int, ordinal: int) -> int {
    if (signature < 0 || !Is(forest, argument, syntax.NamedArgument)) {
        return ordinal;
    }
    label := Text(forest, text, Field(forest, argument, syntax.FieldName));
    parameters := Members(forest, Field(forest, signature, syntax.FieldParameters));
    index: int = 0;
    while (index < length(parameters)) {
        if (Text(forest, text, Field(forest, parameters[index], syntax.FieldName)) == label) {
            return index;
