        node := pending[length(pending) - 1];
        pending = slice(pending, 0, length(pending) - 1);
        if (Is(forest, node, syntax.IsExpression) && PatternScope(forest, text, node, read)) {
            pattern := Field(forest, node, syntax.FieldType);
            for (bound in Members(forest, Field(forest, pattern, syntax.FieldBindings))) {
                if (Text(forest, text, bound) == name) {
                    return true;
