GenericLambdaOwnName :: (forest: snapshot.SnapshotNode[], text: string, lambda: int, read: int, name: string) -> bool {
    for (param in Members(forest, Field(forest, lambda, syntax.FieldParameters))) {
        if (Text(forest, text, Field(forest, param, syntax.FieldName)) == name) {
