// The successful path of `if name` / `while name` shadows the optional with
// its payload. The body's scope removes that proof before the next iteration
// or the alternative branch; the declaration outside that scope stays optional.
// As stage zero unwraps it, each use reads the optional, through the shadow's
// `index` naming it, and takes the payload, or its place, from it.
OptionalConditionNames :: (types: TypeDecl[], names: Name[], forest: snapshot.SnapshotNode[], text: string,
                           condition: int, value: Value) -> Name[] {
    subject := condition;
    while (Is(forest, subject, syntax.ParenthesizedExpression)) {
        subject = Field(forest, subject, syntax.FieldExpression);
    }
    element := OptionalElement(types, value);
    found: int = -1;
    if (Is(forest, subject, syntax.Identifier)) {
        found = Lookup(names, Text(forest, text, subject));
    }
    if (element.storage == 0 || found < 0) {
        return [];
    }
    // A fresh guard refers to storage, not to an earlier guard's shadow.
    while (names[found].place == NarrowedPlace) {
        found = names[found].index;
    }
    original := names[found];
    binding: Name = {owned: false, name: original.name, place: NarrowedPlace, index: found, storage: element.storage,
                     container: element.container, record: element.record, writable: original.writable,
                     node: original.node};
    return [binding];
}

OptionalProofChanged :: (forest: snapshot.SnapshotNode[], text: string, root: int, start: int, finish: int,
                         name: string, aliased: bool) -> bool {
    pending: int[] = [root];
    while length(pending) > 0 {
        node := pending[length(pending) - 1];
        pending = slice(pending, 0, length(pending) - 1);
        if forest[node].start >= start && forest[node].end <= finish {
            if aliased && (Is(forest, node, syntax.CallExpression) || Is(forest, node, syntax.AwaitExpression) ||
                           Is(forest, node, syntax.YieldStatement)) {
                return true;
            }
            if Is(forest, node, syntax.Assignment) {
                destination := Unparenthesized(forest, StatementTarget(forest, node));
                if aliased || (Is(forest, destination, syntax.Identifier) && Text(forest, text, destination) == name) {
                    return true;
                }
            }
        }
        pending.extend(Members(forest, node));
    }
    return false;
}
OptionalBranchExits :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    if node < 0 {
        return false;
    }
    if Is(forest, node, syntax.ReturnStatement) || Is(forest, node, syntax.BreakStatement) ||
       Is(forest, node, syntax.ContinueStatement) {
        return true;
    }
    if Is(forest, node, syntax.Block) || Is(forest, node, syntax.CallableBody) {
        children := Members(forest, node);
        return length(children) > 0 && OptionalBranchExits(forest, children[length(children) - 1]);
    }
    return Is(forest, node, syntax.IfStatement) &&
           OptionalBranchExits(forest, Field(forest, node, syntax.FieldConsequence)) &&
           OptionalBranchExits(forest, Field(forest, node, syntax.FieldAlternative));
