// The latest optional read that establishes this condition's presence proof.
// Invalidation starts at that read, including any later condition operands.
OptionalGuardEnd :: (forest: snapshot.SnapshotNode[], text: string, condition: int, name: string, truth: bool) -> int {
    node := Unparenthesized(forest, condition);
    if Is(forest, node, syntax.Identifier) || Is(forest, node, syntax.MemberExpression) {
        if truth && Text(forest, text, node) == name {
            return forest[node].end;
        }
        return -1;
    }
    if Is(forest, node, syntax.UnaryExpression) {
        operator := Operator(forest, node);
        if operator == tk.Not || operator == tk.NotKeyword {
            return OptionalGuardEnd(forest, text, Field(forest, node, syntax.FieldOperand), name, !truth);
        }
        return -1;
    }
    if !Is(forest, node, syntax.BinaryExpression) {
        return -1;
    }
    operator := Operator(forest, node);
    left := Field(forest, node, syntax.FieldLeft);
    right := Field(forest, node, syntax.FieldRight);
    if (truth && (operator == tk.CmpAnd || operator == tk.AndKeyword)) ||
       (!truth && (operator == tk.CmpOr || operator == tk.OrKeyword)) {
        // Both operands run on this edge. A fresh later test can
        // re-establish presence after an earlier mutation.
        latest := OptionalGuardEnd(forest, text, right, name, truth);
        if latest >= 0 {
            return latest;
        }
        return OptionalGuardEnd(forest, text, left, name, truth);
    }
    left = Unparenthesized(forest, left);
    right = Unparenthesized(forest, right);
    if Is(forest, left, syntax.Nil) {
        swapped := left;
        left = right;
        right = swapped;
    }
    if (!Is(forest, left, syntax.Identifier) && !Is(forest, left, syntax.MemberExpression)) ||
       !Is(forest, right, syntax.Nil) || Text(forest, text, left) != name {
        return -1;
    }
    if (truth && operator == tk.NotEq) || (!truth && operator == tk.CmpEq) {
        return forest[left].end;
    }
    return -1;
}
OptionalPresent :: (forest: snapshot.SnapshotNode[], text: string, binding: Name, node: int) -> bool {
    function := node;
    while function >= 0 && !Is(forest, function, syntax.FunctionDeclaration) {
        function = forest[function].parent;
    }
    if function < 0 {
        return false;
    }
    body := Field(forest, function, syntax.FieldBody);
    aliased := binding.place == ReferencePlace || Holds(AddressedNames(forest, text, body, []), binding.name);
    child := node;
    parent := forest[child].parent;
    crossed_for := false;
    while parent >= 0 && parent != function {
        if Is(forest, parent, syntax.BinaryExpression) && Ancestor(forest, Field(forest, parent, syntax.FieldRight), node) {
            operator := Operator(forest, parent);
            truth := operator == tk.CmpAnd || operator == tk.AndKeyword;
            if truth || operator == tk.CmpOr || operator == tk.OrKeyword {
                condition := Field(forest, parent, syntax.FieldLeft);
                proof := OptionalGuardEnd(forest, text, condition, binding.name, truth);
                if proof >= 0 && (binding.node < 0 || forest[binding.node].start < forest[condition].start) &&
                   !OptionalProofChanged(forest, text, parent, proof, forest[node].start, binding.name, aliased) {
                    return true;
                }
            }
        }
        if Is(forest, parent, syntax.IfStatement) || Is(forest, parent, syntax.WhileStatement) {
            condition := Field(forest, parent, syntax.FieldCondition);
            consequence := Field(forest, parent, syntax.FieldConsequence);
            if Is(forest, parent, syntax.WhileStatement) {
                consequence = Field(forest, parent, syntax.FieldBody);
            }
            truth := consequence >= 0 && forest[child].start >= forest[consequence].start &&
                     forest[child].end <= forest[consequence].end;
            alternative := Field(forest, parent, syntax.FieldAlternative);
            other := alternative >= 0 && forest[child].start >= forest[alternative].start &&
                     forest[child].end <= forest[alternative].end;
            proof := OptionalGuardEnd(forest, text, condition, binding.name, truth);
            if (truth || other) && proof >= 0 &&
               (binding.node < 0 || forest[binding.node].start < forest[condition].start) &&
               !OptionalProofChanged(forest, text, parent, proof, forest[node].start,
                                     binding.name, aliased) {
                return true;
            }
        }
        if Is(forest, parent, syntax.WhileStatement) {
            return false;
        }
        if Is(forest, parent, syntax.ForStatement) {
            crossed_for = true;
        }
        if !crossed_for && (Is(forest, parent, syntax.Block) || Is(forest, parent, syntax.CallableBody)) {
            for statement in Members(forest, parent) {
                if forest[statement].end > forest[child].start {
