                    proof = OptionalGuardEnd(forest, text, condition, binding.name, false);
                }
                if OptionalBranchExits(forest, alternative) {
                    other := OptionalGuardEnd(forest, text, condition, binding.name, true);
                    if other > proof {
                        proof = other;
                    }
                }
                if proof >= 0 && !OptionalProofChanged(forest, text, parent, proof, forest[node].start,
                                                       binding.name, aliased) {
                    return true;
                }
            }
        }
        child = parent;
        parent = forest[parent].parent;
    }
    return false;
}
// Presence proves only the optional payload, not the other values returned
