                // The path must refer to the same lexical root as its guard.
                // Repeated calls have no stable root whose proof can be reused.
                root := RootOf(forest, expression);
                if !Is(forest, root, syntax.Identifier) {
                    return step;
                }
                source := Lookup(names, Text(forest, text, root));
                if source < 0 || Alias(names[source].place) {
                    return step;
                }
                binding.node = names[source].node;
            }
            if !OptionalPresent(forest, text, binding, expression) {
                return step;
            }
            rewritten := code;
            if ops.debug {
                // Native narrowing has an unwrap expression around the
                // original optional read. Both retain their debugger origin.
                rewritten.append(ExpressionCode(ops, node));
                rewritten.append(WatchCode(ops, value.slot, value.storage, value.container, value.record,
                                           0, true, node, target));
