Ancestor :: (forest: snapshot.SnapshotNode[], ancestor: int, node: int) -> bool {
    at := node;
    while (at >= 0) {
        if (at == ancestor) {
            return true;
        }
        at = forest[at].parent;
    }
    return false;
}
// A positive payload pattern is visible in its matching body and in the
// right side of && after the pattern has matched. It never enters an else.
PatternScope :: (forest: snapshot.SnapshotNode[], text: string, pattern: int, node: int) -> bool {
    if (Field(forest, pattern, syntax.FieldNegated) >= 0) {
        return false;
    }
    current := pattern;
    while (forest[current].parent >= 0) {
        parent := forest[current].parent;
        if (Is(forest, parent, syntax.ParenthesizedExpression)) {
            current = parent;
            continue;
        }
        if (Is(forest, parent, syntax.BinaryExpression)) {
            operator := Operator(forest, parent);
            if (operator != tk.CmpAnd && operator != tk.AndKeyword) {
                return false;
            }
            if (Ancestor(forest, Field(forest, parent, syntax.FieldLeft), current) &&
                Ancestor(forest, Field(forest, parent, syntax.FieldRight), node)) {
                return true;
            }
            current = parent;
            continue;
        }
        if (Field(forest, parent, syntax.FieldCondition) != current) {
            return false;
        }
        if (Is(forest, parent, syntax.IfStatement)) {
            return Ancestor(forest, Field(forest, parent, syntax.FieldConsequence), node);
        }
        if (Is(forest, parent, syntax.WhileStatement)) {
            return Ancestor(forest, Field(forest, parent, syntax.FieldBody), node);
        }
        return false;
    }
    return false;
