        parent := forest[node].parent;
        if (Is(forest, parent, syntax.ParenthesizedExpression)) {
            node = parent;
            continue;
        }
        if (Is(forest, parent, syntax.IfStatement) || Is(forest, parent, syntax.WhileStatement)) {
            return Field(forest, parent, syntax.FieldCondition) == node;
        }
        operator := Operator(forest, parent);
        if (Is(forest, parent, syntax.UnaryExpression)) {
            return operator == tk.Not || operator == tk.NotKeyword;
