package package_compiler

import facts "project:scalar_facts"
import snapshot "project:source_snapshot"
import syntax "project:syntax_diagnostics"

// Arrays for the scalar producer: a variable, parameter, result or call that
// is an array of numbers, bool, strings, or records or unions the source
// declares, with its literals, reads `a[i]`, `a[i].f`,
// `length(a)` and `a.length()`, `slice(a, start, count)`, `resize(a, n)` and
// `contains(a, x)`, stores `a[i] = x`, `a[i] += x` and `a[i].f = x`,
// `a.append(x)`, `a.extend(b)` and `a.remove_index(i)`, and loops over its
// elements. The ordinary compiler's decisions
// type them; these rows say which array a statement changes, and where a
// value that would otherwise be shared is copied. An array that is read from a
// variable and stored in another, or returned from a parameter, is copied; a
// call's argument is lent, since a function cannot change its parameters.

// The facts type of the elements `shape` describes, a number, bool, string,
// or a record or union the source declares; 0 for any other.
ScalarElementType :: (types: TypeDecl[], shape: ValueType) -> int {
    return ScalarValueType(types, shape.storage, 0, shape.record);
}
// The facts type of an array whose elements are of `storage` and `record`, or
// 0 when they are of no such type.
ScalarArrayType :: (types: TypeDecl[], storage: int, record: int) -> int {
    element := ScalarValueType(types, storage, 0, record);
    if (element == 0) {
        return 0;
    }
    return facts.ArrayType + element;
}
// Whether elements of `storage` can be in a scalar module's array.
ScalarArrayElement :: (storage: int) -> bool {
    return ScalarTypeOf(storage) != 0 || storage == StructStorage || storage == UnionStorage;
}
// The array the literal `node` is, from its first element when that names its
// own storage: a string, a bool, a number conversion such as `u8(0)`, a call of
// a function of the source, or a variable, a record's field or an array's element that holds one number, bool, string, record or union.
// An element of another form, such as a bare number, has storage 0.
ScalarLiteralShape :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                       names: Name[], types: TypeDecl[], members: TypeMember[], package: int, node: int) -> ValueType {
    head := FirstMember(forest, node);
    storage: int = 0;
    record: int = -1;
    if (head < 0) {
        return {storage: 0, container: 0, record: -1};
    }
    first := Unparenthesized(forest, head);
    if (Is(forest, first, syntax.String)) {
        storage = TextStorage;
    } else if (Is(forest, first, syntax.Boolean)) {
        storage = BoolStorage;
    } else if (Is(forest, first, syntax.CallExpression)) {
        callee := CalledFunction(forest, text, callables, [], names, package, first);
        if (callee >= 0 && callables[callee].result_container == 0) {
            storage = callables[callee].result;
            record = callables[callee].result_record;
        } else if (callee < 0) {
            storage = NumberConversionType(forest, text, first);
        }
    } else if (Is(forest, first, syntax.Identifier)) {
        found := Lookup(names, Text(forest, text, first));
        if (found >= 0 && names[found].container == 0) {
            storage = names[found].storage;
            record = names[found].record;
        }
    } else if (Is(forest, first, syntax.MemberExpression)) {
        field := ScalarMember(forest, text, callables, params, names, types, members, package, first);
        if (field >= 0 && members[field].container == 0) {
            storage = members[field].storage;
            record = members[field].record;
        }
    } else if (Is(forest, first, syntax.IndexExpression)) {
        // An element of an array of numbers, bool, strings, records or unions.
        held := ScalarArrayShape(forest, text, callables, params, names, types, members, package, Field(forest, first, syntax.FieldObject));
        if (held.container == ArrayContainer) {
            storage = held.storage;
            record = held.record;
        }
    }
    if (!ScalarArrayElement(storage)) {
        return {storage: 0, container: 0, record: -1};
    }
    return {storage: storage, container: ArrayContainer, record: record};
}
// The array the value `node` is, as the storage of its elements: a variable,
// a field of a record, or a call of a function of the source that returns one.
// Any other value has storage 0.
ScalarArrayShape :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                     names: Name[], types: TypeDecl[], members: TypeMember[], package: int, node: int) -> ValueType {
    none: ValueType = {storage: 0, container: 0, record: -1};
    value := Unparenthesized(forest, node);
    if (Is(forest, value, syntax.ArrayExpression)) {
        return ScalarLiteralShape(forest, text, callables, params, names, types, members, package, value);
    }
    if (Is(forest, value, syntax.Identifier)) {
        found := Lookup(names, Text(forest, text, value));
        if (found >= 0 && names[found].container == ArrayContainer) {
            return {storage: names[found].storage, container: ArrayContainer, record: names[found].record};
        }
        return none;
    }
    // An array field of a record.
    if (Is(forest, value, syntax.MemberExpression)) {
        field := ScalarMember(forest, text, callables, params, names, types, members, package, value);
        if (field >= 0 && members[field].container == ArrayContainer) {
            return {storage: members[field].storage, container: ArrayContainer, record: members[field].record};
        }
        return none;
    }
    if (Is(forest, value, syntax.CallExpression)) {
        callee := CalledFunction(forest, text, callables, [], names, package, value);
        if (callee >= 0 && callables[callee].result_container == ArrayContainer) {
            return {storage: callables[callee].result, container: ArrayContainer,
                    record: callables[callee].result_record};
        }
        native := ScalarArrayCall(forest, text, callables, params, names, types, members, package, value);
        if (native.operator == facts.ArrayBytes) {
            return {storage: IntStorage, container: ArrayContainer, record: -1};
        }
        if (native.operator != 0 && native.operator != facts.ArrayContains && native.operator != facts.ArrayText) {
            return ScalarArrayShape(forest, text, callables, params, names, types, members, package, native.array);
        }
    }
    return none;
}
// A call of an array native: the Array operator, the node of the array it
// takes and the nodes of its other arguments.
ScalarNativeCall :: struct {
    operator: int;
    array: int;
    arguments: int[];
}
// The array native `node` calls on an array: `slice(a, start, count)`,
// `resize(a, n)`, `append(a, x)`, `extend(a, b)` or `contains(a, x)`, or
// `a.contains(x)`; operator 0 for any other call. The first four give new
// arrays and change nothing they take.
ScalarArrayCall :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                    names: Name[], types: TypeDecl[], members: TypeMember[], package: int,
                    node: int) -> ScalarNativeCall {
    none: ScalarNativeCall = {operator: 0, array: -1, arguments: []};
    if (!Is(forest, node, syntax.CallExpression) ||
        CalledFunction(forest, text, callables, [], names, package, node) >= 0) {
        return none;
    }
    function := Field(forest, node, syntax.FieldFunction);
    arguments := Members(forest, Field(forest, node, syntax.FieldArguments));
    name := "";
    array: int = -1;
    others: int[] = [];
    if (Is(forest, function, syntax.Identifier) && length(arguments) > 0) {
        name = Text(forest, text, function);
        array = arguments[0];
        for (index in 1..<length(arguments)) {
            others.append(arguments[index]);
        }
    } else if (Is(forest, function, syntax.MemberExpression)) {
        name = Text(forest, text, Field(forest, function, syntax.FieldMember));
        array = Field(forest, function, syntax.FieldObject);
        others = arguments;
    }
    operator: int = 0;
    wanted: int = 0;
    if (NameMatches(name, "slice") && Is(forest, function, syntax.Identifier)) {
        operator = facts.ArraySlice;
        wanted = 2;
    } else if (NameMatches(name, "resize") && Is(forest, function, syntax.Identifier)) {
        operator = facts.ArrayResize;
        wanted = 1;
    } else if (NameMatches(name, "append") && Is(forest, function, syntax.Identifier)) {
        operator = facts.ArrayWith;
        wanted = 1;
    } else if (NameMatches(name, "extend") && Is(forest, function, syntax.Identifier)) {
        operator = facts.ArrayJoin;
        wanted = 1;
    } else if (NameMatches(name, "contains")) {
        operator = facts.ArrayContains;
        wanted = 1;
    } else if (NameMatches(name, "text_bytes") && Is(forest, function, syntax.Identifier)) {
        operator = facts.ArrayBytes;
    } else if (NameMatches(name, "text_from_bytes") && Is(forest, function, syntax.Identifier)) {
        operator = facts.ArrayText;
    }
    if (operator == facts.ArrayBytes) {
        // The argument is a string, not an array.
        if (length(others) != 0 || array < 0) {
            return none;
        }
        return {operator: operator, array: array, arguments: others};
    }
    if (operator == 0 || length(others) != wanted || array < 0 ||
        ScalarArrayShape(forest, text, callables, params, names, types, members, package, array).storage == 0) {
        return none;
    }
    return {operator: operator, array: array, arguments: others};
}
// The array whose length `node` takes, `length(a)` or `a.length()`, or -1.
ScalarLengthOf :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                   names: Name[], types: TypeDecl[], members: TypeMember[], package: int, node: int) -> int {
    if (!Is(forest, node, syntax.CallExpression)) {
        return -1;
    }
    function := Field(forest, node, syntax.FieldFunction);
    arguments := Members(forest, Field(forest, node, syntax.FieldArguments));
    array: int = -1;
    if (Is(forest, function, syntax.Identifier) && NameMatches(Text(forest, text, function), "length") &&
        length(arguments) == 1 && CalledFunction(forest, text, callables, [], names, package, node) < 0) {
        array = arguments[0];
    } else if (Is(forest, function, syntax.MemberExpression) &&
               NameMatches(Text(forest, text, Field(forest, function, syntax.FieldMember)), "length") && length(arguments) == 0 &&
               CalledFunction(forest, text, callables, [], names, package, node) < 0) {
        array = Field(forest, function, syntax.FieldObject);
    }
    if (array >= 0 && ScalarArrayShape(forest, text, callables, params, names, types, members, package, array).storage != 0) {
        return array;
    }
    return -1;
}
// The array that `statement`, an expression statement, changes, or -1: its
// call is `a.append(x)`, `a.extend(b)`, `a.remove_index(i)` or `a.resize(n)` on a variable
// `a`, or on an array field `r.f` of a record variable `r`.
ScalarChangeOf :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                   names: Name[], types: TypeDecl[], members: TypeMember[], package: int, statement: int) -> int {
    call := FirstMember(forest, statement);
    if (!Is(forest, statement, syntax.ExpressionStatement) || !Is(forest, call, syntax.CallExpression)) {
        return -1;
    }
    function := Field(forest, call, syntax.FieldFunction);
    if (!Is(forest, function, syntax.MemberExpression) ||
        ScalarChangeKind(forest, text, statement) == 0 ||
        length(Members(forest, Field(forest, call, syntax.FieldArguments))) != 1) {
        return -1;
    }
    object := Unparenthesized(forest, Field(forest, function, syntax.FieldObject));
    if ((Is(forest, object, syntax.Identifier) ||
         (Is(forest, object, syntax.MemberExpression) &&
          Is(forest, Unparenthesized(forest, Field(forest, object, syntax.FieldObject)), syntax.Identifier) &&
          ScalarMember(forest, text, callables, params, names, types, members, package, object) >= 0)) &&
        ScalarArrayShape(forest, text, callables, params, names, types, members, package, object).storage != 0) {
        return object;
    }
    return -1;
}
// The Array operator of the method `statement` calls: ArrayPush for append,
// ArrayExtend for extend, ArrayRemove for remove_index and ArrayResize for
// resize; 0 for any other.
ScalarChangeKind :: (forest: snapshot.SnapshotNode[], text: string, statement: int) -> int {
    function := Field(forest, FirstMember(forest, statement), syntax.FieldFunction);
    if (!Is(forest, function, syntax.MemberExpression)) {
        return 0;
    }
    method := Text(forest, text, Field(forest, function, syntax.FieldMember));
    if (NameMatches(method, "append")) {
        return facts.ArrayPush;
    }
    if (NameMatches(method, "extend")) {
        return facts.ArrayExtend;
    }
    if (NameMatches(method, "remove_index")) {
        return facts.ArrayRemove;
    }
    if (NameMatches(method, "resize")) {
        return facts.ArrayResize;
    }
    return 0;
}
// Whether `node` reads an array another place keeps: a variable, a field or
// an element. Storing it copies it, so no two places share the elements.
ScalarBorrowed :: (forest: snapshot.SnapshotNode[], node: int) -> bool {
    return Is(forest, node, syntax.Identifier) || Is(forest, node, syntax.MemberExpression) ||
           Is(forest, node, syntax.IndexExpression);
}
// Whether `value`, returned, reads an array the caller keeps: a parameter, a
// pattern's binding or a loop's variable, or a field or an element of any.
ScalarKeptRead :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], value: int) -> bool {
    node := Unparenthesized(forest, value);
    if (Is(forest, node, syntax.MemberExpression) || Is(forest, node, syntax.IndexExpression)) {
        return true;
    }
    if (!Is(forest, node, syntax.Identifier)) {
        return false;
    }
    found := Lookup(names, Text(forest, text, node));
    return found >= 0 && (names[found].place == ParameterPlace || !names[found].writable);
}
// Whether `value`, the array a loop visits, is a variable that the loop's
// `body` changes, so the loop visits a copy of it.
ScalarIterationCopies :: (forest: snapshot.SnapshotNode[], text: string, body: int, value: int) -> bool {
    node := Unparenthesized(forest, value);
    return Is(forest, node, syntax.Identifier) &&
           NamePosition(MutatedNames(forest, text, body, []), Text(forest, text, node)) >= 0;
}
// The array a loop visits, `node`: ScalarArrayShape's, or for a literal whose
// first element it cannot type, such as a package constant or a bare number,
// the storage that element has where it is written, as a local declaration of
// the literal types it. Storage 0 for any other value.
ScalarVisitedShape :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                       callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                       constants: ConstDecl[], node: int) -> ValueType {
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, node);
    literal := Unparenthesized(forest, node);
    first := FirstMember(forest, literal);
    if (shape.storage != 0 || !Is(forest, literal, syntax.ArrayExpression) || first < 0) {
        return shape;
    }
    storage := ScalarOperandStorage(forest, text, callables, params, callable, names, types, members, constants, first,
                                    ConstantExpressionStorage(forest, text, first));
    if (!ScalarArrayElement(storage)) {
        return shape;
    }
    return {storage: storage, container: ArrayContainer, record: -1};
}
// The array variable's type as a facts type, or 0 for a value that is none.
ScalarArrayHeld :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                    names: Name[], types: TypeDecl[], members: TypeMember[], package: int, node: int) -> int {
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, package, node);
    if (shape.storage == 0) {
        return 0;
    }
    return ScalarArrayType(types, shape.storage, shape.record);
}
// The facts type of member `field` of a record or union: a number, bool,
// string, array, or record or union the source declares; 0 for any other.
ScalarMemberType :: (types: TypeDecl[], members: TypeMember[], field: int) -> int {
    return ScalarValueType(types, members[field].storage, members[field].container, members[field].record);
}
// The shape of member `field`: its storage, container and record.
ScalarMemberShape :: (members: TypeMember[], field: int) -> ValueType {
    return {storage: members[field].storage, container: members[field].container, record: members[field].record};
}
// The shape of the elements of the array `shape` describes.
ScalarElementShape :: (shape: ValueType) -> ValueType {
    return {storage: shape.storage, container: 0, record: shape.record};
}
// The rows of `node`, a value of the elements or member `shape` describes,
// after `rows`: an array as ScalarArrayStored reads one, a record as
// ScalarRecordValue reads one, any other converted to its storage.
ScalarElementValue :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                       callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                       constants: ConstDecl[], node: int, shape: ValueType, rows: facts.Row[]) -> ScalarOperands {
    if (shape.container == ArrayContainer) {
        return ScalarArrayStored(forest, text, callables, params, callable, names, types, members, constants, node, shape,
                                 true, rows);
    }
    if (shape.storage == StructStorage || (shape.storage == UnionStorage && ScalarOptional(types, shape.record))) {
        return ScalarRecordValue(forest, text, callables, params, callable, names, types, members, constants, node,
                                 shape.record, rows);
    }
    return ScalarConvert(forest, text, callables, params, callable, names, types, members, constants, node, node,
                         shape.storage, shape.storage, facts.Clamp, rows);
}
// The rows of `operand`, an array of the elements `shape` describes, after
// `rows`: a variable's read, a call of a function of the source that returns
// one, or a literal, each element as ScalarElementValue reads it, then its
// ArrayNew. The array is the variable's own, not a copy.
ScalarArrayValue :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                     callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                     constants: ConstDecl[], operand: int, shape: ValueType, rows: facts.Row[]) -> ScalarOperands {
    node := Unparenthesized(forest, operand);
    output := rows;
    array := ScalarArrayType(types, shape.storage, shape.record);
    held := ScalarArrayHeld(forest, text, callables, params, names, types, members, callable.package, node);
    if (Is(forest, node, syntax.Identifier) && held != 0) {
        output.append(ScalarAt(forest, node, facts.ReadRow, held, ScalarVariable(names, Text(forest, text, node)).index,
                               0, ""));
        return ScalarOperands.Built(output);
    }
    if ((Is(forest, node, syntax.CallExpression) || Is(forest, node, syntax.MemberExpression)) && held != 0) {
        return ScalarOperand(forest, text, callables, params, callable, names, types, members, constants, node, 0, rows);
    }
    if (!Is(forest, node, syntax.ArrayExpression) || array == 0) {
        return ScalarOperands.Failed(Diagnose(forest, node, 0,
                                              "scalar proof takes arrays only from literals, variables and calls"));
    }
    elements := Members(forest, node);
    for (element in elements) {
        switch ScalarElementValue(forest, text, callables, params, callable, names, types, members, constants, element,
                                  ScalarElementShape(shape), output) {
            case .Failed(diagnostic):
                return ScalarOperands.Failed(diagnostic);
            case .Built(built):
                output = built;
        }
    }
    output.append(ScalarAt(forest, node, facts.ArrayRow, array, facts.ArrayNew, length(elements), ""));
    return ScalarOperands.Built(output);
}
// The rows of `operand` as ScalarArrayValue gives them, then an ArrayCopy
// when `copy` and the value is one an array variable holds.
ScalarArrayStored :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                      callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                      constants: ConstDecl[], operand: int, shape: ValueType, copied: bool,
                      rows: facts.Row[]) -> ScalarOperands {
    switch ScalarArrayValue(forest, text, callables, params, callable, names, types, members, constants, operand, shape,
                            rows) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output := built;
            if (copied && ScalarBorrowed(forest, Unparenthesized(forest, operand))) {
                output.append(ScalarAt(forest, operand, facts.ArrayRow, ScalarArrayType(types, shape.storage, shape.record),
                                       facts.ArrayCopy, 1, ""));
            }
            return ScalarOperands.Built(output);
    }
}
// The rows of `node`, `a[i]` of an array, after `rows`: the array, the index
// as an int, then its ArrayGet.
ScalarIndexed :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                  callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[], constants: ConstDecl[],
                  node: int, rows: facts.Row[]) -> ScalarOperands {
    object := Field(forest, node, syntax.FieldObject);
    index := Field(forest, node, syntax.FieldIndex);
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, object);
    if (ScalarArrayHeld(forest, text, callables, params, names, types, members, callable.package, object) == 0 ||
        Is(forest, index, syntax.RangeExpression)) {
        return ScalarOperands.Failed(Diagnose(forest, node, 0, "scalar proof indexes only arrays of numbers, bool, strings, records and unions by an int"));
    }
    output := rows;
    switch ScalarArrayValue(forest, text, callables, params, callable, names, types, members, constants, object, shape,
                            output) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output = built;
    }
    switch ScalarConvert(forest, text, callables, params, callable, names, types, members, constants, index, index,
                         IntStorage, IntStorage, facts.Clamp, output) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output = built;
    }
    output.append(ScalarAt(forest, node, facts.ArrayRow, ScalarElementType(types, shape), facts.ArrayGet, 2, ""));
    return ScalarOperands.Built(output);
}
// The rows of `node`, `length(a)` or `a.length()` of the array `object`,
// after `rows`: the array, then its ArrayLength.
ScalarLength :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                 callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[], constants: ConstDecl[],
                 node: int, object: int, rows: facts.Row[]) -> ScalarOperands {
    if (ScalarArrayHeld(forest, text, callables, params, names, types, members, callable.package, object) == 0) {
        return ScalarOperands.Failed(Diagnose(forest, node, 0, "scalar proof supports only arrays of numbers, bool, strings, records and unions"));
    }
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, object);
    switch ScalarArrayValue(forest, text, callables, params, callable, names, types, members, constants, object, shape,
                            rows) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output := built;
            output.append(ScalarAt(forest, node, facts.ArrayRow, facts.IntType, facts.ArrayLength, 1, ""));
            return ScalarOperands.Built(output);
    }
}
// The rows that read the array variable `object` and the index `index` of an
// element, after `rows`.
ScalarElementPlace :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                       callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                       constants: ConstDecl[], object: int, index: int, shape: ValueType,
                       rows: facts.Row[]) -> ScalarOperands {
    switch ScalarArrayValue(forest, text, callables, params, callable, names, types, members, constants, object, shape,
                            rows) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            return ScalarConvert(forest, text, callables, params, callable, names, types, members, constants, index,
                                 index, IntStorage, IntStorage, facts.Clamp, built);
    }
}
// The operand rows of the assignment `node` to element `a[i]` or to its field
// `a[i].f`, after `rows`, as StatementStep writes them. The element's place is
// the array and the index. The value is stored at the place after it: a plain
// store of an element, or a field, is the value converted to the element's or
// the field's storage, after the element read, whose field it replaces; a
// compound assignment reads the element, then the field, and combines it with
// the value. Each ends with ArraySet.
ScalarElementAssigned :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                          callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                          constants: ConstDecl[], node: int, rows: facts.Row[]) -> ScalarOperands {
    destination := Field(forest, node, syntax.FieldTarget);
    fielded := Is(forest, destination, syntax.MemberExpression);
    place := destination;
    if (fielded) {
        place = Unparenthesized(forest, Field(forest, destination, syntax.FieldObject));
    }
    object := Field(forest, place, syntax.FieldObject);
    index := Field(forest, place, syntax.FieldIndex);
    if (!fielded && Is(forest, Unparenthesized(forest, object), syntax.MemberExpression)) {
        return ScalarFieldElementAssigned(forest, text, callables, params, callable, names, types, members, constants, node,
                                          rows);
    }
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, object);
    array := ScalarArrayHeld(forest, text, callables, params, names, types, members, callable.package, object);
    element := ScalarElementType(types, shape);
    if (array == 0 || !Is(forest, Unparenthesized(forest, object), syntax.Identifier) ||
        Is(forest, index, syntax.RangeExpression)) {
        return ScalarOperands.Failed(Diagnose(forest, destination, 0,
                                              "scalar proof assigns only elements of array variables"));
    }
    // What the value replaces: the element, or one of its fields.
    stored := ScalarElementShape(shape);
    field := -1;
    if (fielded) {
        field = ScalarMember(forest, text, callables, params, names, types, members, callable.package, destination);
        if (field < 0) {
            return ScalarOperands.Failed(Diagnose(forest, destination, 0,
                                                  "scalar proof assigns only elements of array variables"));
        }
        stored = ScalarMemberShape(members, field);
    }
    place_type := ScalarTypeOf(stored.storage);
    if (!fielded) {
        place_type = element;
    }
    output := rows;
    operator := ScalarArithmetic(CompoundOperator(Operator(forest, node)));
    reads := 1;
    if (operator != 0 || fielded) {
        reads = 2;
    }
    if (operator != 0 && fielded) {
        reads = 3;
    }
    for (read in 0..<reads) {
        switch ScalarElementPlace(forest, text, callables, params, callable, names, types, members, constants, object,
                                  index, shape, output) {
            case .Failed(diagnostic):
                return ScalarOperands.Failed(diagnostic);
            case .Built(built):
                output = built;
        }
        if (read > 0) {
            output.append(ScalarAt(forest, destination, facts.ArrayRow, element, facts.ArrayGet, 2, ""));
        }
    }
    if (operator != 0 && fielded) {
        output.append(ScalarAt(forest, destination, facts.FieldRow, place_type, field - types[shape.record].first, 1,
                               ""));
    }
    value := Field(forest, node, syntax.FieldValue);
    switch ScalarElementValue(forest, text, callables, params, callable, names, types, members, constants, value, stored,
                              output) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output = built;
    }
    if (operator != 0) {
        output.append(ScalarAt(forest, node, facts.ArithmeticRow, place_type, operator, 2, ""));
    }
    if (fielded) {
        output.append(ScalarAt(forest, destination, facts.UpdateRow, element, field - types[shape.record].first, 2, ""));
    }
    output.append(ScalarAt(forest, destination, facts.ArrayRow, array, facts.ArraySet, 3, ""));
    return ScalarOperands.Built(output);
}
// The operand rows of the assignment `node` to element `r.f[i]` of an array
// field of a record variable, after `rows`: a read of `r`, the field read from
// a second read of `r`, the index, for a compound assignment the element read
// again, the value converted to the element, their combination, then ArraySet
// and the record's Update of the field.
ScalarFieldElementAssigned :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                               callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                               constants: ConstDecl[], node: int, rows: facts.Row[]) -> ScalarOperands {
    destination := Field(forest, node, syntax.FieldTarget);
    object := Unparenthesized(forest, Field(forest, destination, syntax.FieldObject));
    index := Field(forest, destination, syntax.FieldIndex);
    variable := Unparenthesized(forest, Field(forest, object, syntax.FieldObject));
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, object);
    array := ScalarArrayHeld(forest, text, callables, params, names, types, members, callable.package, object);
    field := ScalarMember(forest, text, callables, params, names, types, members, callable.package, object);
    if (array == 0 || field < 0 || !Is(forest, variable, syntax.Identifier) || Is(forest, index, syntax.RangeExpression)) {
        return ScalarOperands.Failed(Diagnose(forest, destination, 0,
                                              "scalar proof assigns only elements of array variables"));
    }
    record := ScalarRecordOf(forest, text, callables, params, names, types, members, callable.package, variable);
    place := field - types[record].first;
    element := ScalarElementType(types, shape);
    ordinal := ScalarVariable(names, Text(forest, text, variable)).index;
    read := ScalarAt(forest, variable, facts.ReadRow, ScalarRecordType(types, record), ordinal, 0, "");
    held := ScalarAt(forest, object, facts.FieldRow, array, place, 1, "");
    operator := ScalarArithmetic(CompoundOperator(Operator(forest, node)));
    output := rows;
    output.extend([read, read, held]);
    switch ScalarConvert(forest, text, callables, params, callable, names, types, members, constants, index, index,
                         IntStorage, IntStorage, facts.Clamp, output) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output = built;
    }
    if (operator != 0) {
        output.extend([read, held]);
        switch ScalarConvert(forest, text, callables, params, callable, names, types, members, constants, index, index,
                             IntStorage, IntStorage, facts.Clamp, output) {
            case .Failed(diagnostic):
                return ScalarOperands.Failed(diagnostic);
            case .Built(built):
                output = built;
        }
        output.append(ScalarAt(forest, destination, facts.ArrayRow, element, facts.ArrayGet, 2, ""));
    }
    switch ScalarElementValue(forest, text, callables, params, callable, names, types, members, constants,
                              Field(forest, node, syntax.FieldValue), ScalarElementShape(shape), output) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output = built;
    }
    if (operator != 0) {
        output.append(ScalarAt(forest, node, facts.ArithmeticRow, element, operator, 2, ""));
    }
    output.append(ScalarAt(forest, destination, facts.ArrayRow, array, facts.ArraySet, 3, ""));
    output.append(ScalarAt(forest, destination, facts.UpdateRow, ScalarRecordType(types, record), place, 2, ""));
    return ScalarOperands.Built(output);
}
// The operand rows of the statement `a.append(x)`, `a.extend(b)` or
// `a.remove_index(i)` of array variable `object`, after `rows`: a read of the
// array, the argument, an element, another array or an int, then the Array
// row of `operator`. For an array field `r.f`, the array is r's field read
// under a read of r, and the record's Update of f follows the Array row.
ScalarChanged :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                  callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                  constants: ConstDecl[], statement: int, object: int, operator: int,
                  rows: facts.Row[]) -> ScalarOperands {
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, object);
    array := ScalarArrayType(types, shape.storage, shape.record);
    call := FirstMember(forest, statement);
    if (array == 0) {
        return ScalarOperands.Failed(Diagnose(forest, call, 0, "scalar proof supports only arrays of numbers, bool, strings, records and unions"));
    }
    output := rows;
    // An array field of a record variable: the record, then the record again
    // and its field, which the Array row changes and the record's Update takes
    // back.
    fielded := Is(forest, object, syntax.MemberExpression);
    variable := object;
    field := -1;
    record := -1;
    if (fielded) {
        variable = Unparenthesized(forest, Field(forest, object, syntax.FieldObject));
        field = ScalarMember(forest, text, callables, params, names, types, members, callable.package, object);
        record = ScalarRecordOf(forest, text, callables, params, names, types, members, callable.package, variable);
        ordinal := ScalarVariable(names, Text(forest, text, variable)).index;
        read := ScalarAt(forest, variable, facts.ReadRow, ScalarRecordType(types, record), ordinal, 0, "");
        output.extend([read, read, ScalarAt(forest, object, facts.FieldRow, array, field - types[record].first, 1, "")]);
    } else {
        output.append(ScalarAt(forest, object, facts.ReadRow, array, ScalarVariable(names, Text(forest, text, object)).index,
                               0, ""));
    }
    value := FirstMember(forest, Field(forest, call, syntax.FieldArguments));
    switch ScalarArrayArgument(forest, text, callables, params, callable, names, types, members, constants, value, shape,
                               operator, output) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output = built;
    }
    output.append(ScalarAt(forest, call, facts.ArrayRow, array, operator, 2, ""));
    if (fielded) {
        output.append(ScalarAt(forest, object, facts.UpdateRow, ScalarRecordType(types, record), field - types[record].first,
                               2, ""));
    }
    return ScalarOperands.Built(output);
}
// The rows of `node`, the argument of the array native `operator` on arrays of
// the elements `shape` describes, after `rows`: another array for
// ArrayExtend, an element for ArrayPush and ArrayContains, otherwise an int.
ScalarArrayArgument :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                        callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                        constants: ConstDecl[], node: int, shape: ValueType, operator: int,
                        rows: facts.Row[]) -> ScalarOperands {
    if (operator == facts.ArrayExtend || operator == facts.ArrayJoin) {
        return ScalarArrayValue(forest, text, callables, params, callable, names, types, members, constants, node, shape,
                                rows);
    }
    if (operator == facts.ArrayPush || operator == facts.ArrayWith || operator == facts.ArrayContains) {
        return ScalarElementValue(forest, text, callables, params, callable, names, types, members, constants, node,
                                  ScalarElementShape(shape), rows);
    }
    return ScalarConvert(forest, text, callables, params, callable, names, types, members, constants, node, node,
                         IntStorage, IntStorage, facts.Clamp, rows);
}
// The rows of `node`, a call of the array native described by `native`, after
// `rows`: the array, its arguments, then the Array row.
ScalarNativeRows :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                     callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                     constants: ConstDecl[], node: int, native: ScalarNativeCall,
                     rows: facts.Row[]) -> ScalarOperands {
    if (native.operator == facts.ArrayBytes) {
        // The string's rows, then the int array of its bytes.
        switch ScalarOperand(forest, text, callables, params, callable, names, types, members, constants, native.array,
                             TextStorage, rows) {
            case .Failed(diagnostic):
                return ScalarOperands.Failed(diagnostic);
            case .Built(built):
                output := built;
                output.append(ScalarAt(forest, node, facts.ArrayRow, facts.ArrayType + facts.IntType, native.operator, 1,
                                       ""));
                return ScalarOperands.Built(output);
        }
    }
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, native.array);
    array := ScalarArrayType(types, shape.storage, shape.record);
    if (array == 0 || (native.operator == facts.ArrayContains && ScalarTypeOf(shape.storage) == 0)) {
        return ScalarOperands.Failed(Diagnose(forest, node, 0, "scalar proof supports only arrays of numbers, bool, strings, records and unions"));
    }
    switch ScalarArrayValue(forest, text, callables, params, callable, names, types, members, constants, native.array,
                            shape, rows) {
        case .Failed(diagnostic):
            return ScalarOperands.Failed(diagnostic);
        case .Built(built):
            output := built;
            for (argument in native.arguments) {
                switch ScalarArrayArgument(forest, text, callables, params, callable, names, types, members, constants,
                                           argument, shape, native.operator, output) {
                    case .Failed(diagnostic):
                        return ScalarOperands.Failed(diagnostic);
                    case .Built(argued):
                        output = argued;
                }
            }
            type := array;
            if (native.operator == facts.ArrayContains) {
                type = facts.BoolType;
            }
            if (native.operator == facts.ArrayText) {
                type = facts.StringType;
            }
            output.append(ScalarAt(forest, node, facts.ArrayRow, type, native.operator, 1 + length(native.arguments), ""));
            return ScalarOperands.Built(output);
    }
}
// The array that the local declaration `node` declares, as the storage of its
// elements, or storage 0 for a declaration of another type: its declared
// type's, or its value's, a literal's from its first element.
ScalarLocalArray :: (forest: snapshot.SnapshotNode[], text: string, callables: Callable[], params: Param[],
                     callable: Callable, names: Name[], types: TypeDecl[], members: TypeMember[],
                     constants: ConstDecl[], node: int) -> ValueType {
    none: ValueType = {storage: 0, container: 0, record: -1};
    declared := Field(forest, node, syntax.FieldType);
    value := Field(forest, node, syntax.FieldValue);
    if (declared >= 0) {
        // Reading a type may add an optional or pointer type; this analysis
        // keeps none of them.
        table := types;
        resolved := ReadType(forest, text, &table, names, callable.package, declared);
        if (resolved.container == ArrayContainer) {
            return resolved;
        }
        return none;
    }
    shape := ScalarArrayShape(forest, text, callables, params, names, types, members, callable.package, value);
    if (shape.storage != 0) {
        return shape;
    }
    literal := Unparenthesized(forest, value);
    first := FirstMember(forest, literal);
    if (!Is(forest, literal, syntax.ArrayExpression) || first < 0) {
        return none;
    }
    storage := ScalarOperandStorage(forest, text, callables, params, callable, names, types, members, constants, first,
                                    ConstantExpressionStorage(forest, text, first));
    return {storage: storage, container: ArrayContainer, record: -1};
}
package package_compiler

import snapshot "project:source_snapshot"
import syntax "project:syntax_diagnostics"

SequenceSliceIntrinsic: int : 51;
SequenceViewIntrinsic: int : 52;
SequenceCloneIntrinsic: int : 53;
ArrayMutateIntrinsic: int : 54;
SequenceGetIntrinsic: int : 55;
SequenceLengthIntrinsic: int : 56;
SequenceBorrowIntrinsic: int : 62;

// Ranges occur only as an index or a sequence method's argument. They never
// become runtime values. Existing slice(start, count) calls stay native calls.
SequenceOperation :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], package: int, node: int) -> int {
    if (Is(forest, node, syntax.IndexExpression) && Is(forest, Field(forest, node, syntax.FieldIndex), syntax.RangeExpression)) {
        return 0;
    }
    if (!Is(forest, node, syntax.CallExpression)) {
        return -1;
    }
    callee := Field(forest, node, syntax.FieldFunction);
    if (!Is(forest, callee, syntax.MemberExpression) ||
        QualifierOf(forest, text, names, package, Field(forest, callee, syntax.FieldObject)) >= 0) {
        return -1;
    }
    receiver := Field(forest, callee, syntax.FieldObject);
    if (Is(forest, receiver, syntax.Identifier) && Lookup(names, Text(forest, text, receiver)) < 0) {
        return -1;
    }
    member := Text(forest, text, Field(forest, callee, syntax.FieldMember));
    argument := FirstMember(forest, Field(forest, node, syntax.FieldArguments));
    if (member == "clone" && argument < 0) {
        return 2;
    }
    if (member == "length" && argument < 0) {
        return 3;
    }
    if (member == "view") {
        return 1;
    }
    if (member == "slice" && Is(forest, argument, syntax.RangeExpression)) {
        return 0;
    }
    return -1;
}

// Emits one intrinsic call with typed cells. A literal tag, when present,
// follows the evaluated arguments. No argument is copied implicitly.
SequenceCallStep :: (arguments: Value[], intrinsic: int, result: Value, tag: u64, tagged: bool,
                     popped: int, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    code: Code[] = [];
    slots: Slot[] = [];
    cells: Cell[] = [];
    roots: Root[] = [];
    index: int = 0;
    for (argument in arguments) {
        cell := MovedCell(argument);
        written := SlotStorage(argument.storage, argument.container, target);
        if (argument.place || argument.storage == ReferenceStorage) {
            cell = ReferenceCell(target);
            written = target.pointer_storage;
        }
        cells.append(cell);
        slots.append(AddressSlot(target));
        code.append(Instruction(ops.host_slot, target.pointer_storage, at.slot + index, at.cell + index, 0, 0, node));
        write := Instruction(ops.write, written, 0,
                             argument.slot, at.slot + index, 0, node);
        write.offset = target.payload_offset;
        code.append(write);
        if (!argument.place) {
            code.extend(SchemaWriteCode(argument, at.slot + index, ops, target, node));
        }
        index += 1;
    }
    if (tagged) {
        cells.append({storage: WordStorage, container: 0, record: -1, constant: tag, variant: -1, kind: ValueKind});
    }
    output := at.cell + length(cells);
    cells.append(MovedCell(result));
    hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: intrinsic, linked: -1, first: at.cell, result_first: output,
                      result_count: 1, written: false}];
    // An index outside the sequence is an argument failure, as stage zero
    // reports it.
    failure := target.data_failure;
    if (intrinsic == SequenceGetIntrinsic || intrinsic == SequenceBorrowIntrinsic) {
        failure = target.argument_failure;
    }
    code.append(Instruction(ops.host_call, 0, 0, failure, 0, at.host, node));
    slots.append(AddressSlot(target));
    address := at.slot + length(slots) - 1;
    code.append(Instruction(ops.host_slot, target.pointer_storage, address, output, 0, 0, node));
    slots.append({storage: SlotStorage(result.storage, result.container, target),
                  kind: SlotKind(result.storage, result.container)});
    result.slot = at.slot + length(slots) - 1;
    read := Instruction(ops.load, SlotStorage(result.storage, result.container, target), result.slot, address, 0, 0, node);
    read.offset = target.payload_offset;
    code.append(read);
    if (Pointer(result.storage, result.container)) {
        roots.append({slot: result.slot, storage: result.storage, container: result.container, record: result.record});
    }
    result.cell = output;
    result.owned = intrinsic == ValueCopyIntrinsic || intrinsic == SequenceSliceIntrinsic ||
                   intrinsic == SequenceCloneIntrinsic || intrinsic == SequenceViewIntrinsic;
    return CellSchemaStep(Step.Emitted(code, slots, [], cells, hosts, roots, [], [], [], popped, result, NoValue(), []),
                          output, ops, target, at, node);
}

SequenceStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, table: ^(TypeDecl[]),
                 values: Value[], top: int, item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    types := table^;
    node := forest[item.node];
    index := node.kind == syntax.IndexExpression;
    receiver := Field(forest, item.node, syntax.FieldObject);
    range := Field(forest, item.node, syntax.FieldIndex);
    operation: int = 0;
    if (!index) {
        callee := Field(forest, item.node, syntax.FieldFunction);
        receiver = Field(forest, callee, syntax.FieldObject);
        range = FirstMember(forest, Field(forest, item.node, syntax.FieldArguments));
        member := Text(forest, text, Field(forest, callee, syntax.FieldMember));
        if (member == "view") {
            operation = 1;
        } else if (member == "clone") {
            operation = 2;
        } else if (member == "length") {
            operation = 3;
        }
    }
    count: int = 1;
    ranged := operation == 0 || operation == 1;
    if (ranged) {
        count = 3;
        if (!Is(forest, range, syntax.RangeExpression) || (!index && NextMember(forest, range) >= 0)) {
            return Fail(forest, item.node, document, "sequence slice or view needs one half-open range");
        }
    }
    if (item.phase == 0) {
        next: Work[] = [Visit(receiver)];
        if (ranged) {
            next.append(Expect(Field(forest, range, syntax.FieldStart), IntStorage, 0, -1));
            next.append(Expect(Field(forest, range, syntax.FieldEnd), IntStorage, 0, -1));
        }
        next.append(Resume(item.node, 1, 0, 0));
        return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
    }
    object := values[top - count];
    element: ValueType = {storage: object.storage, container: object.container, record: object.record};
    if (operation == 1 && Single(object, PointerStorage)) {
        element = PointerElement(types, object);
        if (element.container != ArrayContainer || types[object.record].key != 0) {
            return Fail(forest, receiver, document, "mutable view needs a present pointer to an array");
        }
    } else if (operation == 1 && !Single(object, TextStorage)) {
        return Fail(forest, receiver, document, "mutable view needs a pointer to an array");
    } else if (object.container != ArrayContainer && object.container != ViewContainer && !Single(object, TextStorage)) {
        return Fail(forest, receiver, document, "slice, view and clone need a string or array");
    }
    observed: int = 0;
    if (object.container == ViewContainer) {
        observed = ReadEffect;
    }
    if (operation == 3) {
        emitted := SequenceCallStep([object], SequenceLengthIntrinsic, Typed(-1, IntStorage, 0, -1),
                                    u64(0), false, 1, ops, target, at, node);
        return EffectsStep(CleanupSequenceValues(emitted, [object], ops, target, at, node),
                           observed);
    }
    if (element.container != 0) {
        element.container = ArrayContainer;
        if (operation == 1) {
            element.container = ViewContainer;
        }
    }
    result := Typed(-1, element.storage, element.container, element.record);
    intrinsic := SequenceCloneIntrinsic;
    if (ranged) {
        if (!Single(values[top - 2], IntStorage) || !Single(values[top - 1], IntStorage)) {
            return Fail(forest, range, document, "range bounds need int values");
        }
        optional := EnsureOptional(table, element, 0);
        types = table^;
        result = Typed(-1, UnionStorage, 0, optional);
        intrinsic = SequenceSliceIntrinsic;
        if (operation == 1) {
            intrinsic = SequenceViewIntrinsic;
        }
    }
    arguments := slice(values, top - count, count);
    emitted := SequenceCallStep(arguments, intrinsic, result, OptionalTag(types, element),
                                ranged, count, ops, target, at, node);
    return EffectsStep(CleanupSequenceValues(emitted, arguments, ops, target, at, node),
                       observed);
}

ArrayMutation :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], natives: ResolvedNative[],
                  ports: ResolvedPort[], package: int, node: int) -> int {
    // A method that changes its array is a statement of its own; the call
    // step rejects one used as a value.
    if (!Is(forest, node, syntax.CallExpression) || !Is(forest, forest[node].parent, syntax.ExpressionStatement)) {
        return 0;
    }
    callee := Field(forest, node, syntax.FieldFunction);
    if (!Is(forest, callee, syntax.MemberExpression) ||
        QualifierOf(forest, text, names, package, Field(forest, callee, syntax.FieldObject)) >= 0) {
        return 0;
    }
    receiver := Field(forest, callee, syntax.FieldObject);
    if (Is(forest, receiver, syntax.Identifier) && Lookup(names, Text(forest, text, receiver)) < 0) {
        return 0;
    }
    method := Text(forest, text, Field(forest, callee, syntax.FieldMember));
    native := ArrayMethod(natives, ports, method);
    if (native < 0 || !ArrayChanger(natives, native)) {
        return 0;
    }
    changers: string[] = ["append", "add_unique", "extend", "set_array_elem", "insert", "remove_index",
                          "remove_item", "clear", "reverse", "swap", "resize"];
    operation: int = 1;
    for (changer in changers) {
        if (NameMatches(method, changer)) {
            return operation;
        }
        operation += 1;
    }
    return 0;
}

MutationStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[], members: TypeMember[],
                 natives: ResolvedNative[], ports: ResolvedPort[], names: Name[], values: Value[], top: int,
                 item: Work, operation: int, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    receiver := Field(forest, Field(forest, item.node, syntax.FieldFunction), syntax.FieldObject);
    first := FirstMember(forest, Field(forest, item.node, syntax.FieldArguments));
    if (item.phase == 0) {
        return Step.Emitted([], [], [], [], [], [], [], [],
                            [PlaceVisit(receiver), Resume(item.node, 1, 0, 0)], 0, NoValue(), NoValue(), []);
    }
    if (item.phase == 1) {
        object := values[top - 1];
        if (object.place && Single(object, PointerStorage)) {
            return PointerContinue(ReadSequencePlace(object, 1, ops, target, at, node),
                                   Resume(item.node, PlacePointerPhase, 1, 0));
        }
        if (object.container != ArrayContainer && object.container != ViewContainer) {
            return Fail(forest, receiver, document, "mutating method needs an array or view");
        }
        if (object.container == ViewContainer && operation != 4 && operation != 9 && operation != 10) {
            return Fail(forest, item.node, document, "a view has fixed length");
        }
        next: Work[] = [];
        argument := first;
        count: int = 0;
        element := SequenceElement(types, {storage: object.storage, container: object.container, record: object.record});
        if (operation == 11 && NeedsPointerValue(types, members, element.storage, element.container, element.record)) {
            return Fail(forest, item.node, document, "resize cannot create missing initialized values");
        }
        native := ArrayMethod(natives, ports, Text(forest, text, Field(forest, Field(forest, item.node, syntax.FieldFunction),
                                                                       syntax.FieldMember)));
        while (argument >= 0) {
            // A named argument binds as stage zero binds it; this step takes
            // the arguments in parameter order.
            value := argument;
            if (Is(forest, argument, syntax.NamedArgument)) {
                value = Field(forest, argument, syntax.FieldValue);
                if (value < 0) {
                    value = Field(forest, argument, syntax.FieldSource);
                }
                parameter := NativeParameter(ports, natives[native], Text(forest, text, Field(forest, argument, syntax.FieldName)),
                                             count + 2);
                if (parameter != count + 1) {
                    return Fail(forest, argument, document, "name an array update's arguments in parameter order");
                }
            }
            storage := element.storage;
            container := element.container;
            record := element.record;
            if (operation == 3) {
                storage = object.storage;
                container = ArrayContainer;
                record = object.record;
            } else if (operation == 6 || operation == 10 || operation == 11 ||
                       ((operation == 4 || operation == 5) && count == 0)) {
                storage = IntStorage;
                container = 0;
                record = -1;
            }
            next.append(Expect(value, storage, container, record));
            next.append(Resume(value, CopyValuePhase, 0, 0));
            count += 1;
            argument = NextMember(forest, argument);
        }
        expected: int = 1;
        if (operation == 4 || operation == 5 || operation == 10) {
            expected = 2;
        } else if (operation == 8 || operation == 9) {
            expected = 0;
        }
        if (count != expected) {
            return Fail(forest, item.node, document, "mutating method has the wrong number of arguments");
        }
        next.append(Resume(item.node, 2, count, 0));
        // Stage zero watches a named array, not a pointer it follows, where
        // it evaluates it, before the arguments, which can invoke another body.
        found: int = -1;
        if (Is(forest, receiver, syntax.Identifier)) {
            found = Lookup(names, Text(forest, text, receiver));
        }
        if (!ops.debug || found < 0 || (names[found].storage == PointerStorage && names[found].container == 0)) {
            return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
        }
        switch ReadSequencePlace(object, 0, ops, target, at, node) {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, scheduled, popped, value, retained,
                          marks):
                watches: Code[] = [WatchCode(ops, value.slot, value.storage, value.container, value.record, 0, true,
                                             forest[receiver], target),
                                   WatchCode(ops, value.slot, value.storage, value.container, value.record, 0, false,
                                             node, target)];
                return Step.Emitted(extend(code, watches), slots, locals, cells, hosts, roots, calls, bound, next,
                                    0, NoValue(), retained, marks);
        }
    }
    count := item.a + 1;
    arguments := slice(values, top - count, count);
    object := arguments[0];
    element := SequenceElement(types, {storage: object.storage, container: object.container, record: object.record});
    index: int = 1;
    while (index < count) {
        expected := Typed(-1, element.storage, element.container, element.record);
        if (operation == 3) {
            expected = Typed(-1, object.storage, ArrayContainer, object.record);
        } else if (operation == 6 || operation == 10 || operation == 11 ||
                   ((operation == 4 || operation == 5) && index == 1)) {
            expected = Typed(-1, IntStorage, 0, -1);
        }
        if (!Accepts(types, expected.storage, expected.container, expected.record, arguments[index])) {
            return Fail(forest, item.node, document, "argument differs from the mutating method's parameter type");
        }
        index += 1;
    }
    // Each argument is the call's next watched input, as stage zero watches it.
    watches: Code[] = [];
    index = 1;
    while (ops.debug && index < count) {
        argument := arguments[index];
        watches.append(WatchCode(ops, argument.slot, argument.storage, argument.container, argument.record, index,
                                 false, node, target));
        index += 1;
    }
    // Runtime accepts the operation as its second, int-typed argument.
    operation_slot := at.slot;
    operation_code := ConstantCode(ops, IntStorage, u64(operation), operation_slot, node);
    watches.append(operation_code);
    operation_value := Typed(operation_slot, IntStorage, 0, -1);
    // slice and extend rather than insert, which the native lane lacks.
    arguments = extend([arguments[0], operation_value], slice(arguments, 1, length(arguments) - 1));
    shifted: Bases = {pc: at.pc + length(watches), slot: at.slot + 1, local: at.local, cell: at.cell, host: at.host,
                      call: at.call};
    switch SequenceCallStep(arguments, ArrayMutatePlaceIntrinsic, Typed(-1, BoolStorage, 0, -1), u64(0), false,
                            count, ops, target, shifted, node) {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, names, next, popped, result, retained, marks):
            emitted := Step.Emitted(extend(watches, code), extend([ValueLocal(IntStorage)], slots),
                                    locals, cells, hosts, roots, calls, names, next, popped, result, retained, marks);
            return CleanupSequenceValues(emitted, Held(types, members, arguments), ops, target, at, node);
    }
}

ArrayElementAssignment :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], node: int) -> bool {
    if (!Is(forest, node, syntax.Assignment)) {
        return false;
    }
    destination := Field(forest, node, syntax.FieldTarget);
    if (Is(forest, destination, syntax.IndexExpression)) {
        return true;
    }
    if (!Is(forest, destination, syntax.MemberExpression)) {
        return false;
    }
    root := RootOf(forest, destination);
    if (Is(forest, root, syntax.Identifier)) {
        named := Lookup(names, Text(forest, text, root));
        // A name the body may not write reports as stage zero does, and
        // `e.C.f = v` on a handle writes the entity's component instead.
        return named >= 0 && names[named].writable && names[named].place != SelfPlace &&
               names[named].place != AliasPlace &&
               (names[named].storage != HandleStorage || names[named].container != 0);
    }
    return Is(forest, root, syntax.DereferenceExpression);
}

ElementAssignStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                      values: Value[], top: int, item: Work, ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    destination := Field(forest, item.node, syntax.FieldTarget);
    operator := CompoundOperator(Operator(forest, item.node));
    compound := operator != NoOperator;
    if (item.phase == 0) {
        return Step.Emitted([], [], [], [], [], [], [], [],
                            [DestinationVisit(destination), Resume(item.node, 1, 0, 0)],
                            0, NoValue(), NoValue(), []);
    }
    if (item.phase == 1) {
        place := values[top - 1];
        next: Work[] = [Expect(Field(forest, item.node, syntax.FieldValue), place.storage, place.container, place.record),
                        Resume(Field(forest, item.node, syntax.FieldValue), CopyValuePhase, 0, 0),
                        Resume(item.node, 2, 0, 0)];
        if (place.newkey && compound) {
            // An absent key reads as its value type's zero, so `counts[name] += 1`
            // counts from zero; the right side is evaluated before the store.
            if (!Numeric(place.storage) || place.container != 0) {
                return Fail(forest, destination, document, "compound assignment needs numeric operands");
            }
            zero := Typed(at.slot, place.storage, 0, -1);
            zero_code := ConstantCode(ops, place.storage, u64(0), at.slot, node);
            switch SequenceCallStep([place, zero], ReferenceReadIntrinsic,
                                    Typed(-1, place.storage, place.container, place.record), u64(0), false, 0,
                                    ops, target,
                                    {pc: at.pc + 1, slot: at.slot + 1, local: at.local, cell: at.cell, host: at.host,
                                     call: at.call}, node) {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, scheduled,
                              popped, value, retained, marks):
                    return Step.Emitted(extend([zero_code], code), extend([ValueLocal(place.storage)], slots), locals,
                                        cells, hosts, roots, calls, bound, next, 0, value, NoValue(), marks);
            }
        }
        if (place.newkey) {
            return Step.Emitted([], [], [], [], [], [], [], [], next, 0, NoValue(), NoValue(), []);
        }
        // Validate the destination before evaluating the right side. The
        // eventual write resolves the path again after any authored calls.
        switch ReadSequencePlace(place, 0, ops, target, at, node) {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, scheduled,
                          popped, value, retained, marks):
                kept := value;
                if (!compound) {
                    kept = NoValue();
                }
                return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                    0, kept, NoValue(), marks);
        }
    }
    count: int = 2;
    if (compound) {
        count = 3;
    }
    place := values[top - count];
    value := values[top - 1];
    code: Code[] = [];
    slots: Slot[] = [];
    if (place.container == 0 && MixedCompoundIntegers(operator, place.storage, value)) {
        return Fail(forest, item.node, document,
                    format_text("Mismatched integer types {} and {}; convert one operand",
                                TypeName(place.storage), TypeName(value.storage)));
    }
    // A number converts to the destination's type, as stage zero converts it.
    if (place.container == 0 && value.container == 0 && value.storage != place.storage &&
        Converts(value.storage, place.storage)) {
        slots.extend(NumberSlots(value.storage, place.storage));
        code.extend(NumberCode(ops, value.storage, place.storage, value.slot, at.slot, node));
        value = Typed(at.slot + length(slots) - 1, place.storage, 0, -1);
    }
    if (!Accepts(types, place.storage, place.container, place.record, value)) {
        return Fail(forest, destination, document, "assigned value differs from its destination");
    }
    if (compound) {
        before := values[top - 2];
        operation := BinaryOp(ops, operator);
        if (!Numeric(place.storage) || place.container != 0 || !Computes(ops, operation, place.storage)) {
            return Fail(forest, destination, document, "compound assignment needs numeric operands");
        }
        // The destination's current value is watched at it, as stage zero
        // does, except an array or view element, which it updates in place.
        if (ops.debug && (!Is(forest, destination, syntax.IndexExpression) || place.newkey)) {
            code.append(WatchCode(ops, before.slot, before.storage, before.container, before.record, 0, true,
                                  forest[destination], target));
        }
        slots.append(ValueLocal(place.storage));
        code.append(Instruction(operation, place.storage, at.slot + length(slots) - 1, before.slot, value.slot, -1,
                                node));
        value.slot = at.slot + length(slots) - 1;
    }
    shifted := SlotsPast(at, length(slots));
    emitted := PointerPrefix(code, slots, IgnoreSequenceValue(SequenceCallStep([place, value], ReferenceWriteIntrinsic,
                                                                               Typed(-1, BoolStorage, 0, -1), u64(0), false, count,
                                                                               ops, target, shifted, node)));
    return CleanupSequenceValues(emitted, [value], ops, target, at, node);
}
IgnoreSequenceValue :: (step: Step) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, value, retained, marks):
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                popped, NoValue(), retained, marks);
    }
}

ValueCopyIntrinsic: int : 57;
ValueDropIntrinsic: int : 58;
ArrayMutatePlaceIntrinsic: int : 59;
PlacePhase: int : 41;
PlaceFieldPhase: int : 42;
PlaceIndexPhase: int : 43;
PlaceIndexDonePhase: int : 44;
PlacePointerPhase: int : 45;
CopyValuePhase: int : 46;
ReferenceKeyIntrinsic: int : 35;
ReferenceUnionIntrinsic: int : 60;
PlaceComponentPhase: int : 49;

// A record, union or collection its consumer keeps: a temporary passes as it
// is, since nothing else holds it, and anything else is copied.
CopyValueStep :: (value: Value, popped: int, ops: Ops, target: Target, at: Bases,
                  node: snapshot.SnapshotNode) -> Step {
    if (value.owned || value.place || value.storage <= 0 ||
        (value.container == 0 && value.storage != StructStorage && value.storage != UnionStorage)) {
        return Step.Emitted([], [], [], [], [], [], [], [], [], popped, value, NoValue(), []);
    }
    return SequenceCallStep([value], ValueCopyIntrinsic, Typed(-1, value.storage, value.container, value.record),
                            u64(0), false, popped, ops, target, at, node);
}

PlaceVisit :: (node: int) -> Work {
    return Resume(node, PlacePhase, 0, 0);
}
// The place an assignment writes, which as an array element has no point of its own.
DestinationVisit :: (node: int) -> Work {
    return Resume(node, PlacePhase, 0, 1);
}
PlaceResult :: (step: Step, element: ValueType) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, value, retained, marks):
            result := value;
            result.storage = element.storage;
            result.container = element.container;
            result.record = element.record;
            result.place = true;
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                popped, result, retained, marks);
    }
}
ReadSequencePlace :: (place: Value, popped: int, ops: Ops, target: Target, at: Bases,
                      node: snapshot.SnapshotNode) -> Step {
    return SequenceCallStep([place], ReferenceReadIntrinsic,
                            Typed(-1, place.storage, place.container, place.record), u64(0), false,
                            popped, ops, target, at, node);
}
// A place carries only a rooted logical location. Projections preserve the
// owner and their evaluated indices; they never retain a backing data pointer.
SequencePlaceStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, types: TypeDecl[],
                      members: TypeMember[], names: Name[], values: Value[], top: int, item: Work,
                      ops: Ops, target: Target, at: Bases) -> Step {
    node := forest[item.node];
    if (item.phase == PlaceComponentPhase) {
        entity := values[top - 1];
        if (!Single(entity, HandleStorage)) {
            return Fail(forest, item.node, document, "component place requires an entity");
        }
        return SequenceComponentPlace(types, item.a, entity.slot, 1, ops, target, at, node);
    }
    if (item.phase == PlacePointerPhase) {
        pointer := values[top - 1];
        element := PointerElement(types, pointer);
        if (element.storage == 0 || (pointer.record >= 0 && types[pointer.record].key != 0)) {
            return Fail(forest, item.node, document, "place requires a present pointer");
        }
        step := PlaceResult(PointerReferenceStep(pointer, ops, target, at, node), element);
        if (item.a != 0) {
            return PointerContinue(step, Resume(item.node, item.a, 0, 0));
        }
        return step;
    }
    if (item.phase == PlaceFieldPhase) {
        base := values[top - 1];
        if (base.storage == PointerStorage && base.container == 0) {
            resumed := Resume(item.node, PlacePointerPhase, PlaceFieldPhase, 0);
            return PointerContinue(ReadSequencePlace(base, 1, ops, target, at, node), resumed);
        }
        if (!base.place || base.storage != StructStorage || base.container != 0) {
            return Fail(forest, item.node, document, "field mutation requires a writable record");
        }
        field := FindField(types, members, base.record, Text(forest, text, Field(forest, item.node, syntax.FieldMember)));
        if (field < 0) {
            return Fail(forest, item.node, document, "Unknown field");
        }
        part := members[field];
        element: ValueType = {storage: part.storage, container: part.container, record: part.record};
        offset := TypedCell(WordStorage, 0, -1);
        offset.constant = u64(part.offset);
        cells: Cell[] = [ReferenceCell(target), TypedCell(part.storage, part.container, part.record),
                         offset, TypedCell(BoolStorage, 0, -1), ReferenceCell(target)];
        code := CellWrite(target.pointer_storage, base.slot, at.cell, ops, target, at.slot, node);
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        code.extend(CellRead(target.pointer_storage, at.cell + 4, ops, target, at.slot + 1, node));
        hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: ReferenceFieldIntrinsic, linked: -1, first: at.cell,
                          result_first: at.cell + 4, result_count: 1, written: false}];
        result := Typed(at.slot + 2, part.storage, part.container, part.record);
        result.place = true;
        // A component-typed record's field reads it, as stage zero records.
        return EffectsStep(Step.Emitted(code, [AddressSlot(target), AddressSlot(target), DescriptorSlot(target)], [],
                                        cells, hosts, [], [], [], [], 1, result, NoValue(), []),
                           MemberEffects(types, base.record));
    }
    if (item.phase == PlaceIndexPhase) {
        base := values[top - 1];
        storage := IntStorage;
        if (IsMap(base)) {
            storage = types[base.record].key;
        }
        if (!base.place || (base.container != ArrayContainer && base.container != ViewContainer && !IsMap(base))) {
            return Fail(forest, item.node, document, "indexed mutation requires a writable array or map");
        }
        // A map entry an assignment writes keeps its point, as stage zero
        // marks a key it stores.
        points: Code[] = [];
        if (item.b == 1 && IsMap(base)) {
            points = [ExpressionCode(ops, node)];
        }
        return Step.Emitted(points, [], [], [], [], [], [], [],
                            [Expect(Field(forest, item.node, syntax.FieldIndex), storage, 0, -1),
                             Resume(item.node, PlaceIndexDonePhase, 0, 0)],
                            0, NoValue(), NoValue(), []);
    }
    if (item.phase == PlaceIndexDonePhase) {
        base := values[top - 2];
        index := values[top - 1];
        element := SequenceElement(types, {storage: base.storage, container: base.container, record: base.record});
        intrinsic := ReferenceFieldIntrinsic;
        if (IsMap(base)) {
            map := types[base.record];
            element = {storage: map.value_storage, container: map.value_container, record: map.value_record};
            intrinsic = ReferenceKeyIntrinsic;
        }
        cells: Cell[] = [ReferenceCell(target), TypedCell(element.storage, element.container, element.record),
                         TypedCell(index.storage, index.container, index.record)];
        if (intrinsic == ReferenceFieldIntrinsic) {
            selected := TypedCell(BoolStorage, 0, -1);
            selected.constant = 1;
            cells.append(selected);
        }
        output := at.cell + length(cells);
        cells.append(ReferenceCell(target));
        code := CellWrite(target.pointer_storage, base.slot, at.cell, ops, target, at.slot, node);
        code.extend(CellWrite(index.storage, index.slot, at.cell + 2, ops, target, at.slot + 1, node));
        code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
        code.extend(CellRead(target.pointer_storage, output, ops, target, at.slot + 2, node));
        hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: intrinsic, linked: -1, first: at.cell, result_first: output,
                          result_count: 1, written: false}];
        result := Typed(at.slot + 3, element.storage, element.container, element.record);
        result.place = true;
        result.newkey = IsMap(base);
        return Step.Emitted(code, [AddressSlot(target), AddressSlot(target), AddressSlot(target), DescriptorSlot(target)],
                            [], cells, hosts, [], [], [], [], 2, result, NoValue(), []);
    }
    if (node.kind == syntax.ParenthesizedExpression) {
        return Step.Emitted([], [], [], [], [], [], [], [],
                            [PlaceVisit(Field(forest, item.node, syntax.FieldExpression))], 0, NoValue(), NoValue(), []);
    }
    if (node.kind == syntax.DereferenceExpression) {
        operand := Unparenthesized(forest, Field(forest, item.node, syntax.FieldOperand));
        if (Is(forest, operand, syntax.Identifier)) {
            scoped := Lookup(names, Text(forest, text, operand));
            if (scoped >= 0 && names[scoped].place == ReferencePlace) {
                return Step.Emitted([], [], [], [], [], [], [], [], [PlaceVisit(operand)],
                                    0, NoValue(), NoValue(), []);
            }
        }
        // Stage zero marks a pointer it follows to reach an element or field.
        points: Code[] = [];
        if (Is(forest, node.parent, syntax.IndexExpression) || Is(forest, node.parent, syntax.MemberExpression)) {
            points = [ExpressionCode(ops, node)];
        }
        return Step.Emitted(points, [], [], [], [], [], [], [],
                            [Visit(Field(forest, item.node, syntax.FieldOperand)), Resume(item.node, PlacePointerPhase, 0, 0)],
                            0, NoValue(), NoValue(), []);
    }
    if (node.kind == syntax.MemberExpression) {
        component := SelfComponent(forest, text, types, names, item.node);
        if (component >= 0) {
            return SequenceComponentPlace(types, component, -1, 0, ops, target, at, node);
        }
        object := Field(forest, item.node, syntax.FieldObject);
        found: int = -1;
        if (Is(forest, object, syntax.Identifier)) {
            found = Lookup(names, Text(forest, text, object));
        }
        // Only a handle's member can name a component, and finding one scans
        // every type, so the handle comes first.
        if (found >= 0 && names[found].storage == HandleStorage) {
            component = Component(types, Text(forest, text, Field(forest, item.node, syntax.FieldMember)));
            if (component >= 0) {
                return Step.Emitted([], [], [], [], [], [], [], [],
                                    [Visit(object), Resume(item.node, PlaceComponentPhase, component, 0)],
                                    0, NoValue(), NoValue(), []);
            }
        }
    }
    if (node.kind == syntax.MemberExpression || node.kind == syntax.IndexExpression) {
        // As stage zero marks a place: each field and element, outermost
        // first, then the name it starts from.
        phase := PlaceFieldPhase;
        points: Code[] = [ExpressionCode(ops, node)];
        root := PlaceVisit(Field(forest, item.node, syntax.FieldObject));
        if (node.kind == syntax.IndexExpression) {
            phase = PlaceIndexPhase;
        }
        if (node.kind == syntax.IndexExpression && item.b == 1) {
            points = [];
            // Stage zero stores an element of a local array in place: it
            // marks the element, and the array's name at the statement.
            if (StoresLocalElement(forest, text, names, item.node)) {
                points = [ExpressionCode(ops, node)];
                root.b = 2;
            }
        }
        return Step.Emitted(points, [], [], [], [], [], [], [], [root, Resume(item.node, phase, 0, item.b)],
                            0, NoValue(), NoValue(), []);
    }
    found := Lookup(names, Text(forest, text, item.node));
    if (node.kind != syntax.Identifier || found < 0 || !names[found].writable) {
        return Fail(forest, item.node, document, "mutation requires a writable place");
    }
    points := NamePoints(forest, text, names, ops, item.node);
    binding := names[found];
    if (item.b == 2) {
        points = [SymbolCode(ops, binding.node, forest[forest[node.parent].parent])];
    }
    if (binding.place == NarrowedPlace) {
        // The payload's place in the optional's, which stage zero marks
        // again as the payload.
        points.append(ExpressionCode(ops, node));
        element: ValueType = {storage: binding.storage, container: binding.container, record: binding.record};
        return PointerPrefix(points, [], PayloadPlaceAfter(types, NamePlaceStep(forest, document, types, names[binding.index],
                                                                                item.node, ops, target, at),
                                                           element, ops, target, at, node));
    }
    return PointerPrefix(points, [], NamePlaceStep(forest, document, types, binding, item.node, ops, target, at));
}
// Whether the assignment target `node` is an element of a local array that
// stage zero stores in place: a plain assignment to a writable local's
// element, not a parameter's.
StoresLocalElement :: (forest: snapshot.SnapshotNode[], text: string, names: Name[], node: int) -> bool {
    object := Field(forest, node, syntax.FieldObject);
    statement := forest[node].parent;
    if (!Is(forest, object, syntax.Identifier) || !Is(forest, statement, syntax.Assignment) ||
        CompoundOperator(Operator(forest, statement)) != NoOperator) {
        return false;
    }
    found := Lookup(names, Text(forest, text, object));
    return found >= 0 && names[found].place == CellPlace && names[found].container == ArrayContainer &&
           names[found].writable && !Parameter(forest, names[found]);
}
// The place of the local `binding` that the name `name` reads.
NamePlaceStep :: (forest: snapshot.SnapshotNode[], document: int, types: TypeDecl[], binding: Name, name: int, ops: Ops,
                  target: Target, at: Bases) -> Step {
    node := forest[name];
    element: ValueType = {storage: binding.storage, container: binding.container, record: binding.record};
    if (binding.place == ManagedPlace) {
        pointer := FindPointer(types, element, false);
        code := CellRead(PointerStorage, binding.index, ops, target, at.slot, node);
        slots: Slot[] = [AddressSlot(target), {storage: PointerStorage, kind: ValueKind}];
        return PlaceResult(PointerPrefix(code, slots, PointerPopped(PointerReferenceStep(
            Typed(at.slot + 1, PointerStorage, 0, pointer), ops, target, SlotsPast(at, 2), node), 0)), element);
    }
    if (binding.place == LocalPlace && Single(Typed(-1, binding.storage, binding.container, binding.record),
                                              PointerStorage)) {
        // A pointer local writes through to its target, whose place it is;
        // stage zero marks and watches the pointer as the value it
        // dereferences.
        pointer := Typed(at.slot, PointerStorage, 0, binding.record);
        target_type := PointerElement(types, pointer);
        if (target_type.storage == 0 || types[binding.record].key != 0) {
            return Fail(forest, name, document, "place requires a present pointer");
        }
        code: Code[] = [ExpressionCode(ops, node), Instruction(ops.local, PointerStorage, at.slot, binding.index, 0, 0, node)];
        if (ops.debug) {
            code.append(WatchCode(ops, at.slot, PointerStorage, 0, binding.record, 0, true, node, target));
        }
        return PlaceResult(PointerPrefix(code, [ValueLocal(PointerStorage)],
                                         PointerPopped(PointerReferenceStep(
                                             pointer, ops, target, SlotsPast(at, 1), node), 0)), target_type);
    }
    if (binding.place != CellPlace && binding.place != BoxPlace && binding.place != ReferencePlace) {
        return Fail(forest, name, document, "mutation requires a local value");
    }
    code: Code[] = [];
    slots: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    descriptor := at.slot;
    if (binding.place == ReferencePlace) {
        slots.append(DescriptorSlot(target));
        code.append(DescriptorCode(ops, target, binding.index, descriptor, node));
    } else {
        cells = MakeValueCells(target, binding.storage, binding.container, binding.record);
        slots = MakeValueSlots(target);
        code.extend(MakeValueCode(ops, target, binding.index, at.cell, at.host, at.slot, node));
        hosts = [MakeValueHost(at.cell)];
        descriptor = at.slot + 5;
    }
    result := Typed(descriptor, binding.storage, binding.container, binding.record);
    result.place = true;
    return Step.Emitted(code, slots, [], cells, hosts, [], [], [], [], 0, result, NoValue(), []);
}

SequenceJoined :: (prefix: Step, suffix: Step) -> Step {
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, value, retained, marks):
            switch suffix {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(tail_code, tail_slots, tail_locals, tail_cells, tail_hosts, tail_roots,
                              tail_calls, tail_bound, tail_next, tail_popped, tail_value, tail_retained, tail_marks):
                    return Step.Emitted(extend(code, tail_code), extend(slots, tail_slots), extend(locals, tail_locals),
                                        extend(cells, tail_cells), extend(hosts, tail_hosts), extend(roots, tail_roots),
                                        extend(calls, tail_calls), extend(bound, tail_bound), extend(next, tail_next),
                                        popped + tail_popped, tail_value, tail_retained, extend(marks, tail_marks));
            }
    }
}
// Whether a value of record or union type `record` can hold a collection,
// which is all a drop releases. A record reaches one only through a union
// field. A type met again on the way may hold one.
HoldsCollection :: (types: TypeDecl[], members: TypeMember[], record: int, visiting: int[]) -> bool {
    if (MathKind(types, record) != 0) {
        return false;
    }
    for (seen in visiting) {
        if (seen == record) {
            return true;
        }
    }
    declared := types[record];
    within := extend(visiting, [record]);
    if (declared.kind == UnionDecl) {
        variant := declared.first;
        while (variant < declared.first + declared.count) {
            if (HoldsCollection(types, members, variant, within)) {
                return true;
            }
            variant += 1;
        }
        return false;
    }
    if (declared.kind != RecordDecl && declared.kind != VariantDecl && declared.kind != MathDecl) {
        return true;
    }
    index := declared.first;
    while (index < declared.first + declared.count) {
        field := members[index];
        if (field.container != 0 ||
            ((field.storage == StructStorage || field.storage == UnionStorage) &&
             HoldsCollection(types, members, field.record, within))) {
            return true;
        }
        index += 1;
    }
    return false;
}
// The values a drop could release anything from: collections, and records
// and unions that can hold one. Dropping any other value does nothing.
Held :: (types: TypeDecl[], members: TypeMember[], values: Value[]) -> Value[] {
    held: Value[] = [];
    for (value in values) {
        if (value.container != 0 || value.record < 0 || value.record >= length(types) ||
            (value.storage != StructStorage && value.storage != UnionStorage) ||
            HoldsCollection(types, members, value.record, [])) {
            held.append(value);
        }
    }
    return held;
}
// Release only values whose producer handed ownership to this expression.
// Plain reads and logical places never own the value they temporarily expose.
DropSequenceValues :: (values: Value[], ops: Ops, target: Target, at: Bases,
                       node: snapshot.SnapshotNode) -> Step {
    result := Step.Emitted([], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
    shifted := at;
    for (value in values) {
        if (value.owned && value.storage > 0) {
            step := IgnoreSequenceValue(SequenceCallStep([value], ValueDropIntrinsic,
                                                         Typed(-1, BoolStorage, 0, -1), u64(0), false,
                                                         0, ops, target, shifted, node));
            switch step {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(code);
                    shifted.slot += length(slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            result = SequenceJoined(result, step);
        }
    }
    return result;
}
CleanupSequenceValues :: (prefix: Step, values: Value[], ops: Ops, target: Target, at: Bases,
                          node: snapshot.SnapshotNode) -> Step {
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots),
                              local: at.local + length(locals), cell: at.cell + length(cells),
                              host: at.host + length(hosts), call: at.call + length(calls)};
            joined := SequenceJoined(prefix, DropSequenceValues(values, ops, target, shifted, node));
            switch joined {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                              all_calls, all_bound, all_next, all_popped, dropped, all_retained, all_marks):
                    return Step.Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                                        all_calls, all_bound, all_next, all_popped, produced, retained, all_marks);
            }
    }
}

DropNamesStep :: (names: Name[], first: int, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target, at: Bases,
                  node: snapshot.SnapshotNode) -> Step {
    prefix := Step.Emitted([], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
    shifted := at;
    index := first;
    while (index < length(names)) {
        binding := names[index];
        if (binding.owned && binding.place == ResultsPlace && binding.storage == ResultsStorage) {
            dropped := DropNativeResultsStep(Typed(binding.index, ResultsStorage, 0, binding.record),
                                             natives, ports, ops, target, shifted, node);
            switch dropped {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(added_code, added_slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(added_code);
                    shifted.slot += length(added_slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            prefix = SequenceJoined(prefix, dropped);
        }
        if (binding.owned && binding.place == CellPlace) {
            value := Typed(shifted.slot + 1, binding.storage, binding.container, binding.record);
            value.owned = true;
            code := CellRead(SlotStorage(binding.storage, binding.container, target), binding.index,
                             ops, target, shifted.slot, node);
            slots: Slot[] = [AddressSlot(target),
                             {storage: SlotStorage(binding.storage, binding.container, target),
                              kind: SlotKind(binding.storage, binding.container)}];
            read := Step.Emitted(code, slots, [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
            dropped := CleanupSequenceValues(read, [value], ops, target, shifted, node);
            switch dropped {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(added_code, added_slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(added_code);
                    shifted.slot += length(added_slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            prefix = SequenceJoined(prefix, dropped);
        }
        index += 1;
    }
    return prefix;
}
DropBeforeFinish :: (step: Step, names: Name[], natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target, at: Bases,
                     node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            if (length(code) == 0 || code[length(code) - 1].op != ops.finish) {
                return step;
            }
            finish := code[length(code) - 1];
            prefix := Step.Emitted(slice(code, 0, length(code) - 1), slots, locals, cells, hosts, roots,
                                   calls, bound, next, popped, produced, retained, marks);
            shifted: Bases = {pc: at.pc + length(code) - 1, slot: at.slot + length(slots),
                              local: at.local + length(locals), cell: at.cell + length(cells),
                              host: at.host + length(hosts), call: at.call + length(calls)};
            dropped := DropNamesStep(names, 0, natives, ports, ops, target, shifted, node);
            suffix := Step.Emitted([finish], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
            return SequenceJoined(SequenceJoined(prefix, dropped), suffix);
    }
}

DropNativeResultsStep :: (bundle: Value, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target,
                          at: Bases, node: snapshot.SnapshotNode) -> Step {
    prefix := Step.Emitted([], [], [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
    shifted := at;
    called := natives[bundle.record];
    index: int = 0;
    while (index < called.results) {
        port := ports[called.first + called.parameters + index];
        if (Pointer(port.storage, port.container)) {
            value := Typed(shifted.slot + 1, port.storage, port.container, port.record);
            value.owned = true;
            code := CellRead(SlotStorage(port.storage, port.container, target), bundle.slot + index,
                             ops, target, shifted.slot, node);
            slots: Slot[] = [AddressSlot(target),
                             {storage: SlotStorage(port.storage, port.container, target),
                              kind: SlotKind(port.storage, port.container)}];
            read := Step.Emitted(code, slots, [], [], [], [], [], [], [], 0, NoValue(), NoValue(), []);
            dropped := CleanupSequenceValues(read, [value], ops, target, shifted, node);
            switch dropped {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(added_code, added_slots, locals, cells, hosts, roots, calls, bound, next,
                              popped, produced, retained, marks):
                    shifted.pc += length(added_code);
                    shifted.slot += length(added_slots);
                    shifted.local += length(locals);
                    shifted.cell += length(cells);
                    shifted.host += length(hosts);
                    shifted.call += length(calls);
            }
            prefix = SequenceJoined(prefix, dropped);
        }
        index += 1;
    }
    return prefix;
}

SequenceComponentPlace :: (types: TypeDecl[], component: int, entity: int, popped: int, ops: Ops,
                           target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    code := OwnerCode(ops, target, at.cell, entity, at.slot, node);
    code.append(Instruction(ops.host_call, 0, 0, target.data_failure, 0, at.host, node));
    code.extend(CellRead(target.pointer_storage, at.cell + 9, ops, target, at.slot + 4, node));
    slots := extend(OwnerSlots(target), [AddressSlot(target), DescriptorSlot(target)]);
    cells := MakeCells(target, component, ComponentFacts(types[component]));
    hosts: Host[] = [{owned_arguments: false, command: 0, syntax_node: 0, intrinsic: ReferenceMakeIntrinsic, linked: -1, first: at.cell,
                      result_first: at.cell + 9, result_count: 1, written: true}];
    result := Typed(at.slot + 5, StructStorage, 0, component);
    result.place = true;
    return Step.Emitted(code, slots, [], cells, hosts, [], [], [], [], popped, result, NoValue(), []);
}

SequenceKept :: (prefix: Step, suffix: Step) -> Step {
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            joined := SequenceJoined(prefix, suffix);
            switch joined {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                              all_calls, all_bound, all_next, all_popped, dropped, all_retained, all_marks):
                    return Step.Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                                        all_calls, all_bound, all_next, all_popped, produced, retained, all_marks);
            }
    }
}
// A projection from a temporary must keep its selected value before the
// temporary's owner is released. Projections from named values stay borrowed.
CleanupProjectionStep :: (prefix: Step, owner: Value, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops,
                          target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    if (!owner.owned) {
        return prefix;
    }
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots),
                              local: at.local + length(locals), cell: at.cell + length(cells),
                              host: at.host + length(hosts), call: at.call + length(calls)};
            copied := SequenceJoined(prefix, CopyValueStep(produced, 0, ops, target, shifted, node));
            if (owner.storage != ResultsStorage) {
                return CleanupSequenceValues(copied, [owner], ops, target, at, node);
            }
            switch copied {
                case .Failed(diagnostic):
                    return Step.Failed(diagnostic);
                case .Emitted(all_code, all_slots, all_locals, all_cells, all_hosts, all_roots,
                              all_calls, all_bound, all_next, all_popped, value, held, all_marks):
                    cleanup_at: Bases = {pc: at.pc + length(all_code), slot: at.slot + length(all_slots),
                                         local: at.local + length(all_locals), cell: at.cell + length(all_cells),
                                         host: at.host + length(all_hosts), call: at.call + length(all_calls)};
                    return SequenceKept(copied, DropNativeResultsStep(owner, natives, ports, ops, target, cleanup_at, node));
            }
    }
}

CopyResultCellsStep :: (bundle: Value, result_types: Value[], ops: Ops, target: Target,
                        at: Bases, node: snapshot.SnapshotNode) -> Step {
    output_cells: Cell[] = [];
    index: int = 0;
    while (index < length(result_types)) {
        port := result_types[index];
        output_cells.append(TypedCell(port.storage, port.container, port.record));
        index += 1;
    }
    prefix := Step.Emitted([], [], [], output_cells, [], [], [], [], [], 0, NoValue(), NoValue(), []);
    index = 0;
    while (index < length(result_types)) {
        port := result_types[index];
        switch prefix {
            case .Failed(diagnostic):
                return Step.Failed(diagnostic);
            case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                          popped, produced, retained, marks):
                shifted: Bases = {pc: at.pc + length(code), slot: at.slot + length(slots),
                                  local: at.local + length(locals), cell: at.cell + length(cells),
                                  host: at.host + length(hosts), call: at.call + length(calls)};
                value := Typed(shifted.slot + 1, port.storage, port.container, port.record);
                read_code := CellRead(SlotStorage(port.storage, port.container, target), bundle.slot + index,
                                      ops, target, shifted.slot, node);
                read_slots: Slot[] = [AddressSlot(target),
                                      {storage: SlotStorage(port.storage, port.container, target),
                                       kind: SlotKind(port.storage, port.container)}];
                read := Step.Emitted(read_code, read_slots, [], [], [], [], [], [], [], 0, value, NoValue(), []);
                copy_at := SlotsPast(shifted, 2);
                copied := SequenceJoined(read, CopyValueStep(value, 0, ops, target, copy_at, node));
                switch copied {
                    case .Failed(diagnostic):
                        return Step.Failed(diagnostic);
                    case .Emitted(copy_code, copy_slots, copy_locals, copy_cells, copy_hosts, copy_roots,
                                  copy_calls, copy_bound, copy_next, copy_popped, result, copy_retained, copy_marks):
                        store_code := CellWrite(SlotStorage(port.storage, port.container, target), result.slot,
                                                at.cell + index, ops, target, shifted.slot + length(copy_slots), node);
                        store := Step.Emitted(store_code, [AddressSlot(target)], [], [], [], [], [], [], [],
                                              0, NoValue(), NoValue(), []);
                        prefix = SequenceJoined(prefix, SequenceJoined(copied, store));
                }
        }
        index += 1;
    }
    result := Typed(at.cell, bundle.storage, 0, bundle.record);
    result.cell = at.cell;
    result.owned = true;
    switch prefix {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                      popped, produced, retained, marks):
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                1, result, NoValue(), marks);
    }
}

CopyNativeResultsStep :: (bundle: Value, natives: ResolvedNative[], ports: ResolvedPort[], ops: Ops, target: Target,
                          at: Bases, node: snapshot.SnapshotNode) -> Step {
    called := natives[bundle.record];
    result_types: Value[] = [];
    index: int = 0;
    while (index < called.results) {
        port := ports[called.first + called.parameters + index];
        result_types.append(Typed(-1, port.storage, port.container, port.record));
        index += 1;
    }
    return CopyResultCellsStep(bundle, result_types, ops, target, at, node);
}
CopyFunctionResultsStep :: (bundle: Value, callables: Callable[], params: Param[], ops: Ops, target: Target,
                            at: Bases, node: snapshot.SnapshotNode) -> Step {
    called := callables[bundle.record];
    result_types: Value[] = [];
    index: int = 0;
    while (index < called.results) {
        param := params[called.first + called.count + index];
        result_types.append(Typed(-1, param.storage, param.container, param.record));
        index += 1;
    }
    return CopyResultCellsStep(bundle, result_types, ops, target, at, node);
}
package package_compiler

import snapshot "project:source_snapshot"
import syntax "project:syntax_diagnostics"
import json "project:json_string"
import parser "project:source_parser"
import strings "core:strings"
import tk "project:source_tokenizer"

// The steps EmitBody takes for nodes other than control flow. Each reads the
// body's tables, which calls share rather than copy, and returns only what it
// adds, numbered from the sizes in `at`.

// Whether an array of this element type may hold its elements inline, with a
// nonzero stride, as the runtime decides: scalars and records of those may,
// while strings, unions and records with a string, union or array field,
// however deeply nested, are always boxed.
Packable :: (storage: int, record: int, types: TypeDecl[], members: TypeMember[]) -> bool {
    if (storage == TextStorage || storage == UnionStorage) {
        return false;
    }
    if (storage != StructStorage) {
        return true;
    }
    at := types[record].first;
    while (at < types[record].first + types[record].count) {
        if (members[at].container != 0 || members[at].storage == TextStorage || members[at].storage == UnionStorage ||
            (members[at].storage == StructStorage && !Packable(StructStorage, members[at].record, types, members))) {
            return false;
        }
        at += 1;
    }
    return true;
}
// The slots ElementRead numbers from its `first`: zero, the lower check, the
// count and the upper check, then the slots of ElementLoad.
ElementSlots :: (storage: int, packable: bool, target: Target) -> Slot[] {
    number: Slot = {storage: IntStorage, kind: ValueKind};
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    checks: Slot[] = [number, flag, number, flag];
    return extend(checks, LoadSlots(storage, packable, target));
}
// Reads the element of the array in slot `array` at the index in slot
// `position` into the last of ElementSlots, after checking 0 <= index < count
// as stage zero does. `pc` is where its code starts; a packable record element
// needs the local `local`.
ElementRead :: (array: int, position: int, storage: int, packable: bool, first: int, pc: int, local: int,
                ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    constant := Instruction(ops.constant, IntStorage, first, 0, 0, 0, node);
    constant.value_storage = IntStorage;
    code.append(constant);
    code.append(Instruction(ops.ge, IntStorage, first + 1, position, first, -1, node));
    code.append(Instruction(ops.guard, 0, 0, first + 1, 0, target.argument_failure, node));
    code.append(Instruction(ops.guard, 0, 0, array, 0, target.argument_failure, node));
    count := Instruction(ops.load, IntStorage, first + 2, array, 0, 0, node);
    count.offset = target.count_offset;
    code.append(count);
    code.append(Instruction(ops.lt, IntStorage, first + 3, position, first + 2, -1, node));
    code.append(Instruction(ops.guard, 0, 0, first + 3, 0, target.argument_failure, node));
    return extend(code, ElementLoad(array, position, storage, packable, first + 4, pc + length(code), local, ops,
                                    target, node));
}
// The slots ElementLoad numbers from its `first`. For an element type that is
// never packed: the array's items, the item and the element. Otherwise: the
// array's items, data and stride, a zero word, whether the array is packed,
// the boxed and the actual element width, the index as a word, its byte
// offset, the base, the item, then for a record its boxed pointer and the
// element, and for any other element the payload offset, the offset to use,
// its address and the element.
LoadSlots :: (storage: int, packable: bool, target: Target) -> Slot[] {
    flag: Slot = {storage: BoolStorage, kind: ValueKind};
    address: Slot = {storage: target.pointer_storage, kind: AddressKind};
    word: Slot = {storage: target.pointer_storage, kind: ValueKind};
    element: Slot = {storage: SlotStorage(storage, 0, target), kind: SlotKind(storage, 0)};
    if (!packable) {
        return [address, address, element];
    }
    slots: Slot[] = [address, address, word, word, flag, word, word, word, word, address, address];
    if (storage == StructStorage) {
        return extend(slots, [address, element]);
    }
    return extend(slots, [word, word, address, element]);
}
// Loads the element at the index in slot `position`, already checked, into
// the last of LoadSlots, as stage zero does: a packed array (nonzero stride)
// holds elements inline in `data`, and any other holds value headers in
// `items`. An element type that is never packed reads `items` alone. A packed
// record is the element itself, so the boxed pointer is loaded only past a
// branch, through local `local`; `pc` is where the code starts.
ElementLoad :: (array: int, position: int, storage: int, packable: bool, first: int, pc: int, local: int,
                ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    code: Code[] = [];
    items := Instruction(ops.load, target.pointer_storage, first, array, 0, 0, node);
    items.offset = target.items_offset;
    code.append(items);
    if (!packable) {
        // The header's payload is the value, or a record's pointer.
        item := Instruction(ops.index, target.pointer_storage, first + 1, first, position, 0, node);
        item.offset = target.value_size;
        code.append(item);
        element := Instruction(ops.load, SlotStorage(storage, 0, target), first + 2, first + 1, 0, 0, node);
        element.offset = target.payload_offset;
        return append(code, element);
    }
    data := Instruction(ops.load, target.pointer_storage, first + 1, array, 0, 0, node);
    data.offset = target.data_offset;
    code.append(data);
    stride := Instruction(ops.load, target.pointer_storage, first + 2, array, 0, 0, node);
    stride.offset = target.stride_offset;
    code.append(stride);
    code.append(ConstantCode(ops, target.pointer_storage, 0, first + 3, node));
    code.append(Instruction(ops.ne, target.pointer_storage, first + 4, first + 2, first + 3, -1, node));
    code.append(ConstantCode(ops, target.pointer_storage, u64(target.value_size), first + 5, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 6, first + 4, first + 2, first + 5, node));
    code.append(CastCode(ops, target.pointer_storage, first + 7, position, 0, node));
    code.append(Instruction(ops.mul, target.pointer_storage, first + 8, first + 7, first + 6, -1, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 9, first + 4, first + 1, first, node));
    code.append(Instruction(ops.add, target.pointer_storage, first + 10, first + 9, first + 8, -1, node));
    if (storage == StructStorage) {
        code.append(Instruction(ops.save, target.pointer_storage, 0, first + 10, 0, local, node));
        code.append(Instruction(ops.branch_if, 0, 0, first + 4, 0, pc + length(code) + 3, node));
        pointer := Instruction(ops.load, target.pointer_storage, first + 11, first + 10, 0, 0, node);
        pointer.offset = target.payload_offset;
        code.append(pointer);
        code.append(Instruction(ops.save, target.pointer_storage, 0, first + 11, 0, local, node));
        return append(code, Instruction(ops.local, target.pointer_storage, first + 12, local, 0, 0, node));
    }
    code.append(ConstantCode(ops, target.pointer_storage, u64(target.payload_offset), first + 11, node));
    code.append(Instruction(ops.select, target.pointer_storage, first + 12, first + 4, first + 3, first + 11, node));
    code.append(Instruction(ops.add, target.pointer_storage, first + 13, first + 10, first + 12, -1, node));
    return append(code, Instruction(ops.load, SlotStorage(storage, 0, target), first + 14, first + 13, 0, 0, node));
}
// The locals ElementRead and ElementLoad need: one for a packable record
// element.
ElementLocals :: (storage: int, packable: bool, target: Target) -> Slot[] {
    if (storage == StructStorage && packable) {
        return [{storage: target.pointer_storage, kind: AddressKind}];
    }
    return [];
}

// An ownership boundary makes an independent value. Runtime copies retain
// immutable storage and pointer identity, and share mutable backing with CoW.
RetainStep :: (kept: Value, ops: Ops, target: Target, at: Bases, item: snapshot.SnapshotNode) -> Step {
    return CopyValueStep(kept, 0, ops, target, at, item);
}

// The cell a fresh value moves into instead of a copy, and the code that
// gives the cell's header its payload as it stands.
MovedCell :: (value: Value) -> Cell {
    return {storage: value.storage, container: value.container, record: value.record, constant: 0, variant: -1,
            kind: ValueKind};
}
AddressSlot :: (target: Target) -> Slot {
    return {storage: target.pointer_storage, kind: AddressKind};
}
MoveCode :: (value: Value, ops: Ops, target: Target, slot: int, cell: int, item: snapshot.SnapshotNode) -> Code[] {
    write := Instruction(ops.write, target.pointer_storage, 0, value.slot, slot, 0, item);
    write.offset = target.payload_offset;
    code: Code[] = [Instruction(ops.host_slot, target.pointer_storage, slot, cell, 0, 0, item), write];
    return extend(code, SchemaWriteCode(value, slot, ops, target, item));
}

// A runtime native record schema travels beside its payload pointer. These
// helpers add no cells or locals, and keep the original step's numbering.
SchemaWriteCode :: (value: Value, address: int, ops: Ops, target: Target, node: snapshot.SnapshotNode) -> Code[] {
    if (value.storage != StructStorage || value.container != 0 || value.schema < 0) {
        return [];
    }
    write := Instruction(ops.write, target.pointer_storage, 0, value.schema, address, 0, node);
    write.offset = target.schema_offset;
    return [write];
}
ValueWriteCode :: (value: Value, cell: int, ops: Ops, target: Target, slot: int,
                   node: snapshot.SnapshotNode) -> Code[] {
    code := CellWrite(SlotStorage(value.storage, value.container, target), value.slot, cell, ops, target, slot, node);
    return extend(code, SchemaWriteCode(value, slot, ops, target, node));
}
CellSchemaStep :: (step: Step, cell: int, ops: Ops, target: Target, at: Bases, node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, retained, marks):
            body_code := code;
            body_slots := slots;
            value := produced;
            if (value.storage == StructStorage && value.container == 0) {
                first := at.slot + length(body_slots);
                body_code.append(Instruction(ops.host_slot, target.pointer_storage, first, cell, 0, 0, node));
                load := Instruction(ops.load, target.pointer_storage, first + 1, first, 0, 0, node);
                load.offset = target.schema_offset;
                body_code.append(load);
                body_slots.extend([AddressSlot(target), AddressSlot(target)]);
                value.schema = first + 1;
            }
            return Step.Emitted(body_code, body_slots, locals, cells, hosts, roots, calls, bound, next, popped, value, retained, marks);
    }
}
ArgumentSchemaStep :: (step: Step, argument: int, ops: Ops, target: Target, at: Bases,
                       node: snapshot.SnapshotNode) -> Step {
    switch step {
        case .Failed(diagnostic):
            return Step.Failed(diagnostic);
        case .Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, popped, produced, retained, marks):
            body_code := code;
            body_slots := slots;
            value := produced;
            if (value.storage == StructStorage && value.container == 0) {
                first := at.slot + length(body_slots);
                bank := Instruction(ops.context, target.pointer_storage, first, 0, 0, 0, node);
                bank.offset = target.arguments_offset;
                body_code.append(bank);
                body_code.append(ConstantCode(ops, IntStorage, u64(argument), first + 1, node));
                header := Instruction(ops.index, target.pointer_storage, first + 2, first, first + 1, 0, node);
                header.offset = target.value_size;
                body_code.append(header);
                load := Instruction(ops.load, target.pointer_storage, first + 3, first + 2, 0, 0, node);
                load.offset = target.schema_offset;
                body_code.append(load);
                body_slots.extend([AddressSlot(target), ValueLocal(IntStorage), AddressSlot(target), AddressSlot(target)]);
                value.schema = first + 3;
            }
            return Step.Emitted(body_code, body_slots, locals, cells, hosts, roots, calls, bound, next, popped, value, retained, marks);
    }
}

// A literal without context takes its storage from its spelling, as stage zero
// does. Other expressions supply their own type. Hexadecimal e is a digit;
// only decimal spellings have an exponent.
InferredNumberStorage :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    literal := Unparenthesized(forest, node);
    digits := literal;
    if (Is(forest, digits, syntax.UnaryExpression)) {
        digits = Field(forest, digits, syntax.FieldOperand);
        operator := Operator(forest, literal);
        if (operator != tk.Sub && operator != tk.Add) {
            return 0;
        }
        if (operator == tk.Add) {
            literal = digits;
        }
    }
    if (!Is(forest, digits, syntax.Number)) {
        return 0;
    }
    spelling := Text(forest, text, digits);
    size := strings.ByteLength(spelling);
    hexadecimal := size > 2 && strings.ByteAt(spelling, 0) == 48 &&
                   (strings.ByteAt(spelling, 1) == 120 || strings.ByteAt(spelling, 1) == 88);
    if (!hexadecimal) {
        index: int = 0;
        while (index < size) {
            character := strings.ByteAt(spelling, index);
            if (character == 46 || character == 101 || character == 69) {
                return FloatStorage;
            }
            index += 1;
        }
    }
    switch ParseNumber(forest, text, literal) {
        case .Number(negative, magnitude):
            if (Fits(negative, magnitude, IntStorage)) {
                return IntStorage;
            }
            if (Fits(negative, magnitude, Int64Storage)) {
                return Int64Storage;
            }
        case .Invalid:
            return WordStorage;
    }
    // The constant emitter diagnoses a value beyond uint64's range.
    return WordStorage;
}

// A local initializer built only from literals and arithmetic takes the
// storage its literals spell, as a lone literal does: `1 + 2` is int, `1 + 2.5`
// is number, and a literal beyond int widens the result. A shift keeps its left
// operand's storage. Anything else is 0.
ConstantExpressionStorage :: (forest: snapshot.SnapshotNode[], text: string, node: int) -> int {
    expression := Unparenthesized(forest, node);
    spelled := InferredNumberStorage(forest, text, expression);
    if (spelled != 0) {
        return spelled;
    }
    if (Is(forest, expression, syntax.UnaryExpression)) {
        sign := Operator(forest, expression);
        if (sign == tk.Sub || sign == tk.Add || sign == tk.Complement) {
            return ConstantExpressionStorage(forest, text, Field(forest, expression, syntax.FieldOperand));
        }
        return 0;
    }
    if (!Is(forest, expression, syntax.BinaryExpression)) {
        return 0;
    }
    operator := Operator(forest, expression);
    shifts := operator == tk.Shl || operator == tk.Shr;
    if (!shifts && operator != tk.Add && operator != tk.Sub && operator != tk.Mul && operator != tk.Quo && operator != tk.Mod &&
        operator != tk.And && operator != tk.Or && operator != tk.Xor) {
        return 0;
    }
    left := ConstantExpressionStorage(forest, text, Field(forest, expression, syntax.FieldLeft));
    right := ConstantExpressionStorage(forest, text, Field(forest, expression, syntax.FieldRight));
    if (left == 0 || right == 0) {
        return 0;
    }
    if (shifts) {
        return left;
    }
    if (left == FloatStorage || right == FloatStorage) {
        return FloatStorage;
    }
    if (left > right) {
        return left;
    }
    return right;
}

// Statements: local declarations, assignments, expression statements and
// returns, from scheduling to the value's store.
// A function's named results are locals from `named` on.
StatementStep :: (forest: snapshot.SnapshotNode[], text: string, document: int, callables: Callable[],
                  params: Param[], table: ^(TypeDecl[]), members: TypeMember[], natives: ResolvedNative[], ports: ResolvedPort[],
                  identities: u64[], names: Name[], scope: int, package: int, values: Value[], top: int,
                  function: int, named: int, referenced: string[], mutated: string[], built: int[], addressed: string[],
                  generic_updates: int[], item: Work,
                  ops: Ops, target: Target, at: Bases) -> Step {
    types := table^;
    callable := callables[function];
    node := forest[item.node];
    kind := node.kind;
    code: Code[] = [];
    slots: Slot[] = [];
    locals: Slot[] = [];
    cells: Cell[] = [];
    hosts: Host[] = [];
    roots: Root[] = [];
    calls: Invocation[] = [];
    bound: Name[] = [];
    next: Work[] = [];
    marks: int[] = [];
    popped: int = 0;
    produced := NoValue();
    retained := NoValue();
    // Mutating methods are calls on the shared root, with no assignment to
    // their receiver; `xs.append(x)` and `xs.extend(ys)` on a local array
    // push in place as `xs = append(xs, x)` does. A debug build keeps the
    // method call's own points.
    changing := item.phase == 0 && !ops.debug && kind == syntax.ExpressionStatement &&
                LocalPush(forest, text, callables, natives, ports, identities, names, package, generic_updates,
                          item.node);
    if (item.phase == 0) {
        code.append(Instruction(ops.check, 0, 0, 0, 0, 0, node));
        value := Field(forest, item.node, syntax.FieldValue);
        if (kind == syntax.ExpressionStatement) {
            value = FirstMember(forest, item.node);
        }
        if (kind == syntax.DeleteStatement ||
            (kind == syntax.ExpressionStatement && MapMethod(forest, text, names, value, "delete"))) {
            return MapDeleteStep(forest, text, document, types, names, item, ops, node);
        }
        if (kind == syntax.Assignment && PointerDestination(forest, text, types, members, names,
                                                       StatementTarget(forest, item.node))) {
            return PointerAssignmentStart(forest, text, document, types, members, names, item, ops, target, at);
        }
        expected := Visit(value);
        if (kind == syntax.LocalDeclaration) {
            declared := Field(forest, item.node, syntax.FieldType);
            if (declared >= 0) {
                hidden := PrivateType(forest, text, types, names, package, declared);
                if (hidden >= 0) {
                    return Fail(forest, hidden, document, PrivateMessage(Text(forest, text, hidden)));
                }
                resolved := ReadType(forest, text, table, names, package, declared);
                types = table^;
                if (resolved.storage == 0) {
                    return Fail(forest, declared, document, "local type is not supported yet");
                }
                if (value < 0) {
                    if (resolved.container == ViewContainer) {
                        return Fail(forest, item.node, document, "view local requires an initial value");
                    }
                    if (OptionalElement(types, Typed(-1, resolved.storage, resolved.container, resolved.record)).storage != 0) {
                        name_node := Field(forest, item.node, syntax.FieldName);
                        name := Text(forest, text, name_node);
                        if (Declared(names, scope, name)) {
                            return Fail(forest, name_node, document, format_text("Duplicate declaration '{}'", name));
                        }
                        cells.append(TypedCell(UnionStorage, 0, resolved.record));
                        code.append(SymbolCode(ops, name_node, node));
                        bound.append({owned: true, name: name, place: CellPlace, index: at.cell, storage: UnionStorage,
                                      container: 0, record: resolved.record, writable: true, node: name_node});
                        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next,
                                            0, NoValue(), NoValue(), marks);
                    }
                    if (resolved.storage != PointerStorage || resolved.container != 0 || resolved.record < 0 ||
                        types[resolved.record].key == 0) {
                        return Fail(forest, item.node, document, "non-null pointer local requires an initial value");
                    }
                    name_node := Field(forest, item.node, syntax.FieldName);
                    name := Text(forest, text, name_node);
                    if (Declared(names, scope, name)) {
                        return Fail(forest, name_node, document, format_text("Duplicate declaration '{}'", name));
                    }
                    constant := ConstantCode(ops, PointerStorage, 0, at.slot, node);
                    constant.value_record = resolved.record;
                    if (Holds(addressed, name)) {
                        EnsurePointer(table, {storage: PointerStorage, container: 0, record: resolved.record}, false, 0);
                        return PointerPrefix([constant], [{storage: PointerStorage, kind: ValueKind}],
                                             ManagedBoxStep(table^, members, Typed(at.slot, PointerStorage, 0, resolved.record),
                                                            name, name_node, 0, ops, target, SlotsPast(at, 1), node));
                    }
                    code.extend([constant, Instruction(ops.save, PointerStorage, 0, at.slot, 0, at.local, node),
                                 SymbolCode(ops, name_node, node)]);
                    binding: Name = {owned: false, name: name, place: LocalPlace, index: at.local, storage: PointerStorage,
                                     container: 0, record: resolved.record, writable: true, node: name_node};
                    return Step.Emitted(code, [{storage: PointerStorage, kind: ValueKind}],
                                        [ValueLocal(PointerStorage)], [], [], [], [], [binding], [], 0,
                                        NoValue(), NoValue(), []);
                }
                expected = Expect(value, resolved.storage, resolved.container, resolved.record);
            } else {
                inferred := ConstantExpressionStorage(forest, text, value);
                if (inferred > 0) {
                    expected = Expect(value, inferred, 0, -1);
                }
            }
        } else if (kind == syntax.ReturnStatement) {
            expected = Expect(value, callable.result, callable.result_container, callable.result_record);
        } else if (kind == syntax.Assignment || changing) {
            destination := StatementTarget(forest, item.node);
            operator := CompoundOperator(Operator(forest, item.node));
            whole := SelfComponent(forest, text, types, names, destination);
            owned: int = -1;
            if (Is(forest, destination, syntax.MemberExpression)) {
                owned = SelfComponent(forest, text, types, names, Field(forest, destination, syntax.FieldObject));
            }
            other := EntityComponent(forest, text, types, members, names, destination);
            other_owned: int = -1;
            if (Is(forest, destination, syntax.MemberExpression)) {
                other_owned = EntityComponent(forest, text, types, members, names,
                                              Field(forest, destination, syntax.FieldObject));
            }
            if (Is(forest, destination, syntax.Identifier)) {
                found := Lookup(names, Text(forest, text, destination));
                if (found >= 0) {
                    binding := names[found];
                    expected = Expect(value, binding.storage, binding.container, binding.record);
                    // A compound write reads a managed target, with its points,
                    // before its value, as stage zero caches the target.
                    if (binding.place == ManagedPlace && operator != NoOperator) {
                        code.extend(NamePoints(forest, text, names, ops, destination));
                        read := PointerContinue(ManagedReadStep(types, binding, ops, target, at, node), expected);
                        return PointerPrefix(code, [], PointerContinue(read, Resume(item.node, PointerCompoundPhase,
                                                                                    found, 0)));
                    }
                    // `xs = append(xs, x)` and `xs = extend(xs, ys)` on a
                    // local array update it in place.
                    update: int = -1;
                    array: int = -1;
                    argument: int = -1;
                    // A method call updates in place only as its own statement;
                    // `xs = xs.append(x)` is an error CallStep reports.
                    if (operator == NoOperator &&
                        (changing || !Is(forest, Field(forest, value, syntax.FieldFunction), syntax.MemberExpression))) {
                        switch InPlaceUpdate(forest, text, callables, natives, ports, identities, names, package,
                                             found, destination, value) {
                            case .NotApplicable:
                                update = -1;
                            case .InPlace(mode, receiver, supplied, native):
                                // Preparation keeps contextual element typing, but no
                                // body is published before its WRITE proof closes.
                                next.append(RecordSemantic(item.node, UpdateFact, supplied));
                                next.append(RecordSemantic(value, NativeFact, native));
                                if (!generic_updates.contains(item.node)) {
                                    update = mode;
                                    array = receiver;
                                    argument = supplied;
                                }
                        }
                    }
                    if (update >= 0) {
                        // Stage zero evaluates the target, the call and the
                        // array it updates, as their points show; it writes a
                        // parameter through the reference the target reads.
                        if (Parameter(forest, binding)) {
                            code.extend(NamePoints(forest, text, names, ops, destination));
                        } else {
                            code.append(ExpressionCode(ops, forest[destination]));
                        }
                        code.append(ExpressionCode(ops, forest[value]));
                        code.extend(NamePoints(forest, text, names, ops, array));
                        address := AddressSlot(target);
                        slots.extend([address, address]);
                        code.extend(CellRead(target.pointer_storage, binding.index, ops, target, at.slot,
                                             forest[array]));
                        receiver: Root = {slot: at.slot + 1, storage: binding.storage, container: ArrayContainer,
                                          record: binding.record};
                        roots.append(receiver);
                        if (ops.debug) {
                            code.append(WatchCode(ops, at.slot + 1, binding.storage, ArrayContainer, binding.record,
                                                  0, true, forest[array], target));
                            code.append(WatchCode(ops, at.slot + 1, binding.storage, ArrayContainer, binding.record,
                                                  0, false, forest[value], target));
                        }
                        container: int = 0;
                        if (update == 1) {
                            container = ArrayContainer;
                        }
                        next.append(Expect(argument, binding.storage, container, binding.record));
                        finish := Resume(item.node, PushPhase, found, update);
                        finish.c = array;
                        next.append(finish);
                        return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0,
                                            NoValue(), retained, marks);
                    }
                    if (operator != NoOperator || Parameter(forest, binding) || binding.place == ManagedPlace) {
                        code.extend(NamePoints(forest, text, names, ops, destination));
                    }
                }
            } else if (whole >= 0) {
                code.extend(TargetPoints(forest, text, names, ops, destination));
                // The target's owner is watched as `self`, in a slot before
                // the component step's.
                code.extend(OwnerWatch(ops, at.slot, forest[TargetRoot(forest, destination)]));
                shifted := SlotsPast(at, 1);
                // `self.C op= v` combines the owner's component with the value
                // and writes the result through the reference it read.
                write := Resume(item.node, ComponentAssignPhase, shifted.slot + ComponentReferenceSlot, whole);
                if (operator == NoOperator) {
                    return PrefixSlots([ValueLocal(HandleStorage)],
                                       ComponentMakeStep(code, types, whole, -1, [Visit(value), write], ops, target,
                                                         shifted, node));
                }
                combine := Resume(item.node, CombinePhase, 0, 0);
                return PrefixSlots([ValueLocal(HandleStorage)],
                                   ComponentReadStep(code, types, whole, true, -1, [Visit(value), combine, write], ops,
                                                     target, shifted, node));
            } else if (owned >= 0) {
                // `self.C.f = v` on a component of the owner.
                code.extend(TargetPoints(forest, text, names, ops, destination));
                member := Text(forest, text, Field(forest, destination, syntax.FieldMember));
                field := FindField(types, members, owned, member);
                if (field < 0) {
                    return Fail(forest, destination, document, format_text("Unknown field '{}'", member));
                }
                if (members[field].c_string) {
                    message := CStringMessage(forest, text, value, members[field].name);
                    if (message != "") {
                        return Fail(forest, value, document, message);
                    }
                }
                if (!members[field].writable) {
                    return Fail(forest, destination, document, "Assignment requires a writable value");
                }
                code.extend(OwnerWatch(ops, at.slot, forest[TargetRoot(forest, destination)]));
                return PrefixSlots([ValueLocal(HandleStorage)],
                                   ComponentReferenceStep(code, types, members, owned, field, -1, value,
                                                          operator != NoOperator, item, ops, target, SlotsPast(at, 1), node));
            } else if (other >= 0 || other_owned >= 0) {
                // `e.C = v` and `e.C.f = v` on a component of another entity:
                // the entity, then the reference to its component.
                component := other;
                field: int = -1;
                entity := Field(forest, destination, syntax.FieldObject);
                if (other_owned >= 0) {
                    component = other_owned;
                    entity = Field(forest, entity, syntax.FieldObject);
                    member := Text(forest, text, Field(forest, destination, syntax.FieldMember));
                    field = FindField(types, members, component, member);
                    if (field < 0) {
                        return Fail(forest, destination, document, format_text("Unknown field '{}'", member));
                    }
                    if (members[field].c_string) {
                        message := CStringMessage(forest, text, value, members[field].name);
                        if (message != "") {
                            return Fail(forest, value, document, message);
                        }
                    }
                    if (!members[field].writable) {
                        return Fail(forest, destination, document, "Assignment requires a writable value");
                    }
                }
                // The members above the entity have points; the entity has
                // its own as it is evaluated.
                at_member := destination;
                while (at_member != entity) {
                    code.append(ExpressionCode(ops, forest[at_member]));
                    at_member = Field(forest, at_member, syntax.FieldObject);
                }
                write := Resume(item.node, EntityComponentPhase, component, field);
