                    return Fail(forest, arguments[index], document, "a procedure takes positional arguments");
                }
                next.append(Expect(arguments[index], shape[index], 0, -1));
            }
            finish := Resume(item.node, 1, address_native, length(arguments) + 1);
            finish.c = ProcCall;
            next.append(finish);
            return Step.Emitted(code, slots, locals, cells, hosts, roots, calls, bound, next, 0, NoValue(), NoValue(), marks);
        }
