        labeled := callback_signature >= 0 || GenericResolvedCall(names, item.node);
        callback_parameters: int[] = [];
        position: int = 0;
        argument := FirstMember(forest, Field(forest, item.node, syntax.FieldArguments));
        while (argument >= 0) {
