            // is read positionally.
            if ((Is(forest, argument, syntax.NamedArgument) && !labeled) || Is(forest, argument, syntax.TypedArgument)) {
                return Fail(forest, argument, document, format_text("unsupported syntax '{}'",
                                                                 parser.KindName(forest[argument].kind)));
            }
            parameter_index := GenericCallParameter(forest, text, callables, params, names, found, item.node, argument, position);
            if (labeled) {
                if (parameter_index < 0 || callback_parameters.contains(parameter_index)) {
                    return Fail(forest, argument, document, "Unknown or repeated callable parameter label");
                }
                callback_parameters.append(parameter_index);
            }
            value_node := argument;
            if (labeled && Is(forest, argument, syntax.NamedArgument)) {
                value_node = Field(forest, argument, syntax.FieldValue);
            }
            expected := Visit(value_node);
            if (found >= 0 && parameter_index < expected_count) {
                param := params[callables[found].first + parameter_index];
                expected = Expect(value_node, param.storage, param.container, param.record);
                if (param.reference && Is(forest, value_node, syntax.AddressExpression)) {
                    // `&x` lends x's location for the call.
                    expected.node = Unparenthesized(forest, Field(forest, value_node, syntax.FieldOperand));
                    expected.phase = ReferencePhase;
                } else if (param.reference) {
                    expected.phase = ScopedPhase;
                }
            }
