        if (Is(forest, parent, syntax.IfStatement) || Is(forest, parent, syntax.WhileStatement)) {
            condition := Unparenthesized(forest, Field(forest, parent, syntax.FieldCondition));
            consequence := Field(forest, parent, syntax.FieldConsequence);
