            truth := consequence >= 0 && forest[child].start >= forest[consequence].start && forest[child].end <= forest[consequence].end;
            alternative := Field(forest, parent, syntax.FieldAlternative);
            false_branch := alternative >= 0 && forest[child].start >= forest[alternative].start &&
                            forest[child].end <= forest[alternative].end;
            subject := Unparenthesized(forest, Field(forest, condition, syntax.FieldValue));
            negated := Field(forest, condition, syntax.FieldNegated) >= 0;
            if (Is(forest, condition, syntax.IsExpression) && TaskResultPattern(forest, text, condition) &&
                Is(forest, subject, syntax.Identifier) && Text(forest, text, subject) == binding.name &&
