        if (!Single(handle, TaskStorage)) {
            return Fail(forest, item.node, document, "task operation needs a task handle");
        }
        cells.append(TypedCell(TaskStorage, 0, -1));
        write := Instruction(ops.command_argument, TaskStorage, 0, handle.slot, 0, at.cell, node);
        write.offset = target.payload_offset;
        code.append(write);
        count = 1;
        popped = 1;
    }
    if (command == JoinCommand) {
        cells.append(ConstantCell(WordStorage, -1, success_tag));
        count = 2;
    }
    if (command == CancelAfterCommand || command == DelayCommand) {
        duration := values[top - 1];
        if (!Single(duration, DoubleStorage)) {
            return Fail(forest, item.node, document, "cancellation duration needs an f64");
        }
        cells.append(TypedCell(DoubleStorage, 0, -1));
        write := Instruction(ops.command_argument, DoubleStorage, 0, duration.slot, 0, at.cell + count, node);
        write.offset = target.payload_offset;
        code.append(write);
        count += 1;
        popped += 1;
