pub Collection :: struct {
    name: string;
    path: string;
    has_name: bool;
    has_path: bool;
}
pub Root :: struct {
    name: string;
    path: string;
}
File :: struct {
    path: string;
    directory: string;
    key: string;
    identity: string;
    root: int;
}
pub ImportInput :: struct {
    directory: string;
    literal: string;
    root: int;
    start: int;
    end: int;
    line: int;
    column: int;
    document: int;
}
pub RootResult :: union {
    Accepted(roots: Root[]) | Rejected(diagnostic: syntax.Diagnostic)
}
pub FileResult :: union {
    Accepted(file: File) | Rejected(diagnostic: syntax.Diagnostic)
}
pub ImportResult :: union {
    Accepted(directory: string) | Rejected(diagnostic: syntax.Diagnostic)
}

FileError :: (message: string, document: int) -> syntax.Diagnostic {
    return {start: 0, end: 0, line: 1, column: 1, document: document, message: message};
}

ImportError :: (message: string, request: ImportInput) -> ImportResult {
    return ImportResult.Rejected({start: request.start, end: request.end,
                                  line: request.line, column: request.column,
                                  document: request.document, message: message});
}

AddRoot :: (roots: Root[], item: Collection) -> RootResult {
    if (!item.has_name || !paths.Bounded(item.name) || !strings.IsIdentifier(item.name)) {
        return RootResult.Rejected(FileError("Invalid collection name", -1));
    }
    normalized := paths.Normalize({base: "", path: item.path, floor: "",
                                   has_base: false, has_path: item.has_path, has_floor: false});
    switch normalized {
        case .Invalid:
            return RootResult.Rejected(FileError("Invalid absolute collection root", -1));
        case .Normalized(path):
            // Name and path checks interleave for each earlier root. The first
            // conflicting earlier root determines the diagnostic.
            for (root in roots) {
                if (root.name == item.name) {
                    return RootResult.Rejected(FileError("Duplicate collection name", -1));
                }
                if (root.path == path) {
                    return RootResult.Rejected(FileError("Duplicate collection root", -1));
                }
            }
            root: Root = {name: item.name, path: path};
            return RootResult.Accepted(append(roots, root));
    }
}

pub RootSet :: (project: string, has_project: bool, collections: Collection[]) -> RootResult {
    // Snapshot option validation already bounds explicit collections to 255.
    roots: Root[] = [];
    first := AddRoot(roots, {name: "project", path: project, has_name: true, has_path: has_project});
    switch first {
        case .Rejected(diagnostic):
            return RootResult.Rejected(diagnostic);
        case .Accepted(items):
            roots = items;
    }
    for (item in collections) {
        added := AddRoot(roots, item);
        switch added {
            case .Rejected(diagnostic):
                return RootResult.Rejected(diagnostic);
            case .Accepted(items):
                roots = items;
        }
    }
    return RootResult.Accepted(roots);
}

// Roots are the nonempty canonical result of RootSet. Inputs use lexical paths;
// neither routing function inspects the filesystem or proves containment there.
OwningRoot :: (roots: Root[], directory: string) -> int {
    selected: int = -1;
    index: int = 0;
    while (index < length(roots)) {
        if (paths.Within(roots[index].path, directory)) {
            if (selected < 0 || strings.ByteLength(roots[index].path) > strings.ByteLength(roots[selected].path)) {
                selected = index;
            }
        }
        index += 1;
    }
    return selected;
}

Relative :: (root: string, path: string) -> string {
    offset := strings.ByteLength(root);
    if (root != "/" && strings.ByteAt(path, offset) == 47) {
        offset += 1;
    }
    return strings.Slice(path, offset, strings.ByteLength(path) - offset);
}

Key :: (root: Root, path: string) -> string {
    return format_text("{}:{}", root.name, Relative(root.path, path));
}

pub FileRoute :: (roots: Root[], path: string, has_path: bool, document: int) -> FileResult {
    if (!has_path || !paths.Bounded(path) || strings.ByteLength(path) == 0) {
        return FileResult.Rejected(FileError("Invalid package file path", document));
    }
    normalized := paths.Normalize({base: roots[0].path, path: path, floor: roots[0].path,
                                   has_base: true, has_path: true,
                                   has_floor: strings.ByteAt(path, 0) != 47});
    switch normalized {
        case .Invalid:
            return FileResult.Rejected(FileError("Invalid package file path or root escape", document));
        case .Normalized(canonical):
            if (canonical == "/") {
                return FileResult.Rejected(FileError("Invalid package file path or root escape", document));
            }
            slash := strings.LastIndexByte(canonical, 47);
            directory := "/";
            if (slash > 0) {
                directory = strings.Slice(canonical, 0, slash);
            }
            root := OwningRoot(roots, directory);
            if (root < 0) {
                return FileResult.Rejected(FileError("Package file is outside the configured roots", document));
            }
            tail := Relative(roots[root].path, directory);
            if (strings.Count(tail, "/") >= 16) {
                return FileResult.Rejected(FileError("Package path nesting exceeds the supported depth", document));
            }
            return FileResult.Accepted({path: canonical, directory: directory,
                                        key: Key(roots[root], canonical),
                                        identity: Key(roots[root], directory), root: root});
    }
}

// The foreign primitive supplies JSON decoding facts only. Collection lookup,
// path validity, root ownership and diagnostics remain authored policy.
pub ImportRoute :: (roots: Root[], request: ImportInput) -> ImportResult {
    decoded := json.Metadata(request.literal);
    if (!decoded.valid || strings.IndexByte(decoded.value, 0) >= 0) {
        return ImportError("Invalid import string or embedded NUL", request);
    }
    path := decoded.value;
    base := request.directory;
    root := request.root;
    colon := strings.IndexByte(path, 58);
    if (colon >= 0) {
        root = -1;
        name := strings.Slice(path, 0, colon);
        index: int = 0;
        while (index < length(roots)) {
            if (roots[index].name == name) {
                root = index;
                break;
            }
            index += 1;
        }
        if (root < 0) {
            return ImportError("Unknown import collection", request);
        }
        path = strings.Slice(path, colon + 1, strings.ByteLength(path) - colon - 1);
        base = roots[root].path;
    }
    if ((colon < 0 && strings.ByteLength(path) == 0) || strings.ByteAt(path, 0) == 47 || !paths.Bounded(path)) {
        return ImportError("Invalid import path", request);
    }
    normalized := paths.Normalize({base: base, path: path, floor: roots[root].path,
                                   has_base: true, has_path: true, has_floor: true});
    switch normalized {
        case .Invalid:
            return ImportError("Import path escapes its collection root or exceeds the path limit", request);
        case .Normalized(directory):
            return ImportResult.Accepted(directory);
    }
}
package package_paths

import strings "core:strings"

// Presence flags preserve the distinction between NULL and an empty C string.
// Base and floor retain the caller's canonical-path preconditions.
pub Request :: struct {
    base: string;
    path: string;
    floor: string;
    has_base: bool;
    has_path: bool;
    has_floor: bool;
}

pub Path :: union {
    Normalized(path: string)
    | Invalid
}

pub Bounded :: (path: string) -> bool {
    return strings.ByteLength(path) < 4096 && strings.IndexByte(path, 92) < 0;
}

pub Within :: (root: string, path: string) -> bool {
    if (root == "/") {
        return strings.ByteAt(path, 0) == 47;
    }
    if (!strings.HasPrefix(path, root)) {
        return false;
    }
    next := strings.ByteAt(path, strings.ByteLength(root));
    return next < 0 || next == 47;
}

pub Normalize :: (request: Request) -> Path {
    if (!request.has_path || !Bounded(request.path)) {
        return Path.Invalid;
    }
    joined := request.path;
    if (strings.ByteAt(request.path, 0) != 47) {
        if (!request.has_base) {
            return Path.Invalid;
        }
        joined = format_text("{}/{}", request.base, request.path);
    }
    if (strings.ByteLength(joined) >= 4096) {
        return Path.Invalid;
    }

    result := "/";
    starts := resize([int(0)], 2048);
    depth: int = 0;
    for (part in strings.Split(joined, "/")) {
        if (part == "..") {
            if (depth == 0) {
                return Path.Invalid;
            }
            depth -= 1;
            result = strings.Slice(result, 0, starts[depth]);
            // Leaving and later re-entering the floor is still an escape.
            if (request.has_floor && !Within(request.floor, result)) {
                return Path.Invalid;
            }
        } else if (part != "." && part != "") {
            starts[depth] = strings.ByteLength(result);
            depth += 1;
            if (strings.ByteLength(result) > 1) {
                result = format_text("{}/{}", result, part);
            } else {
                result = format_text("{}{}", result, part);
            }
        }
    }
    if (request.has_floor && !Within(request.floor, result)) {
        return Path.Invalid;
    }
    return Path.Normalized(result);
}
package package_syntax

import syntax "project:syntax_diagnostics"
import strings "core:strings"

File :: struct {
    path: string;
    directory: string;
    name: string;
    header_start: int;
    header_end: int;
    header_line: int;
    header_column: int;
    header_document: int;
}

pub Import :: struct {
    file: int;
    alias: string;
    explicit_alias: bool;
    range_start: int;
    range_end: int;
    range_line: int;
    range_column: int;
    range_document: int;
    path_start: int;
    path_end: int;
    path_line: int;
    path_column: int;
    path_document: int;
    alias_start: int;
    alias_end: int;
    alias_line: int;
    alias_column: int;
    alias_document: int;
    // Inside a `when` branch, so it binds only if the branch is kept.
    conditional: bool;
}

pub Result :: union {
    Accepted(file: File, imports: Import[])
    | Rejected(diagnostic: syntax.Diagnostic)
}

// Fields align with raw nodes and describe each node's edge from its
// parent. Package headers and imports use direct visible field edges.
FindField :: (nodes: syntax.Node[], fields: int[], node: int, field: int) -> int {
    child := nodes[node].first_child;
    while (child >= 0) {
        if (fields[child] == field) {
            return child;
        }
        child = nodes[child].next_sibling;
    }
    return -1;
}

// The header and imports of a parsed file; the parser has rejected syntax errors.
pub Extract :: (nodes: syntax.Node[], fields: int[], text: string,
                root: int, file: int, path: string, directory: string) -> Result {
    header := FindField(nodes, fields, root, syntax.FieldPackage);
    if (header < 0) {
        node := nodes[root];
        diagnostic: syntax.Diagnostic = {
            start: node.start, end: node.end, line: node.row + 1,
            column: node.column + 1, document: 0,
            message: "Expected package header"
        };
        return Result.Rejected(diagnostic);
    }

    nameNode := nodes[FindField(nodes, fields, header, syntax.FieldName)];
    name := strings.Slice(text, nameNode.start, nameNode.end - nameNode.start);
    if (name == "_") {
        diagnostic: syntax.Diagnostic = {
            start: nameNode.start, end: nameNode.end, line: nameNode.row + 1,
            column: nameNode.column + 1, document: 0,
            message: "A package needs a non-blank name"
        };
        return Result.Rejected(diagnostic);
    }

    descriptor: File = {
        path: path, directory: directory, name: name,
        header_start: nameNode.start, header_end: nameNode.end,
        header_line: nameNode.row + 1, header_column: nameNode.column + 1,
        header_document: 0
    };
    imports: Import[] = [];
    Imports(nodes, fields, text, file, root, false, &imports);
    return Result.Accepted(descriptor, imports);
}

// Appends the imports among `parent`'s children in source order, with those
// inside each `when` declaration's branches, all of which are conditional:
// the compiler keeps the ones of the branch the condition selects.
Imports :: (nodes: syntax.Node[], fields: int[], text: string, file: int, parent: int, conditional: bool,
            imports: ^(Import[])) {
    current := nodes[parent].first_child;
    while (current >= 0) {
        node := nodes[current];
        if (node.kind == syntax.WhenDeclaration || node.kind == syntax.DeclarationBlock) {
            Imports(nodes, fields, text, file, current, true, imports);
        } else if (node.kind == syntax.ImportDeclaration) {
            pathNode := nodes[FindField(nodes, fields, current, syntax.FieldPath)];
            alias := FindField(nodes, fields, current, syntax.FieldAlias);
            aliasName := "";
            aliasStart: int = 0;
            aliasEnd: int = 0;
            aliasLine: int = 0;
            aliasColumn: int = 0;
            if (alias >= 0) {
                aliasNode := nodes[alias];
                aliasName = strings.Slice(text, aliasNode.start, aliasNode.end - aliasNode.start);
                aliasStart = aliasNode.start;
                aliasEnd = aliasNode.end;
                aliasLine = aliasNode.row + 1;
                aliasColumn = aliasNode.column + 1;
            }
            imported: Import = {
                file: file, alias: aliasName, explicit_alias: alias >= 0,
                range_start: node.start, range_end: pathNode.end,
                range_line: node.row + 1, range_column: node.column + 1,
                range_document: 0,
                path_start: pathNode.start, path_end: pathNode.end,
                path_line: pathNode.row + 1, path_column: pathNode.column + 1,
                path_document: 0,
                alias_start: aliasStart, alias_end: aliasEnd,
                alias_line: aliasLine, alias_column: aliasColumn,
                alias_document: 0, conditional: conditional
            };
            imports.append(imported);
        }
        current = nodes[current].next_sibling;
    }
}
package package_graph

import strings "core:strings"

// Inputs are the checked parser/resolver descriptors. Paths and directories are
// canonical, names are identifiers other than _, files number at most 256, and
// every import's file index refers to this input. Neither parsing nor disk IO
// belongs to this component. Package indices preserve input discovery order.
pub File :: struct {
    path: string;
    directory: string;
    name: string;
}
// A conditional import is inside a `when` branch: its binding and edge hold
// only if the compiler keeps that branch, so two conditional imports of one
// file may share an alias, which the compiler checks among the kept ones.
pub Import :: struct {
    file: int;
    directory: string;
    alias: string;
    explicit_alias: bool;
    conditional: bool;
}
pub Package :: struct {
    directory: string;
    name: string;
    member_start: int;
    member_count: int;
}
pub Binding :: struct {
    name: string;
    file: int;
    target: int;
    import_index: int;
    conditional: bool;
}
// Conditional when every import that makes it is.
pub Edge :: struct {
    from: int;
    to: int;
    import_index: int;
    conditional: bool;
}
pub Error :: struct {
    code: int;
    file: int;
    import_index: int;
    related_file: int;
    related_import: int;
    cycle_count: int;
}
pub Graph :: union {
    Accepted(packages: Package[], members: int[], file_packages: int[],
             order: int[], edges: Edge[], bindings: Binding[])
    | Rejected(error: Error, cycle: int[])
}

OK: int : 0;
pub DuplicateFile: int : 1;
pub HeaderMismatch: int : 2;
pub DuplicateName: int : 3;
pub Missing: int : 4;
pub ImportName: int : 5;
pub DuplicateImport: int : 6;
pub Cycle: int : 7;
MaxFiles: int : 256;

Failure :: (error: Error, cycle: int[]) -> Graph {
    return Graph.Rejected(error, cycle);
}

BindingCompare :: (left: Binding, right: Binding) -> int {
    if (left.file < right.file) {
        return -1;
    }
    if (left.file > right.file) {
        return 1;
    }
    names := strings.Compare(left.name, right.name);
    if (names != 0) {
        return names;
    }
    if (left.import_index < right.import_index) {
        return -1;
    }
    if (left.import_index > right.import_index) {
        return 1;
    }
    return 0;
}

// Merge sorting avoids repeated whole-array indexed rewrites of imported bindings.
SortBindings :: (items: Binding[]) -> Binding[] {
    count := length(items);
    if (count < 2) {
        return items;
    }
    middle := count / 2;
    left := SortBindings(slice(items, 0, middle));
    right := SortBindings(slice(items, middle, count - middle));
    result: Binding[] = [];
    a: int = 0;
    b: int = 0;
    while (a < length(left) || b < length(right)) {
        takeLeft := b == length(right);
        if (a < length(left) && b < length(right)) {
            takeLeft = BindingCompare(left[a], right[b]) <= 0;
        }
        if (takeLeft) {
            result.append(left[a]);
            a += 1;
        } else {
            result.append(right[b]);
            b += 1;
        }
    }
    return result;
}

pub Build :: (files: File[], imports: Import[]) -> Graph {
    fileCount := length(files);
    packages: Package[] = [];
    bindings: Binding[] = [];
    edges: Edge[] = [];
    filePackages := resize([int(0)], fileCount);
    members := resize([int(0)], fileCount);
    cycle := resize([int(0)], MaxFiles);
    i: int = 0;
    while (i < fileCount) {
        file := files[i];
        j: int = 0;
        while (j < i) {
            if (file.path == files[j].path) {
                return Failure({code: DuplicateFile, file: i, import_index: -1,
                                related_file: j, related_import: -1, cycle_count: 0}, cycle);
            }
            j += 1;
        }
        found: int = -1;
        j = 0;
        while (j < length(packages)) {
            if (packages[j].directory == file.directory) {
                found = j;
                break;
            }
            j += 1;
        }
        if (found >= 0 && packages[found].name != file.name) {
            return Failure({code: HeaderMismatch, file: i, import_index: -1,
                            related_file: packages[found].member_start,
                            related_import: -1, cycle_count: 0}, cycle);
        }
        if (found < 0) {
            j = 0;
            while (j < length(packages)) {
                if (packages[j].name == file.name) {
                    return Failure({code: DuplicateName, file: i, import_index: -1,
                                    related_file: packages[j].member_start,
                                    related_import: -1, cycle_count: 0}, cycle);
                }
                j += 1;
            }
            found = length(packages);
            // Until membership is sorted, member_start retains the first file
            // responsible for this package's declared name and header.
            item: Package = {directory: file.directory, name: file.name,
                             member_start: i, member_count: 0};
            packages.append(item);
        }
        filePackages[i] = found;
        i += 1;
    }

    // Select sorted members with one output write per file. Insertion shifts
    // would repeatedly snapshot a scalar array under current value semantics.
    selected := resize([false], fileCount);
    offset: int = 0;
    i = 0;
    while (i < length(packages)) {
        item := packages[i];
        memberStart := offset;
        memberCount: int = 0;
        while (true) {
            next: int = -1;
            j: int = 0;
            while (j < fileCount) {
                if (!selected[j] && filePackages[j] == i) {
                    if (next < 0 || strings.Compare(files[j].path, files[next].path) < 0) {
                        next = j;
                    }
                }
                j += 1;
            }
            if (next < 0) {
                break;
            }
            selected[next] = true;
            members[offset] = next;
            offset += 1;
            memberCount += 1;
        }
        updated: Package = {directory: item.directory, name: item.name,
                            member_start: memberStart, member_count: memberCount};
        packages[i] = updated;
        i += 1;
    }

    i = 0;
    while (i < length(imports)) {
        imported := imports[i];
        target: int = -1;
        j: int = 0;
        while (j < length(packages)) {
            if (packages[j].directory == imported.directory) {
                target = j;
                break;
            }
            j += 1;
        }
        if (target < 0) {
            return Failure({code: Missing, file: imported.file, import_index: i,
                            related_file: -1, related_import: -1, cycle_count: 0}, cycle);
        }
        alias := imported.alias;
        if (!imported.explicit_alias) {
            alias = strings.BaseName(imported.directory);
        }
        blank := imported.explicit_alias && alias == "_";
        if (!strings.IsIdentifier(alias) || (!blank && alias == "_")) {
            return Failure({code: ImportName, file: imported.file, import_index: i,
                            related_file: -1, related_import: -1, cycle_count: 0}, cycle);
        }
        if (!blank) {
            binding: Binding = {name: alias, file: imported.file, target: target, import_index: i,
                                conditional: imported.conditional};
            bindings.append(binding);
        }
        from := filePackages[imported.file];
        exists := -1;
        for (index in 0..<length(edges)) {
            if (edges[index].from == from && edges[index].to == target) {
                exists = index;
                break;
            }
        }
        if (exists < 0) {
            edge: Edge = {from: from, to: target, import_index: i, conditional: imported.conditional};
            edges.append(edge);
        } else if (edges[exists].conditional && !imported.conditional) {
            certain: Edge = {from: from, to: target, import_index: i, conditional: false};
            edges[exists] = certain;
        }
        i += 1;
    }
    bindings = SortBindings(bindings);
    duplicate: int = -1;
    i = 1;
    while (i < length(bindings)) {
        a := bindings[i - 1];
        b := bindings[i];
        if (a.file == b.file && a.name == b.name && !(a.conditional && b.conditional)) {
            if (duplicate < 0 || b.import_index < bindings[duplicate].import_index) {
                duplicate = i;
            }
        }
        i += 1;
    }
    if (duplicate >= 0) {
        a := bindings[duplicate - 1];
        b := bindings[duplicate];
        return Failure({code: DuplicateImport, file: b.file, import_index: b.import_index,
                        related_file: b.file, related_import: a.import_index, cycle_count: 0}, cycle);
    }

    count := length(packages);
    dependencies := resize([int(0)], count);
    emitted := resize([false], count);
    order := resize([int(0)], count);
    for (edge in edges) {
        if (edge.from != edge.to) {
            dependencies[edge.from] += 1;
        }
    }
    ordinal: int = 0;
    while (ordinal < count) {
        next: int = -1;
        i = 0;
        while (i < count) {
            if (!emitted[i] && dependencies[i] == 0) {
                if (next < 0 || strings.Compare(packages[i].directory, packages[next].directory) < 0) {
                    next = i;
                }
            }
            i += 1;
        }
        if (next < 0) {
            // Follow the C residual witness exactly: lowest residual index,
            // lexical outgoing target, then trim the acyclic prefix.
            current: int = 0;
            while (emitted[current]) {
                current += 1;
            }
            seen := resize([int(0)], count);
            path: int[] = [];
            while (seen[current] == 0) {
                seen[current] = length(path) + 1;
                target: int = -1;
                importIndex: int = -1;
                for (edge in edges) {
                    if (edge.from == current && edge.to != current && !emitted[edge.to]) {
                        if (target < 0 || strings.Compare(packages[edge.to].directory, packages[target].directory) < 0) {
                            target = edge.to;
                            importIndex = edge.import_index;
                        }
                    }
                }
                path.append(importIndex);
                current = target;
            }
            start := seen[current] - 1;
            cycleCount := length(path) - start;
            i = 0;
            while (i < cycleCount) {
                cycle[i] = path[start + i];
                i += 1;
            }
            first := cycle[0];
            last := cycle[cycleCount - 1];
            return Failure({code: Cycle, file: imports[first].file, import_index: first,
                            related_file: imports[last].file, related_import: last,
                            cycle_count: cycleCount}, cycle);
        }
        emitted[next] = true;
        order[ordinal] = next;
        for (edge in edges) {
            if (edge.to == next && !emitted[edge.from]) {
                dependencies[edge.from] -= 1;
            }
        }
        ordinal += 1;
    }
    return Graph.Accepted(packages, members, filePackages, order, edges, bindings);
}

// Like the C facade, indexed queries require accepted graphs and valid indices.
pub Count :: (graph: Graph) -> int {
    switch graph {
        case .Accepted(packages, members, files, order, edges, bindings):
            return length(packages);
        case .Rejected(error, cycle):
            return 0;
    }
}
pub PackageAt :: (graph: Graph, index: int) -> Package {
    switch graph {
        case .Accepted(packages, members, files, order, edges, bindings):
            return packages[index];
        case .Rejected(error, cycle):
            return {directory: "", name: "", member_start: 0, member_count: 0};
    }
}
pub FilePackage :: (graph: Graph, file: int) -> int {
    switch graph {
        case .Accepted(packages, members, files, order, edges, bindings):
            return files[file];
        case .Rejected(error, cycle):
            return -1;
    }
}
pub Order :: (graph: Graph, ordinal: int) -> int {
    switch graph {
        case .Accepted(packages, members, files, order, edges, bindings):
            return order[ordinal];
        case .Rejected(error, cycle):
            return -1;
    }
}
pub Dependency :: (graph: Graph, from: int, to: int) -> int {
    switch graph {
        case .Accepted(packages, members, files, order, edges, bindings):
            for (edge in edges) {
                if (edge.from == from && edge.to == to) {
                    return edge.import_index;
                }
            }
            return -1;
        case .Rejected(error, cycle):
            return -1;
    }
}
pub Lookup :: (graph: Graph, file: int, alias: string) -> int {
    switch graph {
        case .Accepted(packages, members, files, order, edges, bindings):
            lo: int = 0;
            hi := length(bindings);
            while (lo < hi) {
                middle := lo + (hi - lo) / 2;
                binding := bindings[middle];
                compared := strings.Compare(alias, binding.name);
                if (file < binding.file) {
                    compared = -1;
                }
                if (file > binding.file) {
                    compared = 1;
                }
                if (compared == 0) {
                    return binding.target;
                }
                if (compared < 0) {
                    hi = middle;
                } else {
                    lo = middle + 1;
                }
            }
            return -1;
        case .Rejected(error, cycle):
            return -1;
    }
}
package compiler_syntax

import parser "project:source_parser"

// The raw syntax tree of `text`: every token a leaf, with the kinds, fields,
// named and extra flags and byte ranges of src/language/grammar.js, or the
// diagnostic of the first token it cannot read. The authored parser reads it;
// no native service is involved.
pub Parse :: (text: string) -> parser.Tree {
    return parser.Parse(text);
}
package source_parser

import tk "project:source_tokenizer"
import syntax "project:syntax_diagnostics"

// source_file: a package, or one behavior-like declaration.
ParseSourceFile :: (c: ^Cursor, n: ^(Node[])) -> int {
    root := New(n, syntax.SourceFile);
    if (c.token == tk.Package) {
        header := New(n, syntax.PackageHeader);
        Take(c, n, header, syntax.FieldNone);
        Add(n, header, TakeNameAlone(c, n), syntax.FieldName);
        End(c, n, header);
        Add(n, root, header, syntax.FieldPackage);
        while (!c.failed && c.token != tk.EOF) {
            Add(n, root, ParseDeclaration(c, n), syntax.FieldNone);
        }
    } else {
        // Without a package, the file is one behavior-like declaration.
        Add(n, root, ParseDeclaration(c, n), syntax.FieldNone);
        if (!c.failed && c.token != tk.EOF) {
            Fail(c, n, "Unexpected syntax");
        }
    }
    return root;
}

// An identifier token left for the caller to place.
TakeNameAlone :: (c: ^Cursor, n: ^(Node[])) -> int {
    if (!IsName(c.token)) {
        Fail(c, n, Expected(c, n, "a name"));
        return New(n, syntax.Error);
    }
    at := Take(c, n, -1, syntax.FieldNone);
    n^[at].kind = syntax.Identifier;
    n^[at].named = true;
    return at;
}

// The attributes in front of a declaration become its leading children.
TakeAttributes :: (c: ^Cursor, n: ^(Node[]), owner: int) {
    while (!c.failed && c.token == tk.At) {
        attribute := New(n, syntax.Attribute);
        Take(c, n, attribute, syntax.FieldNone);
        Add(n, attribute, TakeNameAlone(c, n), syntax.FieldName);
        Add(n, owner, attribute, syntax.FieldAttribute);
    }
}

// After a run of attributes, `[pub] Name :: struct` or `union` names a type
// declaration; any other continuation is a function.
AttributedTypeToken :: (c: ^Cursor, n: ^(Node[])) -> int {
    at: int = 0;
    while (Peek(c, n, at) == tk.At && IsName(Peek(c, n, at + 1))) {
        at += 2;
    }
    if (Peek(c, n, at) == tk.Pub) {
        at += 1;
    }
    if (IsName(Peek(c, n, at)) && Peek(c, n, at + 1) == tk.ColonColon) {
        following := Peek(c, n, at + 2);
        if (following == tk.Struct || following == tk.Union) {
            return following;
        }
    }
    return tk.At;
}

// One declaration of a package, a behavior, a library or a body.
// `when condition { declarations } [else when ... | else { declarations }]`:
// package-scope declarations that a constant selects. The word `when` starts
// one unless it names a declaration, `when :: ...`.
ParseWhen :: (c: ^Cursor, n: ^(Node[])) -> int {
    first := New(n, syntax.WhenDeclaration);
    current := first;
    while (!c.failed) {
        keyword := Take(c, n, current, syntax.FieldNone);
        n^[keyword].kind = syntax.When;
        n^[keyword].named = false;
        Add(n, current, ParseBinary(c, n, OrPower), syntax.FieldCondition);
        Add(n, current, ParseDeclarationBlock(c, n), syntax.FieldConsequence);
        if (c.failed || c.token != tk.Else) {
            break;
        }
        Take(c, n, current, syntax.FieldNone);
        if (!IsWord(c, n, "when")) {
            Add(n, current, ParseDeclarationBlock(c, n), syntax.FieldAlternative);
            break;
        }
        chained := New(n, syntax.WhenDeclaration);
        Add(n, current, chained, syntax.FieldAlternative);
        current = chained;
    }
    // The chain grew downward, so each link's range still ends where its own
    // last child did before the next link was added.
    chain: int[] = [first];
    link := first;
    while (n^[link].last >= 0 && n^[n^[link].last].kind == syntax.WhenDeclaration &&
           n^[n^[link].last].field == syntax.FieldAlternative) {
        link = n^[link].last;
        chain.append(link);
    }
    at := length(chain) - 2;
    while (at >= 0) {
        n^[chain[at]].end = n^[n^[chain[at]].last].end;
        at -= 1;
    }
    return first;
}

ParseDeclarationBlock :: (c: ^Cursor, n: ^(Node[])) -> int {
    block := New(n, syntax.DeclarationBlock);
    Expect(c, n, block, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        Add(n, block, ParseDeclaration(c, n), syntax.FieldNone);
    }
    Expect(c, n, block, tk.CloseBrace, syntax.FieldNone);
    return block;
}

ParseDeclaration :: (c: ^Cursor, n: ^(Node[])) -> int {
    token := c.token;
    if (IsWord(c, n, "when") && Peek(c, n, 1) != tk.ColonColon) {
        return ParseWhen(c, n);
    }
    if (token == tk.Import) {
        return ParseImport(c, n);
    }
    if (token == tk.Foreign) {
        return ParseForeign(c, n);
    }
    if (token == tk.At) {
        kind := AttributedTypeToken(c, n);
        if (kind == tk.Struct) {
            return ParseRecord(c, n, false);
        }
        if (kind == tk.Union) {
            return ParseUnion(c, n, false);
        }
        definition2 := New(n, syntax.FunctionDeclaration);
        TakeAttributes(c, n, definition2);
        Accept(c, n, definition2, tk.Pub, syntax.FieldVisibility);
        return ParseFunctionRest(c, n, definition2);
    }
    if (token == tk.Pub) {
        return ParseNamed(c, n, 1, true);
    }
    if (token == tk.Disabled || token == tk.Action) {
        return ParseComputation(c, n, syntax.ActionDeclaration);
    }
    if (token == tk.Event) {
        return ParseComputation(c, n, syntax.EventDeclaration);
    }
    if (token == tk.Bind) {
        Archived(c, n, "bind declarations");
        return New(n, syntax.Error);
    }
    if (token == tk.On || token == tk.After) {
        Archived(c, n, "event handlers");
        return New(n, syntax.Error);
    }
    if (token == tk.Macro) {
        definition := New(n, syntax.MacroDeclaration);
        Take(c, n, definition, syntax.FieldNone);
        TakeName(c, n, definition, syntax.FieldName);
        ParseSignature(c, n, definition);
        return definition;
    }
    if (token == tk.Events) {
        collection := New(n, syntax.EventsDeclaration);
        Take(c, n, collection, syntax.FieldNone);
        TakeName(c, n, collection, syntax.FieldName);
        Add(n, collection, ParseDeclarationBody(c, n, false), syntax.FieldBody);
        return collection;
    }
    if (token == tk.Entry) {
        arrival := New(n, syntax.EntryDeclaration);
        Take(c, n, arrival, syntax.FieldNone);
        TakeName(c, n, arrival, syntax.FieldName);
        Add(n, arrival, ParseBlock(c, n), syntax.FieldBody);
        return arrival;
    }
    if (token == tk.Exit) {
        leaving := New(n, syntax.ExitDeclaration);
        Take(c, n, leaving, syntax.FieldNone);
        TakeName(c, n, leaving, syntax.FieldName);
        End(c, n, leaving);
        return leaving;
    }
    return ParseNamed(c, n, 0, false);
}

ParseImport :: (c: ^Cursor, n: ^(Node[])) -> int {
    imported := New(n, syntax.ImportDeclaration);
    Take(c, n, imported, syntax.FieldNone);
    if (IsName(c.token) && Peek(c, n, 1) == tk.Colon && IsName(Peek(c, n, 2))) {
        collection := Slice(c.text, n^[c.pos].start, n^[c.pos].end);
        package := Slice(c.text, n^[c.pos + 2].start, n^[c.pos + 2].end);
        Fail(c, n, format_text("An import names its package in a string; write `import {} \"{}:{}\"`",
                               package, collection, package));
        return imported;
    }
    if (IsName(c.token)) {
        TakeName(c, n, imported, syntax.FieldAlias);
    }
    if (c.token != tk.String) {
        Fail(c, n, Expected(c, n, "a package string such as \"project:name\""));
        return imported;
    }
    Take(c, n, imported, syntax.FieldPath);
    End(c, n, imported);
    return imported;
}

// `disabled action Name: Type = value`, `event Name = value`.
ParseComputation :: (c: ^Cursor, n: ^(Node[]), kind: int) -> int {
    declaration := New(n, kind);
    Accept(c, n, declaration, tk.Disabled, syntax.FieldNone);
    Take(c, n, declaration, syntax.FieldNone);
    TakeName(c, n, declaration, syntax.FieldName);
    if (Accept(c, n, declaration, tk.Colon, syntax.FieldNone)) {
        if (c.token == tk.OpenParen) {
            Add(n, declaration, ParseParameters(c, n), syntax.FieldType);
        } else {
            Add(n, declaration, ParseType(c, n), syntax.FieldType);
        }
    }
    Expect(c, n, declaration, tk.Eq, syntax.FieldNone);
    Add(n, declaration, ParseBinary(c, n, OrPower), syntax.FieldValue);
    End(c, n, declaration);
    return declaration;
}



// A declaration that starts with a name, `offset` tokens in after a `pub`.
ParseNamed :: (c: ^Cursor, n: ^(Node[]), offset: int, public: bool) -> int {
    second := Peek(c, n, offset + 1);
    third := Peek(c, n, offset + 2);
    if (second == tk.ColonColon) {
        return ParseNamedValue(c, n, offset, public, third);
    }
    if (second == tk.ColonEq) {
        return ParseState(c, n, public);
    }
    if (second == tk.Colon) {
        if (third == tk.Retain) {
            return ParseExplicitState(c, n);
        }
        following := SkipType(n, c.pos + offset + 2, c.final);
        if (following >= 0 && n^[following].token == tk.Colon) {
            return ParseConstant(c, n, public);
        }
        return ParseState(c, n, public);
    }
    Fail(c, n, "Expected a declaration");
    return New(n, syntax.Error);
}

// `Name :: ...` by what follows the double colon.
ParseNamedValue :: (c: ^Cursor, n: ^(Node[]), offset: int, public: bool, third: int) -> int {
    if (third == tk.Behavior && !public) {
        Archived(c, n, "behavior declarations");
        return New(n, syntax.Error);
    }
    if (third == tk.Library && !public) {
        return ParseBehaviorLike(c, n, syntax.Library, true);
    }
    if (third == tk.System && !public) {
        Archived(c, n, "system declarations");
        return New(n, syntax.Error);
    }
    if (third == tk.Component && !public) {
        Archived(c, n, "component declarations");
        return New(n, syntax.Error);
    }
    if (third == tk.Prototype && !public) {
        return ParsePrototype(c, n);
    }
    if (third == tk.Relationship && !public) {
        return ParseRelationship(c, n);
    }
    if (third == tk.Struct) {
        return ParseRecord(c, n, public);
    }
    if (third == tk.Union) {
        return ParseUnion(c, n, public);
    }
    if (third == tk.OpenParen) {
        following := SkipBrackets(n, c.pos + offset + 2, c.final);
        if (following >= 0 && (n^[following].token == tk.ArrowRight ||
                               n^[following].token == tk.FatArrow ||
                               n^[following].token == tk.OpenBrace)) {
            definition2 := New(n, syntax.FunctionDeclaration);
            Accept(c, n, definition2, tk.Pub, syntax.FieldVisibility);
            return ParseFunctionRest(c, n, definition2);
        }
    }
    return ParseConstant(c, n, public);
}

// `name :: value` or `name: Type : value`.
ParseConstant :: (c: ^Cursor, n: ^(Node[]), public: bool) -> int {
    constant := New(n, syntax.ConstantDeclaration);
    Accept(c, n, constant, tk.Pub, syntax.FieldVisibility);
    TakeName(c, n, constant, syntax.FieldName);
    if (!Accept(c, n, constant, tk.ColonColon, syntax.FieldNone)) {
        Expect(c, n, constant, tk.Colon, syntax.FieldNone);
        Add(n, constant, ParseType(c, n), syntax.FieldType);
        Expect(c, n, constant, tk.Colon, syntax.FieldNone);
    }
    Add(n, constant, ParseBinary(c, n, OrPower), syntax.FieldValue);
    End(c, n, constant);
    return constant;
}

// `name := value` and `name: Type [= value]`, retained slot.
ParseState :: (c: ^Cursor, n: ^(Node[]), public: bool) -> int {
    slot := New(n, syntax.StateDeclaration);
    TakeName(c, n, slot, syntax.FieldName);
    if (Accept(c, n, slot, tk.ColonEq, syntax.FieldNone)) {
        Add(n, slot, ParseBinary(c, n, OrPower), syntax.FieldValue);
    } else {
        Expect(c, n, slot, tk.Colon, syntax.FieldNone);
        Add(n, slot, ParseType(c, n), syntax.FieldType);
        if (Accept(c, n, slot, tk.Eq, syntax.FieldNone)) {
            Add(n, slot, ParseBinary(c, n, OrPower), syntax.FieldValue);
        }
    }
    End(c, n, slot);
    return slot;
}

// `name: retain [Type] [= value]`.
ParseExplicitState :: (c: ^Cursor, n: ^(Node[])) -> int {
    slot := New(n, syntax.StateDeclaration);
    TakeName(c, n, slot, syntax.FieldName);
    Expect(c, n, slot, tk.Colon, syntax.FieldNone);
    Expect(c, n, slot, tk.Retain, syntax.FieldStorage);
    if (c.token != tk.Eq) {
        Add(n, slot, ParseType(c, n), syntax.FieldType);
    }
    if (Accept(c, n, slot, tk.Eq, syntax.FieldNone)) {
        Add(n, slot, ParseBinary(c, n, OrPower), syntax.FieldValue);
    }
    End(c, n, slot);
    return slot;
}

// [attributes] [pub] name `::` parameters [`->` results] [`=>`] body [`;`].
ParseFunctionRest :: (c: ^Cursor, n: ^(Node[]), definition2: int) -> int {
    TakeName(c, n, definition2, syntax.FieldName);
    Expect(c, n, definition2, tk.ColonColon, syntax.FieldNone);
    ParseSignature(c, n, definition2);
    return definition2;
}

// `-> Type` or `-> (name: Type, ...)` after the parameters, when present.
ParseResults :: (c: ^Cursor, n: ^(Node[]), owner: int) {
    if (Accept(c, n, owner, tk.ArrowRight, syntax.FieldNone)) {
        if (c.token == tk.OpenParen && (Peek(c, n, 1) == tk.CloseParen ||
                                          (IsName(Peek(c, n, 1)) && Peek(c, n, 2) == tk.Colon))) {
            Add(n, owner, ParseParameters(c, n), syntax.FieldResults);
        } else {
            Add(n, owner, ParseSignatureType(c, n), syntax.FieldResults);
        }
    }
}

// `foreign import alias "path"` names a prebuilt library, and `foreign alias {
// Name :: (parameters) -> result ... }` declares the C functions it provides,
// each by signature alone, as Odin's foreign blocks do. A block with no library,
// `foreign { ... }`, declares C symbols the program's own objects define.
ParseForeign :: (c: ^Cursor, n: ^(Node[])) -> int {
    if (Peek(c, n, 1) == tk.Import) {
        imported := New(n, syntax.ForeignImportDeclaration);
        Take(c, n, imported, syntax.FieldNone);
        Take(c, n, imported, syntax.FieldNone);
        TakeName(c, n, imported, syntax.FieldAlias);
        if (c.token != tk.String) {
            Fail(c, n, Expected(c, n, "a library path string"));
            return imported;
        }
        Take(c, n, imported, syntax.FieldPath);
        End(c, n, imported);
        return imported;
    }
    block := New(n, syntax.ForeignBlock);
    Take(c, n, block, syntax.FieldNone);
    if (c.token != tk.OpenBrace) {
        TakeName(c, n, block, syntax.FieldLibrary);
    }
    Expect(c, n, block, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        Add(n, block, ParseForeignFunction(c, n), syntax.FieldNone);
    }
    Expect(c, n, block, tk.CloseBrace, syntax.FieldNone);
    Accept(c, n, block, tk.Semicolon, syntax.FieldNone);
    return block;
}

ParseForeignFunction :: (c: ^Cursor, n: ^(Node[])) -> int {
    declaration := New(n, syntax.ForeignFunction);
    TakeAttributes(c, n, declaration);
    TakeName(c, n, declaration, syntax.FieldName);
    Expect(c, n, declaration, tk.ColonColon, syntax.FieldNone);
    Add(n, declaration, ParseParameters(c, n), syntax.FieldParameters);
    ParseResults(c, n, declaration);
    Accept(c, n, declaration, tk.Semicolon, syntax.FieldNone);
    return declaration;
}

ParseSignature :: (c: ^Cursor, n: ^(Node[]), owner: int) {
    Add(n, owner, ParseParameters(c, n), syntax.FieldParameters);
    ParseResults(c, n, owner);
    Accept(c, n, owner, tk.FatArrow, syntax.FieldNone);
    Add(n, owner, ParseCallableBody(c, n, syntax.CallableBody), syntax.FieldBody);
    Accept(c, n, owner, tk.Semicolon, syntax.FieldNone);
}

ParseParameters :: (c: ^Cursor, n: ^(Node[])) -> int {
    list := New(n, syntax.ParameterList);
    Expect(c, n, list, tk.OpenParen, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseParen && c.token != tk.EOF) {
        Add(n, list, ParseParameter(c, n), syntax.FieldNone);
        if (!Accept(c, n, list, tk.Comma, syntax.FieldNone)) {
            break;
        }
    }
    Expect(c, n, list, tk.CloseParen, syntax.FieldNone);
    return list;
}

// `[$]name [: Type] [from|split source] [= value]`.
ParseParameter :: (c: ^Cursor, n: ^(Node[])) -> int {
    parameter := New(n, syntax.Parameter);
    Accept(c, n, parameter, tk.Dollar, syntax.FieldComptime);
    TakeName(c, n, parameter, syntax.FieldName);
    if (Accept(c, n, parameter, tk.Colon, syntax.FieldNone)) {
        Add(n, parameter, ParseSignatureType(c, n), syntax.FieldType);
    }
    if (c.token == tk.From || c.token == tk.Split) {
        Take(c, n, parameter, syntax.FieldNone);
        Add(n, parameter, ParseBinary(c, n, OrPower), syntax.FieldSource);
    }
    if (Accept(c, n, parameter, tk.Eq, syntax.FieldNone)) {
        Add(n, parameter, ParseBinary(c, n, OrPower), syntax.FieldValue);
    }
    return parameter;
}

// `Name :: struct [(parameters)] { fields } [;]`.
ParseRecord :: (c: ^Cursor, n: ^(Node[]), public: bool) -> int {
    record := New(n, syntax.RecordDeclaration);
    TakeAttributes(c, n, record);
    Accept(c, n, record, tk.Pub, syntax.FieldVisibility);
    TakeName(c, n, record, syntax.FieldName);
    Expect(c, n, record, tk.ColonColon, syntax.FieldNone);
    Expect(c, n, record, tk.Struct, syntax.FieldNone);
    if (c.token == tk.OpenParen) {
        Add(n, record, ParseParameters(c, n), syntax.FieldParameters);
    }
    body := New(n, syntax.RecordBody);
    Expect(c, n, body, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        field := New(n, syntax.RecordField);
        TakeMember(c, n, field, syntax.FieldName);
        Expect(c, n, field, tk.Colon, syntax.FieldNone);
        Add(n, field, ParseType(c, n), syntax.FieldType);
        if (Accept(c, n, field, tk.Eq, syntax.FieldNone)) {
            Add(n, field, ParseBinary(c, n, OrPower), syntax.FieldValue);
        }
        End(c, n, field);
        Add(n, body, field, syntax.FieldNone);
    }
    Expect(c, n, body, tk.CloseBrace, syntax.FieldNone);
    Add(n, record, body, syntax.FieldBody);
    Accept(c, n, record, tk.Semicolon, syntax.FieldNone);
    return record;
}

// `Name :: union { Variant(fields) | "literal" | ... } [;]`.
ParseUnion :: (c: ^Cursor, n: ^(Node[]), public: bool) -> int {
    declaration := New(n, syntax.UnionDeclaration);
    TakeAttributes(c, n, declaration);
    Accept(c, n, declaration, tk.Pub, syntax.FieldVisibility);
    TakeName(c, n, declaration, syntax.FieldName);
    Expect(c, n, declaration, tk.ColonColon, syntax.FieldNone);
    Expect(c, n, declaration, tk.Union, syntax.FieldNone);
    Expect(c, n, declaration, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        variant := New(n, syntax.UnionVariant);
        if (c.token == tk.String) {
            Take(c, n, variant, syntax.FieldLiteral);
        } else {
            TakeName(c, n, variant, syntax.FieldName);
            if (c.token == tk.OpenParen) {
                Add(n, variant, ParseParameters(c, n), syntax.FieldParameters);
            }
        }
        Add(n, declaration, variant, syntax.FieldNone);
        if (!Accept(c, n, declaration, tk.Or, syntax.FieldNone)) {
            break;
        }
    }
    Expect(c, n, declaration, tk.CloseBrace, syntax.FieldNone);
    Accept(c, n, declaration, tk.Semicolon, syntax.FieldNone);
    return declaration;
}

// `Name :: behavior { ... }` and `Name :: library { ... }`.
ParseBehaviorLike :: (c: ^Cursor, n: ^(Node[]), kind: int, shared: bool) -> int {
    declaration := New(n, kind);
    TakeName(c, n, declaration, syntax.FieldName);
    Expect(c, n, declaration, tk.ColonColon, syntax.FieldNone);
    Take(c, n, declaration, syntax.FieldNone);
    Add(n, declaration, ParseDeclarationBody(c, n, shared), syntax.FieldBody);
    return declaration;
}

ParseDeclarationBody :: (c: ^Cursor, n: ^(Node[]), shared: bool) -> int {
    body := New(n, syntax.DeclarationBody);
    Expect(c, n, body, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        Add(n, body, ParseDeclaration(c, n), syntax.FieldNone);
    }
    Expect(c, n, body, tk.CloseBrace, syntax.FieldNone);
    return body;
}





// `Name :: template [(bases)] { Component { field: value } ... }`.
ParsePrototype :: (c: ^Cursor, n: ^(Node[])) -> int {
    template := New(n, syntax.PrototypeDeclaration);
    TakeName(c, n, template, syntax.FieldName);
    Expect(c, n, template, tk.ColonColon, syntax.FieldNone);
    Take(c, n, template, syntax.FieldNone);
    if (c.token == tk.OpenParen) {
        bases := New(n, syntax.PrototypeBases);
        Take(c, n, bases, syntax.FieldNone);
        while (!c.failed && c.token != tk.CloseParen && c.token != tk.EOF) {
            TakeName(c, n, bases, syntax.FieldNone);
            if (!Accept(c, n, bases, tk.Comma, syntax.FieldNone)) {
                break;
            }
        }
        Expect(c, n, bases, tk.CloseParen, syntax.FieldNone);
        Add(n, template, bases, syntax.FieldBases);
    }
    body := New(n, syntax.PrototypeBody);
    Expect(c, n, body, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        if (Peek(c, n, 1) == tk.OpenBrace) {
            part := New(n, syntax.PrototypeComponent);
            TakeName(c, n, part, syntax.FieldName);
            Add(n, part, ParseStructLiteral(c, n), syntax.FieldBody);
            Add(n, body, part, syntax.FieldNone);
        } else {
            field := New(n, syntax.StructField);
            TakeMember(c, n, field, syntax.FieldName);
            Expect(c, n, field, tk.Colon, syntax.FieldNone);
            Add(n, field, ParseBinary(c, n, OrPower), syntax.FieldValue);
            Add(n, body, field, syntax.FieldNone);
            if (!Accept(c, n, body, tk.Comma, syntax.FieldNone)) {
                End(c, n, body);
            }
        }
    }
    Expect(c, n, body, tk.CloseBrace, syntax.FieldNone);
    Add(n, template, body, syntax.FieldBody);
    return template;
}

// `Name :: link { ... }`.
ParseRelationship :: (c: ^Cursor, n: ^(Node[])) -> int {
    link := New(n, syntax.RelationshipDeclaration);
    TakeName(c, n, link, syntax.FieldName);
    Expect(c, n, link, tk.ColonColon, syntax.FieldNone);
    Take(c, n, link, syntax.FieldNone);
    Add(n, link, ParseStructLiteral(c, n), syntax.FieldBody);
    return link;
}
package source_parser

import tk "project:source_tokenizer"
import syntax "project:syntax_diagnostics"

// Tree-sitter's binding powers (src/language/grammar.js, P).
OrPower: int : 1;
AndPower: int : 2;
BitOrPower: int : 3;
BitXorPower: int : 4;
BitAndPower: int : 5;
EqualityPower: int : 6;
ComparisonPower: int : 7;
CoalescePower: int : 8;
ShiftPower: int : 9;
SumPower: int : 10;
ProductPower: int : 11;

// The binding power of the binary operator at the cursor, or 0.
BinaryPower :: (c: ^Cursor, n: ^(Node[])) -> int {
    token := c.token;
    // Most tokens that end an operand are punctuation below, between or above
    // the operators' kinds.
    if (token < tk.Add || (token > tk.GtEq && token < tk.As) || (token > tk.In && token != tk.Coalesce)) {
        return 0;
    }
    if (token == tk.CmpOr || token == tk.OrKeyword) {
        return OrPower;
    }
    if (token == tk.CmpAnd || token == tk.AndKeyword) {
        return AndPower;
    }
    if (token == tk.Or) {
        return BitOrPower;
    }
    if (token == tk.Xor) {
        return BitXorPower;
    }
    if (token == tk.And) {
        return BitAndPower;
    }
    if (token == tk.CmpEq || token == tk.NotEq) {
        return EqualityPower;
    }
    if (token == tk.Lt || token == tk.LtEq || token == tk.Gt || token == tk.GtEq ||
        token == tk.In || token == tk.Is || token == tk.As) {
        return ComparisonPower;
    }
    if (token == tk.NotKeyword && Peek(c, n, 1) == tk.In) {
        return ComparisonPower;
    }
    if (token == tk.Coalesce) {
        return CoalescePower;
    }
    if (token == tk.Shl || token == tk.Shr) {
        return ShiftPower;
    }
    if (token == tk.Add || token == tk.Sub) {
        return SumPower;
    }
    if (token == tk.Mul || token == tk.Quo || token == tk.Mod) {
        return ProductPower;
    }
    return 0;
}

// Precedence climbing: binary operators are left associative, `??` right.
ParseBinary :: (c: ^Cursor, n: ^(Node[]), least: int) -> int {
    left := ParseUnary(c, n);
    while (!c.failed) {
        power := BinaryPower(c, n);
        if (power == 0 || power < least) {
            break;
        }
        token := c.token;
        if (token == tk.Is) {
            left = ParseIs(c, n, left);
        } else if (token == tk.As) {
            cast := New(n, syntax.AsExpression);
            Add(n, cast, left, syntax.FieldValue);
            Take(c, n, cast, syntax.FieldNone);
            Add(n, cast, ParseType(c, n), syntax.FieldType);
            left = cast;
        } else {
            binary := New(n, syntax.BinaryExpression);
            Add(n, binary, left, syntax.FieldLeft);
            if (token == tk.NotKeyword) {
                joined := New(n, syntax.NotIn);
                Take(c, n, joined, syntax.FieldNone);
                Expect(c, n, joined, tk.In, syntax.FieldNone);
                Add(n, binary, joined, syntax.FieldOperator);
            } else {
                Take(c, n, binary, syntax.FieldOperator);
            }
            SkipSpuriousEnd(c, n);
            next := power + 1;
            if (power == CoalescePower) {
                next = power;
            }
            Add(n, binary, ParseBinary(c, n, next), syntax.FieldRight);
            left = binary;
        }
    }
    return left;
}

// The tokenizer cannot tell a `>` that ends a line as an operator from one
// that closes type arguments, so it may end the statement there; the grammar
// continues the expression.
SkipSpuriousEnd :: (c: ^Cursor, n: ^(Node[])) {
    if (c.token == tk.Semicolon && n^[c.pos].hidden) {
        c.pos += 1;
        c.token = n^[c.pos].token;
    }
}

// value `is` [`not`] (type | variant pattern) [binding name].
ParseIs :: (c: ^Cursor, n: ^(Node[]), left: int) -> int {
    test := New(n, syntax.IsExpression);
    Add(n, test, left, syntax.FieldValue);
    Take(c, n, test, syntax.FieldNone);
    Accept(c, n, test, tk.NotKeyword, syntax.FieldNegated);
    if (c.token == tk.Period) {
        Add(n, test, ParseVariantPattern(c, n), syntax.FieldType);
    } else {
        Add(n, test, ParseType(c, n), syntax.FieldType);
    }
    if (!c.failed && IsName(c.token) && !StartsOperator(c, n)) {
        TakeName(c, n, test, syntax.FieldBinding);
    }
    return test;
}

// A name at the cursor that is a word operator rather than a binding.
StartsOperator :: (c: ^Cursor, n: ^(Node[])) -> bool {
    token := c.token;
    return token == tk.NotKeyword && Peek(c, n, 1) == tk.In;
}

// `.Name` and optional `(bindings)`.
ParseVariantPattern :: (c: ^Cursor, n: ^(Node[])) -> int {
    pattern := New(n, syntax.VariantPattern);
    Expect(c, n, pattern, tk.Period, syntax.FieldNone);
    TakeName(c, n, pattern, syntax.FieldName);
    if (!c.failed && c.token == tk.OpenParen) {
        bindings := New(n, syntax.PatternBindings);
        Take(c, n, bindings, syntax.FieldNone);
        while (!c.failed && c.token != tk.CloseParen && c.token != tk.EOF) {
            TakeName(c, n, bindings, syntax.FieldNone);
            if (!Accept(c, n, bindings, tk.Comma, syntax.FieldNone)) {
                break;
            }
        }
        Expect(c, n, bindings, tk.CloseParen, syntax.FieldNone);
        Add(n, pattern, bindings, syntax.FieldBindings);
    }
    return pattern;
}

ParseUnary :: (c: ^Cursor, n: ^(Node[])) -> int {
    token := c.token;
    if (token == tk.Not || token == tk.Sub || token == tk.Add || token == tk.Complement ||
        (token == tk.NotKeyword && !NamesCall(c, n))) {
        unary := New(n, syntax.UnaryExpression);
        Take(c, n, unary, syntax.FieldOperator);
        Add(n, unary, ParseUnary(c, n), syntax.FieldOperand);
        return unary;
    }
    if (token == tk.And) {
        address := New(n, syntax.AddressExpression);
        Take(c, n, address, syntax.FieldNone);
        Add(n, address, ParseUnary(c, n), syntax.FieldOperand);
        return address;
    }
    if (token == tk.Await) {
        wait := New(n, syntax.AwaitExpression);
        Take(c, n, wait, syntax.FieldNone);
        Add(n, wait, ParseUnary(c, n), syntax.FieldValue);
        return wait;
    }
    left := ParsePrimary(c, n);
    while (!c.failed) {
        token = c.token;
        if (token == tk.Period) {
            member := New(n, syntax.MemberExpression);
            Add(n, member, left, syntax.FieldObject);
            Take(c, n, member, syntax.FieldNone);
            TakeMember(c, n, member, syntax.FieldMember);
            left = member;
        } else if (token == tk.OpenBracket) {
            index := New(n, syntax.IndexExpression);
            Add(n, index, left, syntax.FieldObject);
            Take(c, n, index, syntax.FieldNone);
            Add(n, index, ParseIndexValue(c, n), syntax.FieldIndex);
            Expect(c, n, index, tk.CloseBracket, syntax.FieldNone);
            left = index;
        } else if (token == tk.OpenParen && IsCallTarget(n^[left].kind)) {
            call := New(n, syntax.CallExpression);
            Add(n, call, left, syntax.FieldFunction);
            Add(n, call, ParseArguments(c, n), syntax.FieldArguments);
            left = call;
        } else if (token == tk.Xor && n^[c.pos].start == n^[c.pos - 1].end) {
            deref := New(n, syntax.DereferenceExpression);
            Add(n, deref, left, syntax.FieldOperand);
            Take(c, n, deref, syntax.FieldNone);
            left = deref;
        } else if (token == tk.Question && Peek(c, n, 1) == tk.Period && n^[c.pos].start == n^[c.pos - 1].end &&
                   n^[c.pos + 1].start == n^[c.pos].end) {
            // `value?.member` is nil when value is, else the member as an optional.
            chain := New(n, syntax.OptionalMemberExpression);
            Add(n, chain, left, syntax.FieldOperand);
            Take(c, n, chain, syntax.FieldNone);
            Take(c, n, chain, syntax.FieldNone);
            TakeMember(c, n, chain, syntax.FieldMember);
            left = chain;
        } else if (token == tk.Not && n^[c.pos].start == n^[c.pos - 1].end) {
            // `value!` takes an optional's payload and traps on nil. The `!`
            // must touch its operand, so `a !b` is still not followed by one.
            unwrap := New(n, syntax.ForceUnwrapExpression);
            Add(n, unwrap, left, syntax.FieldOperand);
            Take(c, n, unwrap, syntax.FieldNone);
            left = unwrap;
        } else {
            break;
        }
    }
    return left;
}

// Tree-sitter reads `not (` as a call of a function named `not`, as it reads
// `not(Value: x)`; only another token after `not` makes it the operator.
NamesCall :: (c: ^Cursor, n: ^(Node[])) -> bool {
    return Peek(c, n, 1) == tk.OpenParen;
}

// Members, indexes, calls and dereferences bind tighter than any operator;
// ParseUnary reads them after the primary, to keep nesting shallow.
IsCallTarget :: (kind: int) -> bool {
    return kind == syntax.Identifier || kind == syntax.BuiltinReference || kind == syntax.MemberExpression ||
           kind == syntax.IndexExpression || kind == syntax.CallExpression ||
           kind == syntax.ParenthesizedExpression;
}

// An index or an argument that may be a half-open range.
ParseIndexValue :: (c: ^Cursor, n: ^(Node[])) -> int {
    first := ParseBinary(c, n, OrPower);
    if (c.failed || c.token != tk.HalfOpenRange) {
        return first;
    }
    span := New(n, syntax.RangeExpression);
    Add(n, span, first, syntax.FieldStart);
    Take(c, n, span, syntax.FieldNone);
    Add(n, span, ParseBinary(c, n, OrPower), syntax.FieldEnd);
    return span;
}

ParsePrimary :: (c: ^Cursor, n: ^(Node[])) -> int {
    token := c.token;
    if (StartsLambda(c, n)) {
        return ParseLambda(c, n);
    }
    if (IsName(token)) {
        name := Take(c, n, -1, syntax.FieldNone);
        n^[name].kind = syntax.Identifier;
        n^[name].named = true;
        return name;
    }
    if (token == tk.String || token == tk.Integer || token == tk.Float || token == tk.Char) {
        return Take(c, n, -1, syntax.FieldNone);
    }
    if (token == tk.True || token == tk.False) {
        boolean := New(n, syntax.Boolean);
        Take(c, n, boolean, syntax.FieldNone);
        return boolean;
    }
    if (token == tk.Nil || token == tk.Null) {
        nothing := New(n, syntax.Nil);
        Take(c, n, nothing, syntax.FieldNone);
        return nothing;
    }
    if (token == tk.State || token == tk.Event) {
        builtin := New(n, syntax.BuiltinReference);
        Take(c, n, builtin, syntax.FieldNone);
        return builtin;
    }
    if (token == tk.Emit) {
        Archived(c, n, "emit expressions");
        return New(n, syntax.Error);
    }
    if (token == tk.OpenParen) {
        group := New(n, syntax.ParenthesizedExpression);
        Take(c, n, group, syntax.FieldNone);
        Add(n, group, ParseBinary(c, n, OrPower), syntax.FieldExpression);
        Expect(c, n, group, tk.CloseParen, syntax.FieldNone);
        return group;
    }
    if (token == tk.OpenBracket) {
        return ParseCollection(c, n);
    }
    if (token == tk.OpenBrace) {
        return ParseStructLiteral(c, n);
    }
    if (token == tk.Query) {
        Archived(c, n, "query expressions");
        return New(n, syntax.Error);
    }
    Fail(c, n, "Expected an expression");
    return New(n, syntax.Error);
}

// Whether an inline function starts here: an optional `fn`, a parameter list,
// and then `=>`, `->`, or a block after typed (or no) parameters, as in
// `(value: int) { ... }`. A parenthesized expression before a block is not one.
StartsLambda :: (c: ^Cursor, n: ^(Node[])) -> bool {
    open := c.pos;
    if (n^[open].kind == syntax.Fn) {
        open += 1;
    }
    if (n^[open].token != tk.OpenParen) {
        return false;
    }
    end := SkipBrackets(n, open, c.final);
    if (end < 0) {
        return false;
    }
    next := n^[end].token;
    if (next == tk.FatArrow || next == tk.ArrowRight) {
        return true;
    }
    if (next != tk.OpenBrace) {
        return false;
    }
    return n^[open + 1].token == tk.CloseParen || (IsName(n^[open + 1].token) && n^[open + 2].token == tk.Colon);
}

// `[fn] (parameters) [-> result] { body }` or `[fn] (parameters) => value`.
ParseLambda :: (c: ^Cursor, n: ^(Node[])) -> int {
    lambda := New(n, syntax.LambdaExpression);
    if (c.token != tk.OpenParen) {
        word := Take(c, n, lambda, syntax.FieldNone);
        n^[word].kind = syntax.Fn;
        n^[word].named = false;
    }
    Add(n, lambda, ParseParameters(c, n), syntax.FieldParameters);
    ParseResults(c, n, lambda);
    if (c.token != tk.FatArrow) {
        Add(n, lambda, ParseCallableBody(c, n, syntax.CallableBody), syntax.FieldBody);
        return lambda;
    }
    body := New(n, syntax.CallableBody);
    result := New(n, syntax.ReturnStatement);
    Take(c, n, result, syntax.FieldNone);
    Add(n, result, ParseBinary(c, n, OrPower), syntax.FieldValue);
    Add(n, body, result, syntax.FieldNone);
    Add(n, lambda, body, syntax.FieldBody);
    return lambda;
}


// An array `[a, b]`, a map `["k": v]` or an empty map `[:]`.
ParseCollection :: (c: ^Cursor, n: ^(Node[])) -> int {
    if (Peek(c, n, 1) == tk.Colon && Peek(c, n, 2) == tk.CloseBracket) {
        empty := New(n, syntax.MapExpression);
        Take(c, n, empty, syntax.FieldNone);
        Take(c, n, empty, syntax.FieldNone);
        Take(c, n, empty, syntax.FieldNone);
        return empty;
    }
    open := Take(c, n, -1, syntax.FieldNone);
    if (c.token == tk.CloseBracket) {
        array := New(n, syntax.ArrayExpression);
        Add(n, array, open, syntax.FieldNone);
        Take(c, n, array, syntax.FieldNone);
        return array;
    }
    first := ParseBinary(c, n, OrPower);
    if (!c.failed && c.token == tk.Colon) {
        map := New(n, syntax.MapExpression);
        Add(n, map, open, syntax.FieldNone);
        row := New(n, syntax.MapEntry);
        Add(n, row, first, syntax.FieldKey);
        Take(c, n, row, syntax.FieldNone);
        Add(n, row, ParseBinary(c, n, OrPower), syntax.FieldValue);
        Add(n, map, row, syntax.FieldNone);
        while (!c.failed && Accept(c, n, map, tk.Comma, syntax.FieldNone)) {
            if (c.token == tk.CloseBracket) {
                break;
            }
            row = New(n, syntax.MapEntry);
            Add(n, row, ParseBinary(c, n, OrPower), syntax.FieldKey);
            Expect(c, n, row, tk.Colon, syntax.FieldNone);
            Add(n, row, ParseBinary(c, n, OrPower), syntax.FieldValue);
            Add(n, map, row, syntax.FieldNone);
        }
        Expect(c, n, map, tk.CloseBracket, syntax.FieldNone);
        return map;
    }
    array := New(n, syntax.ArrayExpression);
    Add(n, array, open, syntax.FieldNone);
    Add(n, array, first, syntax.FieldNone);
    while (!c.failed && Accept(c, n, array, tk.Comma, syntax.FieldNone)) {
        if (c.token == tk.CloseBracket) {
            break;
        }
        Add(n, array, ParseBinary(c, n, OrPower), syntax.FieldNone);
    }
    Expect(c, n, array, tk.CloseBracket, syntax.FieldNone);
    return array;
}

// `{ name: value, ... }`.
ParseStructLiteral :: (c: ^Cursor, n: ^(Node[])) -> int {
    literal := New(n, syntax.StructExpression);
    Take(c, n, literal, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        field := New(n, syntax.StructField);
        TakeMember(c, n, field, syntax.FieldName);
        Expect(c, n, field, tk.Colon, syntax.FieldNone);
        Add(n, field, ParseBinary(c, n, OrPower), syntax.FieldValue);
        Add(n, literal, field, syntax.FieldNone);
        if (!Accept(c, n, literal, tk.Comma, syntax.FieldNone)) {
            break;
        }
    }
    Expect(c, n, literal, tk.CloseBrace, syntax.FieldNone);
    return literal;
}

// `(argument, ...)`: named, typed, ranged or plain expressions.
ParseArguments :: (c: ^Cursor, n: ^(Node[])) -> int {
    list := New(n, syntax.ArgumentList);
    Expect(c, n, list, tk.OpenParen, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseParen && c.token != tk.EOF) {
        named := -1;
        if (IsMember(c.token)) {
            following := SkipArgumentName(n, c.pos, c.final);
            if (following > 0 && n^[following].token == tk.Colon) {
                named = following;
            }
        }
        if (named >= 0) {
            Add(n, list, ParseNamedArgument(c, n, named), syntax.FieldNone);
        } else {
            value := ParseBinary(c, n, OrPower);
            if (!c.failed && c.token == tk.HalfOpenRange) {
                span := New(n, syntax.RangeExpression);
                Add(n, span, value, syntax.FieldStart);
                Take(c, n, span, syntax.FieldNone);
                Add(n, span, ParseBinary(c, n, OrPower), syntax.FieldEnd);
                value = span;
            }
            Add(n, list, value, syntax.FieldNone);
        }
        if (!Accept(c, n, list, tk.Comma, syntax.FieldNone)) {
            break;
        }
    }
    Expect(c, n, list, tk.CloseParen, syntax.FieldNone);
    return list;
}

// The position following the argument name that starts at `at`: member names
// joined by dots. 0 when it is not one.
SkipArgumentName :: (n: ^(Node[]), at: int, final: int) -> int {
    at += 1;
    while (at + 1 < final && n^[at].token == tk.Period && IsMember(n^[at + 1].token)) {
        at += 2;
    }
    return at;
}

// `name: value` or `name: Type = value` / `name: Type from source`.
ParseNamedArgument :: (c: ^Cursor, n: ^(Node[]), colon: int) -> int {
    typed := false;
    end := SkipType(n, colon + 1, c.final);
    if (end >= 0) {
        token := n^[end].token;
        typed = token == tk.Eq || token == tk.From || token == tk.Split;
    }
    kind := syntax.NamedArgument;
    if (typed) {
        kind = syntax.TypedArgument;
    }
    argument := New(n, kind);
    name := New(n, syntax.ArgumentName);
    TakeMember(c, n, name, syntax.FieldNone);
    while (!c.failed && c.token == tk.Period) {
        Take(c, n, name, syntax.FieldNone);
        TakeMember(c, n, name, syntax.FieldNone);
    }
    Add(n, argument, name, syntax.FieldName);
    Expect(c, n, argument, tk.Colon, syntax.FieldNone);
    if (!typed) {
        Add(n, argument, ParseBinary(c, n, OrPower), syntax.FieldValue);
        return argument;
    }
    Add(n, argument, ParseType(c, n), syntax.FieldType);
    if (c.token == tk.From || c.token == tk.Split) {
        Take(c, n, argument, syntax.FieldNone);
        Add(n, argument, ParseBinary(c, n, OrPower), syntax.FieldSource);
        if (Accept(c, n, argument, tk.Eq, syntax.FieldNone)) {
            Add(n, argument, ParseBinary(c, n, OrPower), syntax.FieldValue);
        }
        return argument;
    }
    Expect(c, n, argument, tk.Eq, syntax.FieldNone);
    Add(n, argument, ParseBinary(c, n, OrPower), syntax.FieldValue);
    return argument;
}
package source_parser

import tk "project:source_tokenizer"
import syntax "project:syntax_diagnostics"

// A parse that did not reach a tree: why, and where.
Outcome :: union {
    Built(nodes: Node[], root: int) |
    Rejected(message: string, start: int, end: int, row: int, column: int)
}

// Parses a whole source text into the raw facts compiler_syntax.Parse returns:
// every token as a leaf, with the node, field and extra flags of the grammar
// in src/language/grammar.js. Text the grammar does not read gives the
// diagnostic of where the parse stopped, saying what was expected; its
// message keeps the 191 bytes a diagnostic row holds.
pub Parse :: (text: string) -> Tree {
    outcome := Build(text);
    switch outcome {
        case .Built(nodes, root):
            return Emit(nodes, root);
        case .Rejected(message, start, end, row, column):
            return Tree.Rejected({start: start, end: end, line: row + 1, column: column + 1, document: 0,
                                  message: text_slice(message, 0, 191)});
    }
}

Build :: (text: string) -> Outcome {
    scanned := tk.Tokenize(text);
    switch scanned {
        case .Scanned(kinds, starts, ends, rows, columns, errors, error_offsets, error_rows, error_columns):
            if (length(errors) > 0) {
                return Outcome.Rejected(errors[0], error_offsets[0], error_offsets[0] + 1,
                                        error_rows[0], error_columns[0]);
            }
            return Construct(text, kinds, starts, ends, rows, columns);
    }
}

Construct :: (text: string, kinds: int[], starts: int[], ends: int[], rows: int[], columns: int[]) -> Outcome {
    nodes: Node[] = [];
    comments: Node[] = [];
    index: int = 0;
    while (index < length(kinds)) {
        leaf := Leaf(LeafKind(kinds[index]), kinds[index], starts[index], ends[index],
                     rows[index], columns[index]);
        if (kinds[index] == tk.Ident && ends[index] - starts[index] == 2 && Spells(text, starts[index], "fn")) {
            leaf.kind = syntax.Fn;
        }
        if (kinds[index] == tk.Comment) {
            leaf.named = true;
            leaf.extra = true;
            comments.append(leaf);
        } else {
            nodes.append(leaf);
        }
        index += 1;
    }
    cursor: Cursor = {text: text, pos: 0, token: nodes[0].token, final: length(nodes) - 1, failed: false, message: "",
                      at: 0, stop: 0, row: 0, column: 0};
    root := ParseSourceFile(&cursor, &nodes);
    if (cursor.failed) {
        return Outcome.Rejected(cursor.message, cursor.at, cursor.stop, cursor.row, cursor.column);
    }
    if (cursor.pos != cursor.final) {
        return Outcome.Rejected("Expected a declaration", nodes[cursor.pos].start,
                                nodes[cursor.pos].end, nodes[cursor.pos].row, nodes[cursor.pos].column);
    }
    Attach(&nodes, root, comments, text_byte_length(text));
    return Outcome.Built(nodes, root);
}

// Comments are extras: Tree-sitter keeps each in the innermost node that has a
// child after it, and a trailing one in the node that ends before it.
Attach :: (n: ^(Node[]), root: int, comments: Node[], size: int) {
    index: int = 0;
    while (index < length(comments)) {
        comment := comments[index];
        at := length(n^);
        n.append(comment);
        owner := root;
        descending := true;
        while (descending) {
            descending = false;
            child := n^[owner].first;
            while (child >= 0) {
                if (n^[child].first >= 0 && n^[child].start < comment.start && comment.end <= n^[child].end) {
                    owner = child;
                    descending = true;
                    break;
                }
                child = n^[child].next;
            }
        }
        Insert(n, owner, at);
        index += 1;
    }
    n^[root].end = size;
}

// Places `comment` among the children of `owner`, before the first that
// starts after it.
Insert :: (n: ^(Node[]), owner: int, comment: int) {
    n^[comment].parent = owner;
    previous: int = -1;
    child := n^[owner].first;
    while (child >= 0 && n^[child].start < n^[comment].end) {
        previous = child;
        child = n^[child].next;
    }
    n^[comment].next = child;
    if (previous < 0) {
        n^[owner].first = comment;
    } else {
        n^[previous].next = comment;
    }
    if (child < 0) {
        n^[owner].last = comment;
    }
    if (n^[owner].start < 0 || n^[comment].start < n^[owner].start) {
        n^[owner].start = n^[comment].start;
        n^[owner].row = n^[comment].row;
        n^[owner].column = n^[comment].column;
    }
}

// Rows in pre-order, as Tree-sitter's cursor walk lists them, without the
// hidden terminators. One walk fills the rows; a node's next sibling is
// patched in when the walk reaches it.
Emit :: (nodes: Node[], root: int) -> Tree {
    rows: syntax.Node[] = [];
    fields: int[] = [];
    named: bool[] = [];
    extras: bool[] = [];
    place := resize([int(0)], length(nodes));
    current := root;
    while (current >= 0) {
        index := length(rows);
        place[current] = index;
        parent: int = -1;
        if (nodes[current].parent >= 0) {
            parent = place[nodes[current].parent];
        }
        first := nodes[current].first;
        while (first >= 0 && nodes[first].hidden) {
            first = nodes[first].next;
        }
        first_child: int = -1;
        if (first >= 0) {
            first_child = index + 1;
        }
        rows.append({kind: nodes[current].kind, start: nodes[current].start, end: nodes[current].end,
                     row: nodes[current].row, column: nodes[current].column, parent: parent,
                     first_child: first_child, next_sibling: -1});
        fields.append(nodes[current].field);
        named.append(nodes[current].named);
        extras.append(nodes[current].extra);
        next := first;
        climbing := current;
        while (next < 0 && climbing != root) {
            next = nodes[climbing].next;
            while (next >= 0 && nodes[next].hidden) {
                next = nodes[next].next;
            }
            if (next >= 0) {
                rows[place[climbing]].next_sibling = index + 1;
            } else {
                climbing = nodes[climbing].parent;
            }
        }
        current = next;
    }
    return Tree.Parsed(rows, fields, named, extras, 0);
}
package source_parser

import tk "project:source_tokenizer"
import syntax "project:syntax_diagnostics"

// block: `{` statements `}`.
ParseBlock :: (c: ^Cursor, n: ^(Node[])) -> int {
    block := New(n, syntax.Block);
    Expect(c, n, block, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        Add(n, block, ParseStatement(c, n, false), syntax.FieldNone);
    }
    Expect(c, n, block, tk.CloseBrace, syntax.FieldNone);
    return block;
}

// The body of a function, a system or a macro: statements and declarations.
ParseCallableBody :: (c: ^Cursor, n: ^(Node[]), kind: int) -> int {
    body := New(n, kind);
    Expect(c, n, body, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token != tk.CloseBrace && c.token != tk.EOF) {
        Add(n, body, ParseStatement(c, n, true), syntax.FieldNone);
    }
    Expect(c, n, body, tk.CloseBrace, syntax.FieldNone);
    return body;
}

IsAssignment :: (token: int) -> bool {
    return token == tk.Eq || token == tk.AddEq || token == tk.SubEq || token == tk.MulEq ||
           token == tk.QuoEq || token == tk.ModEq || token == tk.AndEq || token == tk.OrEq ||
           token == tk.XorEq;
}

// One statement; with `declarations`, also what a body may declare.
ParseStatement :: (c: ^Cursor, n: ^(Node[]), declarations: bool) -> int {
    token := c.token;
    if (token == tk.If) {
        return ParseIf(c, n);
    }
    if (token == tk.While) {
        loop := New(n, syntax.WhileStatement);
        Take(c, n, loop, syntax.FieldNone);
        Add(n, loop, ParseBinary(c, n, OrPower), syntax.FieldCondition);
        Add(n, loop, ParseBlock(c, n), syntax.FieldBody);
        return loop;
    }
    if (token == tk.For) {
        return ParseFor(c, n);
    }
    if (token == tk.Switch) {
        return ParseSwitch(c, n);
    }
    if (token == tk.Return) {
        return ParseReturn(c, n);
    }
    if (token == tk.Goto) {
        jump := New(n, syntax.GotoStatement);
        Take(c, n, jump, syntax.FieldNone);
        TakeName(c, n, jump, syntax.FieldName);
        End(c, n, jump);
        return jump;
    }
    if (token == tk.Break) {
        return ParseKeywordStatement(c, n, syntax.BreakStatement);
    }
    if (token == tk.Continue) {
        return ParseKeywordStatement(c, n, syntax.ContinueStatement);
    }
    if (token == tk.Yield) {
        return ParseKeywordStatement(c, n, syntax.YieldStatement);
    }
    if (token == tk.Cancel) {
        stop := New(n, syntax.CancelStatement);
        Take(c, n, stop, syntax.FieldNone);
        Add(n, stop, ParseBinary(c, n, OrPower), syntax.FieldValue);
        if (c.token == tk.After) {
            Take(c, n, stop, syntax.FieldNone);
            Add(n, stop, ParseBinary(c, n, OrPower), syntax.FieldDuration);
        }
        End(c, n, stop);
        return stop;
    }
    if (token == tk.Delete) {
        removal := New(n, syntax.DeleteStatement);
        Take(c, n, removal, syntax.FieldNone);
        Add(n, removal, ParseBinary(c, n, OrPower), syntax.FieldTarget);
        End(c, n, removal);
        return removal;
    }
    if (token == tk.Sequence) {
        return ParseSequence(c, n);
    }
    if (token == tk.Reduce) {
        Archived(c, n, "reduce statements");
        return New(n, syntax.Error);
    }
    if (declarations && StartsBodyDeclaration(c, n)) {
        return ParseDeclaration(c, n);
    }
    if (IsName(token)) {
        next := Peek(c, n, 1);
        if (next == tk.ColonEq) {
            return ParseLocal(c, n);
        }
        if (next == tk.ColonColon) {
            return ParseNamed(c, n, 0, false);
        }
        if (next == tk.Colon) {
            return ParseColonStatement(c, n, declarations);
        }
    }
    return ParseExpressionStatement(c, n);
}

// Whether the cursor starts a declaration that only bodies may hold.
StartsBodyDeclaration :: (c: ^Cursor, n: ^(Node[])) -> bool {
    token := c.token;
    if (token == tk.At || token == tk.Disabled || token == tk.Action || token == tk.Bind ||
        token == tk.On || token == tk.After || token == tk.Macro || token == tk.Events ||
        token == tk.Exit || token == tk.Pub) {
        return true;
    }
    if (token == tk.Event) {
        return Peek(c, n, 1) != tk.Period;
    }
    if (token == tk.Entry) {
        return IsName(Peek(c, n, 1));
    }
    return false;
}

// `name : ...`: a typed local, a typed constant, an explicit state, or a label.
ParseColonStatement :: (c: ^Cursor, n: ^(Node[]), declarations: bool) -> int {
    if (declarations && Peek(c, n, 2) == tk.Retain) {
        return ParseExplicitState(c, n);
    }
    following := SkipType(n, c.pos + 2, c.final);
    if (following >= 0 && n^[following].token == tk.Eq) {
        return ParseLocal(c, n);
    }
    if (following >= 0 && n^[following].token == tk.Colon) {
        return ParseConstant(c, n, false);
    }
    label := New(n, syntax.LabelStatement);
    TakeName(c, n, label, syntax.FieldName);
    Expect(c, n, label, tk.Colon, syntax.FieldNone);
    if (c.token == tk.Semicolon && n^[c.pos].hidden) {
        Take(c, n, label, syntax.FieldNone);
    }
    return label;
}

// `name := value` or `name: Type = value`.
ParseLocal :: (c: ^Cursor, n: ^(Node[])) -> int {
    local := New(n, syntax.LocalDeclaration);
    TakeName(c, n, local, syntax.FieldName);
    if (Accept(c, n, local, tk.ColonEq, syntax.FieldNone)) {
        Add(n, local, ParseBinary(c, n, OrPower), syntax.FieldValue);
        End(c, n, local);
        return local;
    }
    Expect(c, n, local, tk.Colon, syntax.FieldNone);
    Add(n, local, ParseType(c, n), syntax.FieldType);
    Expect(c, n, local, tk.Eq, syntax.FieldNone);
    Add(n, local, ParseBinary(c, n, OrPower), syntax.FieldValue);
    End(c, n, local);
    return local;
}

ParseKeywordStatement :: (c: ^Cursor, n: ^(Node[]), kind: int) -> int {
    statement := New(n, kind);
    Take(c, n, statement, syntax.FieldNone);
    End(c, n, statement);
    return statement;
}

// An assignment or an expression used for its effect.
ParseExpressionStatement :: (c: ^Cursor, n: ^(Node[])) -> int {
    value := ParseBinary(c, n, OrPower);
    if (!c.failed && IsAssignment(c.token)) {
        assignment := New(n, syntax.Assignment);
        Add(n, assignment, value, syntax.FieldTarget);
        Take(c, n, assignment, syntax.FieldOperator);
        Add(n, assignment, ParseBinary(c, n, OrPower), syntax.FieldValue);
        End(c, n, assignment);
        return assignment;
    }
    statement := New(n, syntax.ExpressionStatement);
    Add(n, statement, value, syntax.FieldNone);
    End(c, n, statement);
    return statement;
}

ParseIf :: (c: ^Cursor, n: ^(Node[])) -> int {
    first := New(n, syntax.IfStatement);
    current := first;
    while (!c.failed) {
        Take(c, n, current, syntax.FieldNone);
        Add(n, current, ParseBinary(c, n, OrPower), syntax.FieldCondition);
        Add(n, current, ParseBlock(c, n), syntax.FieldConsequence);
        if (c.failed || c.token != tk.Else) {
            break;
        }
        Take(c, n, current, syntax.FieldNone);
        if (c.token != tk.If) {
            Add(n, current, ParseBlock(c, n), syntax.FieldAlternative);
            break;
        }
        chained := New(n, syntax.IfStatement);
        Add(n, current, chained, syntax.FieldAlternative);
        current = chained;
    }
    // The chain grew downward, so each link's range still ends where its own
    // last child did before the next link was added.
    chain: int[] = [first];
    link := first;
    while (n^[link].last >= 0 && n^[n^[link].last].kind == syntax.IfStatement &&
           n^[n^[link].last].field == syntax.FieldAlternative) {
        link = n^[link].last;
        chain.append(link);
    }
    at := length(chain) - 2;
    while (at >= 0) {
        n^[chain[at]].end = n^[n^[chain[at]].last].end;
        at -= 1;
    }
    return first;
}

// `for [<] name in first (..|..<) last`, or `for [key,] [&]name in value`,
// either one parenthesized.
ParseFor :: (c: ^Cursor, n: ^(Node[])) -> int {
    loop := New(n, syntax.ForStatement);
    Take(c, n, loop, syntax.FieldNone);
    Accept(c, n, loop, tk.Lt, syntax.FieldReverse);
    grouped := c.token == tk.OpenParen;
    if (grouped) {
        Take(c, n, loop, syntax.FieldNone);
    }
    if (Peek(c, n, 1) == tk.Comma) {
        TakeName(c, n, loop, syntax.FieldKey);
        Take(c, n, loop, syntax.FieldNone);
    }
    Accept(c, n, loop, tk.And, syntax.FieldReference);
    TakeName(c, n, loop, syntax.FieldName);
    Expect(c, n, loop, tk.In, syntax.FieldNone);
    first := ParseBinary(c, n, OrPower);
    if (!c.failed && (c.token == tk.Ellipsis || c.token == tk.HalfOpenRange)) {
        Add(n, loop, first, syntax.FieldFirst);
        Take(c, n, loop, syntax.FieldBound);
        Add(n, loop, ParseBinary(c, n, OrPower), syntax.FieldLast);
    } else {
        Add(n, loop, first, syntax.FieldValue);
    }
    if (grouped) {
        Expect(c, n, loop, tk.CloseParen, syntax.FieldNone);
    }
    Add(n, loop, ParseBlock(c, n), syntax.FieldBody);
    return loop;
}

ParseSwitch :: (c: ^Cursor, n: ^(Node[])) -> int {
    selection := New(n, syntax.SwitchStatement);
    Take(c, n, selection, syntax.FieldNone);
    Add(n, selection, ParseBinary(c, n, OrPower), syntax.FieldValue);
    Expect(c, n, selection, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token == tk.Case) {
        arm := New(n, syntax.SwitchArm);
        Take(c, n, arm, syntax.FieldNone);
        if (c.token == tk.Colon) {
            // The default arm has no value.
        } else if (c.token == tk.Period) {
            Add(n, arm, ParseVariantPattern(c, n), syntax.FieldValue);
        } else {
            Add(n, arm, ParseBinary(c, n, OrPower), syntax.FieldValue);
        }
        Expect(c, n, arm, tk.Colon, syntax.FieldNone);
        if (c.token == tk.OpenBrace) {
            Add(n, arm, ParseBlock(c, n), syntax.FieldBody);
        } else {
            statements := New(n, syntax.Block);
            while (!c.failed && c.token != tk.Case && c.token != tk.CloseBrace && c.token != tk.EOF) {
                Add(n, statements, ParseStatement(c, n, false), syntax.FieldNone);
            }
            Add(n, arm, statements, syntax.FieldBody);
        }
        Add(n, selection, arm, syntax.FieldNone);
    }
    Expect(c, n, selection, tk.CloseBrace, syntax.FieldNone);
    return selection;
}

// `return [.Outcome] [values]`.
ParseReturn :: (c: ^Cursor, n: ^(Node[])) -> int {
    statement := New(n, syntax.ReturnStatement);
    Take(c, n, statement, syntax.FieldNone);
    if (c.token == tk.Period) {
        Take(c, n, statement, syntax.FieldNone);
        TakeName(c, n, statement, syntax.FieldOutcome);
    }
    if (!c.failed && c.token != tk.Semicolon) {
        if (c.token == tk.OpenParen) {
            Add(n, statement, ParseArgumentsOrGroup(c, n), syntax.FieldValue);
        } else {
            Add(n, statement, ParseBinary(c, n, OrPower), syntax.FieldValue);
        }
    }
    End(c, n, statement);
    return statement;
}

// After `return`, a parenthesized start is an argument list when it is empty,
// holds a comma or starts an element with `name:`, and a parenthesized
// expression otherwise, as Tree-sitter reads it.
ParseArgumentsOrGroup :: (c: ^Cursor, n: ^(Node[])) -> int {
    if (HoldsArguments(c, n)) {
        return ParseArguments(c, n);
    }
    return ParseBinary(c, n, OrPower);
}

HoldsArguments :: (c: ^Cursor, n: ^(Node[])) -> bool {
    at := c.pos + 1;
    if (n^[at].token == tk.CloseParen) {
        return true;
    }
    depth: int = 1;
    start := true;
    while (at < c.final && depth > 0) {
        token := n^[at].token;
        if (depth == 1 && start && IsMember(token)) {
            following := SkipArgumentName(n, at, c.final);
            if (following > 0 && n^[following].token == tk.Colon) {
                return true;
            }
        }
        start = false;
        if (token == tk.OpenParen || token == tk.OpenBracket || token == tk.OpenBrace) {
            depth += 1;
        } else if (token == tk.CloseParen || token == tk.CloseBracket || token == tk.CloseBrace) {
            depth -= 1;
        } else if (depth == 1 && token == tk.Comma) {
            return true;
        }
        at += 1;
    }
    return false;
}

ParseSequence :: (c: ^Cursor, n: ^(Node[])) -> int {
    chain := New(n, syntax.SequenceStatement);
    Take(c, n, chain, syntax.FieldNone);
    Expect(c, n, chain, tk.OpenBrace, syntax.FieldNone);
    while (!c.failed && c.token == tk.Branch) {
        part := New(n, syntax.BranchStatement);
        Take(c, n, part, syntax.FieldNone);
        Add(n, part, ParseBlock(c, n), syntax.FieldBody);
        Add(n, chain, part, syntax.FieldNone);
    }
    Expect(c, n, chain, tk.CloseBrace, syntax.FieldNone);
    return chain;
}

package source_parser

import tk "project:source_tokenizer"
import syntax "project:syntax_diagnostics"

// A node of the tree under construction. The first rows are the tokens, in
// order, and the parser appends interior rows after them. Links use -1 for
// absence; `last` is the newest child, so adding a child is constant time.
// Offsets count bytes, as Tree-sitter's do. `kind` and `field` are
// syntax_diagnostics kinds and fields.
Node :: struct {
    kind: int;
    field: int;
    token: int;
    start: int;
    end: int;
    row: int;
    column: int;
    parent: int;
    first: int;
    last: int;
    next: int;
    named: bool;
    hidden: bool;
    extra: bool;
}

// The parse position. A failure keeps the first message and moves the
// position to the end of the tokens, so every loop that reads tokens stops.
Cursor :: struct {
    text: string;
    pos: int;
    token: int;
    final: int;
    failed: bool;
    message: string;
    at: int;
    stop: int;
    row: int;
    column: int;
}

// What Parse returns: the rows of a tree with each row's field and named and
// extra flags, as compiler_syntax.Parse returns them, or the diagnostic of
// the first token the grammar cannot read.
pub Tree :: union {
    Parsed(nodes: syntax.Node[], fields: int[], is_named: bool[], is_extra: bool[], root: int)
    | Rejected(diagnostic: syntax.Diagnostic)
}

NewNode :: (kind: int, named: bool) -> Node {
    return {kind: kind, field: syntax.FieldNone, token: -1, start: -1, end: -1, row: 0, column: 0,
            parent: -1, first: -1, last: -1, next: -1, named: named, hidden: false,
            extra: false};
}

// An interior node of `kind`, empty until children are added.
New :: (n: ^(Node[]), kind: int) -> int {
    n.append(NewNode(kind, true));
    return length(n^) - 1;
}

// `child` becomes the newest child of `parent`, under `field` (FieldNone for none).
// The parent's range covers its children, zero-width terminators included.
Add :: (n: ^(Node[]), parent: int, child: int, field: int) {
    n^[child].parent = parent;
    n^[child].field = field;
    if (n^[parent].last < 0) {
        n^[parent].first = child;
        n^[parent].start = n^[child].start;
        n^[parent].row = n^[child].row;
        n^[parent].column = n^[child].column;
    } else {
        n^[n^[parent].last].next = child;
    }
    n^[parent].last = child;
    n^[parent].end = n^[child].end;
}

// The kind of the token `ahead` places after the current one; EOF past the end.
Peek :: (c: ^Cursor, n: ^(Node[]), ahead: int) -> int {
    at := c.pos + ahead;
    if (at > c.final) {
        at = c.final;
    }
    return n^[at].token;
}

Fail :: (c: ^Cursor, n: ^(Node[]), message: string) {
    if (!c.failed) {
        c.failed = true;
        c.message = message;
        c.at = n^[c.pos].start;
        c.stop = n^[c.pos].end;
        c.row = n^[c.pos].row;
        c.column = n^[c.pos].column;
    }
    c.pos = c.final;
    c.token = n^[c.final].token;
}

// Behaviors, components, systems and queries are archived (archive/README.md).
// The parser names the form it found and stops.
Archived :: (c: ^Cursor, n: ^(Node[]), form: string) {
    Fail(c, n, format_text("{} are archived: behaviors, components, systems and queries have left the language",
                           form));
}

// Moves the current token under `parent`, keeping its own kind.
Take :: (c: ^Cursor, n: ^(Node[]), parent: int, field: int) -> int {
    at := c.pos;
    if (at < c.final) {
        c.pos += 1;
        c.token = n^[c.pos].token;
    }
    if (parent >= 0) {
        Add(n, parent, at, field);
    }
    return at;
}

// Takes the current token if it has `token` kind, else fails.
Expect :: (c: ^Cursor, n: ^(Node[]), parent: int, token: int, field: int) -> int {
    if (c.token != token) {
        Fail(c, n, format_text("{}{}", Expected(c, n, Describe(token)), Opener(c, n, token)));
        return -1;
    }
    return Take(c, n, parent, field);
}

// Takes the current token if it has `token` kind and says whether it did.
Accept :: (c: ^Cursor, n: ^(Node[]), parent: int, token: int, field: int) -> bool {
    if (c.token != token) {
        return false;
    }
    Take(c, n, parent, field);
    return true;
}

// Takes the current token as an identifier, which a contextual word may be.
TakeName :: (c: ^Cursor, n: ^(Node[]), parent: int, field: int) -> int {
    if (!IsName(c.token)) {
        Fail(c, n, Expected(c, n, "a name"));
        return -1;
    }
    at := Take(c, n, parent, field);
    n^[at].kind = syntax.Identifier;
    n^[at].named = true;
    return at;
}

// Takes the current token as an identifier after a dot: any word will do.
TakeMember :: (c: ^Cursor, n: ^(Node[]), parent: int, field: int) -> int {
    if (!IsMember(c.token)) {
        Fail(c, n, Expected(c, n, "a member name"));
        return -1;
    }
    at := Take(c, n, parent, field);
    n^[at].kind = syntax.Identifier;
    n^[at].named = true;
    return at;
}

// The words that can still name things: Tree-sitter's contextual keywords.
IsName :: (token: int) -> bool {
    return token == tk.Ident || token == tk.Package || token == tk.Import || token == tk.Struct ||
           token == tk.From || token == tk.Split || token == tk.Component ||
           token == tk.NotKeyword || token == tk.Unordered;
}

IsMember :: (token: int) -> bool {
    return token == tk.Ident || (token >= tk.Package && token <= tk.Emit);
}

// Whether the current token is the word `word`, as `view` or `self` are.
IsWord :: (c: ^Cursor, n: ^(Node[]), word: string) -> bool {
    return IsWordAt(c, n, c.pos, word);
}

IsWordAt :: (c: ^Cursor, n: ^(Node[]), at: int, word: string) -> bool {
    return n^[at].token == tk.Ident && n^[at].end - n^[at].start == text_byte_length(word) &&
           Spells(c.text, n^[at].start, word);
}

Spells :: (text: string, start: int, word: string) -> bool {
    index: int = 0;
    while (index < text_byte_length(word)) {
        if (text_byte_at(text, start + index) != text_byte_at(word, index)) {
            return false;
        }
        index += 1;
    }
    return true;
}

// The automatic or written terminator that ends a declaration or statement.
End :: (c: ^Cursor, n: ^(Node[]), parent: int) {
    if (c.token != tk.Semicolon) {
        Fail(c, n, Expected(c, n, "the end of the statement"));
        return;
    }
    Take(c, n, parent, syntax.FieldNone);
}

// The tokens' leaf rows. Comments are not leaves of the tree under
// construction; the tree takes them afterwards.
Leaf :: (kind: int, token: int, start: int, end: int, row: int, column: int) -> Node {
    return {kind: kind, field: syntax.FieldNone, token: token, start: start, end: end, row: row, column: column,
            parent: -1, first: -1, last: -1, next: -1,
            named: token == tk.Ident || token == tk.Integer || token == tk.Float ||
                   token == tk.String || token == tk.Char,
            hidden: token == tk.Semicolon && start == end, extra: false};
}

// A kind as the grammar spells it: a token's text, or a node's type.
pub KindName :: (kind: int) -> string {
    if (kind < syntax.Comment) {
        return tk.KindNames()[kind];
    }
    return syntax.KindNames()[kind - syntax.Comment];
}

// A leaf's kind: a named token's node kind, or an anonymous token's own kind.
LeafKind :: (token: int) -> int {
    if (token == tk.Ident) {
        return syntax.Identifier;
    }
    if (token == tk.Integer || token == tk.Float) {
        return syntax.Number;
    }
    if (token == tk.String) {
        return syntax.String;
    }
    if (token == tk.Char) {
        return syntax.Character;
    }
    if (token == tk.Comment) {
        return syntax.Comment;
    }
    return token;
}

// "Expected X, found Y": what the grammar needed, and the text it met instead.
Expected :: (c: ^Cursor, n: ^(Node[]), wanted: string) -> string {
    return format_text("Expected {}, found {}", wanted, Found(c, n));
}

Found :: (c: ^Cursor, n: ^(Node[])) -> string {
    at := c.pos;
    if (n^[at].token == tk.EOF) {
        return "the end of the file";
    }
    if (n^[at].hidden) {
        return "a new statement";
    }
    return format_text("`{}`", Slice(c.text, n^[at].start, n^[at].end));
}

Slice :: (text: string, start: int, end: int) -> string {
    return text_slice(text, start, end - start);
}

// A token kind as the grammar names it.
Describe :: (token: int) -> string {
    if (token == tk.Ident) {
        return "a name";
    }
    if (token == tk.Integer || token == tk.Float) {
        return "a number";
    }
    if (token == tk.String) {
        return "a string";
    }
    if (token == tk.Semicolon) {
        return "the end of the statement";
    }
    return format_text("`{}`", tk.KindNames()[token]);
}

// For a missing closing bracket, where its opening bracket is: " (to close the
// `(` at 4:10)"; nothing for any other token.
Opener :: (c: ^Cursor, n: ^(Node[]), closing: int) -> string {
    opening: int = -1;
    if (closing == tk.CloseParen) {
        opening = tk.OpenParen;
    } else if (closing == tk.CloseBracket) {
        opening = tk.OpenBracket;
    } else if (closing == tk.CloseBrace) {
        opening = tk.OpenBrace;
    }
    if (opening < 0) {
        return "";
    }
    depth: int = 0;
    at := c.pos - 1;
    while (at >= 0) {
        if (n^[at].token == closing) {
            depth += 1;
        } else if (n^[at].token == opening) {
            if (depth == 0) {
                return format_text(" (to close the `{}` at {}:{})", tk.KindNames()[opening],
                                   n^[at].row + 1, n^[at].column + 1);
            }
            depth -= 1;
        }
        at -= 1;
    }
    return "";
}
package source_parser

import tk "project:source_tokenizer"
import syntax "project:syntax_diagnostics"

// type: a single type or a union of them. A union is a `type` holding one
// `union_type`, whose members are `type` nodes.
ParseType :: (c: ^Cursor, n: ^(Node[])) -> int {
    first := ParseSingleType(c, n);
    if (c.token != tk.Or) {
        return first;
    }
    joined := New(n, syntax.UnionType);
    Add(n, joined, first, syntax.FieldMember);
    while (!c.failed && c.token == tk.Or) {
        Take(c, n, joined, syntax.FieldNone);
        Add(n, joined, ParseSingleType(c, n), syntax.FieldMember);
    }
    outer := New(n, syntax.Type);
    Add(n, outer, joined, syntax.FieldNone);
    return outer;
}

// Traits, one primary, then `[]` and `?` suffixes, all children of one `type`.
ParseSingleType :: (c: ^Cursor, n: ^(Node[])) -> int {
    t := New(n, syntax.Type);
    while (!c.failed && IsTrait(c, n)) {
        if (c.token == tk.Wildcard) {
            Take(c, n, t, syntax.FieldTrait);
            Expect(c, n, t, tk.OpenParen, syntax.FieldTrait);
            Expect(c, n, t, tk.Integer, syntax.FieldTrait);
            Expect(c, n, t, tk.CloseParen, syntax.FieldTrait);
        } else {
            word := Take(c, n, t, syntax.FieldTrait);
            // `view` and `self` are words; plain, service and setting keep their token kinds.
            if (IsWordAt(c, n, word, "view")) {
                n^[word].kind = syntax.View;
            } else if (IsWordAt(c, n, word, "self")) {
                n^[word].kind = syntax.Self;
            }
            n^[word].named = false;
        }
    }
    ParseTypePrimary(c, n, t);
    while (!c.failed) {
        if (c.token == tk.OpenBracket && Peek(c, n, 1) == tk.CloseBracket) {
            Take(c, n, t, syntax.FieldNone);
            Take(c, n, t, syntax.FieldNone);
        } else if (c.token == tk.Question) {
            Take(c, n, t, syntax.FieldNone);
        } else {
            break;
        }
    }
    return t;
}

// A trait word comes before a type: `plain`, `service`, `setting`,
// `wildcard(N)`, `view` and `self` when something that starts a type follows.
IsTrait :: (c: ^Cursor, n: ^(Node[])) -> bool {
    token := c.token;
    if (token == tk.Plain || token == tk.Service || token == tk.Setting || token == tk.Wildcard) {
        return true;
    }
    if (IsWord(c, n, "view") || IsWord(c, n, "self")) {
        return StartsType(Peek(c, n, 1));
    }
    return false;
}

StartsType :: (token: int) -> bool {
    return IsName(token) || token == tk.Xor || token == tk.OpenBracket || token == tk.OpenParen ||
           token == tk.Dollar || token == tk.Plain || token == tk.Service ||
           token == tk.Setting || token == tk.Wildcard;
}

// The primary of a type, added to `t`: a name, a binder, an application, a
// map, a pointer or a parenthesized type.
ParseTypePrimary :: (c: ^Cursor, n: ^(Node[]), t: int) {
    token := c.token;
    if (token == tk.Dollar) {
        binder := New(n, syntax.TypeBinder);
        Take(c, n, binder, syntax.FieldNone);
        TakeName(c, n, binder, syntax.FieldName);
        Add(n, t, binder, syntax.FieldName);
        return;
    }
    if (token == tk.Xor) {
        pointer := New(n, syntax.PointerType);
        Take(c, n, pointer, syntax.FieldNone);
        target := New(n, syntax.Type);
        ParseTypePrimary(c, n, target);
        Add(n, pointer, target, syntax.FieldTarget);
        Add(n, t, pointer, syntax.FieldNone);
        return;
    }
    if (token == tk.OpenBracket) {
        map := New(n, syntax.MapType);
        Take(c, n, map, syntax.FieldNone);
        Add(n, map, ParseType(c, n), syntax.FieldKey);
        Expect(c, n, map, tk.Colon, syntax.FieldNone);
        Add(n, map, ParseType(c, n), syntax.FieldValue);
        Expect(c, n, map, tk.CloseBracket, syntax.FieldNone);
        Add(n, t, map, syntax.FieldMap);
        return;
    }
    if (token == tk.OpenParen) {
        group := New(n, syntax.ParenthesizedType);
        Take(c, n, group, syntax.FieldNone);
        Add(n, group, ParseType(c, n), syntax.FieldType);
        Expect(c, n, group, tk.CloseParen, syntax.FieldNone);
        Add(n, t, group, syntax.FieldNone);
        return;
    }
    if (StartsFn(c, n, c.pos)) {
        Add(n, t, ParseCallableType(c, n), syntax.FieldNone);
        return;
    }
    name := ParseTypeName(c, n);
    if (c.failed) {
        return;
    }
    if (c.token == tk.OpenParen) {
        application := New(n, syntax.TypeApplication);
        Add(n, application, name, syntax.FieldFunction);
        Add(n, application, ParseArguments(c, n), syntax.FieldArguments);
        Add(n, t, application, syntax.FieldNone);
        return;
    }
    Add(n, t, name, syntax.FieldName);
}

// Whether `fn (` starts at token `at`: the word that makes a callable type or
// an inline function. Construct marks the leaf `fn`; reading it as a name
// (TakeName) makes it an identifier again.
StartsFn :: (c: ^Cursor, n: ^(Node[]), at: int) -> bool {
    return n^[at].kind == syntax.Fn && n^[at + 1].token == tk.OpenParen;
}

// `fn (parameters) [-> result]`, a function a parameter takes.
ParseCallableType :: (c: ^Cursor, n: ^(Node[])) -> int {
    callable := New(n, syntax.CallableType);
    word := Take(c, n, callable, syntax.FieldNone);
    n^[word].kind = syntax.Fn;
    n^[word].named = false;
    Add(n, callable, ParseParameters(c, n), syntax.FieldParameters);
    if (Accept(c, n, callable, tk.ArrowRight, syntax.FieldNone)) {
        if (c.token == tk.OpenParen && (Peek(c, n, 1) == tk.CloseParen ||
                                          (IsName(Peek(c, n, 1)) && Peek(c, n, 2) == tk.Colon))) {
            Add(n, callable, ParseParameters(c, n), syntax.FieldResults);
        } else {
            Add(n, callable, ParseType(c, n), syntax.FieldResults);
        }
    }
    return callable;
}

// type_name: a name, then `.name` parts.
ParseTypeName :: (c: ^Cursor, n: ^(Node[])) -> int {
    name := New(n, syntax.TypeName);
    TakeName(c, n, name, syntax.FieldNone);
    while (!c.failed && c.token == tk.Period && IsName(Peek(c, n, 1))) {
        Take(c, n, name, syntax.FieldNone);
        TakeName(c, n, name, syntax.FieldNone);
    }
    return name;
}

// The position after the type that starts at token `at`, or -1 when none does.
// It reads tokens only, so a caller can ask before it commits to a parse.
SkipType :: (n: ^(Node[]), at: int, final: int) -> int {
    at = SkipSingleType(n, at, final);
    while (at >= 0 && n^[at].token == tk.Or) {
        at = SkipSingleType(n, at + 1, final);
    }
    return at;
}

SkipSingleType :: (n: ^(Node[]), at: int, final: int) -> int {
    while (at >= 0 && at < final) {
        token := n^[at].token;
        if (token == tk.Plain || token == tk.Service || token == tk.Setting) {
            at += 1;
        } else if (token == tk.Wildcard) {
            at += 4;
        } else if (token == tk.Ident && (n^[at + 1].token == tk.Ident || n^[at + 1].token == tk.Xor ||
                                         n^[at + 1].token == tk.Dollar)) {
            at += 1;
        } else {
            break;
        }
    }
    return SkipTypeSuffixes(n, SkipTypePrimary(n, at, final), final);
}

SkipTypePrimary :: (n: ^(Node[]), at: int, final: int) -> int {
    if (at < 0 || at >= final) {
        return -1;
    }
    token := n^[at].token;
    if (token == tk.Dollar) {
        if (!IsName(n^[at + 1].token)) {
            return -1;
        }
        return at + 2;
    }
    if (token == tk.Xor) {
        return SkipTypePrimary(n, at + 1, final);
    }
    if (token == tk.OpenBracket) {
        key := SkipType(n, at + 1, final);
        if (key < 0 || n^[key].token != tk.Colon) {
            return -1;
        }
        value := SkipType(n, key + 1, final);
        if (value < 0 || n^[value].token != tk.CloseBracket) {
            return -1;
        }
        return value + 1;
    }
    if (n^[at].kind == syntax.Fn && n^[at + 1].token == tk.OpenParen) {
        return SkipCallableType(n, at + 1, final);
    }
    if (token == tk.OpenParen) {
        inner := SkipType(n, at + 1, final);
        if (inner < 0 || n^[inner].token != tk.CloseParen) {
            return -1;
        }
        return inner + 1;
    }
    if (!IsName(token)) {
        return -1;
    }
    at += 1;
    while (at + 1 < final && n^[at].token == tk.Period && IsName(n^[at + 1].token)) {
        at += 2;
    }
    if (n^[at].token == tk.OpenParen) {
        return SkipBrackets(n, at, final);
    }
    return at;
}

// The position after `fn (parameters) [-> result]` whose `(` is at `at`.
SkipCallableType :: (n: ^(Node[]), at: int, final: int) -> int {
    end := SkipBrackets(n, at, final);
    if (end < 0 || n^[end].token != tk.ArrowRight) {
        return end;
    }
    if (n^[end + 1].token == tk.OpenParen) {
        return SkipBrackets(n, end + 1, final);
    }
    return SkipType(n, end + 1, final);
}

SkipTypeSuffixes :: (n: ^(Node[]), at: int, final: int) -> int {
    while (at >= 0 && at < final) {
        if (n^[at].token == tk.OpenBracket && n^[at + 1].token == tk.CloseBracket) {
            at += 2;
        } else if (n^[at].token == tk.Question) {
            at += 1;
        } else {
            break;
        }
    }
    return at;
}

// The position after the bracket group that opens at `at`, or -1.
SkipBrackets :: (n: ^(Node[]), at: int, final: int) -> int {
    depth: int = 0;
    while (at < final) {
        token := n^[at].token;
        if (token == tk.OpenParen || token == tk.OpenBracket || token == tk.OpenBrace) {
            depth += 1;
        } else if (token == tk.CloseParen || token == tk.CloseBracket || token == tk.CloseBrace) {
            depth -= 1;
            if (depth == 0) {
                return at + 1;
            }
        }
        at += 1;
    }
    return -1;
}

// A unit: terms with optional `^N` powers, joined by `/`.
ParseUnit :: (c: ^Cursor, n: ^(Node[])) -> int {
    unit := New(n, syntax.Unit);
    ParseUnitTerm(c, n, unit);
    while (!c.failed && c.token == tk.Quo) {
        Take(c, n, unit, syntax.FieldNone);
        ParseUnitTerm(c, n, unit);
    }
    return unit;
}

ParseUnitTerm :: (c: ^Cursor, n: ^(Node[]), unit: int) {
    Expect(c, n, unit, tk.Ident, syntax.FieldNone);
    if (Accept(c, n, unit, tk.Xor, syntax.FieldNone)) {
        Expect(c, n, unit, tk.Integer, syntax.FieldNone);
    }
}

// Whether a unit alone starts here: `m/s` or `m^2`.
StartsUnit :: (c: ^Cursor, n: ^(Node[])) -> bool {
    return c.token == tk.Ident && (Peek(c, n, 1) == tk.Xor || Peek(c, n, 1) == tk.Quo);
}

// A type, a type measured in a unit, or a unit alone.
ParseSignatureType :: (c: ^Cursor, n: ^(Node[])) -> int {
    if (StartsUnit(c, n)) {
        return ParseUnit(c, n);
    }
    base := ParseType(c, n);
    if (c.failed || c.token != tk.Ident) {
        return base;
    }
    measured := New(n, syntax.MeasuredType);
    Add(n, measured, base, syntax.FieldBase);
    Add(n, measured, ParseUnit(c, n), syntax.FieldUnit);
    return measured;
}


