pub Module :: union {
    Tables(id: u64, owner_type: u64, abi: u64, pointer_size: int, wide: u64[], values: Value[], ints: int[],
           requirements: Requirement[], fields: Field[], event_declarations: Event[],
           event_fields: EventField[], imports: Import[], functions: Function[], spans: Span[], roots: Root[],
           instructions: Instruction[], locals: Local[], parameters: Parameter[], frames: Frame[],
           sources: Source[], results: ResultLayout[], data: Data[], hosts: Host[], commands: Command[], calls: Call[],
           references: Reference[], components: Component[], points: Point[], watches: Watch[],
           states: State[], entries: Entry[], queries: Query[], query_root: int, query_variable_count: int,
           query_filter: int, descriptions: QueryDescription[], system_description: int)
}

// A 64-bit word as a varint: seven bits at a time from the low end, the high
// bit marking that more follow.
Varint :: (out: ^(u8[]), word: u64) {
    rest := word;
    while ((rest >> 7) != 0) {
        out.append(u8(wrap: rest | 128));
        rest = rest >> 7;
    }
    out.append(u8(wrap: rest));
}
// An int as the varint of its zigzag word, which keeps small negative values,
// such as -1 for none, one byte long.
Int :: (out: ^(u8[]), value: int) {
    wide := i64(value);
    rest := u64(wrap: wide << 1) ^ u64(wrap: wide >> 63);
    while ((rest >> 7) != 0) {
        out.append(u8(wrap: rest | 128));
        rest = rest >> 7;
    }
    out.append(u8(wrap: rest));
}
// values[first, first + count), each as an Int.
Ints :: (out: ^(u8[]), values: int[], first: int, count: int) {
    index := first;
    while (index < first + count) {
        Int(out, values[index]);
        index += 1;
    }
}
// A bool as the varint 0 or 1.
Flag :: (out: ^(u8[]), value: bool) {
    if (value) {
        out.append(u8(1));
        return;
    }
    out.append(u8(0));
}
// `count` zero varints, the encoding of absent fields.
Zeros :: (out: ^(u8[]), count: int) {
    index: int = 0;
    while (index < count) {
        out.append(u8(0));
        index += 1;
    }
}
// The bytes of a string.
Raw :: (out: ^(u8[]), value: string) {
    for (code in strings.Bytes(value)) {
        out.append(u8(wrap: code));
    }
}
// Eight bytes, low byte first.
Fixed64 :: (out: ^(u8[]), value: u64) {
    index: int = 0;
    rest := value;
    while (index < 8) {
        out.append(u8(wrap: rest));
        rest = rest >> 8;
        index += 1;
    }
}
// The slot an open-addressed table of mask + 1 slots starts probing for
// `value` at: FNV-1a over its bytes.
Slot :: (value: string, mask: int) -> int {
    hash: u64 = 14695981039346656037;
    for (code in strings.Bytes(value)) {
        hash = (hash ^ u64(code)) * 1099511628211;
    }
    return int(hash & u64(mask));
}
// A power of two of at least twice `count` slots, which keeps probes short.
SlotCount :: (count: int) -> int {
    size: int = 1;
    while (size < 2 * count) {
        size = size * 2;
    }
    return size;
}
// The string table: each string of `texts` once, in order of first use.
Table :: (texts: string[]) -> string[] {
    mask := SlotCount(length(texts)) - 1;
    slots := resize([int(0)], mask + 1);
    found: string[] = [];
    for (value in texts) {
        at := Slot(value, mask);
        while (slots[at] != 0 && found[slots[at] - 1] != value) {
            at = (at + 1) & mask;
        }
        if (slots[at] == 0) {
            found.append(value);
            slots[at] = length(found);
        }
    }
    return found;
}
// Slots holding the 1-based index of each string of the table.
TableSlots :: (items: string[]) -> int[] {
    mask := SlotCount(length(items)) - 1;
    slots := resize([int(0)], mask + 1);
    index: int = 0;
    while (index < length(items)) {
        at := Slot(items[index], mask);
        while (slots[at] != 0) {
            at = (at + 1) & mask;
        }
        slots[at] = index + 1;
        index += 1;
    }
    return slots;
}
// The table's count, then each string's byte length plus one and its bytes.
TableBytes :: (out: ^(u8[]), items: string[]) {
    Int(out, length(items));
    for (item in items) {
        Varint(out, u64(strings.ByteLength(item) + 1));
        Raw(out, item);
    }
}
// The 1-based index of `value` in the table, which holds it.
TextIndex :: (value: string, items: string[], slots: int[]) -> int {
    mask := length(slots) - 1;
    at := Slot(value, mask);
    while (items[slots[at] - 1] != value) {
        at = (at + 1) & mask;
    }
    return slots[at];
}
// Absent text is 0; otherwise its table index.
Text :: (out: ^(u8[]), value: string, present: bool, items: string[], slots: int[]) {
    if (!present) {
        out.append(u8(0));
        return;
    }
    Varint(out, u64(TextIndex(value, items, slots)));
}
// A value's own bytes; its nested values follow them. `bits` is its wide entry.
ValueHead :: (out: ^(u8[]), v: Value, bits: u64, items: string[], slots: int[]) {
    Int(out, v.tag);
    Int(out, v.container);
    Text(out, v.type_name, v.has_type_name, items, slots);
    Flag(out, v.authored);
    if (v.container != 0) {
        Flag(out, v.present);
        if (v.present) {
            Int(out, v.count);
        }
        return;
    }
    if (v.tag == StructTag) {
        Varint(out, bits);
        Flag(out, v.present);
        Int(out, v.count);
        return;
    }
    if (v.tag == UnionTag) {
        Flag(out, v.present);
        if (v.present) {
            Varint(out, bits);
            Int(out, v.count);
        }
        return;
    }
    if (v.tag == TextTag) {
        Varint(out, u64(strings.ByteLength(v.text)));
        Raw(out, v.text);
        return;
    }
    if (v.tag == NameTag) {
        Text(out, v.text, v.has_text, items, slots);
        return;
    }
    Varint(out, bits);
}
// A source; `asset` is its asset's table index, 0 for none.
SourceBytes :: (out: ^(u8[]), v: Source, wide: u64[], asset: int) {
    Varint(out, wide[v.graph]);
    Varint(out, wide[v.call]);
    Int(out, v.parent);
    Varint(out, u64(asset));
    Int(out, v.start);
    Int(out, v.end);
    Int(out, v.line);
    Int(out, v.column);
}
ReferenceBytes :: (out: ^(u8[]), v: Reference, wide: u64[]) {
    Int(out, v.imported);
    Int(out, v.own);
    Varint(out, wide[v.function]);
    Int(out, v.role);
}
PointBytes :: (out: ^(u8[]), v: Point, wide: u64[]) {
    Varint(out, wide[v.occurrence]);
    Varint(out, wide[v.meaning]);
    Int(out, v.start);
    Int(out, v.end);
    Int(out, v.line);
    Int(out, v.column);
    Int(out, v.kind);
    Flag(out, v.completion);
}
// An instruction's fields that mostly hold their default follow a mask of the
// ones that differ from it, in this bit order, as prepared_function.c reads
// them. A value is default when it encodes as five zero bytes: a single flow
// value without a name. Bits 16 to 256 and 1024 (frame, stack, pin, indirect,
// component, layout) are never set.
InstructionRight: int : 1;
InstructionTarget: int : 2;
InstructionOffset: int : 4;
InstructionValue: int : 8;
InstructionNode: int : 512;
InstructionMessage: int : 2048;
// An instruction with its value, layout and message.
InstructionBytes :: (out: ^(u8[]), v: Instruction, wide: u64[], pool: u8[], starts: int[], sizes: int[],
                     items: string[], slots: int[]) {
    Int(out, v.op);
    Int(out, v.type);
    Int(out, v.output);
    Int(out, v.left);
    Int(out, v.source);
    value := starts[v.value];
    empty := sizes[v.value] == 5 && pool[value] == 0 && pool[value + 1] == 0 && pool[value + 2] == 0 &&
             pool[value + 3] == 0 && pool[value + 4] == 0;
    fields: int = 0;
    if (v.right != 0) {
        fields = fields | InstructionRight;
    }
    if (v.target != 0) {
        fields = fields | InstructionTarget;
    }
    if (v.offset != 0) {
        fields = fields | InstructionOffset;
    }
    if (!empty) {
        fields = fields | InstructionValue;
    }
    if (wide[v.node] != 0) {
        fields = fields | InstructionNode;
    }
    if (v.has_message) {
        fields = fields | InstructionMessage;
    }
    Varint(out, u64(fields));
    if ((fields & InstructionRight) != 0) {
        Int(out, v.right);
    }
    if ((fields & InstructionTarget) != 0) {
        Int(out, v.target);
    }
    if ((fields & InstructionOffset) != 0) {
        Varint(out, u64(v.offset));
    }
    if ((fields & InstructionValue) != 0) {
        out.extend(slice(pool, value, sizes[v.value]));
    }
    if ((fields & InstructionNode) != 0) {
        Varint(out, wide[v.node]);
    }
    if ((fields & InstructionMessage) != 0) {
        Text(out, v.message, true, items, slots);
    }
}
LocalBytes :: (out: ^(u8[]), v: Local, wide: u64[], pool: u8[], starts: int[], sizes: int[]) {
    Int(out, v.kind);
    out.extend(slice(pool, starts[v.initial], sizes[v.initial]));
    Int(out, v.frame);
    Varint(out, wide[v.node]);
    Int(out, v.pin);
    Varint(out, u64(v.offset));
    Flag(out, v.parameter);
    Flag(out, v.array_default);
    Int(out, v.data_index);
}
HostBytes :: (out: ^(u8[]), v: Host, wide: u64[]) {
    Varint(out, wide[v.capability]);
    Varint(out, wide[v.abi]);
    Int(out, v.first);
    Int(out, v.result_first);
    Int(out, v.result_count);
    Flag(out, v.owned_arguments);
    Int(out, v.outcome_count);
    index := v.outcome_first;
    while (index < v.outcome_first + v.outcome_count) {
        Varint(out, wide[index]);
        index += 1;
    }
}
CallBytes :: (out: ^(u8[]), v: Call, target: Reference, wide: u64[]) {
    ReferenceBytes(out, target, wide);
    Int(out, v.first);
    Int(out, v.count);
    Int(out, v.result_first);
    Int(out, v.result_count);
    Flag(out, v.task);
    Flag(out, v.owned_arguments);
}
FunctionHead :: (out: ^(u8[]), v: Function) {
    Int(out, v.argument_count);
    Int(out, v.result_count);
    Int(out, v.variable_count);
    Varint(out, u64(v.root_steps));
    Varint(out, u64(v.child_budget));
    Varint(out, u64(v.depth_bound));
    Varint(out, u64(v.pure_depth_limit));
    Flag(out, v.breakpoints);
    Flag(out, v.batchable);
    Flag(out, v.managed);
    Flag(out, v.custom_lowering);
    Flag(out, v.checkpoints);
    Flag(out, v.pin_watches);
    Varint(out, u64(v.watch_size));
    Flag(out, v.component_bindings);
    Flag(out, v.component_access);
}
// An entry before its body and subscription references.
EntryHead :: (out: ^(u8[]), v: Entry, wide: u64[], items: string[], slots: int[]) {
    // Event, event ABI, the observer's component, layout, field and offset,
    // then its type: a zero flow value with no container, type name, author
    // or bits, as an empty observer type is written.
    Varint(out, wide[v.id]);
    Varint(out, wide[v.event_id]);
    Varint(out, wide[v.event_abi]);
    Zeros(out, 4);
    Int(out, FlowTag);
    Zeros(out, 4);
    // The observer's argument, action, parent and outcome, then no captures.
    Zeros(out, 6);
    Flag(out, v.continuation_wait);
    Int(out, v.kind);
    Text(out, v.entry_name, v.has_entry, items, slots);
    Text(out, v.event_name, v.has_event_name, items, slots);
    Varint(out, wide[v.effects]);
}
// An event declaration with its payload fields.
EventBytes :: (out: ^(u8[]), v: Event, fields: EventField[], wide: u64[], pool: u8[], starts: int[],
               sizes: int[], items: string[], slots: int[]) {
    Varint(out, wide[v.id]);
    Varint(out, wide[v.abi]);
    Text(out, v.name, true, items, slots);
    Int(out, v.count);
    index := v.first;
    while (index < v.first + v.count) {
        field := fields[index];
        Text(out, field.name, true, items, slots);
        Varint(out, wide[field.nominal]);
        Flag(out, field.has_default);
        Flag(out, field.default_owner);
        out.extend(slice(pool, starts[field.initial], sizes[field.initial]));
        index += 1;
    }
}

// What Write writes: which values, and its metadata strings in the order it
// writes them, a run of sources of one asset naming it once.
Gathered :: union {
    Of(texts: string[], used: bool[])
}
Gather :: (module: Module) -> Gathered {
    switch module {
        case .Tables(id, owner_type, abi, pointer_size, wide, values, ints, requirements, fields, event_declarations,
                     event_fields, imports, functions, spans, roots, instructions, locals, parameters, frames,
                     sources, results, data, hosts, commands, calls, references, components, points, watches, states,
                     entries, queries, query_root, query_variable_count, query_filter, descriptions, system_description):
            // Each step is a value Write writes, or -1 - n for named[n].
            named: string[] = [];
            steps: int[] = [];
            for (requirement in requirements) {
                named.append(requirement.name);
                steps.append(-length(named));
                index := requirement.first;
                while (requirement.authored && index < requirement.first + requirement.count) {
                    field := fields[index];
                    named.append(field.name);
                    steps.append(-length(named));
                    if (field.has_type_name) {
                        named.append(field.type_name);
                        steps.append(-length(named));
                    }
                    if (field.has_unit) {
                        named.append(field.unit);
                        steps.append(-length(named));
                    }
                    index += 1;
                }
            }
            for (declared in event_declarations) {
                named.append(declared.name);
                steps.append(-length(named));
                index := declared.first;
                while (index < declared.first + declared.count) {
                    named.append(event_fields[index].name);
                    steps.append(-length(named));
                    steps.append(event_fields[index].initial);
                    index += 1;
                }
            }
            asset := "";
            known := false;
            for (function in functions) {
                table: int = 0;
                while (table < Tables) {
                    span := spans[function.spans + table];
                    item := span.first;
                    last := span.first + span.count;
                    if (table == ArgumentDefaults || table == ResultDefaults || table == VariableDefaults ||
                        table == CommandArguments || table == CommandResults) {
                        while (item < last) {
                            steps.append(item);
                            item += 1;
                        }
                    } else if (table == Roots) {
                        while (item < last) {
                            steps.append(roots[item].shape);
                            item += 1;
                        }
                    } else if (table == Instructions) {
                        while (item < last) {
                            steps.append(instructions[item].value);
                            if (instructions[item].has_message) {
                                named.append(instructions[item].message);
                                steps.append(-length(named));
                            }
                            item += 1;
                        }
                    } else if (table == Locals) {
                        while (item < last) {
                            steps.append(locals[item].initial);
                            item += 1;
                        }
                    } else if (table == Parameters) {
                        while (item < last) {
                            steps.append(parameters[item].initial);
                            item += 1;
                        }
                    } else if (table == Frames || table == Sources || table == Stacks) {
                        while (item < last) {
                            row := item;
                            if (table == Frames) {
                                row = frames[item].source;
                            }
                            source := sources[row];
                            if (source.has_asset && (!known || source.asset != asset)) {
                                asset = source.asset;
                                known = true;
                                named.append(asset);
                                steps.append(-length(named));
                            }
                            item += 1;
                        }
                    } else if (table == Results) {
                        while (item < last) {
                            named.append(results[item].name);
                            steps.append(-length(named));
                            item += 1;
                        }
                    } else if (table == DataValues) {
                        while (item < last) {
                            steps.append(data[item].initial);
                            item += 1;
                        }
                    } else if (table == SourceWatches) {
                        while (item < last) {
                            steps.append(watches[item].initial);
                            item += 1;
                        }
                    }
                    table += 1;
                }
            }
            for (retained in states) {
                steps.append(retained.initial);
            }
            for (item in entries) {
                if (item.has_entry) {
                    named.append(item.entry_name);
                    steps.append(-length(named));
                }
                if (item.has_event_name) {
                    named.append(item.event_name);
                    steps.append(-length(named));
                }
            }
            for (description in descriptions) {
                steps.append(description.row_type);
            }
            // A value writes its own strings, then those of its nested values
            // in order, so a stack walks each written value in that order.
            texts: string[] = [];
            used := resize([false], length(values));
            stack: int[] = [];
            for (step in steps) {
                if (step < 0) {
                    texts.append(named[-1 - step]);
                    continue;
                }
                if (length(stack) == 0) {
                    stack.append(step);
                }
                stack[0] = step;
                top: int = 1;
                while (top > 0) {
                    top -= 1;
                    v := values[stack[top]];
                    used[stack[top]] = true;
                    if (v.has_type_name) {
                        texts.append(v.type_name);
                    }
                    if (v.container == 0 && v.tag == NameTag && v.has_text) {
                        texts.append(v.text);
                    }
                    nested := v.first + v.count - 1;
                    aggregate := v.container != 0 || v.tag == StructTag || v.tag == UnionTag;
                    while (aggregate && v.present && nested >= v.first) {
                        if (top < length(stack)) {
                            stack[top] = nested;
                        } else {
                            stack.append(nested);
                        }
                        top += 1;
                        nested -= 1;
                    }
                }
            }
            return Gathered.Of(texts, used);
    }
}

// The complete inner module.
pub Write :: (module: Module) -> u8[] {
    bytes: u8[] = [];
    switch Gather(module) {
        case .Of(texts, used):
            WriteTables(&bytes, module, Table(texts), used);
    }
    return bytes;
}
WriteTables :: (out: ^(u8[]), module: Module, items: string[], used: bool[]) {
    slots := TableSlots(items);
    switch module {
        case .Tables(id, owner_type, abi, pointer_size, wide, values, ints, requirements, fields, event_declarations,
                     event_fields, imports, functions, spans, roots, instructions, locals, parameters, frames,
                     sources, results, data, hosts, commands, calls, references, components, points, watches, states,
                     entries, queries, query_root, query_variable_count, query_filter, descriptions, system_description):
            // A value's bytes are its own, then those of the values nested in
            // it. Nested values follow their parent, so encoding from the last
            // value back finds every nested value already in the pool.
            pool: u8[] = [];
            starts := resize([int(0)], length(values));
            sizes := resize([int(0)], length(values));
            at := length(values) - 1;
            while (at >= 0) {
                if (used[at]) {
                    start := length(pool);
                    v := values[at];
                    ValueHead(&pool, v, wide[v.wide], items, slots);
                    if ((v.container != 0 || v.tag == StructTag || v.tag == UnionTag) && v.present) {
                        nested := v.first;
                        while (nested < v.first + v.count) {
                            pool.extend(slice(pool, starts[nested], sizes[nested]));
                            nested += 1;
                        }
                    }
                    starts[at] = start;
                    sizes[at] = length(pool) - start;
                }
                at -= 1;
            }

            Varint(out, Magic);
            Varint(out, u64(Version));
            Varint(out, u64(pointer_size));
            Varint(out, abi);
            Varint(out, id);
            Varint(out, owner_type);
            Int(out, length(requirements));
            for (requirement in requirements) {
                Varint(out, wide[requirement.id]);
                Varint(out, wide[requirement.layout]);
                Int(out, requirement.storage);
                Text(out, requirement.name, true, items, slots);
                Varint(out, u64(requirement.size));
                Flag(out, requirement.authored);
                if (requirement.authored) {
                    Int(out, requirement.count);
                    index: int = 0;
                    while (index < requirement.count) {
                        field := fields[requirement.first + index];
                        Text(out, field.name, true, items, slots);
                        Int(out, field.kind);
                        Text(out, field.type_name, field.has_type_name, items, slots);
                        Text(out, field.unit, field.has_unit, items, slots);
                        Flag(out, field.kind == TextTag && field.container == 0);
                        Int(out, field.container);
                        Int(out, field.record);
                        index += 1;
                    }
                }
            }
            Int(out, length(event_declarations));
            for (declared in event_declarations) {
                EventBytes(out, declared, event_fields, wide, pool, starts, sizes, items, slots);
            }
            Int(out, length(imports));
            for (imported in imports) {
                Varint(out, wide[imported.id]);
                Varint(out, wide[imported.fingerprint]);
            }

            // Consecutive sources and frames of one asset look its text up once;
            // asset_index is 0 until the first.
            asset := "";
            asset_index: int = 0;
            Int(out, length(functions));
            for (function in functions) {
                FunctionHead(out, function);
                table: int = 0;
                while (table < Tables) {
                    span := spans[function.spans + table];
                    Int(out, span.count);
                    item := span.first;
                    last := span.first + span.count;
                    if (table == ArgumentDefaults || table == ResultDefaults || table == VariableDefaults ||
                        table == CommandArguments || table == CommandResults) {
                        while (item < last) {
                            out.extend(slice(pool, starts[item], sizes[item]));
                            item += 1;
                        }
                    } else if (table == ArgumentKinds || table == ResultKinds || table == Slots ||
                               table == SlotKinds || table == CommandArgumentKinds || table == CommandResultKinds) {
                        Ints(out, ints, span.first, span.count);
                    } else if (table == Roots) {
                        while (item < last) {
                            Int(out, roots[item].bank);
                            Int(out, roots[item].index);
                            out.extend(slice(pool, starts[roots[item].shape], sizes[roots[item].shape]));
                            item += 1;
                        }
                    } else if (table == Instructions) {
                        while (item < last) {
                            InstructionBytes(out, instructions[item], wide, pool, starts, sizes, items, slots);
                            item += 1;
                        }
                    } else if (table == Locals) {
                        while (item < last) {
                            LocalBytes(out, locals[item], wide, pool, starts, sizes);
                            item += 1;
                        }
                    } else if (table == Parameters) {
                        while (item < last) {
                            initial := parameters[item].initial;
                            out.extend(slice(pool, starts[initial], sizes[initial]));
                            Int(out, parameters[item].frame);
                            Int(out, parameters[item].pin);
                            item += 1;
                        }
                    } else if (table == Frames || table == Sources || table == Stacks) {
                        while (item < last) {
                            row := item;
                            if (table == Frames) {
                                row = frames[item].source;
                            }
                            source := sources[row];
                            if (source.has_asset && (asset_index == 0 || source.asset != asset)) {
                                asset = source.asset;
                                asset_index = TextIndex(asset, items, slots);
                            }
                            if (source.has_asset) {
                                SourceBytes(out, source, wide, asset_index);
                            } else {
                                SourceBytes(out, source, wide, 0);
                            }
                            if (table == Frames) {
                                frame := frames[item];
                                Int(out, frame.depth);
                                Int(out, frame.resume);
                                Int(out, frame.source_index);
                                Int(out, frame.stack);
                            }
                            item += 1;
                        }
                    } else if (table == Results) {
                        while (item < last) {
                            Int(out, results[item].index);
                            Text(out, results[item].name, true, items, slots);
                            item += 1;
                        }
                    } else if (table == DataValues) {
                        while (item < last) {
                            Int(out, data[item].kind);
                            out.extend(slice(pool, starts[data[item].initial], sizes[data[item].initial]));
                            Varint(out, u64(data[item].size));
                            item += 1;
                        }
                    } else if (table == Hosts) {
                        while (item < last) {
                            HostBytes(out, hosts[item], wide);
                            item += 1;
                        }
                        // No query rows. Commands and their banks follow separately.
                        Zeros(out, 1);
                    } else if (table == Commands) {
                        // Capability, ABI, two absent fields and no text; then the
                        // argument range, node, an absent field, the result range
                        // and a last absent field.
                        while (item < last) {
                            command := commands[item];
                            Varint(out, wide[command.capability]);
                            Varint(out, wide[command.abi]);
                            Zeros(out, 3);
                            Int(out, command.first);
                            Int(out, command.count);
                            Varint(out, wide[command.node]);
                            Zeros(out, 1);
                            Int(out, command.result_first);
                            Int(out, command.result_count);
                            Zeros(out, 1);
                            item += 1;
                        }
                    } else if (table == Calls) {
                        while (item < last) {
                            CallBytes(out, calls[item], references[calls[item].function], wide);
                            item += 1;
                        }
                    } else if (table == Definitions) {
                        while (item < last) {
                            ReferenceBytes(out, references[ints[item]], wide);
                            item += 1;
                        }
                    } else if (table == Components) {
                        while (item < last) {
                            Varint(out, wide[components[item].id]);
                            Flag(out, components[item].binding);
                            item += 1;
                        }
                    } else if (table == ComponentWrites) {
                        while (item < last) {
                            Varint(out, wide[ints[item]]);
                            item += 1;
                        }
                        // No state selections follow component writes.
                        Zeros(out, 1);
                    } else if (table == SourcePoints) {
                        while (item < last) {
                            PointBytes(out, points[item], wide);
                            item += 1;
                        }
                    } else {
                        while (item < last) {
                            watch := watches[item];
                            PointBytes(out, points[watch.origin], wide);
                            out.extend(slice(pool, starts[watch.initial], sizes[watch.initial]));
                            Int(out, watch.ordinal);
                            Flag(out, watch.output);
                            Flag(out, watch.reference);
                            item += 1;
                        }
                    }
                    table += 1;
                }
                // Points, watches and edges are debugger tables this module has none of.
                Zeros(out, 3);
            }

            Int(out, length(states));
            for (retained in states) {
                Varint(out, wide[retained.id]);
                out.extend(slice(pool, starts[retained.initial], sizes[retained.initial]));
                Flag(out, retained.shared);
                Flag(out, retained.contains_tasks);
            }
            Int(out, length(entries));
            for (item in entries) {
                EntryHead(out, item, wide, items, slots);
                ReferenceBytes(out, references[item.body], wide);
                ReferenceBytes(out, references[item.subscription], wide);
            }
            Int(out, length(queries));
            for (term in queries) {
                Int(out, term.kind);
                Flag(out, term.required);
                Varint(out, wide[term.component_id]);
                Varint(out, wide[term.source_relationship]);
                Int(out, term.source_traversal);
                Int(out, term.source_variable);
                Int(out, term.target_variable);
                if (term.predicate < 0) {
                    // A null reference.
                    Int(out, -1);
                    Int(out, -1);
                    Zeros(out, 2);
                } else {
                    ReferenceBytes(out, references[term.predicate], wide);
                }
                Int(out, term.count);
                Ints(out, ints, term.first, term.count);
            }
            Int(out, query_root);
            Int(out, query_variable_count);
            Int(out, query_filter);
            Int(out, length(descriptions));
            for (description in descriptions) {
                Int(out, description.query_root);
                Int(out, description.query_variable_count);
                initial := description.row_type;
                out.extend(slice(pool, starts[initial], sizes[initial]));
                ReferenceBytes(out, references[description.evaluate], wide);
            }
            // The selected system description is one-based; zero means none.
            // Reactive bindings and actions are absent from authored compiler modules.
            Int(out, system_description);
            Zeros(out, 2);
            strings_at := length(out^);
            TableBytes(out, items);
            Fixed64(out, u64(strings_at));
    }
}

// FNV-1a over the module bytes, as import fingerprints use; zero becomes one.
pub Fingerprint :: (bytes: u8[]) -> u64 {
    hash: u64 = 14695981039346656037;
    for (item in bytes) {
        hash = (hash ^ u64(item)) * 1099511628211;
    }
    if (hash == 0) {
        return 1;
    }
    return hash;
}

// CHIBICLO v1: header words "CHIBICLO", version, root id and row count, then
// rows sorted bytewise by name: id, name length, module length, name, module.
// Module bytes are data[starts[i], starts[i] + lengths[i]).
pub Closure :: (root: u64, ids: u64[], names: string[], data: u8[],
                starts: int[], lengths: int[]) -> u8[] {
    order: int[] = [];
    index: int = 0;
    while (index < length(names)) {
        at := length(order);
        order.append(index);
        while (at > 0 && strings.Compare(names[order[at - 1]], names[index]) > 0) {
            order[at] = order[at - 1];
            at -= 1;
        }
        order[at] = index;
        index += 1;
    }
    bytes: u8[] = [67, 72, 73, 66, 73, 67, 76, 79];
    Fixed64(&bytes, 1);
    Fixed64(&bytes, root);
    Fixed64(&bytes, u64(length(names)));
    for (row in order) {
        name := names[row];
        Fixed64(&bytes, ids[row]);
        Fixed64(&bytes, u64(strings.ByteLength(name)));
        Fixed64(&bytes, u64(lengths[row]));
        Raw(&bytes, name);
        bytes.extend(slice(data, starts[row], lengths[row]));
    }
    return bytes;
}
package math_types

// Accepted describes the success payload only. Recoverable operations still
// need the language's agreed error-result adapter at the compiler boundary.
// This package does not choose a public optional, union or multi-result ABI.
pub Recoverable :: (name: string) -> bool {
    return name == "normalize" || name == "normalize_or" || name == "inverse" || name == "quat_normalize";
}

UnaryMemberwise :: (name: string) -> bool {
    if (name == "abs") {
        return true;
    }
    if (name == "sign") {
        return true;
    }
    if (name == "floor") {
        return true;
    }
    if (name == "ceil") {
        return true;
    }
    if (name == "round") {
        return true;
    }
    if (name == "fract") {
        return true;
    }
    if (name == "sqrt") {
        return true;
    }
    if (name == "exp") {
        return true;
    }
    if (name == "exp2") {
        return true;
    }
    if (name == "log") {
        return true;
    }
    if (name == "log2") {
        return true;
    }
    if (name == "sin") {
        return true;
    }
    if (name == "cos") {
        return true;
    }
    if (name == "tan") {
        return true;
    }
    if (name == "asin") {
        return true;
    }
    if (name == "acos") {
        return true;
    }
    if (name == "atan") {
        return true;
    }
    if (name == "saturate") {
        return true;
    }
    return false;
}
BinaryMemberwise :: (name: string) -> bool {
    return name == "mod" || name == "min" || name == "max" || name == "pow" ||
           name == "atan2" || name == "step";
}
TernaryMemberwise :: (name: string) -> bool {
    return name == "clamp" || name == "mix" || name == "smoothstep";
}

Memberwise :: (arguments: int[]) -> Result {
    kind := Scalar;
    for (argument in arguments) {
        problem := ScalarError(argument);
        if (problem != "") {
            return Result.Rejected(problem);
        }
        if (argument != Scalar && !IsVector(argument)) {
            return Result.Rejected("memberwise math functions take f32 scalars and vectors");
        }
        if (IsVector(argument)) {
            if (kind != Scalar && kind != argument) {
                return Result.Rejected("memberwise math operands differ in vector width");
            }
            kind = argument;
        }
    }
    return Result.Accepted(kind);
}

pub Function :: (name: string, arguments: int[]) -> Result {
    arity: int = 0;
    if (UnaryMemberwise(name)) {
        arity = 1;
    } else if (BinaryMemberwise(name)) {
        arity = 2;
    } else if (TernaryMemberwise(name)) {
        arity = 3;
    }
    if (arity != 0) {
        if (length(arguments) != arity) {
            return Result.Rejected(format_text("{} needs {} arguments", name, arity));
        }
        return Memberwise(arguments);
    }
    if (name == "length" || name == "normalize" || name == "normalize_or_zero") {
        if (length(arguments) != 1 || !IsVector(arguments[0])) {
            return Result.Rejected(format_text("{} takes one vector", name));
        }
        if (name == "length") {
            return Result.Accepted(Scalar);
        }
        return Result.Accepted(arguments[0]);
    }
    if (name == "distance" || name == "dot" || name == "reflect" || name == "normalize_or") {
        if (length(arguments) != 2 || !IsVector(arguments[0]) || arguments[0] != arguments[1]) {
            return Result.Rejected(format_text("{} takes two vectors of one width", name));
        }
        if (name == "distance" || name == "dot") {
            return Result.Accepted(Scalar);
        }
        return Result.Accepted(arguments[0]);
    }
    if (name == "cross") {
        if (length(arguments) != 2 || arguments[0] != Vec3 || arguments[1] != Vec3) {
            return Result.Rejected("cross takes two vec3 operands");
        }
        return Result.Accepted(Vec3);
    }
    if (name == "refract") {
        if (length(arguments) != 3 || !IsVector(arguments[0]) || arguments[0] != arguments[1] ||
            arguments[2] != Scalar) {
            return Result.Rejected("refract takes two vectors of one width and an f32 ratio");
        }
        return Result.Accepted(arguments[0]);
    }
    if (name == "transpose" || name == "determinant" || name == "inverse") {
        if (length(arguments) != 1 || !IsMatrix(arguments[0])) {
            return Result.Rejected(format_text("{} takes one matrix", name));
        }
        if (name == "determinant") {
            return Result.Accepted(Scalar);
        }
        return Result.Accepted(arguments[0]);
    }
    if (name == "matrix_comp_mult") {
        if (length(arguments) != 2 || !IsMatrix(arguments[0]) || arguments[0] != arguments[1]) {
            return Result.Rejected("matrix_comp_mult takes two matrices of one width");
        }
        return Result.Accepted(arguments[0]);
    }
    if (name == "quat_conjugate" || name == "quat_normalize") {
        if (length(arguments) != 1 || arguments[0] != Quat) {
            return Result.Rejected(format_text("{} takes one quaternion", name));
        }
        return Result.Accepted(Quat);
    }
    return Result.Rejected(format_text("unknown built-in math function '{}'", name));
}
package math_types

import strings "core:strings"
import tk "project:source_tokenizer"

// These are source math categories, not catalog, storage or bytecode IDs.
// Callers canonicalize aliases and resolve contextual literals/conversions
// before asking this package to check an operation. Scalar means f32 only.
pub Unknown: int : 0;
pub Scalar: int : 1;
pub Vec2: int : 2;
pub Vec3: int : 3;
pub Vec4: int : 4;
pub Quat: int : 5;
pub Mat2: int : 6;
pub Mat3: int : 7;
pub Mat4: int : 8;
pub Double: int : 9;
pub Integer: int : 10;
pub Boolean: int : 11;

pub Result :: union {
    Accepted(kind: int) | Rejected(message: string)
}
pub SwizzleResult :: union {
    Accepted(kind: int, components: int[]) | Rejected(message: string)
}

pub Kind :: (name: string) -> int {
    if (name == "number" || name == "f32") {
        return Scalar;
    }
    if (name == "vec2") {
        return Vec2;
    }
    if (name == "vec3") {
        return Vec3;
    }
    if (name == "vec4") {
        return Vec4;
    }
    if (name == "quat") {
        return Quat;
    }
    if (name == "mat2") {
        return Mat2;
    }
    if (name == "mat3") {
        return Mat3;
    }
    if (name == "mat4") {
        return Mat4;
    }
    if (name == "f64") {
        return Double;
    }
    if (name == "bool") {
        return Boolean;
    }
    if (name == "int" || name == "i8" || name == "u8" || name == "i16" || name == "u16" ||
        name == "i32" || name == "u32" || name == "i64" || name == "u64") {
        return Integer;
    }
    return Unknown;
}
pub Name :: (kind: int) -> string {
    if (kind == Scalar) {
        return "number";
    }
    if (kind == Vec2) {
        return "vec2";
    }
    if (kind == Vec3) {
        return "vec3";
    }
    if (kind == Vec4) {
        return "vec4";
    }
    if (kind == Quat) {
        return "quat";
    }
    if (kind == Mat2) {
        return "mat2";
    }
    if (kind == Mat3) {
        return "mat3";
    }
    if (kind == Mat4) {
        return "mat4";
    }
    if (kind == Double) {
        return "f64";
    }
    if (kind == Integer) {
        return "an integer";
    }
    if (kind == Boolean) {
        return "bool";
    }
    return "an unsupported type";
}
pub IsVector :: (kind: int) -> bool {
    return kind >= Vec2 && kind <= Vec4;
}
pub IsMatrix :: (kind: int) -> bool {
    return kind >= Mat2 && kind <= Mat4;
}
pub Width :: (kind: int) -> int {
    if (IsVector(kind)) {
        return kind;
    }
    if (IsMatrix(kind)) {
        return kind - Mat2 + 2;
    }
    return 0;
}
pub Components :: (kind: int) -> int {
    if (kind == Scalar) {
        return 1;
    }
    if (kind == Quat) {
        return 4;
    }
    width := Width(kind);
    if (IsMatrix(kind)) {
        return width * width;
    }
    return width;
}
ScalarError :: (kind: int) -> string {
    if (kind == Double) {
        return "math components require explicit f32(value) narrowing from f64";
    }
    if (kind == Integer) {
        return "math components need a resolved f32 value; convert the integer with f32(value)";
    }
    return "";
}

// Empty text accepts the constructor. A single f32 splats a vector or
// initializes a matrix diagonal. Other scalar/vector arguments fill in
// component order, column-first for a matrix. Quaternions take four scalars.
pub Constructor :: (kind: int, arguments: int[], positional: bool) -> string {
    if (!IsVector(kind) && !IsMatrix(kind) && kind != Quat) {
        return "constructor needs a built-in vector, quaternion or matrix type";
    }
    if (!positional) {
        return "built-in math constructors take positional arguments";
    }
    supplied: int = 0;
    for (argument in arguments) {
        problem := ScalarError(argument);
        if (problem != "") {
            return problem;
        }
        if (argument == Scalar) {
            supplied += 1;
        } else if (IsVector(argument) && kind != Quat) {
            supplied += Components(argument);
        } else {
            if (kind == Quat) {
                return "quat takes four f32 components in x, y, z, w order";
            }
            return "vector and matrix constructors take f32 scalars and vectors";
        }
    }
    if (kind != Quat && length(arguments) == 1 && arguments[0] == Scalar) {
        return "";
    }
    if (supplied != Components(kind)) {
        return format_text("{} needs {} components; these arguments supply {}", Name(kind), Components(kind), supplied);
    }
    return "";
}

// Accepted is the successful payload kind, not an error-result ABI.
// Scalar math belongs to the numeric checker. This entry checks operations
// involving at least one built-in vector, quaternion or matrix; `operator` is
// the operator token's source_tokenizer kind, such as tk.Add. The caller
// must also inspect BinaryRecoverable before constructing the result type.
pub BinaryRecoverable :: (operator: int, left: int, right: int) -> bool {
    return operator == tk.Mul && left == Quat && right == Vec3;
}
pub Binary :: (operator: int, left: int, right: int) -> Result {
    problem := ScalarError(left);
    if (problem == "") {
        problem = ScalarError(right);
    }
    if (problem != "") {
        return Result.Rejected(problem);
    }
    if (operator == tk.CmpEq || operator == tk.NotEq) {
        if (left == right && (IsVector(left) || IsMatrix(left) || left == Quat)) {
            return Result.Accepted(Boolean);
        }
        return Result.Rejected("math equality requires operands of the same built-in type");
    }
    if (left == Quat || right == Quat) {
        if (operator == tk.Mul && left == Quat && (right == Quat || right == Vec3)) {
            return Result.Accepted(right);
        }
        return Result.Rejected("quat supports quaternion composition and quat * vec3 rotation");
    }
    if (operator != tk.Add && operator != tk.Sub && operator != tk.Mul && operator != tk.Quo) {
        return Result.Rejected("math values support + - * / == and !=; compare components instead");
    }
    if (IsVector(left) && right == Scalar) {
        return Result.Accepted(left);
    }
    if (left == Scalar && IsVector(right)) {
        return Result.Accepted(right);
    }
    if (IsVector(left) && left == right) {
        return Result.Accepted(left);
    }
    if (IsMatrix(left) && right == Scalar && (operator == tk.Mul || operator == tk.Quo)) {
        return Result.Accepted(left);
    }
    if (left == Scalar && IsMatrix(right) && operator == tk.Mul) {
        return Result.Accepted(right);
    }
    if (IsMatrix(left) && left == right && (operator == tk.Add || operator == tk.Sub || operator == tk.Mul)) {
        return Result.Accepted(left);
    }
    if (IsMatrix(left) && IsVector(right) && operator == tk.Mul && Width(left) == Width(right)) {
        return Result.Accepted(right);
    }
    if (IsVector(left) && IsMatrix(right) && operator == tk.Mul) {
        return Result.Rejected("a matrix multiplies a column vector on its right; write matrix * vector");
    }
    return Result.Rejected(format_text("cannot apply {} to {} and {}", tk.KindNames()[operator], Name(left), Name(right)));
}
pub Negate :: (kind: int) -> Result {
    if (IsVector(kind) || IsMatrix(kind)) {
        return Result.Accepted(kind);
    }
    return Result.Rejected("unary math negation needs a vector or matrix");
}

Component :: (byte: int) -> int {
    if (byte == 120 || byte == 114) {
        return 0;
    }
    if (byte == 121 || byte == 103) {
        return 1;
    }
    if (byte == 122 || byte == 98) {
        return 2;
    }
    if (byte == 119 || byte == 97) {
        return 3;
    }
    return -1;
}
PositionAlphabet :: (byte: int) -> bool {
    return byte == 120 || byte == 121 || byte == 122 || byte == 119;
}
pub Swizzle :: (kind: int, member: string, writable: bool) -> SwizzleResult {
    if (!IsVector(kind)) {
        return SwizzleResult.Rejected("swizzles require a vector");
    }
    count := strings.ByteLength(member);
    if (count < 1 || count > 4) {
        return SwizzleResult.Rejected("a swizzle needs one to four components");
    }
    position := PositionAlphabet(strings.ByteAt(member, 0));
    components: int[] = [];
    seen: int = 0;
    index: int = 0;
    while (index < count) {
        byte := strings.ByteAt(member, index);
        component := Component(byte);
        if (component < 0) {
            return SwizzleResult.Rejected("swizzles use xyzw or rgba components");
        }
        if (PositionAlphabet(byte) != position) {
            return SwizzleResult.Rejected("a swizzle cannot mix xyzw and rgba components");
        }
        if (component >= Width(kind)) {
            return SwizzleResult.Rejected(format_text("{} has no component '{}'", Name(kind), strings.Slice(member, index, 1)));
        }
        bit := 1 << u32(component);
        if (writable && (seen & bit) != 0) {
            return SwizzleResult.Rejected("a writable swizzle cannot repeat a destination component");
        }
        seen |= bit;
        components.append(component);
        index += 1;
    }
    result: int = Scalar;
    if (count > 1) {
        result = count;
    }
    return SwizzleResult.Accepted(result, components);
}
package native_link

import strings "core:strings"

// The native compiler's link step, without effects: what a program's object
// files and the vendored archives it uses need to become an executable through
// LLVM's lld, which is found in the LLVM folder by name (ld.lld on Linux,
// ld64.lld on macOS, lld-link on Windows), never through PATH. No C compiler
// or compiler driver takes part: the C runtime's start files come from the
// system's development files on Linux, the dylibs a macOS program names are
// small text stubs, and Windows links against the import libraries in the
// `libpaths` and the LIB variable.
//
// Command is the exact argument vector for a plan, tested for every target.
// native_link_host finds the tools, writes the stubs and runs these vectors.

pub LinuxX64: int : 0;
pub MacOSArm64: int : 1;
pub WindowsX64: int : 2;

// What went wrong, by kind; `code` is the failed tool's exit status.
pub BadTriple: int : 1;
pub MissingTool: int : 2;
pub MissingLibc: int : 3;
pub CannotWrite: int : 4;
pub ToolFailed: int : 5;
pub BadPlan: int : 6;

@error
pub Error :: struct {
    kind: int;
    code: int;
}

// A system library and the symbols a program takes from it: `System` or a
// library's name on macOS, a DLL's name without `.dll` on Windows.
pub Import :: struct {
    name: string;
    symbols: string[];
}

// The program to build. `objects` define the platform's entry: `main` when
// the C library starts the program, `_start` (Windows: mainCRTStartup) when
// `static` is set and nothing but the objects and archives runs. `archives`
// are vendored libraries, linked after the objects. `libraries` name system
// libraries without a prefix or suffix: `m` and `pthread` on Linux, `c++` or
// `framework:Cocoa` on macOS, `user32.lib` on Windows. `imports` name the
// symbols the program takes from system libraries: a macOS stub exports them,
// so dyld binds them in that library, and a Windows import library is written
// from them. `libpaths` add folders the Windows linker searches. `work` is a
// folder this plan may write stubs into; `libc` and `interpreter` (Linux, not
// static) come from Discover. `shared` links a Linux shared library of the
// objects instead of a program.
pub Plan :: struct {
    triple: string;
    llvm: string;
    objects: string[];
    archives: string[];
    libraries: string[];
    imports: Import[];
    libpaths: string[];
    output: string;
    work: string;
    libc: string;
    interpreter: string;
    static: bool;
    shared: bool;
}

// A plan for the program of these objects and archives: dynamically linked
// against the system's C library unless `static`. The C library's location is
// found when the plan is linked.
pub Program :: (triple: string, llvm: string, objects: string[], archives: string[], libraries: string[],
                libpaths: string[], output: string, work: string, static: bool) -> Plan {
    plan: Plan = {triple: triple, llvm: llvm, objects: objects, archives: archives, libraries: libraries, imports: [],
                  libpaths: libpaths, output: output, work: work, libc: "", interpreter: "", static: static,
                  shared: false};
    return plan;
}

// The target a triple names, -1 for any this link step does not know.
pub TargetOf :: (triple: string) -> int {
    if (triple == "x86_64-unknown-linux-gnu") {
        return LinuxX64;
    }
    if (triple == "arm64-apple-macosx11.0.0" || strings.HasPrefix(triple, "aarch64-apple-")) {
        return MacOSArm64;
    }
    if (triple == "x86_64-pc-windows-msvc") {
        return WindowsX64;
    }
    return -1;
}

Join :: (parts: string[]) -> string {
    return strings.Join(parts, "");
}

pub Linker :: (target: int) -> string {
    if (target == MacOSArm64) {
        return "ld64.lld";
    }
    if (target == WindowsX64) {
        return "lld-link";
    }
    return "ld.lld";
}

// llc's object for a module: position independent, so it links into a
// program and a shared library alike. The module names its triple and layout.
pub ObjectCommand :: (llc: string, module: string, object: string, level: int) -> string[] {
    optimize := "-O=0";
    if (level != 0) {
        optimize = "-O=2";
    }
    return [llc, "-filetype=obj", optimize, "-relocation-model=pic", "-o", object, module];
}

// A macOS dylib's stub for lld: a text file naming the library the program
// loads and the symbols dyld binds in it. Symbols no stub lists are looked up
// when the program runs (`-undefined dynamic_lookup`), as a vendored archive's
// are; this is how a link needs no SDK of its own.
pub Stub :: (install: string, symbols: string[]) -> string {
    return Join(["--- !tapi-tbd\ntbd-version: 4\ntargets: [ arm64-macos ]\ninstall-name: '", install,
                 "'\nexports:\n  - targets: [ arm64-macos ]\n    symbols: [ ", strings.Join(symbols, ", "), " ]\n...\n"]);
}

// Where the dylib a library name stands for lives on a Mac.
pub InstallName :: (dependency: string) -> string {
    if (strings.HasPrefix(dependency, "framework:")) {
        name := strings.TrimPrefix(dependency, "framework:");
        return Join(["/System/Library/Frameworks/", name, ".framework/", name]);
    }
    if (dependency == "c++") {
        return "/usr/lib/libc++.1.dylib";
    }
    if (dependency == "System") {
        return "/usr/lib/libSystem.B.dylib";
    }
    return Join(["/usr/lib/lib", dependency, ".dylib"]);
}

// The stub file for a library, in the plan's work folder.
pub StubPath :: (work: string, dependency: string) -> string {
    return Join([work, "/", strings.ReplaceAll(strings.ReplaceAll(dependency, ":", "-"), "+", "p"), ".tbd"]);
}

// The import definition of the DLL `name`, from which lld-link writes its
// import library, as rustc writes raw-dylib imports, so no Windows SDK is read.
pub Definition :: (name: string, symbols: string[]) -> string {
    lines: string[] = [Join(["LIBRARY ", name, ".dll\nEXPORTS\n"])];
    for (symbol in symbols) {
        lines.append(Join(["    ", symbol, "\n"]));
    }
    return Join(lines);
}

// Whether `value` spells a library or symbol name a definition can hold:
// letters, digits and `_ . - @ $`.
pub ImportName :: (value: string) -> bool {
    if (value == "") {
        return false;
    }
    for (byte in strings.Bytes(value)) {
        // Stage one has no character literals: 95 is `_`, 46 `.`, 45 `-`,
        // 64 `@` and 36 `$`.
        word := byte == 95 || (byte >= 48 && byte <= 57) || (byte >= 65 && byte <= 90) || (byte >= 97 && byte <= 122);
        if (!word && byte != 46 && byte != 45 && byte != 64 && byte != 36) {
            return false;
        }
    }
    return true;
}

// The system libraries a module's IR imports from, other than libc, once each
// in order: `; chibi-library system:NAME` names one and
// `; chibi-import system:NAME SYMBOL` a symbol of it. The symbols are gathered
// as (library, symbol) pairs first, so no library's list is copied as it
// grows; a module names a few libraries, so each pair searches them in turn
// and each library's symbols are one pass over the pairs.
// The indices of `keys` in key order, equal keys in index order: a bottom-up
// merge sort that appends and never shifts, so it needs no array insert. A
// macOS program imports thousands of symbols, so duplicates are found by sorting
// and searching, not by scanning, and the order of first appearance is kept.
Ordered :: (keys: string[]) -> int[] {
    count := length(keys);
    from: int[] = [];
    for (index in 0..<count) {
        from.append(index);
    }
    width := 1;
    while (width < count) {
        to: int[] = [];
        start := 0;
        while (start < count) {
            middle := start + width;
            if (middle > count) {
                middle = count;
            }
            end := middle + width;
            if (end > count) {
                end = count;
            }
            left := start;
            right := middle;
            while (left < middle || right < end) {
                if (right >= end || (left < middle && strings.Compare(keys[from[left]], keys[from[right]]) <= 0)) {
                    to.append(from[left]);
                    left += 1;
                } else {
                    to.append(from[right]);
                    right += 1;
                }
            }
            start = end;
        }
        from = to;
        width *= 2;
    }
    return from;
}

// Whether each of `keys` is the first of its value in `keys`.
Firsts :: (keys: string[]) -> bool[] {
    order := Ordered(keys);
    first := resize([false], length(keys));
    for (at in 0..<length(order)) {
        if (at == 0 || keys[order[at - 1]] != keys[order[at]]) {
            first[order[at]] = true;
        }
    }
    return first;
}

// `keys` in key order.
Sorted :: (keys: string[]) -> string[] {
    sorted: string[] = [];
    for (index in Ordered(keys)) {
        sorted.append(keys[index]);
    }
    return sorted;
}

// Whether `key` is in `sorted`, by binary search.
Has :: (sorted: string[], key: string) -> bool {
    low := 0;
    high := length(sorted);
    while (low < high) {
        middle := low + (high - low) / 2;
        order := strings.Compare(sorted[middle], key);
        if (order == 0) {
            return true;
        }
        if (order < 0) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    return false;
}

pub SystemImports :: (lines: string[]) -> Import[] {
    names: string[] = [];
    candidate_owners: int[] = [];
    candidate_symbols: string[] = [];
    candidate_keys: string[] = [];
    named := "; chibi-library system:";
    imports := "; chibi-import system:";
    for (line in lines) {
        library_name := "";
        symbol := "";
        if (strings.HasPrefix(line, named)) {
            library_name = strings.TrimPrefix(line, named);
        } else if (strings.HasPrefix(line, imports)) {
            rest := strings.TrimPrefix(line, imports);
            space := strings.Index(rest, " ");
            if (space < 0) {
                continue;
            }
            library_name = strings.Slice(rest, 0, space);
            symbol = strings.Slice(rest, space + 1, strings.ByteLength(rest) - space - 1);
        } else {
            continue;
        }
        if (library_name == "c") {
            continue;
        }
        at := -1;
        for (index in 0..<length(names)) {
            if (names[index] == library_name) {
                at = index;
            }
        }
        if (at < 0) {
            names.append(library_name);
            at = length(names) - 1;
        }
        key := Join([library_name, " ", symbol]);
        if (symbol != "") {
            candidate_owners.append(at);
            candidate_symbols.append(symbol);
            candidate_keys.append(key);
        }
    }
    // Each (library, symbol) once, at its first appearance.
    owners: int[] = [];
    symbols: string[] = [];
    firsts := Firsts(candidate_keys);
    for (index in 0..<length(candidate_keys)) {
        if (firsts[index]) {
            owners.append(candidate_owners[index]);
            symbols.append(candidate_symbols[index]);
        }
    }
    found: Import[] = [];
    for (index in 0..<length(names)) {
        listed: string[] = [];
        for (pair in 0..<length(owners)) {
            if (owners[pair] == index) {
                listed.append(symbols[pair]);
            }
        }
        imported: Import = {name: names[index], symbols: listed};
        found.append(imported);
    }
    return found;
}

// The index of the library `name` in `imports`, -1 when it is not there.
Find :: (imports: Import[], name: string) -> int {
    for (index in 0..<length(imports)) {
        if (imports[index].name == name) {
            return index;
        }
    }
    return -1;
}

// The libraries a plan's link writes stubs for in `work`, in link order, each
// with the symbols it exports. macOS: libSystem, which dyld requires of every
// program and whose stub exports dyld's binder, then each of `libraries`.
// Windows: kernel32 with what the start module imports, when `static`. Then,
// on both, the plan's imports; Linux links none.
pub Imports :: (plan: Plan) -> Import[] {
    target := TargetOf(plan.triple);
    found: Import[] = [];
    if (target == MacOSArm64) {
        libsystem: Import = {name: "System", symbols: ["dyld_stub_binder"]};
        found.append(libsystem);
        for (dependency in plan.libraries) {
            if (Find(found, dependency) < 0) {
                dependent: Import = {name: dependency, symbols: []};
                found.append(dependent);
            }
        }
    } else if (target == WindowsX64) {
        if (plan.static) {
            found.append(StartImports(plan.triple));
        }
    } else {
        return found;
    }
    // Duplicates are found by key: against the symbols already there, then
    // among the plan's own, in order.
    held_keys: string[] = [];
    for (known in found) {
        for (symbol in known.symbols) {
            held_keys.append(Join([known.name, " ", symbol]));
        }
    }
    held_keys = Sorted(held_keys);
    plan_keys: string[] = [];
    for (imported in plan.imports) {
        for (symbol in imported.symbols) {
            plan_keys.append(Join([imported.name, " ", symbol]));
        }
    }
    plan_firsts := Firsts(plan_keys);
    position := 0;
    for (imported in plan.imports) {
        at := Find(found, imported.name);
        if (at < 0) {
            added: Import = {name: imported.name, symbols: []};
            found.append(added);
            at = length(found) - 1;
        }
        changed := found[at];
        symbols := changed.symbols;
        for (symbol in imported.symbols) {
            if (plan_firsts[position] && !Has(held_keys, plan_keys[position])) {
                symbols.append(symbol);
            }
            position += 1;
        }
        changed.symbols = symbols;
        found[at] = changed;
    }
    return found;
}

// The file a stub of Imports is written to: a text stub on macOS, an import
// definition on Windows.
pub ImportPath :: (plan: Plan, name: string) -> string {
    if (TargetOf(plan.triple) == WindowsX64) {
        return Join([plan.work, "/", name, ".def"]);
    }
    return StubPath(plan.work, name);
}

pub ImportText :: (plan: Plan, stub: Import) -> string {
    if (TargetOf(plan.triple) == WindowsX64) {
        return Definition(stub.name, stub.symbols);
    }
    return Stub(InstallName(stub.name), stub.symbols);
}

// The import library lld-link writes from a Windows stub's definition.
pub ImportLibrary :: (plan: Plan, name: string) -> string {
    return Join([plan.work, "/", name, ".lib"]);
}

// The command that turns a stub into what the link reads, after ImportText
// is written: lld-link's import library on Windows, none (an empty vector) on
// macOS, which links the stub itself.
pub ImportCommand :: (plan: Plan, name: string) -> string[] {
    if (TargetOf(plan.triple) != WindowsX64) {
        return [];
    }
    return [Join([plan.llvm, "/lld-link"]), "-flavor", "link", "/lib", "/nologo",
            Join(["/def:", ImportPath(plan, name)]), "/machine:x64", Join(["/out:", ImportLibrary(plan, name)])];
}

// The file the linker writes in `work`, which Link publishes as the plan's
// output. It has the same name whatever the program is called: a macOS
// ad-hoc signature carries it, and two links of the same inputs give the
// same bytes.
pub Partial :: (plan: Plan) -> string {
    if (TargetOf(plan.triple) == WindowsX64) {
        return Join([plan.work, "/a.exe"]);
    }
    return Join([plan.work, "/a.out"]);
}

// Where a Linux system keeps the C library's start files and development
// library, the files that must all be there, and the dynamic linker's paths,
// in the order they are tried.
pub LibcFolders :: () -> string[] {
    return ["/usr/lib/x86_64-linux-gnu", "/usr/lib64", "/lib/x86_64-linux-gnu", "/usr/lib"];
}
pub LibcFiles :: () -> string[] {
    return ["crt1.o", "crti.o", "crtn.o", "libc.so"];
}
pub Interpreters :: () -> string[] {
    return ["/lib64/ld-linux-x86-64.so.2", "/lib/x86_64-linux-gnu/ld-linux-x86-64.so.2", "/usr/lib64/ld-linux-x86-64.so.2"];
}

// The argument vector that links the plan's program to `to`, Partial(plan)
// when Link runs it. Each vector names its flavor, so any of lld's names,
// or lld itself, may run in place of the first argument.
pub Command :: (plan: Plan, to: string) -> string[] {
    target := TargetOf(plan.triple);
    linker := Join([plan.llvm, "/", Linker(target)]);
    if (target == MacOSArm64) {
        command := [linker, "-flavor", "darwin", "-arch", "arm64", "-platform_version", "macos", "11.0.0", "11.0.0",
                    "-dead_strip", "-undefined", "dynamic_lookup", "-e", "_main", "-o", to];
        command.extend(plan.objects);
        command.extend(plan.archives);
        for (stub in Imports(plan)) {
            command.append(StubPath(plan.work, stub.name));
        }
        return command;
    }
    if (target == WindowsX64) {
        command := [linker, "-flavor", "link", "/nologo", "/subsystem:console", "/machine:x64", "/opt:ref", "/Brepro",
                    Join(["/out:", to])];
        if (plan.static) {
            command.extend(["/nodefaultlib", "/entry:mainCRTStartup"]);
        }
        for (folder in plan.libpaths) {
            command.append(Join(["/libpath:", folder]));
        }
        command.extend(plan.objects);
        command.extend(plan.archives);
        for (stub in Imports(plan)) {
            command.append(ImportLibrary(plan, stub.name));
        }
        command.extend(plan.libraries);
        return command;
    }
    if (plan.shared) {
        command := [linker, "-flavor", "gnu", "-shared", "--gc-sections", "-o", to];
        command.extend(plan.objects);
        command.extend(plan.archives);
        return command;
    }
    if (plan.static) {
        command := [linker, "-flavor", "gnu", "-static", "--gc-sections", "-e", "_start", "-o", to];
        command.extend(plan.objects);
        command.extend(plan.archives);
        for (dependency in plan.libraries) {
            command.append(Join(["-l", dependency]));
        }
        return command;
    }
    command := [linker, "-flavor", "gnu", "--dynamic-linker", plan.interpreter, "--gc-sections", "-o", to,
                Join([plan.libc, "/crt1.o"]), Join([plan.libc, "/crti.o"])];
    command.extend(plan.objects);
    command.extend(plan.archives);
    command.extend(["-L", plan.libc]);
    for (dependency in plan.libraries) {
        command.append(Join(["-l", dependency]));
    }
    command.extend(["-lc", Join([plan.libc, "/crtn.o"])]);
    return command;
}
package native_link

// The start modules: the LLVM IR of the shim that starts a native program,
// calls its entry `chibi_scalar() -> i32` (`chibi_scalar(ptr)` with a runtime
// context when `context` is set) and makes the result the exit status. Link it
// as one more object beside the program's own.
//
// The shim keeps the process arguments where core:os reads them: `@chibi_argc`
// (i32) and `@chibi_argv` (ptr to the argument strings) on Linux and macOS, and
// on Windows `@chibi_command_line`, the UTF-16 string GetCommandLineW gives.
// They are set before the entry runs.
//
// A context's allocate is libc's calloc (HeapAlloc on Windows) and its release
// libc's free (HeapFree on Windows); its index
// failure aborts; formatting text is not available to a program. A failed
// assert ends the entry early with its failure in the context, which the shim
// reports on stderr before it exits with status 134.

WindowsPrelude :: () -> string {
    return Join([
        "target triple = \"x86_64-pc-windows-msvc\"\n",
        "module asm \".text\"\n",
        "module asm \".globl __chkstk\"\n",
        "module asm \"__chkstk:\"\n",
        "module asm \"pushq %rcx\"\n",
        "module asm \"pushq %rax\"\n",
        "module asm \"cmpq $0x1000, %rax\"\n",
        "module asm \"leaq 24(%rsp), %rcx\"\n",
        "module asm \"jb 1f\"\n",
        "module asm \"2:\"\n",
        "module asm \"subq $0x1000, %rcx\"\n",
        "module asm \"testq %rcx, (%rcx)\"\n",
        "module asm \"subq $0x1000, %rax\"\n",
        "module asm \"cmpq $0x1000, %rax\"\n",
        "module asm \"ja 2b\"\n",
        "module asm \"1:\"\n",
        "module asm \"subq %rax, %rcx\"\n",
        "module asm \"testq %rcx, (%rcx)\"\n",
        "module asm \"popq %rax\"\n",
        "module asm \"popq %rcx\"\n",
        "module asm \"retq\"\n",
        "@_fltused = dso_local global i32 0\n",
        "declare dllimport void @ExitProcess(i32) noreturn\n",
        "declare dllimport ptr @GetCommandLineW()\n",
        "@chibi_command_line = dso_local global ptr null\n"
    ]);
}

// The runtime context's format_text for a program with no VM to call, as the
// VM formats: each `{}` of the format, the first value, is replaced by the next
// value (decimal text for an integer, signed by its tag; `true` or `false` for
// a bool; a string's bytes), or by nothing when no value is left; `{{` and
// `}}` are one brace; any other brace stays. Floats are not formatted yet and
// trap. The result is made once, in memory chibi_allocate gives, sized from
// the format and the values. Written as a byte copy loop so a program that
// links nothing needs no memcpy.
RuntimeFormat :: () -> string {
    return Join([
        "@chibi_true = private unnamed_addr constant [4 x i8] c\"true\"\n",
        "@chibi_false = private unnamed_addr constant [5 x i8] c\"false\"\n",
        "declare void @llvm.trap()\n",
        "define internal void @chibi_copy(ptr %to, ptr %from, i32 %count) {\n",
        "entry:\n",
        "  br label %loop\n",
        "loop:\n",
        "  %at = phi i32 [ 0, %entry ], [ %next, %body ]\n",
        "  %more = icmp slt i32 %at, %count\n",
        "  br i1 %more, label %body, label %done\n",
        "body:\n",
        "  %source = getelementptr inbounds i8, ptr %from, i32 %at\n",
        "  %byte = load i8, ptr %source\n",
        "  %target = getelementptr inbounds i8, ptr %to, i32 %at\n",
        "  store i8 %byte, ptr %target\n",
        "  %next = add i32 %at, 1\n",
        "  br label %loop\n",
        "done:\n",
        "  ret void\n",
        "}\n",
        "define internal void @chibi_format_text(ptr %ctx, ptr %values, i32 %count, ptr %result) {\n",
        "entry:\n",
        "  %i.slot = alloca i32\n",
        "  %o.slot = alloca i32\n",
        "  %a.slot = alloca i32\n",
        "  %digits = alloca [20 x i8]\n",
        "  store i32 0, ptr %i.slot\n",
        "  store i32 0, ptr %o.slot\n",
        "  store i32 1, ptr %a.slot\n",
        "  %fmt.length.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %values, i32 0, i32 1\n",
        "  %fmt.length = load i32, ptr %fmt.length.at\n",
        "  %fmt.bytes.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %values, i32 0, i32 3\n",
        "  %fmt = load ptr, ptr %fmt.bytes.at\n",
        "  %fmt.wide = zext i32 %fmt.length to i64\n",
        "  br label %size\n",
        "size:\n",
        "  %k = phi i32 [ 1, %entry ], [ %k.next, %size.arg ]\n",
        "  %bound = phi i64 [ %fmt.wide, %entry ], [ %bound.next, %size.arg ]\n",
        "  %counting = icmp slt i32 %k, %count\n",
        "  br i1 %counting, label %size.arg, label %alloc\n",
        "size.arg:\n",
        "  %value = getelementptr inbounds { i32, i32, i64, ptr }, ptr %values, i32 %k\n",
        "  %tag.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %value, i32 0, i32 0\n",
        "  %tag = load i32, ptr %tag.at\n",
        "  %length.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %value, i32 0, i32 1\n",
        "  %length = load i32, ptr %length.at\n",
        "  %length.wide = zext i32 %length to i64\n",
        "  %is.text = icmp eq i32 %tag, 12\n",
        "  %extra = select i1 %is.text, i64 %length.wide, i64 24\n",
        "  %bound.next = add i64 %bound, %extra\n",
        "  %k.next = add i32 %k, 1\n",
        "  br label %size\n",
        "alloc:\n",
        "  %total = add i64 %bound, 1\n",
        "  %buffer = call ptr @chibi_allocate(ptr %ctx, i64 %total)\n",
        "  br label %walk\n",
        "walk:\n",
        "  %i = load i32, ptr %i.slot\n",
        "  %ended = icmp sge i32 %i, %fmt.length\n",
        "  br i1 %ended, label %finish, label %step\n",
        "step:\n",
        "  %c.at = getelementptr inbounds i8, ptr %fmt, i32 %i\n",
        "  %c = load i8, ptr %c.at\n",
        "  %after = add i32 %i, 1\n",
        "  %has.after = icmp slt i32 %after, %fmt.length\n",
        "  br i1 %has.after, label %peek, label %literal\n",
        "peek:\n",
        "  %n.at = getelementptr inbounds i8, ptr %fmt, i32 %after\n",
        "  %n = load i8, ptr %n.at\n",
        "  %c.open = icmp eq i8 %c, 123\n",
        "  %c.close = icmp eq i8 %c, 125\n",
        "  %n.open = icmp eq i8 %n, 123\n",
        "  %n.close = icmp eq i8 %n, 125\n",
        "  %open.open = and i1 %c.open, %n.open\n",
        "  %open.close = and i1 %c.open, %n.close\n",
        "  %close.close = and i1 %c.close, %n.close\n",
        "  %escaped = or i1 %open.open, %close.close\n",
        "  br i1 %escaped, label %escape, label %hole.check\n",
        "hole.check:\n",
        "  br i1 %open.close, label %hole, label %literal\n",
        "escape:\n",
        "  %oe = load i32, ptr %o.slot\n",
        "  %te = getelementptr inbounds i8, ptr %buffer, i32 %oe\n",
        "  store i8 %c, ptr %te\n",
        "  %oe.one = add i32 %oe, 1\n",
        "  store i32 %oe.one, ptr %o.slot\n",
        "  %skip.escape = add i32 %i, 2\n",
        "  store i32 %skip.escape, ptr %i.slot\n",
        "  br label %walk\n",
        "hole:\n",
        "  %a = load i32, ptr %a.slot\n",
        "  %have = icmp slt i32 %a, %count\n",
        "  br i1 %have, label %argument, label %unfilled\n",
        "unfilled:\n",
        "  %skip.hole = add i32 %i, 2\n",
        "  store i32 %skip.hole, ptr %i.slot\n",
        "  br label %walk\n",
        "literal:\n",
        "  %o = load i32, ptr %o.slot\n",
        "  %to = getelementptr inbounds i8, ptr %buffer, i32 %o\n",
        "  store i8 %c, ptr %to\n",
        "  %o.one = add i32 %o, 1\n",
        "  store i32 %o.one, ptr %o.slot\n",
        "  store i32 %after, ptr %i.slot\n",
        "  br label %walk\n",
        "argument:\n",
        "  %arg = getelementptr inbounds { i32, i32, i64, ptr }, ptr %values, i32 %a\n",
        "  %arg.tag.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %arg, i32 0, i32 0\n",
        "  %arg.tag = load i32, ptr %arg.tag.at\n",
        "  %arg.length.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %arg, i32 0, i32 1\n",
        "  %arg.length = load i32, ptr %arg.length.at\n",
        "  %arg.word.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %arg, i32 0, i32 2\n",
        "  %arg.word = load i64, ptr %arg.word.at\n",
        "  %arg.bytes.at = getelementptr inbounds { i32, i32, i64, ptr }, ptr %arg, i32 0, i32 3\n",
        "  %arg.bytes = load ptr, ptr %arg.bytes.at\n",
        "  %a.next = add i32 %a, 1\n",
        "  store i32 %a.next, ptr %a.slot\n",
        "  %skip = add i32 %i, 2\n",
        "  store i32 %skip, ptr %i.slot\n",
        "  %o.arg = load i32, ptr %o.slot\n",
        "  %out = getelementptr inbounds i8, ptr %buffer, i32 %o.arg\n",
        "  %text.arg = icmp eq i32 %arg.tag, 12\n",
        "  br i1 %text.arg, label %text, label %scalar\n",
        "text:\n",
        "  call void @chibi_copy(ptr %out, ptr %arg.bytes, i32 %arg.length)\n",
        "  %o.text = add i32 %o.arg, %arg.length\n",
        "  store i32 %o.text, ptr %o.slot\n",
        "  br label %walk\n",
        "scalar:\n",
        "  %is.bool = icmp eq i32 %arg.tag, 2\n",
        "  br i1 %is.bool, label %boolean, label %number\n",
        "boolean:\n",
        "  %truth = icmp ne i64 %arg.word, 0\n",
        "  %word.ptr = select i1 %truth, ptr @chibi_true, ptr @chibi_false\n",
        "  %word.len = select i1 %truth, i32 4, i32 5\n",
        "  call void @chibi_copy(ptr %out, ptr %word.ptr, i32 %word.len)\n",
        "  %o.bool = add i32 %o.arg, %word.len\n",
        "  store i32 %o.bool, ptr %o.slot\n",
        "  br label %walk\n",
        "number:\n",
        "  %float.a = icmp eq i32 %arg.tag, 10\n",
        "  %float.b = icmp eq i32 %arg.tag, 11\n",
        "  %floating = or i1 %float.a, %float.b\n",
        "  br i1 %floating, label %trap, label %decimal\n",
        "trap:\n",
        "  call void @llvm.trap()\n",
        "  unreachable\n",
        "decimal:\n",
        "  %s1 = icmp eq i32 %arg.tag, 1\n",
        "  %s3 = icmp eq i32 %arg.tag, 3\n",
        "  %s5 = icmp eq i32 %arg.tag, 5\n",
        "  %s8 = icmp eq i32 %arg.tag, 8\n",
        "  %s13 = or i1 %s1, %s3\n",
        "  %s58 = or i1 %s5, %s8\n",
        "  %signed = or i1 %s13, %s58\n",
        "  %below = icmp slt i64 %arg.word, 0\n",
        "  %negative = and i1 %signed, %below\n",
        "  %flipped = sub i64 0, %arg.word\n",
        "  %magnitude = select i1 %negative, i64 %flipped, i64 %arg.word\n",
        "  br label %emit\n",
        "emit:\n",
        "  %rest = phi i64 [ %magnitude, %decimal ], [ %rest.next, %emit ]\n",
        "  %at.now = phi i32 [ 20, %decimal ], [ %at.back, %emit ]\n",
        "  %digit = urem i64 %rest, 10\n",
        "  %char = add i64 %digit, 48\n",
        "  %digit.byte = trunc i64 %char to i8\n",
        "  %at.back = sub i32 %at.now, 1\n",
        "  %slot = getelementptr inbounds [20 x i8], ptr %digits, i32 0, i32 %at.back\n",
        "  store i8 %digit.byte, ptr %slot\n",
        "  %rest.next = udiv i64 %rest, 10\n",
        "  %again = icmp ne i64 %rest.next, 0\n",
        "  br i1 %again, label %emit, label %placed\n",
        "placed:\n",
        "  %width = sub i32 20, %at.back\n",
        "  br i1 %negative, label %minus, label %plain\n",
        "minus:\n",
        "  store i8 45, ptr %out\n",
        "  %out.one = getelementptr inbounds i8, ptr %out, i32 1\n",
        "  br label %plain\n",
        "plain:\n",
        "  %dest = phi ptr [ %out, %placed ], [ %out.one, %minus ]\n",
        "  %sign.width = phi i32 [ 0, %placed ], [ 1, %minus ]\n",
        "  %first = getelementptr inbounds [20 x i8], ptr %digits, i32 0, i32 %at.back\n",
        "  call void @chibi_copy(ptr %dest, ptr %first, i32 %width)\n",
        "  %o.sum = add i32 %o.arg, %width\n",
        "  %o.signed = add i32 %o.sum, %sign.width\n",
        "  store i32 %o.signed, ptr %o.slot\n",
        "  br label %walk\n",
        "finish:\n",
        "  %o.final = load i32, ptr %o.slot\n",
        "  %r.bytes = getelementptr inbounds { ptr, i32, ptr }, ptr %result, i32 0, i32 0\n",
        "  store ptr %buffer, ptr %r.bytes\n",
        "  %r.length = getelementptr inbounds { ptr, i32, ptr }, ptr %result, i32 0, i32 1\n",
        "  store i32 %o.final, ptr %r.length\n",
        "  %r.owner = getelementptr inbounds { ptr, i32, ptr }, ptr %result, i32 0, i32 2\n",
        "  store ptr null, ptr %r.owner\n",
        "  ret void\n",
        "}\n"
    ]);
}

WindowsStart :: () -> string {
    return Join([
        WindowsPrelude(),
        "declare i32 @chibi_scalar()\n",
        "define void @mainCRTStartup() {\n",
        "  %line = call ptr @GetCommandLineW()\n",
        "  store ptr %line, ptr @chibi_command_line\n",
        "  %status = call i32 @chibi_scalar()\n",
        "  call void @ExitProcess(i32 %status)\n",
        "  unreachable\n",
        "}\n"
    ]);
}

WindowsContextStart :: () -> string {
    return Join([
        WindowsPrelude(),
        "declare dllimport ptr @GetProcessHeap()\n",
        "declare dllimport ptr @HeapAlloc(ptr, i32, i64)\n",
        "declare dllimport i32 @HeapFree(ptr, i32, ptr)\n",
        "declare dllimport ptr @GetStdHandle(i32)\n",
        "declare dllimport i32 @WriteFile(ptr, ptr, i32, ptr, ptr)\n",
        "declare i32 @chibi_scalar(ptr)\n",
        "@chibi_report_head = private unnamed_addr constant [29 x i8] c\"assertion failed in function \"\n",
        "@chibi_report_from = private unnamed_addr constant [17 x i8] c\" at source bytes \"\n",
        "@chibi_report_to = private unnamed_addr constant [4 x i8] c\" to \"\n",
        "@chibi_report_end = private unnamed_addr constant [1 x i8] c\"\\0A\"\n",
        RuntimeFormat(),
        "define internal ptr @chibi_allocate(ptr %ctx, i64 %size) {\n",
        "  %heap = call ptr @GetProcessHeap()\n",
        "  %memory = call ptr @HeapAlloc(ptr %heap, i32 8, i64 %size)\n",
        "  ret ptr %memory\n",
        "}\n",
        "define internal void @chibi_release(ptr %ctx, ptr %allocation) {\n",
        "  %heap = call ptr @GetProcessHeap()\n",
        "  %freed = call i32 @HeapFree(ptr %heap, i32 0, ptr %allocation)\n",
        "  ret void\n",
        "}\n",
        "define internal void @chibi_index_failed(ptr %ctx, i32 %index, i32 %length) {\n",
        "  call void @ExitProcess(i32 134)\n",
        "  unreachable\n",
        "}\n",
        "define internal void @chibi_write(ptr %bytes, i32 %count) {\n",
        "  %error = call ptr @GetStdHandle(i32 -12)\n",
        "  %written = alloca i32\n",
        "  %ignored = call i32 @WriteFile(ptr %error, ptr %bytes, i32 %count, ptr %written, ptr null)\n",
        "  ret void\n",
        "}\n",
        "define internal void @chibi_write_decimal(i64 %value) {\n",
        "entry:\n",
        "  %buffer = alloca [20 x i8]\n",
        "  br label %loop\n",
        "loop:\n",
        "  %rest = phi i64 [ %value, %entry ], [ %next, %loop ]\n",
        "  %at = phi i32 [ 20, %entry ], [ %back, %loop ]\n",
        "  %digit = urem i64 %rest, 10\n",
        "  %character = add i64 %digit, 48\n",
        "  %byte = trunc i64 %character to i8\n",
        "  %back = sub i32 %at, 1\n",
        "  %slot = getelementptr inbounds [20 x i8], ptr %buffer, i32 0, i32 %back\n",
        "  store i8 %byte, ptr %slot\n",
        "  %next = udiv i64 %rest, 10\n",
        "  %more = icmp ne i64 %next, 0\n",
        "  br i1 %more, label %loop, label %done\n",
        "done:\n",
        "  %first = getelementptr inbounds [20 x i8], ptr %buffer, i32 0, i32 %back\n",
        "  %count = sub i32 20, %back\n",
        "  call void @chibi_write(ptr %first, i32 %count)\n",
        "  ret void\n",
        "}\n",
        "@chibi_context = global { ptr, ptr, ptr, ptr, ptr } ",
        "{ ptr @chibi_format_text, ptr null, ptr @chibi_allocate, ptr @chibi_index_failed, ptr @chibi_release }\n",
        "define void @mainCRTStartup() {\n",
        "  %line = call ptr @GetCommandLineW()\n",
        "  store ptr %line, ptr @chibi_command_line\n",
        "  %status = call i32 @chibi_scalar(ptr @chibi_context)\n",
        "  %failure.at = getelementptr inbounds { ptr, ptr, ptr, ptr, ptr }, ptr @chibi_context, i32 0, i32 1\n",
        "  %failure = load ptr, ptr %failure.at\n",
        "  %failed = icmp ne ptr %failure, null\n",
        "  br i1 %failed, label %report, label %done\n",
        "report:\n",
        "  %function = load i64, ptr %failure\n",
        "  %start.at = getelementptr inbounds { i64, i32, i32 }, ptr %failure, i32 0, i32 1\n",
        "  %start = load i32, ptr %start.at\n",
        "  %end.at = getelementptr inbounds { i64, i32, i32 }, ptr %failure, i32 0, i32 2\n",
        "  %end = load i32, ptr %end.at\n",
        "  %start.wide = zext i32 %start to i64\n",
        "  %end.wide = zext i32 %end to i64\n",
        "  call void @chibi_write(ptr @chibi_report_head, i32 29)\n",
        "  call void @chibi_write_decimal(i64 %function)\n",
        "  call void @chibi_write(ptr @chibi_report_from, i32 17)\n",
        "  call void @chibi_write_decimal(i64 %start.wide)\n",
        "  call void @chibi_write(ptr @chibi_report_to, i32 4)\n",
        "  call void @chibi_write_decimal(i64 %end.wide)\n",
        "  call void @chibi_write(ptr @chibi_report_end, i32 1)\n",
        "  call void @ExitProcess(i32 134)\n",
        "  unreachable\n",
        "done:\n",
        "  call void @ExitProcess(i32 %status)\n",
        "  unreachable\n",
        "}\n"
    ]);
}

LinuxStart :: () -> string {
    return Join([
        "target triple = \"x86_64-unknown-linux-gnu\"\n",
        "module asm \".text\"\n",
        "module asm \".globl _start\"\n",
        "module asm \".type _start, @function\"\n",
        "module asm \"_start:\"\n",
        "module asm \"xorl %ebp, %ebp\"\n",
        "module asm \"movq (%rsp), %rax\"\n",
        "module asm \"movl %eax, chibi_argc(%rip)\"\n",
        "module asm \"leaq 8(%rsp), %rax\"\n",
        "module asm \"movq %rax, chibi_argv(%rip)\"\n",
        "module asm \"movq (%rsp), %rax\"\n",
        "module asm \"leaq 16(%rsp,%rax,8), %rax\"\n",
        "module asm \"movq %rax, chibi_envp(%rip)\"\n",
        "module asm \"andq $-16, %rsp\"\n",
        "module asm \"callq chibi_scalar\"\n",
        "module asm \"movl %eax, %edi\"\n",
        "module asm \"movl $231, %eax\"\n",
        "module asm \"syscall\"\n",
        "module asm \"ud2\"\n",
        "@chibi_argc = dso_local global i32 0\n",
        "@chibi_argv = dso_local global ptr null\n",
        "declare i32 @chibi_scalar()\n"
    ]);
}

DynamicStart :: (triple: string, context: bool) -> string {
    if (!context) {
        return Join([
            "target triple = \"", triple, "\"\n",
            "declare i32 @chibi_scalar()\n",
            "@chibi_argc = dso_local global i32 0\n",
            "@chibi_argv = dso_local global ptr null\n",
            "define i32 @main(i32 %argc, ptr %argv, ptr %envp) {\n",
            "  store i32 %argc, ptr @chibi_argc\n",
            "  store ptr %argv, ptr @chibi_argv\n",
            "  store ptr %envp, ptr @chibi_envp\n",
            "  %status = call i32 @chibi_scalar()\n",
            "  ret i32 %status\n",
            "}\n"
        ]);
    }
    return Join([
        "target triple = \"", triple, "\"\n",
        "declare ptr @calloc(i64, i64)\n",
        "declare void @free(ptr)\n",
        "declare void @abort() noreturn\n",
        "declare i32 @dprintf(i32, ptr, ...)\n",
        "@chibi_report = private unnamed_addr constant [59 x i8] ",
        "c\"assertion failed in function %lu at source bytes %d to %d\\0A\\00\"\n",
        "declare i32 @chibi_scalar(ptr)\n",
        RuntimeFormat(),
        "define internal ptr @chibi_allocate(ptr %ctx, i64 %size) {\n",
        "  %memory = call ptr @calloc(i64 1, i64 %size)\n",
        "  ret ptr %memory\n",
        "}\n",
        "define internal void @chibi_release(ptr %ctx, ptr %allocation) {\n",
        "  call void @free(ptr %allocation)\n",
        "  ret void\n",
        "}\n",
        "define internal void @chibi_index_failed(ptr %ctx, i32 %index, i32 %length) {\n",
        "  call void @abort()\n",
        "  unreachable\n",
        "}\n",
        "@chibi_context = global { ptr, ptr, ptr, ptr, ptr } ",
        "{ ptr @chibi_format_text, ptr null, ptr @chibi_allocate, ptr @chibi_index_failed, ptr @chibi_release }\n",
        "@chibi_argc = dso_local global i32 0\n",
        "@chibi_argv = dso_local global ptr null\n",
        "define i32 @main(i32 %argc, ptr %argv, ptr %envp) {\n",
        "  store i32 %argc, ptr @chibi_argc\n",
        "  store ptr %argv, ptr @chibi_argv\n",
            "  store ptr %envp, ptr @chibi_envp\n",
        "  %status = call i32 @chibi_scalar(ptr @chibi_context)\n",
        "  %failure.at = getelementptr inbounds { ptr, ptr, ptr, ptr, ptr }, ptr @chibi_context, i32 0, i32 1\n",
        "  %failure = load ptr, ptr %failure.at\n",
        "  %failed = icmp ne ptr %failure, null\n",
        "  br i1 %failed, label %report, label %done\n",
        "report:\n",
        "  %function = load i64, ptr %failure\n",
        "  %start.at = getelementptr inbounds { i64, i32, i32 }, ptr %failure, i32 0, i32 1\n",
        "  %start = load i32, ptr %start.at\n",
        "  %end.at = getelementptr inbounds { i64, i32, i32 }, ptr %failure, i32 0, i32 2\n",
        "  %end = load i32, ptr %end.at\n",
        "  call i32 (i32, ptr, ...) @dprintf(i32 2, ptr @chibi_report, i64 %function, i32 %start, i32 %end)\n",
        "  ret i32 134\n",
        "done:\n",
        "  ret i32 %status\n",
        "}\n"
    ]);
}

// The start module for the triple. A static Linux program has no C library, so
// it takes no context: "" for that combination and for a triple this link step
// does not know.
Module :: (triple: string, static: bool, context: bool) -> string {
    target := TargetOf(triple);
    if (target == WindowsX64 && context) {
        return WindowsContextStart();
    }
    if (target == WindowsX64) {
        return WindowsStart();
    }
    if (target == LinuxX64 && static && context) {
        return "";
    }
    if (target == LinuxX64 && static) {
        return LinuxStart();
    }
    if (target < 0) {
        return "";
    }
    return DynamicStart(triple, context);
}

// The process arguments as C-ABI functions, appended to every start module:
// chibi_argument_count() -> i64; chibi_argument(index, buffer, size) -> i64 copies up to
// `size` bytes of argument `index` (no NUL) and returns its whole length, -1 for an
// index out of range; chibi_environment() -> ptr is the environment block (the envp
// array; null on Windows, which reads it through the system).
PosixArguments :: () -> string {
    return Join([
        "@chibi_envp = dso_local global ptr null\n",
        "define i64 @chibi_argument_count() {\n",
        "  %n = load i32, ptr @chibi_argc\n",
        "  %w = sext i32 %n to i64\n",
        "  ret i64 %w\n",
        "}\n",
        "define ptr @chibi_environment() {\n",
        "  %e = load ptr, ptr @chibi_envp\n",
        "  ret ptr %e\n",
        "}\n",
        "define i64 @chibi_argument(i64 %index, ptr %buffer, i64 %size) {\n",
        "entry:\n",
        "  %count32 = load i32, ptr @chibi_argc\n",
        "  %count = sext i32 %count32 to i64\n",
        "  %below = icmp slt i64 %index, 0\n",
        "  %above = icmp sge i64 %index, %count\n",
        "  %bad = or i1 %below, %above\n",
        "  br i1 %bad, label %missing, label %found\n",
        "missing:\n",
        "  ret i64 -1\n",
        "found:\n",
        "  %argv = load ptr, ptr @chibi_argv\n",
        "  %slot = getelementptr inbounds ptr, ptr %argv, i64 %index\n",
        "  %text = load ptr, ptr %slot\n",
        "  br label %measure\n",
        "measure:\n",
        "  %length = phi i64 [ 0, %found ], [ %next, %measure ]\n",
        "  %at = getelementptr inbounds i8, ptr %text, i64 %length\n",
        "  %byte = load i8, ptr %at\n",
        "  %end = icmp eq i8 %byte, 0\n",
        "  %next = add i64 %length, 1\n",
        "  br i1 %end, label %copy, label %measure\n",
        "copy:\n",
        "  %limit = icmp ult i64 %length, %size\n",
        "  %bytes = select i1 %limit, i64 %length, i64 %size\n",
        "  br label %loop\n",
        "loop:\n",
        "  %i = phi i64 [ 0, %copy ], [ %step, %body ]\n",
        "  %done = icmp uge i64 %i, %bytes\n",
        "  br i1 %done, label %finish, label %body\n",
        "body:\n",
        "  %from = getelementptr inbounds i8, ptr %text, i64 %i\n",
        "  %b = load i8, ptr %from\n",
        "  %to = getelementptr inbounds i8, ptr %buffer, i64 %i\n",
        "  store i8 %b, ptr %to\n",
        "  %step = add i64 %i, 1\n",
        "  br label %loop\n",
        "finish:\n",
        "  ret i64 %length\n",
        "}\n"
    ]);
}

// Windows: the same functions over the UTF-16 command line, split by the C
// runtime's rules (the program name ends at the first quote or white space; a quote
// toggles quoting; 2n backslashes before a quote are n, an odd one makes the quote
// literal) and encoded as UTF-8.
// The LLVM IR that splits a UTF-16 command line into arguments and encodes them as
// UTF-8: chibi_command_argument(line, index, buffer, size) -> i64 and
// chibi_command_count(line) -> i64. It touches no system function, so test/native_aot/link
// runs it on any host.
pub CommandLineParser :: () -> string {
    return Join([
        "define internal i64 @chibi_utf8(i32 %cp, ptr %out) {\n",
        "entry:\n",
        "  %one = icmp ult i32 %cp, 128\n",
        "  br i1 %one, label %one.byte, label %not.one\n",
        "one.byte:\n",
        "  %b0 = trunc i32 %cp to i8\n",
        "  store i8 %b0, ptr %out\n",
        "  ret i64 1\n",
        "not.one:\n",
        "  %two = icmp ult i32 %cp, 2048\n",
        "  br i1 %two, label %two.bytes, label %not.two\n",
        "two.bytes:\n",
        "  %t0 = lshr i32 %cp, 6\n",
        "  %t0o = or i32 %t0, 192\n",
        "  %t0b = trunc i32 %t0o to i8\n",
        "  store i8 %t0b, ptr %out\n",
        "  %t1 = and i32 %cp, 63\n",
        "  %t1o = or i32 %t1, 128\n",
        "  %t1b = trunc i32 %t1o to i8\n",
        "  %t1p = getelementptr inbounds i8, ptr %out, i64 1\n",
        "  store i8 %t1b, ptr %t1p\n",
        "  ret i64 2\n",
        "not.two:\n",
        "  %three = icmp ult i32 %cp, 65536\n",
        "  br i1 %three, label %three.bytes, label %four.bytes\n",
        "three.bytes:\n",
        "  %h0 = lshr i32 %cp, 12\n",
        "  %h0o = or i32 %h0, 224\n",
        "  %h0b = trunc i32 %h0o to i8\n",
        "  store i8 %h0b, ptr %out\n",
        "  %h1 = lshr i32 %cp, 6\n",
        "  %h1m = and i32 %h1, 63\n",
        "  %h1o = or i32 %h1m, 128\n",
        "  %h1b = trunc i32 %h1o to i8\n",
        "  %h1p = getelementptr inbounds i8, ptr %out, i64 1\n",
        "  store i8 %h1b, ptr %h1p\n",
        "  %h2 = and i32 %cp, 63\n",
        "  %h2o = or i32 %h2, 128\n",
        "  %h2b = trunc i32 %h2o to i8\n",
        "  %h2p = getelementptr inbounds i8, ptr %out, i64 2\n",
        "  store i8 %h2b, ptr %h2p\n",
        "  ret i64 3\n",
        "four.bytes:\n",
        "  %f0 = lshr i32 %cp, 18\n",
        "  %f0o = or i32 %f0, 240\n",
        "  %f0b = trunc i32 %f0o to i8\n",
        "  store i8 %f0b, ptr %out\n",
        "  %f1 = lshr i32 %cp, 12\n",
        "  %f1m = and i32 %f1, 63\n",
        "  %f1o = or i32 %f1m, 128\n",
        "  %f1b = trunc i32 %f1o to i8\n",
        "  %f1p = getelementptr inbounds i8, ptr %out, i64 1\n",
        "  store i8 %f1b, ptr %f1p\n",
        "  %f2 = lshr i32 %cp, 6\n",
        "  %f2m = and i32 %f2, 63\n",
        "  %f2o = or i32 %f2m, 128\n",
        "  %f2b = trunc i32 %f2o to i8\n",
        "  %f2p = getelementptr inbounds i8, ptr %out, i64 2\n",
        "  store i8 %f2b, ptr %f2p\n",
        "  %f3 = and i32 %cp, 63\n",
        "  %f3o = or i32 %f3, 128\n",
        "  %f3b = trunc i32 %f3o to i8\n",
        "  %f3p = getelementptr inbounds i8, ptr %out, i64 3\n",
        "  store i8 %f3b, ptr %f3p\n",
        "  ret i64 4\n",
        "}\n",
        "define internal i64 @chibi_decode(ptr %line, i64 %p, ptr %cp) {\n",
        "entry:\n",
        "  %at = getelementptr inbounds i16, ptr %line, i64 %p\n",
        "  %unit16 = load i16, ptr %at\n",
        "  %u = zext i16 %unit16 to i32\n",
        "  %not.low = icmp ult i32 %u, 55296\n",
        "  %past = icmp ugt i32 %u, 57343\n",
        "  %plain = or i1 %not.low, %past\n",
        "  br i1 %plain, label %single, label %surrogate\n",
        "single:\n",
        "  store i32 %u, ptr %cp\n",
        "  ret i64 1\n",
        "surrogate:\n",
        "  %is.high = icmp ult i32 %u, 56320\n",
        "  br i1 %is.high, label %pair, label %lone\n",
        "pair:\n",
        "  %next = add i64 %p, 1\n",
        "  %nat = getelementptr inbounds i16, ptr %line, i64 %next\n",
        "  %low16 = load i16, ptr %nat\n",
        "  %low = zext i16 %low16 to i32\n",
        "  %low.lo = icmp uge i32 %low, 56320\n",
        "  %low.hi = icmp ule i32 %low, 57343\n",
        "  %is.low = and i1 %low.lo, %low.hi\n",
        "  br i1 %is.low, label %combine, label %lone\n",
        "combine:\n",
        "  %hi.bits = sub i32 %u, 55296\n",
        "  %hi.shift = shl i32 %hi.bits, 10\n",
        "  %lo.bits = sub i32 %low, 56320\n",
        "  %sum = add i32 %hi.shift, %lo.bits\n",
        "  %scalar = add i32 %sum, 65536\n",
        "  store i32 %scalar, ptr %cp\n",
        "  ret i64 2\n",
        "lone:\n",
        "  store i32 65533, ptr %cp\n",
        "  ret i64 1\n",
        "}\n",
        "define internal void @chibi_emit(i32 %cp, i1 %want, ptr %buffer, i64 %size, ptr %out) {\n",
        "entry:\n",
        "  br i1 %want, label %encode, label %skip\n",
        "skip:\n",
        "  ret void\n",
        "encode:\n",
        "  %scratch = alloca [4 x i8]\n",
        "  %count = call i64 @chibi_utf8(i32 %cp, ptr %scratch)\n",
        "  br label %loop\n",
        "loop:\n",
        "  %i = phi i64 [ 0, %encode ], [ %step, %next ]\n",
        "  %done = icmp uge i64 %i, %count\n",
        "  br i1 %done, label %finish, label %body\n",
        "body:\n",
        "  %at = load i64, ptr %out\n",
        "  %room = icmp ult i64 %at, %size\n",
        "  br i1 %room, label %store, label %next\n",
        "store:\n",
        "  %from = getelementptr inbounds i8, ptr %scratch, i64 %i\n",
        "  %b = load i8, ptr %from\n",
        "  %to = getelementptr inbounds i8, ptr %buffer, i64 %at\n",
        "  store i8 %b, ptr %to\n",
        "  br label %next\n",
        "next:\n",
        "  %at2 = load i64, ptr %out\n",
        "  %at3 = add i64 %at2, 1\n",
        "  store i64 %at3, ptr %out\n",
        "  %step = add i64 %i, 1\n",
        "  br label %loop\n",
        "finish:\n",
        "  ret void\n",
        "}\n",
        "define internal i64 @chibi_command_argument(ptr %line, i64 %index, ptr %buffer, i64 %size) {\n",
        "entry:\n",
        "  %p = alloca i64\n",
        "  %arg = alloca i64\n",
        "  %out = alloca i64\n",
        "  %cp = alloca i32\n",
        "  %quoted = alloca i1\n",
        "  %slashes = alloca i64\n",
        "  store i64 0, ptr %p\n",
        "  store i64 0, ptr %arg\n",
        "  store i64 0, ptr %out\n",
        "  %first = load i16, ptr %line\n",
        "  %opens = icmp eq i16 %first, 34\n",
        "  %name.want = icmp eq i64 %index, 0\n",
        "  br i1 %opens, label %name.quoted, label %name.plain\n",
        "name.quoted:\n",
        "  store i64 1, ptr %p\n",
        "  br label %name.quoted.loop\n",
        "name.quoted.loop:\n",
        "  %nq.p = load i64, ptr %p\n",
        "  %nq.at = getelementptr inbounds i16, ptr %line, i64 %nq.p\n",
        "  %nq.u = load i16, ptr %nq.at\n",
        "  %nq.end = icmp eq i16 %nq.u, 0\n",
        "  %nq.close = icmp eq i16 %nq.u, 34\n",
        "  %nq.stop = or i1 %nq.end, %nq.close\n",
        "  br i1 %nq.stop, label %name.quoted.end, label %name.quoted.take\n",
        "name.quoted.take:\n",
        "  %nq.used = call i64 @chibi_decode(ptr %line, i64 %nq.p, ptr %cp)\n",
        "  %nq.cp = load i32, ptr %cp\n",
        "  call void @chibi_emit(i32 %nq.cp, i1 %name.want, ptr %buffer, i64 %size, ptr %out)\n",
        "  %nq.next = add i64 %nq.p, %nq.used\n",
        "  store i64 %nq.next, ptr %p\n",
        "  br label %name.quoted.loop\n",
        "name.quoted.end:\n",
        "  br i1 %nq.close, label %name.quoted.skip, label %name.done\n",
        "name.quoted.skip:\n",
        "  %nq.after = add i64 %nq.p, 1\n",
        "  store i64 %nq.after, ptr %p\n",
        "  br label %name.done\n",
        "name.plain:\n",
        "  br label %name.plain.loop\n",
        "name.plain.loop:\n",
        "  %np.p = load i64, ptr %p\n",
        "  %np.at = getelementptr inbounds i16, ptr %line, i64 %np.p\n",
        "  %np.u = load i16, ptr %np.at\n",
        "  %np.end = icmp eq i16 %np.u, 0\n",
        "  %np.space = icmp eq i16 %np.u, 32\n",
        "  %np.tab = icmp eq i16 %np.u, 9\n",
        "  %np.white = or i1 %np.space, %np.tab\n",
        "  %np.stop = or i1 %np.end, %np.white\n",
        "  br i1 %np.stop, label %name.done, label %name.plain.take\n",
        "name.plain.take:\n",
        "  %np.used = call i64 @chibi_decode(ptr %line, i64 %np.p, ptr %cp)\n",
        "  %np.cp = load i32, ptr %cp\n",
        "  call void @chibi_emit(i32 %np.cp, i1 %name.want, ptr %buffer, i64 %size, ptr %out)\n",
        "  %np.next = add i64 %np.p, %np.used\n",
        "  store i64 %np.next, ptr %p\n",
        "  br label %name.plain.loop\n",
        "name.done:\n",
        "  br i1 %name.want, label %answer, label %arguments\n",
        "answer:\n",
        "  %name.length = load i64, ptr %out\n",
        "  ret i64 %name.length\n",
        "arguments:\n",
        "  br label %next.argument\n",
        "next.argument:\n",
        "  br label %skip.white\n",
        "skip.white:\n",
        "  %sw.p = load i64, ptr %p\n",
        "  %sw.at = getelementptr inbounds i16, ptr %line, i64 %sw.p\n",
        "  %sw.u = load i16, ptr %sw.at\n",
        "  %sw.space = icmp eq i16 %sw.u, 32\n",
        "  %sw.tab = icmp eq i16 %sw.u, 9\n",
        "  %sw.white = or i1 %sw.space, %sw.tab\n",
        "  br i1 %sw.white, label %skip.step, label %skip.done\n",
        "skip.step:\n",
        "  %sw.next = add i64 %sw.p, 1\n",
        "  store i64 %sw.next, ptr %p\n",
        "  br label %skip.white\n",
        "skip.done:\n",
        "  %sd.end = icmp eq i16 %sw.u, 0\n",
        "  br i1 %sd.end, label %missing, label %begin\n",
        "missing:\n",
        "  ret i64 -1\n",
        "begin:\n",
        "  %arg.old = load i64, ptr %arg\n",
        "  %arg.new = add i64 %arg.old, 1\n",
        "  store i64 %arg.new, ptr %arg\n",
        "  %want = icmp eq i64 %arg.new, %index\n",
        "  store i1 false, ptr %quoted\n",
        "  br label %scan\n",
        "scan:\n",
        "  store i64 0, ptr %slashes\n",
        "  br label %count\n",
        "count:\n",
        "  %c.p = load i64, ptr %p\n",
        "  %c.at = getelementptr inbounds i16, ptr %line, i64 %c.p\n",
        "  %c.u = load i16, ptr %c.at\n",
        "  %c.slash = icmp eq i16 %c.u, 92\n",
        "  br i1 %c.slash, label %count.step, label %counted\n",
        "count.step:\n",
        "  %c.n = load i64, ptr %slashes\n",
        "  %c.n1 = add i64 %c.n, 1\n",
        "  store i64 %c.n1, ptr %slashes\n",
        "  %c.next = add i64 %c.p, 1\n",
        "  store i64 %c.next, ptr %p\n",
        "  br label %count\n",
        "counted:\n",
        "  %n = load i64, ptr %slashes\n",
        "  %quote = icmp eq i16 %c.u, 34\n",
        "  br i1 %quote, label %before.quote, label %literal.slashes\n",
        "before.quote:\n",
        "  %half = lshr i64 %n, 1\n",
        "  br label %half.loop\n",
        "half.loop:\n",
        "  %hi = phi i64 [ 0, %before.quote ], [ %hi.next, %half.body ]\n",
        "  %hdone = icmp uge i64 %hi, %half\n",
        "  br i1 %hdone, label %half.done, label %half.body\n",
        "half.body:\n",
        "  call void @chibi_emit(i32 92, i1 %want, ptr %buffer, i64 %size, ptr %out)\n",
        "  %hi.next = add i64 %hi, 1\n",
        "  br label %half.loop\n",
        "half.done:\n",
        "  %odd.bit = and i64 %n, 1\n",
        "  %odd = icmp ne i64 %odd.bit, 0\n",
        "  %q.p = load i64, ptr %p\n",
        "  %q.next = add i64 %q.p, 1\n",
        "  store i64 %q.next, ptr %p\n",
        "  br i1 %odd, label %literal.quote, label %toggle.quote\n",
        "literal.quote:\n",
        "  call void @chibi_emit(i32 34, i1 %want, ptr %buffer, i64 %size, ptr %out)\n",
        "  br label %after.unit\n",
        "toggle.quote:\n",
        "  %was = load i1, ptr %quoted\n",
        "  %now = xor i1 %was, true\n",
        "  store i1 %now, ptr %quoted\n",
        "  br label %after.unit\n",
        "literal.slashes:\n",
        "  br label %slash.loop\n",
        "slash.loop:\n",
        "  %si = phi i64 [ 0, %literal.slashes ], [ %si.next, %slash.body ]\n",
        "  %sdone = icmp uge i64 %si, %n\n",
        "  br i1 %sdone, label %slash.done, label %slash.body\n",
        "slash.body:\n",
        "  call void @chibi_emit(i32 92, i1 %want, ptr %buffer, i64 %size, ptr %out)\n",
        "  %si.next = add i64 %si, 1\n",
        "  br label %slash.loop\n",
        "slash.done:\n",
        "  %e.p = load i64, ptr %p\n",
        "  %e.at = getelementptr inbounds i16, ptr %line, i64 %e.p\n",
        "  %e.u = load i16, ptr %e.at\n",
        "  %e.end = icmp eq i16 %e.u, 0\n",
        "  br i1 %e.end, label %finish, label %ordinary\n",
        "ordinary:\n",
        "  %e.space = icmp eq i16 %e.u, 32\n",
        "  %e.tab = icmp eq i16 %e.u, 9\n",
        "  %e.white = or i1 %e.space, %e.tab\n",
        "  %e.in = load i1, ptr %quoted\n",
        "  %e.not.in = xor i1 %e.in, true\n",
        "  %e.split = and i1 %e.white, %e.not.in\n",
        "  br i1 %e.split, label %finish, label %take\n",
        "take:\n",
        "  %t.used = call i64 @chibi_decode(ptr %line, i64 %e.p, ptr %cp)\n",
        "  %t.cp = load i32, ptr %cp\n",
        "  call void @chibi_emit(i32 %t.cp, i1 %want, ptr %buffer, i64 %size, ptr %out)\n",
        "  %t.next = add i64 %e.p, %t.used\n",
        "  store i64 %t.next, ptr %p\n",
        "  br label %scan\n",
        "after.unit:\n",
        "  %a.p = load i64, ptr %p\n",
        "  %a.at = getelementptr inbounds i16, ptr %line, i64 %a.p\n",
        "  %a.u = load i16, ptr %a.at\n",
        "  %a.end = icmp eq i16 %a.u, 0\n",
        "  br i1 %a.end, label %finish, label %after.check\n",
        "after.check:\n",
        "  %a.space = icmp eq i16 %a.u, 32\n",
        "  %a.tab = icmp eq i16 %a.u, 9\n",
        "  %a.white = or i1 %a.space, %a.tab\n",
        "  %a.in = load i1, ptr %quoted\n",
        "  %a.not.in = xor i1 %a.in, true\n",
        "  %a.split = and i1 %a.white, %a.not.in\n",
        "  br i1 %a.split, label %finish, label %scan\n",
        "finish:\n",
        "  br i1 %want, label %done.wanted, label %next.argument\n",
        "done.wanted:\n",
        "  %length = load i64, ptr %out\n",
        "  ret i64 %length\n",
        "}\n",
        "define internal i64 @chibi_command_count(ptr %line) {\n",
        "entry:\n",
        "  br label %loop\n",
        "loop:\n",
        "  %i = phi i64 [ 0, %entry ], [ %next, %step ]\n",
        "  %length = call i64 @chibi_command_argument(ptr %line, i64 %i, ptr null, i64 0)\n",
        "  %missing = icmp slt i64 %length, 0\n",
        "  br i1 %missing, label %done, label %step\n",
        "step:\n",
        "  %next = add i64 %i, 1\n",
        "  br label %loop\n",
        "done:\n",
        "  ret i64 %i\n",
        "}\n"
    ]);
}

WindowsArguments :: () -> string {
    return Join([
        CommandLineParser(),
        "define i64 @chibi_argument_count() {\n",
        "  %line = load ptr, ptr @chibi_command_line\n",
        "  %n = call i64 @chibi_command_count(ptr %line)\n",
        "  ret i64 %n\n",
        "}\n",
        "define ptr @chibi_environment() {\n",
        "  ret ptr null\n",
        "}\n",
        "define i64 @chibi_argument(i64 %index, ptr %buffer, i64 %size) {\n",
        "  %line = load ptr, ptr @chibi_command_line\n",
        "  %n = call i64 @chibi_command_argument(ptr %line, i64 %index, ptr %buffer, i64 %size)\n",
        "  ret i64 %n\n",
        "}\n"
    ]);
}

// What a start module for `triple` imports from system libraries: on Windows
// the kernel32 functions its `declare dllimport` lines name, with or without
// a context, which the link's kernel32 stub exports. Other start modules take
// theirs from the C library. A test holds this list to the modules.
pub StartImports :: (triple: string) -> Import {
    if (TargetOf(triple) != WindowsX64) {
        none: Import = {name: "", symbols: []};
        return none;
    }
    kernel32: Import = {name: "kernel32",
                        symbols: ["ExitProcess", "GetCommandLineW", "GetProcessHeap", "HeapAlloc", "HeapFree", "GetStdHandle",
                                  "WriteFile"]};
    return kernel32;
}

pub Start :: (triple: string, static: bool, context: bool) -> string {
    module := Module(triple, static, context);
    if (module == "") {
        return "";
    }
    if (TargetOf(triple) == WindowsX64) {
        return Join([module, WindowsArguments()]);
    }
    return Join([module, PosixArguments()]);
}
package native_link_host

import link "project:native_link"
import os "core:os"
import strings "core:strings"

// The effects of the link step: finding the LLVM tools and the C library's
// start files, writing the macOS stubs and running the tools. Everything it
// runs comes from native_link, which has no effects and is tested on its own.

Join :: (parts: string[]) -> string {
    return strings.Join(parts, "");
}

Fail :: (kind: int, code: int) -> link.Error {
    failed: link.Error = {kind: kind, code: code};
    return failed;
}

// The LLVM tool `name` in the LLVM folder, "" when it is not there. A Windows
// folder holds name.exe, and a distribution's lld tools are links to lld.
pub Tool :: (llvm: string, name: string) -> string {
    for (candidate in [Join([llvm, "/", name]), Join([llvm, "/", name, ".exe"])]) {
        kind := os.Kind(candidate);
        if (kind == os.KindFile || kind == os.KindLink) {
            return candidate;
        }
    }
    return "";
}

pub Object :: (llvm: string, module: string, object: string, level: int) -> link.Error? {
    llc := Tool(llvm, "llc");
    if (llc == "") {
        return Fail(link.MissingTool, 0);
    }
    status := os.Run(link.ObjectCommand(llc, module, object, level));
    if (status != 0) {
        return Fail(link.ToolFailed, status);
    }
    return nil;
}

// The folder with the C library's start files and development library, and
// the dynamic linker's path, on a Linux system; empty strings when it has none.
pub Libc :: () -> (folder: string, interpreter: string) {
    for (folder in link.LibcFolders()) {
        complete := true;
        for (name in link.LibcFiles()) {
            complete = complete && os.IsFile(Join([folder, "/", name]));
        }
        if (!complete) {
            continue;
        }
        for (interpreter in link.Interpreters()) {
            if (os.Exists(interpreter)) {
                return (folder, interpreter);
            }
        }
    }
    return ("", "");
}

// The plan with what the system provides filled in.
pub Discover :: (plan: link.Plan) -> link.Plan {
    found := plan;
    if (link.TargetOf(plan.triple) == link.LinuxX64 && !plan.static && plan.libc == "") {
        located := Libc();
        found.libc = located.folder;
        found.interpreter = located.interpreter;
    }
    return found;
}

Write :: (path: string, text: string) -> bool {
    return os.WriteText(path, text) == nil;
}

// The link itself, with the stubs written into plan.work.
Build :: (plan: link.Plan) -> link.Error? {
    target := link.TargetOf(plan.triple);
    if (target < 0) {
        return Fail(link.BadTriple, 0);
    }
    if (length(plan.objects) == 0 || plan.output == "") {
        return Fail(link.BadPlan, 0);
    }
    if (Tool(plan.llvm, link.Linker(target)) == "") {
        return Fail(link.MissingTool, 0);
    }
    ready := Discover(plan);
    if (target == link.LinuxX64 && !plan.static && ready.libc == "") {
        return Fail(link.MissingLibc, 0);
    }
    // The stubs, and on Windows the import libraries lld-link writes from them.
    for (stub in link.Imports(ready)) {
        if (!Write(link.ImportPath(ready, stub.name), link.ImportText(ready, stub))) {
            return Fail(link.CannotWrite, 0);
        }
        made := link.ImportCommand(ready, stub.name);
        if (length(made) > 0) {
            made[0] = Tool(plan.llvm, "lld-link");
            written := os.Run(made);
            if (written != 0) {
                return Fail(link.ToolFailed, written);
            }
        }
    }
    partial := link.Partial(ready);
    if (os.Exists(partial) && os.Remove(partial) != nil) {
        return Fail(link.CannotWrite, 0);
    }
    command := link.Command(ready, partial);
    command[0] = Tool(plan.llvm, link.Linker(target));
    status := os.Run(command);
    if (status != 0) {
        if (os.Exists(partial) && os.Remove(partial) != nil) {
            return Fail(link.CannotWrite, 0);
        }
        return Fail(link.ToolFailed, status);
    }
    if (os.Rename(partial, plan.output) != nil) {
        return Fail(link.CannotWrite, 0);
    }
    return nil;
}

// The files Build leaves in the work folder.
Leftovers :: (plan: link.Plan) -> string[] {
    names: string[] = [link.Partial(plan)];
    for (stub in link.Imports(plan)) {
        names.append(link.ImportPath(plan, stub.name));
        if (length(link.ImportCommand(plan, stub.name)) > 0) {
            names.append(link.ImportLibrary(plan, stub.name));
        }
    }
    return names;
}

// Links the plan's program and publishes it at `output`, replacing nothing
// until the link has succeeded. Nothing else outlives the call: the work
// folder, `output.work` unless the plan names one, holds only the stubs and is
// removed with them. No path, time or process id reaches the program's bytes.
pub Link :: (plan: link.Plan) -> link.Error? {
    ready := plan;
    own := false;
    if (plan.work == "") {
        ready.work = Join([plan.output, ".work"]);
        own = true;
    }
    if (os.Kind(ready.work) == os.KindNone) {
        if (os.MakeDirectory(ready.work) != nil) {
            return Fail(link.CannotWrite, 0);
        }
    } else {
        own = false;
    }
    failure := Build(ready);
    cleaned := true;
    for (path in Leftovers(ready)) {
        cleaned = cleaned && (!os.Exists(path) || os.Remove(path) == nil);
    }
    if (own) {
        cleaned = cleaned && (!os.Exists(ready.work) || os.Remove(ready.work) == nil);
    }
    if (failure != nil) {
        return failure;
    }
    if (!cleaned) {
        return Fail(link.CannotWrite, 0);
    }
    return nil;
}
package os

import target "core:target"

// Files, directories, processes and the environment, as Odin's core:os offers
// them. On the VM every operation is the build host's native underneath; in a
// native program (core:target's Native) it is the platform's libc or kernel32
// through core:sys/posix or core:sys/windows. One set of signatures serves
// both, so a package imports core:os and compiles either way. A native
// program has no Stamp, Copy, Reserve, Publish, RealPath, HashFile, Root,
// ProgramDirectory, Start, Kill, FindExecutable, Environment or Platform yet.
//
// Paths are relative to the program's root unless absolute. A fallible
// operation reports an expected failure of the file system or a process as
// an Error and leaves its other results empty. A bug (an invalid argument)
// stops the program.

pub NotFound: int : 1;
pub Permission: int : 2;
pub AlreadyExists: int : 3;
pub Failed: int : 4;

@error
pub Error :: struct {
    kind: int;
    code: int;
}

pub KindNone: int : 0;
pub KindFile: int : 1;
pub KindDirectory: int : 2;
pub KindLink: int : 3;
pub KindOther: int : 4;

// A finished child process. `status` is its exit status; a nonzero status is
// not an Error.
pub Result :: struct {
    status: int;
    stdout: string;
    stderr: string;
}

Failure :: (kind: int) -> Error {
    failed: Error = {kind: kind, code: 0};
    return failed;
}

