pub KindNone: int : 0;
pub KindFile: int : 1;
pub KindDirectory: int : 2;
pub KindLink: int : 3;
pub KindOther: int : 4;

Utf8: u32 : 65001;
InvalidAttributes: u32 : 4294967295;
DirectoryAttribute: u32 : 16;
LinkAttribute: u32 : 1024;
ReadAccess: u32 : 2147483648;
WriteAccess: u32 : 1073741824;
ShareAll: u32 : 7;
CreateAlways: u32 : 2;
OpenExisting: u32 : 3;
ReplaceExisting: u32 : 1;
ReadChunk: int : 65536;
FindDataUnits: int : 296;
FindNameUnit: int : 22;
FindNameUnits: int : 260;
Infinite: u32 : 4294967295;
UseStandardHandles: u32 : 256;

// A zeroed block for a structure the program only passes along.
Block :: (size: int) -> u8[] {
    block: u8[] = [];
    for index in 0..<size {
        block.append(0);
    }
    return block;
}

// The UTF-16 units of `text` and a terminating NUL.
Wide :: (text: string) -> u16[] {
    wide: u16[] = [];
    size := MultiByteToWideChar(Utf8, 0, text, -1, wide, 0);
    for index in 0..<int(size) {
        wide.append(0);
    }
    converted := MultiByteToWideChar(Utf8, 0, text, -1, wide, size);
    assert(converted == size, "the string converts");
    return wide;
}

// The text of the first `count` UTF-16 units of `wide`.
Narrow :: (wide: u16[], count: int) -> string {
    if count == 0 {
        return "";
    }
    none: u8[] = [];
    size := WideCharToMultiByte(Utf8, 0, wide, i32(count), none, 0, 0, 0);
    buffer := Block(int(size));
    converted := WideCharToMultiByte(Utf8, 0, wide, i32(count), buffer, size, 0, 0);
    return text_from_bytes(buffer);
}

// The attribute bits of the path, InvalidAttributes when it does not exist.
Attributes :: (path: string) -> u32 {
    return GetFileAttributesW(Wide(path));
}

// Whether the path names anything.
pub Exists :: (path: string) -> bool {
    return Attributes(path) != InvalidAttributes;
}

// What the path names, KindNone when nothing. A link is not followed.
pub Kind :: (path: string) -> int {
    attributes := Attributes(path);
    if attributes == InvalidAttributes {
        return KindNone;
    }
    if (attributes & LinkAttribute) != 0 {
        return KindLink;
    }
    if (attributes & DirectoryAttribute) != 0 {
        return KindDirectory;
    }
    return KindFile;
}

pub MakeDirectory :: (path: string) -> bool {
    return CreateDirectoryW(Wide(path), 0) != 0;
}

// Removes a file or link, or an empty directory.
pub Remove :: (path: string) -> bool {
    if Kind(path) == KindDirectory {
        return RemoveDirectoryW(Wide(path)) != 0;
    }
    return DeleteFileW(Wide(path)) != 0;
}

// Renames, replacing an existing destination as rename does elsewhere.
pub Rename :: (source: string, destination: string) -> bool {
    return MoveFileExW(Wide(source), Wide(destination), ReplaceExisting) != 0;
}

// The file's size in bytes, -1 when it cannot be opened.
pub FileSize :: (path: string) -> int {
    handle := CreateFileW(Wide(path), ReadAccess, ShareAll, 0, OpenExisting, 0, 0);
    if ~handle == 0 {
        return -1;
    }
    size := Block(8);
    found := GetFileSizeEx(handle, size);
    closed := CloseHandle(handle);
    if found == 0 {
        return -1;
    }
    total := 0;
    for index in 0..<8 {
        total += int(size[index]) << u32(8 * index);
    }
    return total;
}

// The file's bytes, including NUL and malformed UTF-8; no bytes when it cannot
// be read (FileSize tells that from an empty file).
pub ReadBytes :: (path: string) -> u8[] {
    contents: u8[] = [];
    handle := CreateFileW(Wide(path), ReadAccess, ShareAll, 0, OpenExisting, 0, 0);
    if ~handle == 0 {
        return contents;
    }
    chunk := Block(ReadChunk);
    read: u32[] = [0];
    while true {
        if ReadFile(handle, chunk, u32(ReadChunk), read, 0) == 0 {
            contents = [];
            break;
        }
        count := int(read[0]);
        if count == 0 {
            break;
        }
        for index in 0..<count {
            contents.append(chunk[index]);
        }
    }
    closed := CloseHandle(handle);
    return contents;
}

// Replaces the file with the bytes; false when it cannot be written whole.
pub WriteBytes :: (path: string, data: u8[]) -> bool {
    handle := CreateFileW(Wide(path), WriteAccess, ShareAll, 0, CreateAlways, 0, 0);
    if ~handle == 0 {
        return false;
    }
    written: u32[] = [0];
    done := true;
    if length(data) > 0 {
        done = WriteFile(handle, data, u32(length(data)), written, 0) != 0 && int(written[0]) == length(data);
    }
    closed := CloseHandle(handle);
    return done && closed != 0;
}

// The bytes of the text, a copy.
Bytes :: (text: string) -> u8[] {
    data: u8[] = [];
    size := text_byte_length(text);
    for index in 0..<size {
        data.append(u8(text_byte_at(text, index)));
    }
    return data;
}

// Writes the line and a newline to standard error, as build reports do; false
// when it cannot be written whole.
pub Print :: (line: string) -> bool {
    data := Bytes(line);
    data.append(10);
    written: u32[] = [0];
    done := WriteFile(GetStdHandle(-12), data, u32(length(data)), written, 0);
    return done != 0 && int(written[0]) == length(data);
}

// Replaces the file with the text; false when it cannot be written whole.
pub WriteText :: (path: string, text: string) -> bool {
    return WriteBytes(path, Bytes(text));
}

pub IsFile :: (path: string) -> bool {
    return Kind(path) == KindFile;
}

pub IsDirectory :: (path: string) -> bool {
    return Kind(path) == KindDirectory;
}

// Ends the process with the exit status; it does not return.
pub Exit :: (code: int) -> int {
    return int(ExitProcess(u32(code)));
}

// The text of the bytes, which may hold NUL and malformed UTF-8.
pub Text :: (data: u8[]) -> string {
    return text_from_bytes(data);
}

// The file's text, "" when it cannot be read.
pub ReadText :: (path: string) -> string {
    return text_from_bytes(ReadBytes(path));
}

// The environment variable's value, "" when it is unset.
pub Getenv :: (name: string) -> string {
    none: u16[] = [];
    wide := Wide(name);
    size := GetEnvironmentVariableW(wide, none, 0);
    if size == 0 {
        return "";
    }
    buffer: u16[] = [];
    for index in 0..<int(size) {
        buffer.append(0);
    }
    count := GetEnvironmentVariableW(wide, buffer, size);
    return Narrow(buffer, int(count));
}

// The names in the directory, in the order the system gives them and without
// "." and "..". Empty when it cannot be opened (Kind tells a missing directory
// from an empty one).
pub List :: (path: string) -> string[] {
    names: string[] = [];
    data: u16[] = [];
    for index in 0..<FindDataUnits {
        data.append(0);
    }
    pattern := Wide(path);
    pattern[length(pattern) - 1] = 92;
    pattern.append(42);
    pattern.append(0);
    handle := FindFirstFileW(pattern, data);
    if ~handle == 0 {
        return names;
    }
    more := true;
    while more {
        count := 0;
        while count < FindNameUnits && data[FindNameUnit + count] != 0 {
            count += 1;
        }
        name: u16[] = [];
        for index in 0..<count {
            name.append(data[FindNameUnit + index]);
        }
        text := Narrow(name, count);
        if text != "." && text != ".." {
            names.append(text);
        }
        more = FindNextFileW(handle, data) != 0;
    }
    closed := FindClose(handle);
    return names;
}

// The program's arguments, the first being how it was started, split from the
// command line by the C runtime's rules: spaces and tabs separate them outside
// quotes, a quote toggles quoting, 2n backslashes before a quote are n
// backslashes and a toggle, 2n+1 are n backslashes and a literal quote. The
// program name keeps its backslashes.
pub Arguments :: () -> string[] {
    source := GetCommandLineW();
    size := int(lstrlenW(source));
    wide: u16[] = [];
    for index in 0..<size {
        wide.append(0);
    }
    moved := RtlMoveMemory(wide, source, u64(size) * 2);
    return Split(Narrow(wide, size));
}

// The arguments of the command line `line`.
pub Split :: (line: string) -> string[] {
    arguments: string[] = [];
    size := text_byte_length(line);
    at := 0;
    first := true;
    while at < size {
        while at < size && (text_byte_at(line, at) == 32 || text_byte_at(line, at) == 9) {
            at += 1;
        }
        if at >= size {
            break;
        }
        current: u8[] = [];
        quoted := false;
        while at < size {
            byte := text_byte_at(line, at);
            if !quoted && (byte == 32 || byte == 9) {
                break;
            }
            if byte == 92 && !first {
                slashes := 0;
                while at < size && text_byte_at(line, at) == 92 {
                    slashes += 1;
                    at += 1;
                }
                if at < size && text_byte_at(line, at) == 34 {
                    for index in 0..<(slashes / 2) {
                        current.append(92);
                    }
                    if slashes % 2 == 1 {
                        current.append(34);
                        at += 1;
                    }
                } else {
                    for index in 0..<slashes {
                        current.append(92);
                    }
                }
                continue;
            }
            if byte == 34 {
                quoted = !quoted;
                at += 1;
                continue;
            }
            current.append(u8(byte));
            at += 1;
        }
        first = false;
        arguments.append(text_from_bytes(current));
    }
    return arguments;
}

// A finished child process: its exit status (-1 when it could not be waited
// for, 127 when the program could not be started) and, for Capture, what it
// wrote.
pub Output :: struct {
    status: int;
    stdout: string;
    stderr: string;
}

// The argument quoted for a command line, by the C runtime's rules: an argument
// with a space, tab or quote, or an empty one, is quoted; backslashes before a
// quote, and at the end of a quoted argument, are doubled.
Quoted :: (argument: string) -> u8[] {
    out: u8[] = [];
    size := text_byte_length(argument);
    bare := size > 0;
    for index in 0..<size {
        byte := text_byte_at(argument, index);
        if byte == 32 || byte == 9 || byte == 34 {
            bare = false;
        }
    }
    if bare {
        for index in 0..<size {
            out.append(u8(text_byte_at(argument, index)));
        }
        return out;
    }
    out.append(34);
    slashes := 0;
    for index in 0..<size {
        byte := text_byte_at(argument, index);
        if byte == 92 {
            slashes += 1;
            continue;
        }
        if byte == 34 {
            for each in 0..<(slashes * 2 + 1) {
                out.append(92);
            }
            out.append(34);
            slashes = 0;
            continue;
        }
        for each in 0..<slashes {
            out.append(92);
        }
        slashes = 0;
        out.append(u8(byte));
    }
    for each in 0..<(slashes * 2) {
        out.append(92);
    }
    out.append(34);
    return out;
}

// The command line of the command's arguments, separated by spaces.
CommandLine :: (command: string[]) -> string {
    line: u8[] = [];
    for argument in command {
        if length(line) > 0 {
            line.append(32);
        }
        line.extend(Quoted(argument));
    }
    return text_from_bytes(line);
}

// A SECURITY_ATTRIBUTES whose handles a child inherits.
Inheritable :: () -> u8[] {
    attributes := Block(24);
    attributes[0] = 24;
    attributes[16] = 1;
    return attributes;
}

// The 64-bit integer at `at` in `bytes`, little endian.
Word64 :: (bytes: u8[], at: int) -> u64 {
    value: u64 = 0;
    for index in 0..<8 {
        value = value | (u64(bytes[at + index]) << u32(8 * index));
    }
    return value;
}

// The bytes with the 64-bit integer stored at `at`, little endian. Arrays are
// values, so the caller keeps what this returns.
Put64 :: (bytes: u8[], at: int, value: u64) -> u8[] {
    changed := bytes;
    for index in 0..<8 {
        changed[at + index] = u8((value >> u32(8 * index)) & 255);
    }
    return changed;
}

// A standard handle made inheritable, or 0 when this process has none, so a
// child can be given it.
Shared :: (handle: u64) -> u64 {
    if handle == 0 || ~handle == 0 {
        return 0;
    }
    marked := SetHandleInformation(handle, 1, 1);
    if marked == 0 {
        return 0;
    }
    return handle;
}

// Starts the program with `command`'s arguments, its standard streams being
// `input`, `output` and `errors` when they are not zero, and returns its
// process handle; -1 when it cannot be started.
Start :: (command: string[], input: u64, output: u64, errors: u64) -> int {
    if length(command) == 0 {
        return -1;
    }
    startup := Block(104);
    startup[0] = 104;
    startup[61] = 1;
    startup = Put64(startup, 80, input);
    startup = Put64(startup, 88, output);
    startup = Put64(startup, 96, errors);
    information := Block(24);
    started := CreateProcessW(0, Wide(CommandLine(command)), 0, 0, 1, 0, 0, 0, startup, information);
    if started == 0 {
        return -1;
    }
    thread := Word64(information, 8);
    closed := CloseHandle(thread);
    return int(Word64(information, 0));
}

// Starts the program with the command's arguments, keeping this process's
// standard streams, and returns its process handle; -1 when it cannot be
// started.
pub Spawn :: (command: string[]) -> int {
    return Start(command, Shared(GetStdHandle(-10)), Shared(GetStdHandle(-11)), Shared(GetStdHandle(-12)));
}

// Waits for the process, closes its handle and returns its exit status.
pub Wait :: (process: int) -> int {
    waited := WaitForSingleObject(u64(process), Infinite);
    code: u32[] = [0];
    found := GetExitCodeProcess(u64(process), code);
    closed := CloseHandle(u64(process));
    if waited != 0 || found == 0 {
        return -1;
    }
    return int(code[0]);
}

// Runs the program, keeping the standard streams, and returns its exit status;
// 127 when it cannot be started.
pub Run :: (command: string[]) -> int {
    process := Spawn(command);
    if process < 0 {
        return 127;
    }
    return Wait(process);
}

// How many bytes are waiting in the pipe; -1 once it is closed or broken.
Waiting :: (pipe: u64) -> int {
    available: u32[] = [0];
    if PeekNamedPipe(pipe, 0, 0, 0, available, 0) == 0 {
        return -1;
    }
    return int(available[0]);
}

// Up to `count` of the bytes waiting in the pipe.
Take :: (pipe: u64, count: int) -> u8[] {
    wanted := count;
    if wanted > 4096 {
        wanted = 4096;
    }
    chunk := Block(wanted);
    read: u32[] = [0];
    taken: u8[] = [];
    if ReadFile(pipe, chunk, u32(wanted), read, 0) != 0 {
        for index in 0..<int(read[0]) {
            taken.append(chunk[index]);
        }
    }
    return taken;
}

// Runs the program with its standard output and error read into the result.
// Both pipes are read together, so a child filling one cannot stop on the other.
pub Capture :: (command: string[]) -> Output {
    result: Output = {status: 127, stdout: "", stderr: ""};
    if length(command) == 0 {
        return result;
    }
    out_read: u64[] = [0];
    out_write: u64[] = [0];
    err_read: u64[] = [0];
    err_write: u64[] = [0];
    made := CreatePipe(out_read, out_write, Inheritable(), 0);
    made = made * CreatePipe(err_read, err_write, Inheritable(), 0);
    if made == 0 {
        return result;
    }
    process := Start(command, Shared(GetStdHandle(-10)), out_write[0], err_write[0]);
    closed := CloseHandle(out_write[0]);
    closed = CloseHandle(err_write[0]);
    standard: u8[] = [];
    errors: u8[] = [];
    if process >= 0 {
        open_out := true;
        open_err := true;
        while open_out || open_err {
            before := length(standard) + length(errors);
            if open_out {
                waiting := Waiting(out_read[0]);
                if waiting < 0 {
                    open_out = false;
                } else if waiting > 0 {
                    standard.extend(Take(out_read[0], waiting));
                }
            }
            if open_err {
                waiting := Waiting(err_read[0]);
                if waiting < 0 {
                    open_err = false;
                } else if waiting > 0 {
                    errors.extend(Take(err_read[0], waiting));
                }
            }
            if length(standard) + length(errors) == before && (open_out || open_err) {
                // Nothing waiting: let the child run for a moment.
                waited := WaitForSingleObject(u64(process), 10);
            }
        }
        result.status = Wait(process);
    }
    closed = CloseHandle(out_read[0]);
    closed = CloseHandle(err_read[0]);
    result.stdout = text_from_bytes(standard);
    result.stderr = text_from_bytes(errors);
    return result;
}
package posix

import target "core:target"

// The POSIX calls core:os needs, declared against libc and called from native
// programs; the VM never runs foreign code. Paths are copied with a NUL into
// the call's stack buffer (see "Foreign libraries" in docs/code-language.md),
// so a path of 4096 bytes or more traps. A call that fails returns its libc
// result unchanged: 0 for success, -1 for failure; errno is not read yet.
// Getenv, which builds a string from C bytes, waits for allocating text natively.
//
// The stat layout and the directory entry's name offset are Linux x86-64's, and
// Darwin's when the build's destination is Darwin; Linux on other processors is
// not covered yet.

foreign import libc "system:c"

foreign libc {
    access :: (path: cstring, mode: i32) -> i32
    mkdir :: (path: cstring, mode: u32) -> i32
    unlink :: (path: cstring) -> i32
    rmdir :: (path: cstring) -> i32
    rename :: (source: cstring, destination: cstring) -> i32
    stat :: (path: cstring, buffer: u8[]) -> i32
    lstat :: (path: cstring, buffer: u8[]) -> i32
    fopen :: (path: cstring, mode: cstring) -> rawptr
    fread :: (buffer: u8[], size: u64, count: u64, stream: rawptr) -> u64
    fwrite :: (buffer: u8[], size: u64, count: u64, stream: rawptr) -> u64
    fclose :: (stream: rawptr) -> i32
    fseek :: (stream: rawptr, offset: i64, whence: i32) -> i32
    ftell :: (stream: rawptr) -> i64
    getenv :: (name: cstring) -> rawptr
    strlen :: (text: rawptr) -> u64
    memcpy :: (destination: u8[], source: rawptr, count: u64) -> rawptr
    opendir :: (path: cstring) -> rawptr
    readdir :: (directory: rawptr) -> rawptr
    closedir :: (directory: rawptr) -> i32
    calloc :: (count: u64, size: u64) -> rawptr
    memmove :: (destination: rawptr, source: u8[], count: u64) -> rawptr
    pipe :: (descriptors: u8[]) -> i32
    read :: (descriptor: i32, buffer: u8[], count: u64) -> i64
    close :: (descriptor: i32) -> i32
    write :: (descriptor: i32, buffer: u8[], count: u64) -> i64
    _exit :: (code: i32) -> i32
    poll :: (descriptors: u8[], count: u64, timeout: i32) -> i32
    waitpid :: (pid: i32, status: u8[], options: i32) -> i32
    posix_spawnp :: (pid: u8[], file: cstring, actions: u8[], attributes: rawptr, arguments: u8[], environment: rawptr) -> i32
    posix_spawn_file_actions_init :: (actions: u8[]) -> i32
    posix_spawn_file_actions_adddup2 :: (actions: u8[], descriptor: i32, target: i32) -> i32
    posix_spawn_file_actions_addclose :: (actions: u8[], descriptor: i32) -> i32
    posix_spawn_file_actions_destroy :: (actions: u8[]) -> i32
}

// Exports of the program's own start module (tools/compiler/native_link/Start.chibi):
// the process arguments and the environment its entry received.
foreign {
    chibi_argument_count :: () -> i64
    chibi_argument :: (index: i64, buffer: u8[], size: i64) -> i64
    chibi_environment :: () -> rawptr
}

pub KindNone: int : 0;
pub KindFile: int : 1;
pub KindDirectory: int : 2;
pub KindLink: int : 3;
pub KindOther: int : 4;

StatBytes: int : 256;

when target.Os == target.Darwin {
    ModeOffset: int : 4;
    ModeBytes: int : 2;
    NameOffset: int : 21;
} else {
    ModeOffset: int : 24;
    ModeBytes: int : 4;
    NameOffset: int : 19;
}

// A directory entry begins with its inode and offset (8 bytes each) and then
// its record length, two bytes, at 16 on both platforms; the name follows the
// type at NameOffset.
RecordLengthOffset: int : 16;

// Whether the path names anything a link points at.
pub Exists :: (path: string) -> bool {
    return access(path, 0) == 0;
}

// The mode bits of the path's stat, -1 when it does not exist. A link is
// followed unless `link`.
Mode :: (path: string, link: bool) -> int {
    buffer: u8[] = [];
    for index in 0..<StatBytes {
        buffer.append(0);
    }
    status: i32 = 0;
    if link {
        status = lstat(path, buffer);
    } else {
        status = stat(path, buffer);
    }
    if status != 0 {
        return -1;
    }
    mode := 0;
    for index in 0..<ModeBytes {
        mode += int(buffer[ModeOffset + index]) << u32(8 * index);
    }
    return mode;
}

// What the path names, KindNone when nothing. A link is not followed.
pub Kind :: (path: string) -> int {
    mode := Mode(path, true);
    if mode < 0 {
        return KindNone;
    }
    format := mode & 61440;
    if format == 32768 {
        return KindFile;
    }
    if format == 16384 {
        return KindDirectory;
    }
    if format == 40960 {
        return KindLink;
    }
    return KindOther;
}

pub MakeDirectory :: (path: string) -> bool {
    return mkdir(path, 493) == 0;
}

// Removes a file or link, or an empty directory.
pub Remove :: (path: string) -> bool {
    if Kind(path) == KindDirectory {
        return rmdir(path) == 0;
    }
    return unlink(path) == 0;
}

pub Rename :: (source: string, destination: string) -> bool {
    return rename(source, destination) == 0;
}

// The file's size in bytes, -1 when it cannot be opened.
pub FileSize :: (path: string) -> int {
    stream := fopen(path, "rb");
    if stream == 0 {
        return -1;
    }
    status := fseek(stream, 0, 2);
    size := ftell(stream);
    status = fclose(stream);
    return int(size);
}

// The file's bytes, including NUL and malformed UTF-8; no bytes when it cannot
// be read (FileSize tells that from an empty file). Opens through stdio, which
// takes no variadic arguments, so it is the same call on every platform.
pub ReadBytes :: (path: string) -> u8[] {
    buffer: u8[] = [];
    stream := fopen(path, "rb");
    if stream == 0 {
        return buffer;
    }
    status := fseek(stream, 0, 2);
    size := int(ftell(stream));
    status = fseek(stream, 0, 0);
    for index in 0..<size {
        buffer.append(0);
    }
    read := fread(buffer, 1, u64(size), stream);
    status = fclose(stream);
    if int(read) != size {
        empty: u8[] = [];
        return empty;
    }
    return buffer;
}

// Replaces the file with the bytes; false when it cannot be written whole.
pub WriteBytes :: (path: string, data: u8[]) -> bool {
    stream := fopen(path, "wb");
    if stream == 0 {
        return false;
    }
    written := fwrite(data, 1, u64(length(data)), stream);
    closed := fclose(stream);
    return int(written) == length(data) && closed == 0;
}

// The text of the bytes, which may hold NUL and malformed UTF-8.
pub Text :: (data: u8[]) -> string {
    return text_from_bytes(data);
}

// The file's text, "" when it cannot be read.
pub ReadText :: (path: string) -> string {
    return text_from_bytes(ReadBytes(path));
}

// The environment variable's value, "" when it is unset.
pub Getenv :: (name: string) -> string {
    value := getenv(name);
    if value == 0 {
        return "";
    }
    size := int(strlen(value));
    buffer: u8[] = [];
    for index in 0..<size {
        buffer.append(0);
    }
    moved := memcpy(buffer, value, u64(size));
    return text_from_bytes(buffer);
}

// The names in the directory, in the order the system gives them and without
// "." and "..". Empty when it cannot be opened (Kind tells a missing directory
// from an empty one).
pub List :: (path: string) -> string[] {
    names: string[] = [];
    directory := opendir(path);
    if directory == 0 {
        return names;
    }
    record_at := readdir(directory);
    while record_at != 0 {
        // The record length is read from a copy of the entry's head, then
        // exactly that many bytes are copied, so nothing past the entry is read.
        head: u8[] = [];
        for index in 0..<RecordLengthOffset + 2 {
            head.append(0);
        }
        moved := memcpy(head, record_at, u64(RecordLengthOffset + 2));
        size := int(head[RecordLengthOffset]) + int(head[RecordLengthOffset + 1]) * 256;
        record: u8[] = [];
        for index in 0..<size {
            record.append(0);
        }
        moved = memcpy(record, record_at, u64(size));
        name: u8[] = [];
        at := NameOffset;
        while at < length(record) && record[at] != 0 {
            name.append(record[at]);
            at += 1;
        }
        text := text_from_bytes(name);
        if text != "." && text != ".." {
            names.append(text);
        }
        record_at = readdir(directory);
    }
    status := closedir(directory);
    return names;
}

// A finished child process (named Output so the record does not share a name with core:os's Result: the native lane keys records by name): its exit status (the negative signal number when a
// signal ended it, 127 when the program could not be started) and, for Capture,
// what it wrote.
pub Output :: struct {
    status: int;
    stdout: string;
    stderr: string;
}

// The argument vector `execvp` takes, as bytes: one 8-byte little-endian
// pointer to each argument's NUL-ended copy, then a null pointer. The copies
// live in the heap until the program exits.
Vector :: (command: string[]) -> u8[] {
    vector: u8[] = [];
    for argument in command {
        size := text_byte_length(argument);
        data: u8[] = [];
        for index in 0..<size {
            data.append(u8(text_byte_at(argument, index)));
        }
        block := calloc(u64(size + 1), 1);
        moved := memmove(block, data, u64(size));
        word := u64(block);
        for index in 0..<8 {
            vector.append(u8((word >> u32(8 * index)) & 255));
        }
    }
    for index in 0..<8 {
        vector.append(0);
    }
    return vector;
}

// What `waitpid` reported as an exit status.
Decoded :: (status: int) -> int {
    signal := status & 127;
    if signal == 0 {
        return (status >> 8) & 255;
    }
    return -signal;
}

// A zeroed block for a libc structure the program only passes along.
Block :: (size: int) -> u8[] {
    block: u8[] = [];
    for index in 0..<size {
        block.append(0);
    }
    return block;
}

// The 32-bit integer at `at` in `bytes`, little endian.
Word32 :: (bytes: u8[], at: int) -> int {
    return int(bytes[at]) + int(bytes[at + 1]) * 256 + int(bytes[at + 2]) * 65536 + int(bytes[at + 3]) * 16777216;
}

// Starts the program with the command's arguments, keeping this process's
// standard streams, and returns its process id; -1 when it cannot be started.
pub Spawn :: (command: string[]) -> int {
    if length(command) == 0 {
        return -1;
    }
    pid := Block(8);
    actions := Block(256);
    status := posix_spawn_file_actions_init(actions);
    started := posix_spawnp(pid, command[0], actions, 0, Vector(command), chibi_environment());
    status = posix_spawn_file_actions_destroy(actions);
    if started != 0 {
        return -1;
    }
    return Word32(pid, 0);
}

// Waits for the process and returns its exit status.
pub Wait :: (process: int) -> int {
    status := Block(8);
    done := waitpid(i32(process), status, 0);
    if done < 0 {
        return -1;
    }
    return Decoded(Word32(status, 0));
}

// Runs the program, keeping the standard streams, and returns its exit status;
// 127 when it cannot be started.
pub Run :: (command: string[]) -> int {
    process := Spawn(command);
    if process < 0 {
        return 127;
    }
    return Wait(process);
}

// Runs the program with its standard output and error read into the result.
// Both pipes are read together, so a child filling one cannot stop on the other.
pub Capture :: (command: string[]) -> Output {
    result: Output = {status: 127, stdout: "", stderr: ""};
    if length(command) == 0 {
        return result;
    }
    out := Block(8);
    err := Block(8);
    made := pipe(out);
    made = made + pipe(err);
    if made != 0 {
        return result;
    }
    out_read := i32(Word32(out, 0));
    out_write := i32(Word32(out, 4));
    err_read := i32(Word32(err, 0));
    err_write := i32(Word32(err, 4));
    pid := Block(8);
    actions := Block(256);
    status := posix_spawn_file_actions_init(actions);
    status = posix_spawn_file_actions_adddup2(actions, out_write, 1);
    status = posix_spawn_file_actions_adddup2(actions, err_write, 2);
    status = posix_spawn_file_actions_addclose(actions, out_read);
    status = posix_spawn_file_actions_addclose(actions, err_read);
    started := posix_spawnp(pid, command[0], actions, 0, Vector(command), chibi_environment());
    status = posix_spawn_file_actions_destroy(actions);
    status = close(out_write);
    status = close(err_write);
    standard: u8[] = [];
    errors: u8[] = [];
    if started == 0 {
        // Two pollfd records: descriptor (4 bytes), requested events (2),
        // returned events (2). POLLIN is 1 and POLLHUP is 16 on both platforms.
        watched := Block(16);
        for index in 0..<4 {
            watched[index] = u8(Word32(out, 0) >> u32(8 * index));
            watched[8 + index] = u8(Word32(err, 0) >> u32(8 * index));
